(function createSplashScreen() {
    if (document.getElementById('appSplashScreen')) return;

    var splash = document.createElement('div');
    splash.id = 'appSplashScreen';

    // Detect dark/light preference for stroke color
    var isDark = !window.matchMedia || window.matchMedia('(prefers-color-scheme: dark)').matches;
    var bgColor = '#000000';
    var strokeColor = '#ffffff';

    splash.style.cssText = 'position:absolute;inset:0;z-index:99999;background:' + bgColor + ';display:flex;flex-direction:column;align-items:center;justify-content:center;transition:opacity 0.5s ease;';

    splash.innerHTML =
        '<svg class="splash-infinity-svg" viewBox="0 0 160 80" xmlns="http://www.w3.org/2000/svg" style="width:160px;height:80px;overflow:visible;">' +
            '<path class="splash-infinity-path" id="splashInfinityPath"' +
            ' d="M80 40' +
            ' C80 18 62 6 44 18' +
            ' C26 30 26 50 44 62' +
            ' C62 74 80 62 80 40' +
            ' C80 18 98 6 116 18' +
            ' C134 30 134 50 116 62' +
            ' C98 74 80 62 80 40 Z"' +
            ' fill="none" stroke="' + strokeColor + '" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"' +
            ' style="stroke-dasharray:1000;stroke-dashoffset:1000;animation:drawInfinity 1.4s cubic-bezier(0.4,0,0.2,1) 0.2s forwards;"/>' +
        '</svg>' +
        '<div class="splash-text" style="color:' + strokeColor + ';font-size:16px;font-weight:900;letter-spacing:4px;text-transform:uppercase;opacity:0;margin-top:28px;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',sans-serif;animation:splashFadeIn 0.6s ease 1.4s forwards;">TrustFirst</div>';

    function mountSplash() {
        var app = document.getElementById('app');
        var target = app || document.body;
        target.insertBefore(splash, target.firstChild);

        // After SVG is in DOM, measure real path length and set dasharray correctly
        requestAnimationFrame(function() {
            var path = document.getElementById('splashInfinityPath');
            if (path) {
                try {
                    var len = path.getTotalLength();
                    if (len > 0) {
                        path.style.strokeDasharray = len;
                        path.style.strokeDashoffset = len;
                    }
                } catch(e) {}
            }
        });
    }

    if (document.body) {
        mountSplash();
    } else {
        document.addEventListener('DOMContentLoaded', mountSplash);
    }
})();

// Track user activity for "last seen"
(function startActivityTracking() {
    function pingActivity() {
        if (!currentUser) return;
        var now = Date.now();
        localStorage.setItem('tf_last_active', now.toString());
        if (window.sb && currentUser) {
            sb.from('profiles').update({ last_seen: new Date(now).toISOString(), is_online: true }).eq('id', currentUser.id).then(function(){});
        }
    }
    ['mousemove','keydown','touchstart','scroll','click'].forEach(function(ev) {
        document.addEventListener(ev, function() {
            clearTimeout(window._activityTimer);
            clearTimeout(window._activityPingTimer);
            window._activityPingTimer = setTimeout(function() { pingActivity(); }, 30000); // max once per 30s
            window._activityTimer = setTimeout(function() {
                if (window.sb && currentUser) {
                    sb.from('profiles').update({ is_online: false }).eq('id', currentUser.id).then(function(){});
                }
            }, 5 * 60 * 1000); // 5 min idle = offline
        }, { passive: true });
    });
})();

function dismissSplash() {
    var splash = document.getElementById('appSplashScreen');
    if (!splash) return;
    // Wait for draw animation to finish (1.6s total) before fading
    var elapsed = performance.now();
    var minWait = 1800; // ms — let the full draw + text play
    var remaining = Math.max(0, minWait - elapsed);
    setTimeout(function() {
        splash.style.opacity = '0';
        splash.style.pointerEvents = 'none';
        setTimeout(function() { splash.remove(); }, 500);
    }, remaining);
}

