(function initDarkMode() {
    const saved = localStorage.getItem('trustfirst-theme');
    if (saved) {
        document.documentElement.setAttribute('data-theme', saved);
    } else {
        const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
        document.documentElement.setAttribute('data-theme', prefersDark ? 'dark' : 'light');
    }
})();

function toggleDarkMode() {
    const current = document.documentElement.getAttribute('data-theme');
    const newTheme = current === 'dark' ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', newTheme);
    localStorage.setItem('trustfirst-theme', newTheme);

    // Force feed background update immediately
    const feedEl = document.getElementById('feed-panels');
    const appEl = document.getElementById('app');
    if (feedEl) feedEl.style.background = newTheme === 'dark' ? '#000' : '#fff';
    if (appEl) appEl.style.background = newTheme === 'dark' ? '#000' : '#fff';

    // Sync all post cards
    document.querySelectorAll('.post-card').forEach(function(card) {
        card.style.background = newTheme === 'dark' ? '#111' : '#fff';
        card.style.borderBottomColor = newTheme === 'dark' ? '#1e1e1e' : '#f2f2f2';
    });

    // Update toggle switch if it exists
    const toggle = document.getElementById('dark-mode-toggle');
    if (toggle) {
        if (newTheme === 'dark') { toggle.classList.add('active'); }
        else { toggle.classList.remove('active'); }
    }
    return newTheme;
}

// When settings page loads, sync the toggle
function syncDarkModeToggle() {
    const toggle = document.getElementById('dark-mode-toggle');
    if (toggle) {
        const current = document.documentElement.getAttribute('data-theme');
        if (current === 'dark') {
            toggle.classList.add('active');
        } else {
            toggle.classList.remove('active');
        }
    }
}

