// --- SECURITY CORE ---
function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function isValidEmail(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function isValidUsername(username) {
    return /^[a-zA-Z0-9_]{3,20}$/.test(username);
}

function secureSave(key, data) {
    // NOTE: localStorage is never truly secure. Do not store tokens, passwords,
    // or PII here. This is for UI preferences and non-sensitive session state only.
    try {
        localStorage.setItem('tf_' + key, JSON.stringify(data));
    } catch(e) { console.warn('[secureSave error]', e); }
}
function secureLoad(key) {
    try {
        var raw = localStorage.getItem('tf_' + key);
        return raw ? JSON.parse(raw) : null;
    } catch(e) { return null; }
}
function secureLoad(key) {
    try {
        var raw = localStorage.getItem('tf_' + key);
        return raw ? JSON.parse(raw) : null;
    } catch(e) { return null; }
}

function generateToken() {
    return Array.from(crypto.getRandomValues(new Uint8Array(32)))
        .map(b => b.toString(16).padStart(2, '0')).join('');
}

function isChildAccount() {
    return currentUser && currentUser.type === 'child';
}

function isVerified() {
    return currentUser && currentUser.verified === true;
}

function isAdultContent(text) {
    if (!text) return false;
    const lower = text.toLowerCase();
    return APP_CONFIG.adultContentTags.some(tag => lower.includes(tag));
}

function isAIGenerated(text) {
    if (!text) return false;
    const lower = text.toLowerCase();
    const aiFlags = ["deepfake", "ai generated", "ai-generated", "made with ai", "not real"];
    return aiFlags.some(flag => lower.includes(flag));
}

function containsBannedWords(text) {
    if (!text) return false;
    const lower = text.toLowerCase();
    return APP_CONFIG.bannedKeywords.some(word => lower.includes(word));
}

// --- CHILD SAFETY ENFORCEMENT ---
function blockChildAction(actionName) {
    const overlay = document.createElement('div');
    overlay.className = 'child-blocked-overlay';
    overlay.innerHTML = `
        <i class="fa-solid fa-shield-halved" style="font-size:60px; color:#34C759; margin-bottom:20px;"></i>
        <h2 style="margin-bottom:10px;">Permission Needed</h2>
        <p style="color:#888; margin-bottom:5px;">You need parent approval to <b>${escapeHtml(actionName)}</b>.</p>
        <p style="color:#888; font-size:13px; margin-bottom:25px;">A request has been sent to your parent.</p>
        <button onclick="this.parentElement.remove()" style="padding:12px 30px; background:#34C759; color:white; border:none; border-radius:15px; font-weight:bold; font-size:15px; cursor:pointer;">OK</button>
    `;
    document.getElementById('app').appendChild(overlay);
    triggerHaptic(30);
}

function requireVerification(actionName) {
    const overlay = document.createElement('div');
    overlay.className = 'child-blocked-overlay';
    overlay.innerHTML = `
        <i class="fa-solid fa-id-card" style="font-size:60px; color:#FF9500; margin-bottom:20px;"></i>
        <h2 style="margin-bottom:10px;">Verification Required</h2>
        <p style="color:#888; margin-bottom:5px;">You must verify your identity to <b>${escapeHtml(actionName)}</b>.</p>
        <p style="color:#888; font-size:13px; margin-bottom:25px;">This protects our community from bots and scammers.</p>
        <button onclick="this.parentElement.remove()" style="padding:12px 30px; background:#007AFF; color:white; border:none; border-radius:15px; font-weight:bold; font-size:15px; cursor:pointer;">OK</button>
    `;
    document.getElementById('app').appendChild(overlay);
}

function canPerformAction(actionName) {
    if (!isVerified()) {
        requireVerification(actionName);
        return false;
    }
    if (isChildAccount()) {
        blockChildAction(actionName);
        parentRequests.push({
            id: Date.now(),
            kid: currentUser ? currentUser.name : 'Child',
            action: actionName,
            content: 'Wants to ' + actionName.toLowerCase(),
            status: 'pending'
        });
        // Notify parent in real-time
        notifyParentOfChildAction('attempted: ' + actionName, 'Waiting for your approval');
        return false;
    }
    return true;
}

