// ---- MAIN REGISTRATION ----
async function completeRegistration(verified) {
    // Wait for Supabase to be ready
    await waitForSb();

    const firstName = (document.getElementById('reg-firstname')?.value || '').trim();
    const lastName = (document.getElementById('reg-lastname')?.value || '').trim();
    const name = (firstName + ' ' + lastName).trim();
    const email = (document.getElementById('reg-email')?.value || '').trim().toLowerCase();
    const username = (document.getElementById('reg-username')?.value || '').trim().toLowerCase();
    const password = document.getElementById('reg-pass')?.value || '';
    const confirmPass = document.getElementById('reg-confirm-pass')?.value || '';

    // Client-side validation
    if (firstName.length < 2) return showAuthError('First name must be at least 2 characters', 'step-register');
    if (lastName.length < 1) return showAuthError('Please enter your last name', 'step-register');
    if (!email || !isValidEmail(email)) return showAuthError('Enter a valid email', 'step-register');
    if (!username || !isValidUsername(username)) return showAuthError('Username: 3-20 chars, letters/numbers/underscore only', 'step-register');

    if (password !== confirmPass) return showAuthError('Passwords do not match.', 'step-register');

    // Password policy enforcement
    const pwResult = PasswordPolicy.validate(password);
    if (!pwResult.valid) {
        const firstFail = pwResult.results.find(r => !r.passed);
        return showAuthError('Password requirement not met: ' + firstFail.label, 'step-register');
    }

    showAuthLoader();

    try {
        // Get device fingerprint
        const deviceInfo = await DeviceFingerprint.getDeviceInfo();

        // One-account enforcement checks
        const validation = await OneAccountPolicy.validateRegistration(
            email, username, deviceInfo.device_fingerprint
        );
        if (!validation.valid) {
            return showAuthError(validation.errors[0], 'step-register');
        }

        // Register with Supabase Auth
        const authData = await DB.signUp(email, password, {
            full_name: name,
            username: username,
            account_type: selectedAccountType || 'personal'
        });

        if (!authData.user || (authData.user.identities && authData.user.identities.length === 0)) {
            return showAuthError('This email is already registered. Please log in instead.', 'step-register');
        }

        // Create user profile in our users table
        let profile = null;
try {
    profile = await DB.createUserProfile({
        id: authData.user.id,
        email: email,
        username: username,
        full_name: name,
        account_type: selectedAccountType || 'personal',
        verified: verified,
        badge_tier: getTierForType(selectedAccountType || 'personal'),
        trust_score: verified ? 85 : 20,
        parent_id: selectedAccountType === 'child' ? secureLoad('pending_parent') : null
    });
} catch(profileErr) {
    console.error('[Profile Create Error]', profileErr);
    return showAuthError('Account created but profile setup failed: ' + profileErr.message, 'step-register');
}

        // Register this device as trusted
        const geo = await GeoIP.lookup();
        await DB.registerDevice({
            user_id: authData.user.id,
            ...deviceInfo,
            ip_address: geo.ip,
            location_city: geo.city,
            location_country: geo.country,
            is_trusted: true,
            is_current: true
        });

        // Log the login activity
        await DB.logLoginActivity({
            user_id: authData.user.id,
            ip_address: geo.ip,
            location_city: geo.city,
            location_country: geo.country,
            user_agent: navigator.userAgent,
            login_method: 'password',
            status: 'success'
        });

        // Generate and publish E2E encryption keys
        await E2E.init();
        await E2E.publishKeyBundle(authData.user.id);

        // Set local state
        var phoneVal = (document.getElementById('reg-phone') || {}).value || '';
        currentUser = {
        is_admin: false,
            id: authData.user.id,
            name: name,
            email: email,
            phone: phoneVal,
            handle: '@' + username,
            username: username,
            type: selectedAccountType || 'personal',
            tier: getTierForType(selectedAccountType || 'personal'),
            verified: verified,
            trust_score: verified ? 85 : 20
        };
        secureSave('current_user', currentUser);

        // Launch
        document.getElementById('splash').style.transform = 'translateX(-50%) translateY(100%)';
        setTimeout(() => launchApp(), 600);

    } catch (error) {
        console.error('[Registration]', error);
        let msg = 'Registration failed. ';
        if (error.message?.includes('duplicate')) {
            msg += 'This email or username is already taken.';
        } else if (error.message?.includes('password')) {
            msg += 'Password does not meet requirements.';
        } else {
            msg += error.message || 'Please try again.';
        }
        showAuthError(msg, 'step-register');
    }
}

// ---- MAIN LOGIN ----
async function authenticateUser() {
    // Wait for Supabase to be ready
    await waitForSb();

    const regName = document.getElementById('reg-name');

    // If coming from registration verify step
       if (regName && regName.value && regName.value.trim().length > 0) {
        return completeRegistration(true);
    }

        // Check lockout
    const lockoutUntil = localStorage.getItem('tf_lockout_until');
    var burstAttempts = JSON.parse(localStorage.getItem('tf_burst') || '[]');
burstAttempts = burstAttempts.filter(function(t) { return Date.now() - t < 60000; });
if (burstAttempts.length >= 5) {
    showAuthError('Too many attempts. Please wait 60 seconds.', 'step-login');
    return;
}
burstAttempts.push(Date.now());
localStorage.setItem('tf_burst', JSON.stringify(burstAttempts));
    if (lockoutUntil && Date.now() < parseInt(lockoutUntil)) {
        var remainMins = Math.ceil((parseInt(lockoutUntil) - Date.now()) / 60000);
        return showAuthError('Account locked. Try again in ' + remainMins + ' minute(s).', 'step-login');
    }

    // Login flow
    const identifier = (document.getElementById('login-user')?.value || '').trim();
    const password = document.getElementById('login-pass')?.value || '';

    if (!identifier) return showAuthError('Enter your Trust-ID or email', 'step-login');
    if (!password) return showAuthError('Enter your password', 'step-login');

    showAuthLoader();

    try {
        let email = identifier;

        // If user entered a username instead of email, look up the email
       if (!isValidEmail(identifier)) {
    const cleanUsername = identifier.replace('@', '').toLowerCase();
    const userProfile = await DB.getUserByUsername(cleanUsername);

    if (!userProfile) {
        // Could be a user added directly via Supabase dashboard (no users table profile)
        // We can't look up their email by username, so tell them to use their email instead
        return showAuthError(
            'Account not found by username. Try logging in with your email address instead.',
            'step-login'
        );
    }

    if (userProfile.is_locked) {
        return showAuthError(
            'This account is locked. Contact support to unlock it.',
            'step-login'
        );
    }

    email = userProfile.email;
}

        // Sign in with Supabase
        const authData = await DB.signIn(email, password);

        if (!authData.user) {
            return showAuthError('Invalid credentials', 'step-login');
        }

        // Fetch full profile
        const profile = await DB.getUserProfile(authData.user.id);

        if (!profile) {
            return showAuthError('Account found but no profile exists. Please register again or contact support.', 'step-login');
        }

        if (profile.is_locked) {
            await DB.signOut();
            return showAuthError(
                'This account is locked and frozen. Contact support to unlock.',
                'step-login'
            );
        }

        if (profile.is_banned) {
            await DB.signOut();
            return showAuthError(
                'This account has been permanently banned for policy violations.',
                'step-login'
            );
        }

        // Register/update device
        const deviceInfo = await DeviceFingerprint.getDeviceInfo();
        const geo = await GeoIP.lookup();

        await DB.registerDevice({
            user_id: authData.user.id,
            ...deviceInfo,
            ip_address: geo.ip,
            location_city: geo.city,
            location_country: geo.country,
            is_trusted: true,
            is_current: true
        });

        // Log login activity
        await DB.logLoginActivity({
            user_id: authData.user.id,
            ip_address: geo.ip,
            location_city: geo.city,
            location_country: geo.country,
            user_agent: navigator.userAgent,
            login_method: 'password',
            status: 'success'
        });

        // Make sure E2E keys exist
        await E2E.init();
        const existingKeys = await DB.getKeyBundle(authData.user.id);
        if (!existingKeys) {
            await E2E.publishKeyBundle(authData.user.id);
        }

        trackLogin(true, false);
        // Set local state
        currentUser = {
        is_admin: profile.is_admin || false,
            id: profile.id,
            name: profile.full_name,
            email: profile.email,
            handle: '@' + profile.username,
            username: profile.username,
            type: profile.account_type,
            tier: profile.badge_tier,
            verified: profile.verified,
            trust_score: profile.trust_score,
            avatar_url: profile.avatar_url,
            bio: profile.bio
        };
        secureSave('current_user', currentUser);

        // Launch
        document.getElementById('splash').style.transform = 'translateX(-50%) translateY(100%)';
        setTimeout(() => launchApp(), 600);

    } catch (error) {
    hideAuthLoader();
    console.error('[Login Error]', error);

    let msg = '';
    const code = error?.message?.toLowerCase() || '';

    if (code.includes('email not confirmed')) {
        msg = 'Please check your email and click the confirmation link first.';
    } else if (code.includes('invalid login') || code.includes('invalid credentials')) {
        msg = 'Wrong email or password. Please try again.';
    } else if (code.includes('too many requests')) {
        msg = 'Too many attempts. Wait a moment and try again.';
    } else {
        msg = 'Login failed: ' + (error.message || 'Unknown error');
    }
    showAuthError(msg, 'step-login');
}
}   // ← THIS is the missing closing brace for authenticateUser()

// ---- SESSION RESTORATION ----
async function restoreSession() {
    if (!window.sb) return false;
    try {
        // Check lockout
        const lockoutUntil = localStorage.getItem('tf_lockout_until');
        if (lockoutUntil && Date.now() < parseInt(lockoutUntil)) {
            console.debug('[Auth] Account temporarily locked out');
            return false;
        }
        localStorage.removeItem('tf_failed_logins');

        const session = await DB.getSession();
        if (!session) return false;

        const profile = await DB.getUserProfile(session.user.id);
        if (!profile || profile.is_locked || profile.is_banned) {
            await DB.signOut();
            return false;
        }

        // Update device last_active
        const deviceInfo = await DeviceFingerprint.getDeviceInfo();
        await DB.registerDevice({
            user_id: session.user.id,
            ...deviceInfo,
            is_current: true,
            last_active: new Date().toISOString()
        });

        currentUser = {
            id: profile.id,
            name: profile.full_name,
            email: profile.email,
            handle: '@' + profile.username,
            username: profile.username,
            type: profile.account_type,
            tier: profile.badge_tier,
            verified: profile.verified,
            trust_score: profile.trust_score,
            avatar_url: profile.avatar_url,
            bio: profile.bio
        };
        secureSave('current_user', currentUser);

        await E2E.init();
        return true;
    } catch (e) {
        console.error('[Session] Restore failed:', e);
        return false;
    }
}

// ---- LOGOUT ----
async function logOut() {
    var sheet = document.createElement('div');
    sheet.style.cssText = 'position:fixed;bottom:0;left:0;right:0;z-index:99999;background:rgba(0,0,0,0.5);top:0;display:flex;align-items:flex-end;justify-content:center;';
    sheet.innerHTML =
        '<div style="background:var(--card-bg,#fff);border-radius:24px 24px 0 0;padding:28px 20px 36px;width:100%;max-width:430px;text-align:center;">' +
        '<div style="width:36px;height:4px;background:rgba(0,0,0,0.15);border-radius:2px;margin:0 auto 24px;"></div>' +
        '<p style="font-size:17px;font-weight:700;margin-bottom:8px;">Log out?</p>' +
        '<p style="font-size:14px;color:#888;margin-bottom:24px;">You\'ll need to sign back in to access your account.</p>' +
        '<button id="confirmLogoutBtn" style="width:100%;padding:16px;background:#FF3B30;color:#fff;border:none;border-radius:16px;font-size:16px;font-weight:700;cursor:pointer;margin-bottom:10px;">Log Out</button>' +
        '<button onclick="this.closest(\'div[style*=z-index\\:99999]\').remove()" style="width:100%;padding:16px;background:var(--bg-secondary,#f2f2f7);color:var(--text-primary,#000);border:none;border-radius:16px;font-size:16px;font-weight:600;cursor:pointer;">Cancel</button>' +
        '</div>';
    document.body.appendChild(sheet);
    document.getElementById('confirmLogoutBtn').onclick = async function() {
        sheet.remove();
        try { await DB.signOut(); } catch(e) {}
        localStorage.removeItem('tf_current_user');
        localStorage.removeItem('tf_failed_logins');
        localStorage.removeItem('tf_lockout_until');
        currentUser = null;
        location.reload();
    };
}

