function hideVoiceRecordUI() {
    stopVoiceWaveform();
    clearInterval(_vrTimerInterval);
    var el = document.getElementById('voice-record-overlay');
    if (el) { el.style.opacity='0'; el.style.transition='opacity 0.2s'; setTimeout(function(){ el.remove(); },200); }
}

function lockVoiceRecord() {
    var lockUI = document.getElementById('vr-lock-ui');
    if (lockUI) lockUI.style.display = 'flex';
    var hint = document.getElementById('vr-hint');
    if (hint) { hint.textContent = '🔒 Recording locked'; hint.style.color = '#007AFF'; }
    triggerHaptic(40);
}

function cancelVoiceRecord() {
    if (voiceRecorder && voiceRecording) {
        voiceRecording = false;
        voiceRecorder.stop();
        voiceRecorder.stream.getTracks().forEach(function(t){ t.stop(); });
        clearInterval(voiceRecordingInterval);
    }
    _voiceLocked = false;
    var voiceBtn = document.getElementById('voice-btn');
    if (voiceBtn) { voiceBtn.style.color = '#007AFF'; }
    showToast('Voice note deleted 🗑️');
}

var _vrTimerInterval = null;
var _vrTimerSecs = 0;
function startVoiceTimerUI() {
    _vrTimerSecs = 0;
    clearInterval(_vrTimerInterval);
    _vrTimerInterval = setInterval(function() {
        _vrTimerSecs++;
        var m = Math.floor(_vrTimerSecs/60);
        var s = _vrTimerSecs%60;
        var el = document.getElementById('vr-timer');
        if (el) el.textContent = m+':'+(s<10?'0':'')+s;
    }, 1000);
}

var _vrWaveAF = null;
var _vrAnalyser = null;
var _vrAudioCtx = null;
function startVoiceWaveform() {
    var canvas = document.getElementById('vr-waveform');
    if (!canvas) return;
    var ctx = canvas.getContext('2d');
    var W = canvas.offsetWidth * window.devicePixelRatio || 350;
    var H = 50;
    canvas.width = W;

    // Try to connect to actual mic stream
    if (voiceRecorder && voiceRecorder.stream) {
        try {
            _vrAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
            var source = _vrAudioCtx.createMediaStreamSource(voiceRecorder.stream);
            _vrAnalyser = _vrAudioCtx.createAnalyser();
            _vrAnalyser.fftSize = 64;
            source.connect(_vrAnalyser);
        } catch(e) { _vrAnalyser = null; }
    }

    var dataArray = _vrAnalyser ? new Uint8Array(_vrAnalyser.frequencyBinCount) : null;
    var bars = 32;
    var barHeights = new Array(bars).fill(4);

    function draw() {
        _vrWaveAF = requestAnimationFrame(draw);
        ctx.clearRect(0,0,W,H);
        if (_vrAnalyser && dataArray) {
            _vrAnalyser.getByteFrequencyData(dataArray);
        }
        var barW = (W - bars * 2) / bars;
        for (var i=0; i<bars; i++) {
            var target = _vrAnalyser && dataArray
                ? Math.max(4, (dataArray[i] / 255) * H * 0.85)
                : (4 + Math.abs(Math.sin(Date.now()/300 + i*0.4)) * 18 * Math.random());
            barHeights[i] += (target - barHeights[i]) * 0.35;
            var x = i * (barW + 2);
            var h = barHeights[i];
            ctx.fillStyle = '#007AFF';
            ctx.beginPath();
            ctx.roundRect(x, (H-h)/2, barW, h, 3);
            ctx.fill();
        }
    }
    draw();
}
function stopVoiceWaveform() {
    if (_vrWaveAF) { cancelAnimationFrame(_vrWaveAF); _vrWaveAF = null; }
    if (_vrAudioCtx) { try { _vrAudioCtx.close(); } catch(e){} _vrAudioCtx = null; }
    _vrAnalyser = null;
}

async function startVoiceRecord() {
stopMusicPreview();
    stopSoundPreview && stopSoundPreview();
    if (_thoughtViewerAudio) { try { _thoughtViewerAudio.pause(); } catch(e) { if (e) console.warn('[Suppressed error]', e); } }
    try {
        // Request microphone permission
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

        // Create MediaRecorder
        voiceRecorder = new MediaRecorder(stream);
        voiceRecording = true;
        voiceRecordingTime = 0;
        voiceChunks.length = 0; // Clear array

        // Update button color
        const voiceBtn = document.getElementById('voice-btn');
        if (voiceBtn) { voiceBtn.style.color = '#FF3B30'; voiceBtn.style.fontSize = '18px'; }

        // Show timer
        const timerDiv = document.createElement('div');
        timerDiv.id = 'voice-timer';
        timerDiv.style.cssText = `
            position: absolute; top: -30px; left: 50%; transform: translateX(-50%);
            background: #FF3B30; color: white; padding: 4px 12px; border-radius: 12px;
            font-size: 12px; font-weight: 700; white-space: nowrap;
        `;
        var timerAnchor = document.querySelector('[style*="bottom:20px"]');
        if (timerAnchor) timerAnchor.parentElement.appendChild(timerDiv);

        // Start timer
        voiceRecordingInterval = setInterval(() => {
            voiceRecordingTime++;
            const mins = Math.floor(voiceRecordingTime / 60);
            const secs = voiceRecordingTime % 60;
            const display = `${mins}:${secs.toString().padStart(2, '0')}`;
            timerDiv.textContent = '🔴 Recording... ' + display;

            // Max 5 minutes
            if (voiceRecordingTime >= 300) {
                stopVoiceRecord();
            }
        }, 1000);

        // Collect audio data
        voiceRecorder.ondataavailable = (e) => {
            voiceChunks.push(e.data);
        };

        // Start recording
        voiceRecorder.start();
        triggerHaptic(30);

    } catch (error) {
        console.error('[VoiceRecord] Permission denied:', error);
        ShowToast('Microphone permission required to send voice messages');
        voiceRecording = false;
    }
}

async function stopVoiceRecord() {
    if (!voiceRecorder || !voiceRecording) return;

    voiceRecording = false;

    // Stop recording
    voiceRecorder.stop();
    voiceRecorder.stream.getTracks().forEach(track => track.stop());

    // Clear ALL timers
    clearInterval(voiceRecordingInterval);
    clearInterval(_vrTimerInterval);
    _vrTimerInterval = null;
    voiceRecordingTime = 0;   // ← reset so next recording starts from 0
    const timerDiv = document.getElementById('voice-timer');
    if (timerDiv) timerDiv.remove();

    // Reset button
    const voiceBtn = document.getElementById('voice-btn');
    voiceBtn.style.color = '#007AFF';
    voiceBtn.style.fontSize = '22px';

    // Wait for recording to finish
    await new Promise(resolve => {
        voiceRecorder.onstop = resolve;
    });

    // Create audio blob
    const audioBlob = new Blob(voiceChunks, { type: 'audio/webm' });
    console.debug('[VoiceRecord] Audio recorded:', audioBlob.size, 'bytes');

    // Compress if needed (optional - WebM is already compressed)
    // For now, just send it

    // Send voice message
    await sendVoiceMessage(audioBlob, voiceRecordingTime);

    triggerHaptic(20);
}

async function sendVoiceMessage(audioBlob, duration) {
    try {
        showAuthLoader();

        const session = await DB.getSession();
        if (!session) throw new Error('Not authenticated');

        // Convert blob to base64 for storage
        const reader = new FileReader();
        reader.readAsDataURL(audioBlob);

        reader.onload = async () => {
            const base64Audio = reader.result; // data:audio/webm;base64,...

            try {
                // Store in Supabase Storage
                const fileName = `voice_${Date.now()}.webm`;
                const { data: uploadData, error: uploadError } = await sb.storage
                    .from('chat-media')
                    .upload(`voice-messages/${fileName}`, audioBlob, {
                        contentType: 'audio/webm',
                        upsert: false
                    });

                if (uploadError) throw uploadError;

                // Get public URL
                const { data: { publicUrl } } = sb.storage
                    .from('chat-media')
                    .getPublicUrl(`voice-messages/${fileName}`);

                // Send message record
                const message = await DB.sendEncryptedMessage({
                    conversation_id: currentConversationId,
                    sender_id: session.user.id,
                    ciphertext: publicUrl, // Store URL as "ciphertext"
                    nonce: 'voice_message',
                    message_type: 'voice',
                    voice_duration_seconds: duration
                });

                // Display in chat
                appendVoiceMessageToChat(publicUrl, duration, true, message);

                hideAuthLoader();
                triggerHaptic(15);

            } catch (e) {
                console.error('[VoiceUpload]', e);
                hideAuthLoader();
                alert('Failed to send voice message: ' + e.message);
            }
        };

    } catch (e) {
        console.error('[SendVoiceMessage]', e);
        hideAuthLoader();
        howToast('Something went wrong — please try again.');
    }
}

function appendVoiceMessageToChat(audioUrl, duration, isSent, messageObj) {
    var chatBody = document.getElementById('chat-body');
    if (!chatBody) return;
    var msgId = messageObj ? (messageObj.id || ('vm' + Date.now())) : ('vm' + Date.now());
    var time = new Date().toLocaleTimeString('en-ZA', { hour: '2-digit', minute: '2-digit' });
    var mins = Math.floor(duration / 60), secs = duration % 60;
    var durStr = mins + ':' + (secs < 10 ? '0' : '') + secs;
    var heights = [4,7,12,9,16,11,8,14,6,10,13,7,15,9,5,11,8,14,6,12,10,7,13,9,4,11,8,6];
    var bars = heights.map(function(h){
        return '<div style="width:3px;height:' + h + 'px;background:rgba(255,255,255,0.8);border-radius:2px;flex-shrink:0;"></div>';
    }).join('');

    var wrap = document.createElement('div');
    wrap.style.cssText = 'display:flex;flex-direction:column;' + (isSent ? 'align-items:flex-end;' : 'align-items:flex-start;') + 'margin-bottom:6px;padding:0 2px;';
    wrap.setAttribute('data-msg-bubble', 'true');
    wrap.setAttribute('data-msg-type', 'voice');
    wrap.setAttribute('data-msg-id', String(msgId));
    wrap.innerHTML =
        '<div id="vn-bubble-' + msgId + '" onclick="playVoiceNote(this,\'' + escapeHtml(audioUrl) + '\')" style="background:#007AFF;padding:10px 14px;border-radius:' + (isSent ? '20px 20px 4px 20px' : '20px 20px 20px 4px') + ';max-width:260px;display:flex;align-items:center;gap:10px;cursor:pointer;">' +
            '<div id="vn-play-' + msgId + '" style="width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,0.2);display:flex;align-items:center;justify-content:center;flex-shrink:0;">' +
                '<i class="fa-solid fa-play" style="color:white;font-size:14px;margin-left:2px;"></i></div>' +
            '<div style="flex:1;min-width:0;">' +
                '<div style="display:flex;align-items:flex-end;gap:2px;height:20px;">' + bars + '</div>' +
                '<div style="display:flex;align-items:center;gap:4px;margin-top:4px;">' +
                    '<small style="color:rgba(255,255,255,0.8);font-size:11px;" id="vn-dur-' + msgId + '">' + durStr + '</small>' +
                    '<span style="color:rgba(255,255,255,0.4);font-size:9px;">•</span>' +
                    '<small style="color:rgba(255,255,255,0.5);font-size:10px;">' + time + '</small>' +
                '</div>' +
            '</div>' +
        '</div>';
    chatBody.appendChild(wrap);
    chatBody.scrollTop = chatBody.scrollHeight;
}

// Play voice note inline (toggle play/pause)
var _vnAudio = null;
var _vnActiveBubble = null;
function playVoiceNote(bubble, audioUrl) {
    if (_vnAudio && _vnActiveBubble === bubble) {
        if (!_vnAudio.paused) {
            _vnAudio.pause();
            var icon = bubble.querySelector('i.fa-pause');
            if (icon) { icon.className = 'fa-solid fa-play'; icon.style.marginLeft = '2px'; }
        } else {
            _vnAudio.play();
            var icon2 = bubble.querySelector('i.fa-play');
            if (icon2) { icon2.className = 'fa-solid fa-pause'; icon2.style.marginLeft = '0'; }
        }
        return;
    }
    if (_vnAudio) { _vnAudio.pause(); _vnAudio.currentTime = 0; }
    _vnActiveBubble = bubble;
    _vnAudio = new Audio(audioUrl);
    var playIcon = bubble.querySelector('i');
    if (playIcon) { playIcon.className = 'fa-solid fa-pause'; playIcon.style.marginLeft = '0'; }
    _vnAudio.onended = function() {
        if (playIcon) { playIcon.className = 'fa-solid fa-play'; playIcon.style.marginLeft = '2px'; }
        _vnActiveBubble = null;
    };
    _vnAudio.play().catch(function() {});
    triggerHaptic(10);
}

function playVoiceMessage(audioUrl) {
    const audio = new Audio(audioUrl);
    audio.play().catch(e => console.error('[AudioPlay]', e));
    triggerHaptic(10);
}

// --- PARENTAL HUB ---
function renderParentRequests() {
    const container = document.getElementById('parent-requests');
    if (!container) return;
    container.innerHTML = '';
    const pending = parentRequests.filter(r => r.status === 'pending');
    if (pending.length === 0) {
        container.innerHTML = '<div style="text-align:center; color:#888; padding:20px;">No pending requests ✅</div>';
        return;
    }
    pending.forEach(req => {
        const div = document.createElement('div');
        div.className = 'request-card';
        div.innerHTML = `
            <div class="req-header"><span>${escapeHtml(req.action)} Request</span><span style="color:#FF9500;">Pending</span></div>
            <p><b>${escapeHtml(req.kid)}:</b> ${escapeHtml(req.content)}</p>
            <div class="req-actions">
                <button class="btn-reject" onclick="resolveRequest(${req.id}, 'rejected')">Reject</button>
                <button class="btn-approve" onclick="resolveRequest(${req.id}, 'approved')">Approve</button>
            </div>
        `;
        container.appendChild(div);
    });
}

function resolveRequest(id, status) {
    const req = parentRequests.find(r => r.id === id);
    if (req) {
        req.status = status;
        alert(`Request ${status}!`);
        renderParentRequests();
    }
}


// --- COMPOSER ---
async function createPostFromComposer() {
    if (!canPerformAction('create a post')) return;

    var textarea = document.getElementById('composer-text');
    var postText = textarea.value.trim();

    if (!postText && !window._composerMediaUrl) {
        showToast('Write something or add a photo/video first.');
        return;
    }
    if (isAIGenerated(postText)) {
        showToast('AI-generated content about real people is not allowed.');
        return;
    }
    if (containsBannedWords(postText)) {
        showToast('Your post contains content that violates our guidelines.');
        return;
    }

    var postBtn = document.getElementById('composer-post-btn');
    if (postBtn) {
        postBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Posting...';
        postBtn.disabled = true;
    }

    try {
        var mediaUrl = window._composerMediaUrl || null;
        var mediaType = window._composerMediaType || null;

        var post = await RealData.createPost(postText, mediaUrl, mediaType);

        if (post) {
            // Clear composer state
            textarea.value = '';
            window._composerMediaUrl = null;
            window._composerMediaType = null;
            var preview = document.getElementById('composer-media-preview');
            if (preview) preview.innerHTML = '';

            closePage('composer-overlay');
            triggerHaptic(50);

            // Prepend new post to top of feed instantly
            var feed = document.getElementById('feed-panels');
            if (feed && typeof renderRealPostCard === 'function') {
                var newCard = renderRealPostCard(post);
                newCard.style.animation = 'popIn 0.4s ease';
                feed.insertBefore(newCard, feed.firstChild);
            }
        }
    } finally {
        if (postBtn) {
            postBtn.textContent = 'Post';
            postBtn.style.opacity = '0.5';
            postBtn.style.pointerEvents = 'none';
            postBtn.disabled = false;
        }
    }
}

function updateComposerState() {
    var textarea = document.getElementById('composer-text');
    var btn = document.getElementById('composer-post-btn');
    var counter = document.getElementById('composer-char-count');
    if (!textarea || !btn) return;

    var len = textarea.value.trim().length;
    var max = 500;

    if (counter) counter.textContent = len + '/' + max;

    var hasMedia = !!window._composerImageData;
    if ((len > 0 && len <= max) || hasMedia) {
        btn.style.opacity = '1';
        btn.style.pointerEvents = 'all';
    } else {
        btn.style.opacity = '0.5';
        btn.style.pointerEvents = 'none';
    }

    if (len > max && counter) {
        counter.style.color = '#FF3B30';
    } else if (counter) {
        counter.style.color = '#ccc';
    }
}

