var thoughtSelectedMusic = (function() {
    try { var s = localStorage.getItem('tf_thought_music'); return s ? JSON.parse(s) : null; } catch(e) { return null; }
})();

function onThoughtInput(textarea) {
    var len = textarea ? textarea.value.length : 0;
    var counter = document.getElementById('thoughtCharCount');
    var shareBtn = document.getElementById('thoughtShareBtn');
    if (counter) { counter.textContent = len + '/60'; counter.style.color = len > 50 ? '#FF3B30' : '#ccc'; }
    var hasContent = len > 0 || !!thoughtSelectedMusic;
    if (shareBtn) {
        shareBtn.disabled = !hasContent;
        shareBtn.style.opacity = hasContent ? '1' : '0.35';
        shareBtn.style.boxShadow = hasContent ? '0 4px 16px rgba(0,122,255,0.35)' : 'none';
        shareBtn.style.pointerEvents = hasContent ? 'all' : 'none';
    }
}

function insertThoughtEmoji(emoji) {
    var input = document.getElementById('thoughtInput');
    if (!input) return;
    var pos = input.selectionStart;
    input.value = input.value.slice(0, pos) + emoji + input.value.slice(pos);
    input.dispatchEvent(new Event('input'));
    input.focus();
    triggerHaptic(10);
}

