    // ==========================================================================
// AI AUTO-MODERATOR
// ==========================================================================
const BANNED_SEARCH_TERMS = [
    'sex', 'porn', 'xxx', 'nude', 'naked', 'drugs', 'cocaine', 'meth',
    'suicide', 'kill myself', 'self harm', 'cutting', 'anorexia',
    'child abuse', 'terrorism', 'bomb', 'weapon', 'gun sale'
];

const SLUR_WORDS = [
    'n word placeholder', 'f word placeholder', 'retard'
    // In production these would be comprehensive lists
];

const ADULT_KEYWORDS = [
    'nsfw', '18+', 'adult content', 'explicit', 'sexual',
    'gore', 'graphic violence', 'self-harm', 'suicide'
];

function moderateContent(text) {
    if (!text) return { safe: true, text: text };
    const lower = text.toLowerCase();

    // Check for adult/illegal content - BLOCK entirely
    for (const keyword of ADULT_KEYWORDS) {
        if (lower.includes(keyword)) {
            return { safe: false, blocked: true, reason: 'Adult/Explicit content detected', text: text };
        }
    }

    // Check for slurs - BLUR with warning
    for (const slur of SLUR_WORDS) {
        if (lower.includes(slur)) {
            return { safe: false, blurred: true, reason: 'Potentially harmful language', text: text };
        }
    }

    // Check banned words
    if (containsBannedWords(text)) {
        return { safe: false, blocked: true, reason: 'Content violates community guidelines', text: text };
    }

    return { safe: true, text: text };
}

function moderateSearchInput(text) {
    if (!text) return true;
    const lower = text.toLowerCase().trim();
    for (const term of BANNED_SEARCH_TERMS) {
        if (lower.includes(term)) {
            return false;
        }
    }
    return true;
}

// Override the search function to include moderation
const _originalSearch = simulateRealtimeSearch;
simulateRealtimeSearch = function() {
    const searchBox = document.getElementById('s-input');
    const term = searchBox.value.trim();

    if (!moderateSearchInput(term)) {
        const discoveryPage = document.getElementById('discovery-page');
        discoveryPage.innerHTML = `
            <div class="header-container"><div class="liquid-glass-btn" onclick="resetNav()"><i class="fa-solid fa-chevron-left"></i></div><b>Search</b><div></div></div>
            <div style="padding:60px 30px; text-align:center;">
                <i class="fa-solid fa-shield-halved" style="font-size:50px; color:#FF3B30; margin-bottom:15px;"></i>
                <h3 style="margin-bottom:10px;">Search Blocked</h3>
                <p style="color:#888; font-size:14px;">This search term violates our Safe Space guidelines. TrustFirst is committed to keeping our community safe.</p>
            </div>`;
        return;
    }
    _originalSearch();
};

