async function renderComments() {
    var list = document.getElementById('comment-list');
    if (!list) return;
    list.innerHTML = '<p style="text-align:center;color:#aaa;padding:20px;">Loading comments…</p>';
    var comments = [];
    if (window.sb && currentCommentPostId && !String(currentCommentPostId).startsWith('local_')) {
        var { data } = await sb.from('comments')
            .select('id, text, created_at, user_id, users(full_name, avatar_url)')
            .eq('post_id', currentCommentPostId)
            .eq('is_hidden', false)
            .order('created_at', { ascending: true });
        comments = data || [];
    }
    list.innerHTML = '';
    if (!comments.length) {
        list.innerHTML = '<p style="text-align:center;color:#aaa;padding:20px;">No comments yet. Be the first!</p>';
        return;
    }
    comments.forEach(function(c) {
        var item = document.createElement('div');
        item.className = 'comment-item';
        item.style.cssText = 'align-items:flex-start;';

        var avatar = document.createElement('img');
        avatar.src = c.avatar_url || 'https://ui-avatars.com/api/?name=' + encodeURIComponent(c.user || 'U') + '&background=random&color=fff&bold=true&size=80';
        avatar.className = 'comment-avatar';
        avatar.style.alignSelf = 'flex-start';

        var bubble = document.createElement('div');
        bubble.className = 'comment-bubble';
        bubble.style.flex = '1';

        var nameRow = document.createElement('div');
        nameRow.style.cssText = 'display:flex;align-items:center;gap:5px;margin-bottom:3px;';

        var nameEl = document.createElement('b');
        nameEl.textContent = c.user;
        nameEl.style.cssText = 'font-size:13px;color:var(--text-primary,#000);';

        var badge = document.createElement('i');
        badge.className = 'fa-solid fa-circle-check ' + c.tier;
        badge.style.fontSize = '9px';

        var timeEl = document.createElement('small');
        timeEl.textContent = c.time;
        timeEl.style.cssText = 'color:#aaa;font-size:11px;margin-left:4px;';

        nameRow.appendChild(nameEl);
        nameRow.appendChild(badge);
        nameRow.appendChild(timeEl);

        var textEl = document.createElement('p');
        textEl.textContent = c.text;
        textEl.style.cssText = 'font-size:14px;line-height:1.4;margin:0 0 6px;';

        var actionsRow = document.createElement('div');
        actionsRow.style.cssText = 'display:flex;align-items:center;gap:14px;';

        var likeDiv = document.createElement('div');
        likeDiv.style.cssText = 'display:flex;align-items:center;gap:4px;cursor:pointer;';
        likeDiv.addEventListener('click', function() { toggleCommentLike(likeDiv); });

        var heartIcon = document.createElement('i');
        heartIcon.className = 'fa-regular fa-heart';
        heartIcon.style.cssText = 'font-size:13px;color:#888;transition:0.2s;';

        var likeCount = document.createElement('span');
        likeCount.textContent = c.likes;
        likeCount.style.cssText = 'font-size:11px;color:#888;';

        likeDiv.appendChild(heartIcon);
        likeDiv.appendChild(likeCount);

        var replySpan = document.createElement('span');
        replySpan.textContent = 'Reply';
        replySpan.style.cssText = 'font-size:12px;color:#888;cursor:pointer;font-weight:600;';
        replySpan.addEventListener('click', function() { openCommentReply(c.user); });

        actionsRow.appendChild(likeDiv);
        actionsRow.appendChild(replySpan);

        bubble.appendChild(nameRow);
        bubble.appendChild(textEl);
        bubble.appendChild(actionsRow);

        item.appendChild(avatar);
        item.appendChild(bubble);
        list.appendChild(item);
    });
}

