function toggleCommentGifs() {
    const panel = document.getElementById('gif-panel');
    if (panel.style.display === 'block') {
        panel.style.display = 'none';
        return;
    }
    panel.style.display = 'block';
    const grid = document.getElementById('gif-grid');
    grid.innerHTML = '<div style="text-align:center;padding:20px;color:#aaa;"><i class="fa-solid fa-spinner fa-spin"></i></div>';

    async function loadGifSearch(query) {
        try {
            const res = await fetch(`/api/giphy/search/?q=${encodeURIComponent(query)}`);
            const json = await res.json();
            // Remove only images, keep the search input
            Array.from(grid.children).forEach(function(child) {
                if (child.tagName !== 'INPUT') child.remove();
            });
            if (!json.data || !json.data.length) {
                grid.innerHTML = '<div style="text-align:center;padding:20px;color:#aaa;font-size:13px;">No results</div>';
                return;
            }
            json.data.forEach(function(gif) {
                const img = document.createElement('img');
                img.src = gif.images.fixed_height_small.url;
                img.style.cssText = 'width:100%;border-radius:8px;cursor:pointer;';
                img.onclick = function() { postGifComment(gif.images.original.url); };
                grid.appendChild(img);
            });
        } catch(e) {
            grid.innerHTML = '<div style="text-align:center;padding:20px;color:#aaa;font-size:13px;">Could not load stickers</div>';
        }
    }

    // Add search box
    grid.innerHTML = '<input id="gif-search-input" placeholder="Search stickers..." style="width:100%;padding:8px 12px;border-radius:20px;border:1px solid var(--border-color,#eee);font-size:13px;margin-bottom:8px;box-sizing:border-box;" oninput="clearTimeout(window._gifTimer);window._gifTimer=setTimeout(function(){loadGifSearch(document.getElementById(\'gif-search-input\').value||\'happy\')},400)">';
    window.loadGifSearch = loadGifSearch;
    loadGifSearch('happy'); // default stickers on open
}


async function postGifComment(src) {
    var list = document.getElementById('comment-list');
    var name = currentUser ? currentUser.name : 'You';
    var tier = currentUser ? currentUser.tier : 'verify-blue';
    var avatar = currentUser?.avatar_url || ('https://ui-avatars.com/api/?name=' + encodeURIComponent(name||'U') + '&background=007AFF&color=fff&size=80');
    var newComment = document.createElement('div');
    newComment.className = 'comment-item';
    newComment.style.alignItems = 'flex-start';
    newComment.innerHTML = `
        <img src="${escapeHtml(avatar)}" class="comment-avatar" style="align-self:flex-start;">
        <div class="comment-bubble" style="flex:1;">
            <div style="display:flex;align-items:center;gap:5px;margin-bottom:6px;">
                <b style="font-size:13px;color:var(--text-primary,#000);">${escapeHtml(name)}</b>
                <i class="fa-solid fa-circle-check ${tier}" style="font-size:9px;"></i>
                <small style="color:#aaa;font-size:11px;margin-left:4px;">now</small>
            </div>
            <img src="${escapeHtml(src)}" style="width:150px;border-radius:12px;display:block;">
            <div style="display:flex;align-items:center;gap:14px;margin-top:6px;">
                <div onclick="toggleCommentLike(this)" style="display:flex;align-items:center;gap:4px;cursor:pointer;">
                    <i class="fa-regular fa-heart" style="font-size:13px;color:#888;"></i>
                    <span style="font-size:11px;color:#888;">0</span>
                </div>
                <span onclick="openCommentReply('${escapeHtml(name)}')" style="font-size:12px;color:#888;cursor:pointer;font-weight:600;">Reply</span>
            </div>
        </div>`;
    list.insertBefore(newComment, list.firstChild);
    document.getElementById('gif-panel').style.display = 'none';
    triggerHaptic(15);

    // Save GIF comment to DB and update count
    if (window.sb && currentUser && currentCommentPostId) {
        try {
            await sb.from('comments').insert({
                user_id: currentUser.id,
                post_id: currentCommentPostId,
                text_content: '',
                gif_url: src
            });
            // Update comment count on the post card
            var postCard = document.querySelector('[data-post-id="' + currentCommentPostId + '"]');
            if (postCard) {
                postCard.querySelectorAll('button, div').forEach(function(btn) {
                    if (btn.querySelector('.fa-comment, .fa-comment-dots')) {
                        var span = btn.querySelector('span');
                        if (span) span.textContent = (parseInt(span.textContent) || 0) + 1;
                    }
                });
            }
        } catch(e) { console.warn('[GIF Comment]', e); }
    }
}

