const channelsData = [
    { name: 'TrustFirst Official', desc: 'Platform updates & news', icon: 'fa-bullhorn', color: '#007AFF', members: '12.5K', unread: 3 },
    { name: 'SA Tech Hub', desc: 'South African tech community', icon: 'fa-microchip', color: '#34C759', members: '8.2K', unread: 0 },
    { name: 'Creator Studio', desc: 'Tips for content creators', icon: 'fa-wand-magic-sparkles', color: '#FF9500', members: '5.1K', unread: 1 },
    { name: 'Safety Updates', desc: 'Community safety alerts', icon: 'fa-shield-halved', color: '#FF3B30', members: '22K', unread: 0 },
    { name: 'Music SA', desc: 'South African music scene', icon: 'fa-music', color: '#AF52DE', members: '15K', unread: 7 },
];

function openChannels() {
    openPage('channels-overlay');
    renderChannels();
}

function renderChannels() {
    // Delegate to the real async Supabase renderer in setMsgTab
    var tab = Array.from(document.querySelectorAll('.m-tab')).find(function(t){
        return t.textContent.trim().toLowerCase().includes('channel');
    });
    setMsgTab('channels', tab || null);
}

function setMsgTab(tabName, element) {
    document.querySelectorAll('.m-tab').forEach(function(tab) { tab.classList.remove('active'); });
    if (element) element.classList.add('active');
    var content = document.getElementById('chat-list-content');
    if (!content) return;

    if (tabName === 'primary') {
        fillMsgContent();

    } else if (tabName === 'requests') {
        content.innerHTML = '<div style="text-align:center;padding:30px 0;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;font-size:20px;"></i></div>';
        (async function() {
            if (!window.sb || !currentUser) {
                content.innerHTML = '<div style="text-align:center;padding:60px 20px;color:#888;"><i class="fa-regular fa-envelope-open" style="font-size:40px;color:#ccc;display:block;margin-bottom:15px;"></i><b style="color:var(--text-primary,#333);display:block;margin-bottom:8px;">Message Requests</b><p style="font-size:13px;">Sign in to see requests</p></div>';
                return;
            }
            try {
                var { data: follows } = await window.sb.from('follows').select('follower_id').eq('following_id', currentUser.id);
                var followerIds = (follows||[]).map(function(f){ return f.follower_id; });
                var { data: myReqParts } = await window.sb.from('conversation_participants')
                    .select('conversation_id').eq('user_id', currentUser.id).eq('is_blocked', false);
                var myReqConvIds = (myReqParts || []).map(function(p){ return p.conversation_id; });
                var rawReqConvos = [], reqErr = null;
                if (myReqConvIds.length) {
                    var rr = await window.sb.from('conversations').select('id,updated_at')
                        .in('id', myReqConvIds).order('updated_at',{ascending:false}).limit(30);
                    rawReqConvos = rr.data || []; reqErr = rr.error;
                }
                if (reqErr) throw reqErr;

                // Hydrate other participant for each convo
                var reqConvIds = rawReqConvos.map(function(c){ return c.id; });
                var reqOtherIdByConv = {};
                if (reqConvIds.length) {
                    var { data: rOtherP } = await window.sb.from('conversation_participants')
                        .select('conversation_id, user_id').in('conversation_id', reqConvIds).neq('user_id', currentUser.id);
                    (rOtherP || []).forEach(function(p){ reqOtherIdByConv[p.conversation_id] = p.user_id; });
                }
                var reqUserMap = {};
                if (rawReqConvos && rawReqConvos.length) {
                    var rIds = rawReqConvos.map(function(c){ return reqOtherIdByConv[c.id]; }).filter(Boolean);
                    var uRIds = rIds.filter(function(id,i){ return rIds.indexOf(id)===i; });
                    if (uRIds.length) {
                        var { data: rURows } = await window.sb.from('users').select('id,full_name,username,avatar_url,badge_tier,verified').in('id', uRIds);
                        (rURows||[]).forEach(function(u){ reqUserMap[u.id]=u; });
                    }
                }
                var convos = (rawReqConvos||[]).map(function(c){
                    var oid = c.participant1_id === currentUser.id ? c.participant2_id : c.participant1_id;
                    c._other = reqUserMap[reqOtherIdByConv[c.id]] || {}; return c;
                });
                var requests = (convos||[]).filter(function(c) {
                    var other = c.participant1_id === currentUser.id ? (c.users2||{}) : (c.users1||{});
                    return other.id && !followerIds.includes(other.id) && other.id !== currentUser.id;
                });
                if (!requests.length) {
                    content.innerHTML = '<div style="text-align:center;padding:60px 20px;color:#888;"><i class="fa-regular fa-envelope-open" style="font-size:40px;color:#ccc;display:block;margin-bottom:15px;"></i><b style="color:var(--text-primary,#333);display:block;margin-bottom:8px;">No requests yet</b><p style="font-size:13px;">People you don\'t follow will appear here</p></div>';
                    return;
                }
                var html = '';
                requests.forEach(function(c) {
                    var other = c._other || {};
                    var name = other.full_name || other.username || 'Unknown';
                    var avatar = other.avatar_url || '';
                    var avHtml = avatar
                        ? '<img src="'+escapeHtml(avatar)+'" style="width:50px;height:50px;border-radius:50%;object-fit:cover;" onerror="this.style.display=\'none\';this.nextSibling.style.display=\'flex\'">'
                          + '<div style="display:none;width:50px;height:50px;border-radius:50%;background:#007AFF;align-items:center;justify-content:center;color:white;font-size:18px;font-weight:700;">'+escapeHtml(name.charAt(0).toUpperCase())+'</div>'
                        : '<div style="width:50px;height:50px;border-radius:50%;background:#007AFF;display:flex;align-items:center;justify-content:center;color:white;font-size:18px;font-weight:700;">'+escapeHtml(name.charAt(0).toUpperCase())+'</div>';
                    html += '<div class="msg-row" data-uid="'+escapeHtml(other.id||'')+'" data-cid="'+escapeHtml(c.id||'')+'" data-name="'+escapeHtml(name||'User')+'" onclick="_openMsgRow(this)" style="position:relative;">'
                        + '<div style="position:relative;flex-shrink:0;">'+avHtml+'</div>'
                        + '<div style="flex:1;padding-left:4px;min-width:0;"><b>'+escapeHtml(name)+'</b>'
                        + '<small style="color:#888;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">Sent you a message</small></div>'
                        + '<small style="color:#007AFF;font-size:11px;font-weight:700;flex-shrink:0;align-self:center;margin-left:8px;">Request</small>'
                        + '</div>';
                });
                content.innerHTML = html;
            } catch(e) {
                console.error('[requests tab]', e);
                content.innerHTML = '<div style="text-align:center;padding:40px 20px;color:#888;">Could not load requests</div>';
            }
        })();

    } else if (tabName === 'channels') {
        content.innerHTML = '<div style="text-align:center;padding:40px 0;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;font-size:20px;"></i></div>';
        (async function() {
            var html = '<div style="padding:10px 20px 4px;font-size:11px;font-weight:800;color:#888;text-transform:uppercase;letter-spacing:0.06em;">Channels</div>';
            if (window.sb) {
                var localChs = JSON.parse(localStorage.getItem('tf-local-channels') || '[]');
                var channels = localChs;
                try {
                    var followedIds = [];
                        if (currentUser) {
                            var { data: myFollows } = await sb.from('channel_followers').select('channel_id').eq('user_id', currentUser.id);
                            followedIds = (myFollows || []).map(function(f){ return f.channel_id; });
                        }
                        var chQuery = sb.from('channels').select('id, name, emoji, color, verified, follower_count, owner_id').order('follower_count', { ascending: false }).limit(30);
                        if (currentUser && followedIds.length) {
                            chQuery = sb.from('channels').select('id, name, emoji, color, verified, follower_count, owner_id').in('id', followedIds).order('follower_count', { ascending: false });
                        }
                        var { data: remoteChs, error: chErr } = await chQuery;
                    if (!chErr && remoteChs) {
                        // Merge: remote first, then any local-only ones not in remote
                        var remoteIds = remoteChs.map(function(c){ return c.id; });
                        var localOnly = localChs.filter(function(c){ return !remoteIds.includes(c.id); });
                        channels = remoteChs.concat(localOnly);
                    }
                    (channels || []).forEach(function(ch) {
                        var bgColor = ch.color || '#007AFF';
                        var emoji = ch.emoji || '📢';
                        var followers = ch.follower_count ? (ch.follower_count >= 1000 ? (ch.follower_count / 1000).toFixed(1) + 'K' : ch.follower_count) : '0';
                        html += '<div onclick="openChannelBroadcast(\'' + escapeHtml(ch.id) + '\')" style="display:flex;align-items:center;gap:12px;padding:14px 20px;border-bottom:1px solid var(--border-color,#f5f5f5);cursor:pointer;" onmouseover="this.style.background=\'var(--hover-bg,rgba(0,122,255,0.03))\'" onmouseout="this.style.background=\'\'">' +
                            '<div style="width:52px;height:52px;border-radius:16px;background:' + escapeHtml(bgColor) + ';display:flex;align-items:center;justify-content:center;color:white;font-size:24px;flex-shrink:0;">' + emoji + '</div>' +
                            '<div style="flex:1;min-width:0;">' +
                                '<b style="font-size:15px;color:var(--text-primary,#000);display:block;">' + escapeHtml(ch.name) +
                                (ch.verified ? ' <i class="fa-solid fa-circle-check verify-blue" style="font-size:10px;"></i>' : '') + '</b>' +
                                '<small style="color:var(--text-secondary,#888);font-size:12px;">' + followers + ' followers</small>' +
                            '</div>' +
                            '<i class="fa-solid fa-chevron-right" style="color:#ccc;flex-shrink:0;"></i>' +
                        '</div>';
                    });
                    if (!channels || channels.length === 0) {
                        html += '<div style="text-align:center;padding:40px 20px;color:#888;">'
                            + '<i class="fa-solid fa-tower-broadcast" style="font-size:36px;color:#ccc;display:block;margin-bottom:12px;"></i>'
                            + '<b style="color:var(--text-primary,#333);display:block;margin-bottom:8px;">No channels yet</b>'
                            + '<p style="font-size:13px;margin-bottom:16px;">Create your first channel or discover some</p>'
                            + '<button onclick="openCreateChannelModal()" style="padding:12px 24px;border-radius:20px;border:none;background:#007AFF;color:white;font-size:14px;font-weight:700;cursor:pointer;"><i class="fa-solid fa-plus"></i> Create Channel</button>'
                            + '</div>';
                    }
                } catch(e) {
                    // Use local-only if remote failed
                }
            } else {
                html += '<div style="text-align:center;padding:40px 20px;color:#888;font-size:13px;">Not connected</div>';
            }
            content.innerHTML = html;
        })();
    }
}

