// ==========================================================================
// DATABASE LAYER — IndexedDB (Local) + Supabase-Ready (Remote)
// ==========================================================================

const DB_NAME = 'TrustFirstDB';
const DB_VERSION = 3;
let db = null;

function openDatabase() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;

      // Users store
      if (!db.objectStoreNames.contains('users')) {
        const userStore = db.createObjectStore('users', { keyPath: 'id', autoIncrement: true });
        userStore.createIndex('handle', 'handle', { unique: true });
        userStore.createIndex('email', 'email', { unique: true });
        userStore.createIndex('type', 'type', { unique: false });
      }

      // Posts store
      if (!db.objectStoreNames.contains('posts')) {
        const postStore = db.createObjectStore('posts', { keyPath: 'id', autoIncrement: true });
        postStore.createIndex('userId', 'userId', { unique: false });
        postStore.createIndex('createdAt', 'createdAt', { unique: false });
        postStore.createIndex('type', 'type', { unique: false });
      }

      // Messages store
      if (!db.objectStoreNames.contains('messages')) {
        const msgStore = db.createObjectStore('messages', { keyPath: 'id', autoIncrement: true });
        msgStore.createIndex('conversationId', 'conversationId', { unique: false });
        msgStore.createIndex('senderId', 'senderId', { unique: false });
        msgStore.createIndex('timestamp', 'timestamp', { unique: false });
      }

      // Conversations store
      if (!db.objectStoreNames.contains('conversations')) {
        const convStore = db.createObjectStore('conversations', { keyPath: 'id', autoIncrement: true });
        convStore.createIndex('participants', 'participants', { unique: false, multiEntry: true });
        convStore.createIndex('lastActivity', 'lastActivity', { unique: false });
      }

      // Notifications store
      if (!db.objectStoreNames.contains('notifications')) {
        const notifStore = db.createObjectStore('notifications', { keyPath: 'id', autoIncrement: true });
        notifStore.createIndex('userId', 'userId', { unique: false });
        notifStore.createIndex('read', 'read', { unique: false });
        notifStore.createIndex('createdAt', 'createdAt', { unique: false });
      }

      // Activity/History store
      if (!db.objectStoreNames.contains('activity')) {
        const actStore = db.createObjectStore('activity', { keyPath: 'id', autoIncrement: true });
        actStore.createIndex('userId', 'userId', { unique: false });
        actStore.createIndex('type', 'type', { unique: false });
        actStore.createIndex('date', 'date', { unique: false });
      }

      // Offline queue — for background sync
      if (!db.objectStoreNames.contains('syncQueue')) {
        const syncStore = db.createObjectStore('syncQueue', { keyPath: 'id', autoIncrement: true });
        syncStore.createIndex('type', 'type', { unique: false });
        syncStore.createIndex('status', 'status', { unique: false });
      }

      // Media cache metadata
      if (!db.objectStoreNames.contains('mediaCache')) {
        const mediaStore = db.createObjectStore('mediaCache', { keyPath: 'id' });
        mediaStore.createIndex('type', 'type', { unique: false });
        mediaStore.createIndex('size', 'size', { unique: false });
      }
    };

    request.onsuccess = (event) => {
      db = event.target.result;
      console.debug('[DB] IndexedDB opened successfully');
      resolve(db);
    };

    request.onerror = (event) => {
      console.error('[DB] IndexedDB error:', event.target.error);
      reject(event.target.error);
    };
  });
}

// Generic CRUD operations
var DB = {
  async add(storeName, data) {
    const database = db || await openDatabase();
    return new Promise((resolve, reject) => {
      const tx = database.transaction(storeName, 'readwrite');
      const store = tx.objectStore(storeName);
      data.createdAt = data.createdAt || Date.now();
      data.updatedAt = Date.now();
      const request = store.add(data);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  },

  async get(storeName, id) {
    const database = db || await openDatabase();
    return new Promise((resolve, reject) => {
      const tx = database.transaction(storeName, 'readonly');
      const store = tx.objectStore(storeName);
      const request = store.get(id);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  },

  async getAll(storeName, indexName, query, count) {
    const database = db || await openDatabase();
    return new Promise((resolve, reject) => {
      const tx = database.transaction(storeName, 'readonly');
      const store = tx.objectStore(storeName);
      const source = indexName ? store.index(indexName) : store;
      const request = query ? source.getAll(query, count) : source.getAll(null, count);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  },

  async update(storeName, data) {
    const database = db || await openDatabase();
    return new Promise((resolve, reject) => {
      const tx = database.transaction(storeName, 'readwrite');
      const store = tx.objectStore(storeName);
      data.updatedAt = Date.now();
      const request = store.put(data);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  },

  async delete(storeName, id) {
    const database = db || await openDatabase();
    return new Promise((resolve, reject) => {
      const tx = database.transaction(storeName, 'readwrite');
      const store = tx.objectStore(storeName);
      const request = store.delete(id);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  },

  async clear(storeName) {
    const database = db || await openDatabase();
    return new Promise((resolve, reject) => {
      const tx = database.transaction(storeName, 'readwrite');
      const store = tx.objectStore(storeName);
      const request = store.clear();
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  },

  async count(storeName) {
    const database = db || await openDatabase();
    return new Promise((resolve, reject) => {
      const tx = database.transaction(storeName, 'readonly');
      const store = tx.objectStore(storeName);
      const request = store.count();
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  },

  // Query by index with cursor for complex queries
  async query(storeName, indexName, range, direction = 'next') {
    const database = db || await openDatabase();
    return new Promise((resolve, reject) => {
      const tx = database.transaction(storeName, 'readonly');
      const store = tx.objectStore(storeName);
      const index = store.index(indexName);
      const results = [];
      const request = index.openCursor(range, direction);
      request.onsuccess = (event) => {
        const cursor = event.target.result;
        if (cursor) {
          results.push(cursor.value);
          cursor.continue();
        } else {
          resolve(results);
        }
      };
      request.onerror = () => reject(request.error);
    });
  },

  // Queue action for background sync
  async queueSync(type, data) {
    await this.add('syncQueue', {
      type: type,
      data: data,
      status: 'pending',
      retries: 0,
      createdAt: Date.now()
    });
    // Trigger background sync if available
    queueForSync('sync-' + type);
  }
};

