// Keys are loaded from the Django backend — do NOT hardcode here
let SUPABASE_URL = '';
let SUPABASE_ANON_KEY = '';
let STRIPE_PUBLISHABLE_KEY = '';
let GIPHY_KEY_FROM_SERVER = '';
var sb = null; // alias for window._sb — assigned in initSupabase()

(async function loadConfig() {
    try {
        const res = await fetch('/api/config/');
        if (!res.ok) throw new Error('Config fetch failed: ' + res.status);
        const cfg = await res.json();
        SUPABASE_URL = cfg.supabase_url || '';
        SUPABASE_ANON_KEY = cfg.supabase_anon_key || '';
        STRIPE_PUBLISHABLE_KEY = cfg.stripe_publishable_key || '';
        GIPHY_KEY_FROM_SERVER = cfg.giphy_api_key || '';
        initSupabase();
    } catch(e) {
        console.error('[Config] Failed to load config from server:', e);
        showToast('Could not connect to server. Please refresh.');
    }
})();

var GeoIP = {
    lookup: async function() {
        try {
            var r = await fetch('https://ipapi.co/json/');
            var d = await r.json();
            return {
                ip: d.ip || 'unknown',
                city: d.city || 'Unknown',
                country: d.country_name || 'Unknown'
            };
        } catch(e) {
            return { ip: null, city: 'Unknown', country: 'Unknown' };
        }
    }
};

function initSupabase() {
    // Supabase JS is loaded via CDN in the <head>; keys come from /api/config/
    // This function is called after loadConfig() resolves
    if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
        console.error('[TrustFirst] Supabase keys missing — check /api/config/');
        showToast('Connection error. Please refresh.');
        return;
    }
    try {
        window._sb = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
        window.sb = window._sb;
        sb = window._sb;
        initRealtimeSubscriptions();
        if (currentUser === null) {
            restoreSession().then(function(restored) {
                if (restored) {
                    dismissSplash();
                    var htmlSplash = document.getElementById('splash');
                    if (htmlSplash) htmlSplash.remove();
                    launchApp();
                }
            }).catch(function(e) {
                console.error('[Session] Late restore failed:', e);
            });
        }
    } catch(e) {
        console.error('[Supabase] Init failed:', e);
        showToast('Connection error. Please refresh.');
    }
}  // end initSupabase()

// Wrapper for safe Supabase calls
// Wait for Supabase to be ready before any DB call
function waitForSb() {
    if (window.sb) return Promise.resolve();
    return new Promise(function(resolve) {
        var check = setInterval(function() {
            if (window.sb) { clearInterval(check); resolve(); }
        }, 100);
        // Safety timeout after 10 seconds
        setTimeout(function() { clearInterval(check); resolve(); }, 10000);
    });
}
