// ==========================================================================
// REALTIME SUBSCRIPTIONS
// ==========================================================================
function initRealtimeSubscriptions() {
    if (!window.sb) return;

    // Listen for new messages in real-time
    sb.channel('messages')
        .on('postgres_changes', {
            event: 'INSERT',
            schema: 'public',
            table: 'messages'
        }, (payload) => {
            handleNewMessage(payload.new);
        })
        .subscribe();

    // Listen for screenshot events
    sb.channel('screenshots')
        .on('postgres_changes', {
            event: 'INSERT',
            schema: 'public',
            table: 'screenshot_events'
        }, (payload) => {
            handleScreenshotNotification(payload.new);
        })
        .subscribe();

    // Listen for profile views
    sb.channel('profile_views')
        .on('postgres_changes', {
            event: 'INSERT',
            schema: 'public',
            table: 'profile_views'
        }, (payload) => {
            handleProfileViewNotification(payload.new);
        })
        .subscribe();

    console.debug('[Realtime] Subscriptions active');
}

function handleNewMessage(message) {
    // Decrypt and display in UI if chat is open
    if (currentChatUser && document.getElementById('chat-interface').style.display === 'block') {
        // Decrypt using E2E module then append to chat
        E2E.decryptMessage(message.ciphertext, message.nonce, message.sender_id)
            .then(plaintext => {
                appendMessageToChat(plaintext, message.message_type, false, message);
            })
            .catch(err => console.error('[E2E] Decrypt failed:', err));
    }
}

async function handleScreenshotNotification(event) {
    try {
        const { data: { session } } = await sb.auth.getSession();
        if (!session || event.user_id === session.user.id) return;

        const toast = document.createElement('div');
        toast.className = 'screenshot-toast';
        toast.innerHTML = `<i class="fa-solid fa-camera"></i> Someone took a ${event.event_type === 'screenshot' ? 'screenshot' : 'screen recording'}!`;
        document.getElementById('app').appendChild(toast);
        triggerHaptic(50);
        setTimeout(() => toast.remove(), 4000);
    } catch (e) {
        console.error('[Screenshot]', e);
    }
}

function handleProfileViewNotification(view) {
    // Could show a subtle notification
    console.debug('[ProfileView] Someone viewed your profile');
}

// ==========================================================================
// HYBRID DATA LAYER — Uses local DB + syncs to Supabase when available
// ==========================================================================
const DataLayer = {
  async savePost(postData) {
    // Always save locally first
    const localId = await DB.add('posts', postData);

    // Try to sync to server
    if (SUPABASE_CONFIG.enabled && navigator.onLine) {
      const remote = await SupabaseAPI.createPost(postData);
      if (remote) {
        postData.remoteId = remote.id;
        postData.synced = true;
        await DB.update('posts', { ...postData, id: localId });
      }
    } else {
      // Queue for background sync
      await DB.queueSync('posts', { ...postData, localId });
    }

    return localId;
  },

  async getPosts(page = 1, limit = 10) {
    // Try server first if online
    if (SUPABASE_CONFIG.enabled && navigator.onLine) {
      const remote = await SupabaseAPI.fetchPosts(page, limit);
      if (remote && remote.length > 0) {
        // Cache locally
        for (const post of remote) {
          try { await DB.add('posts', { ...post, synced: true }); } catch (e) { /* exists */ }
        }
        return remote;
      }
    }

    // Fall back to local
    return DB.getAll('posts', 'createdAt', null, limit);
  },

  async saveMessage(messageData) {
    const localId = await DB.add('messages', messageData);

    if (SUPABASE_CONFIG.enabled && navigator.onLine) {
      const remote = await SupabaseAPI.sendMessage(messageData);
      if (remote) {
        messageData.remoteId = remote.id;
        messageData.synced = true;
        await DB.update('messages', { ...messageData, id: localId });
      }
    } else {
      await DB.queueSync('messages', { ...messageData, localId });
    }

    return localId;
  },

  async getMessages(conversationId) {
    if (SUPABASE_CONFIG.enabled && navigator.onLine) {
      const remote = await SupabaseAPI.fetchMessages(conversationId);
      if (remote) return remote;
    }
    return DB.query('messages', 'conversationId', IDBKeyRange.only(conversationId));
  },

  async saveActivity(type, data) {
    return DB.add('activity', {
      userId: currentUser?.handle,
      type: type,
      data: data,
      date: new Date().toISOString().split('T')[0]
    });
  },

  async getActivity(type) {
    return DB.query('activity', 'type', IDBKeyRange.only(type));
  }
};

