// LEGAL PAGE FUNCTIONS
// ==========================================================================
async function downloadMyData() {
  const toast = document.createElement('div');
  toast.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:rgba(255,255,255,0.95);backdrop-filter:blur(20px);padding:30px;border-radius:25px;box-shadow:0 20px 60px rgba(0,0,0,0.2);z-index:99999;text-align:center;animation:popIn 0.3s;';
  toast.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="font-size:30px;color:#007AFF;margin-bottom:15px;"></i><p style="font-weight:700;">Preparing your data...</p><p style="color:#888;font-size:13px;margin-top:5px;">This may take a moment</p>';
  document.body.appendChild(toast);

  try {
    // Gather all user data
    const userData = {
      profile: currentUser,
      posts: await DB.getAll('posts'),
      messages: await DB.getAll('messages'),
      activity: await DB.getAll('activity'),
      notifications: await DB.getAll('notifications'),
      preferences: {
        language: secureLoad('language'),
        darkMode: secureLoad('dark_mode'),
        privateAccount: secureLoad('private_account')
      },
      exportDate: new Date().toISOString(),
      platform: 'TrustFirst v2.0'
    };

    // Remove sensitive fields
    if (userData.profile) {
      delete userData.profile.passwordHash;
      delete userData.profile.token;
      delete userData.profile.supabaseToken;
    }

    // Create downloadable file
    const blob = new Blob([JSON.stringify(userData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `trustfirst-data-${(currentUser?.handle || 'user').replace(/[^a-z0-9_-]/gi,'_')}-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);

    toast.innerHTML = '<i class="fa-solid fa-check-circle" style="font-size:30px;color:#34C759;margin-bottom:15px;"></i><p style="font-weight:700;">Download started!</p>';
    setTimeout(() => toast.remove(), 2000);
  } catch (err) {
    toast.innerHTML = '<i class="fa-solid fa-xmark-circle" style="font-size:30px;color:#FF3B30;margin-bottom:15px;"></i><p style="font-weight:700;">Export failed</p>';
    setTimeout(() => toast.remove(), 2000);
  }
}

async function requestDataDeletion() {
  if (!confirm('Are you absolutely sure? This will permanently delete all your data and cannot be undone.')) return;

  try {
    // Clear all IndexedDB stores
    await DB.clear('posts');
    await DB.clear('messages');
    await DB.clear('conversations');
    await DB.clear('notifications');
    await DB.clear('activity');
    await DB.clear('syncQueue');
    await DB.clear('mediaCache');
    await DB.clear('users');

    // Clear all localStorage
    localStorage.clear();

    // Clear all sessionStorage
    sessionStorage.clear();

    // Clear caches
    if ('caches' in window) {
      const keys = await caches.keys();
      await Promise.all(keys.map(key => caches.delete(key)));
    }

    // Unregister service worker
    if ('serviceWorker' in navigator) {
      const registrations = await navigator.serviceWorker.getRegistrations();
      await Promise.all(registrations.map(r => r.unregister()));
    }


    location.reload();
  } catch (err) {
    toast('Deletion failed. Please contact support.', 'error');
  }
}

async function clearLocalData() {
  if (!confirm('This will clear cached content and offline data. Your account will not be affected.')) return;

  try {
    await DB.clear('mediaCache');
    await DB.clear('syncQueue');

    if ('caches' in window) {
      const keys = await caches.keys();
      await Promise.all(keys.filter(k => k.includes('dynamic') || k.includes('images')).map(k => caches.delete(k)));
    }

    alert('Local data cleared successfully!');
  } catch (err) {
    alert('Could not clear all data.');
  }
}

(function patchAndroidKeyboard() {
    if (!window.visualViewport) return;
    var chatBar = null;
    function onViewportResize() {
        if (!chatBar) chatBar = document.getElementById('chat-bar');
        if (!chatBar) return;
        var gap = window.innerHeight - window.visualViewport.height;
        if (gap > 100) {
            chatBar.style.bottom = gap + 'px';
            chatBar.style.transition = 'bottom 0.1s';
        } else {
            chatBar.style.bottom = '';
        }
    }
    window.visualViewport.addEventListener('resize', onViewportResize, { passive: true });
    window.visualViewport.addEventListener('scroll', onViewportResize, { passive: true });
})();

    // ==========================================================================
// PWA SERVICE WORKER REGISTRATION
// ==========================================================================
if ('serviceWorker' in navigator) {
  window.addEventListener('load', async () => {
    try {
      const registration = await navigator.serviceWorker.register('/sw.js', { scope: '/' });
      console.debug('[PWA] Service Worker registered:', registration.scope);

      // Check for updates every 60 seconds
      setInterval(() => registration.update(), 60000);

      // Listen for update found
      registration.addEventListener('updatefound', () => {
        const newWorker = registration.installing;
        newWorker.addEventListener('statechange', () => {
          if (newWorker.state === 'activated') {
            showUpdateBanner();
          }
        });
      });
    } catch (err) {
      console.debug('[PWA] SW registration failed:', err);
    }
  });
}

function showUpdateBanner() {
  const banner = document.createElement('div');
  banner.style.cssText = 'position:fixed;top:0;left:0;width:100%;background:#007AFF;color:white;padding:12px;text-align:center;z-index:99999;font-weight:700;font-size:14px;cursor:pointer;';
  banner.innerHTML = '🔄 New version available — Tap to refresh';
  banner.onclick = () => location.reload();
  document.body.appendChild(banner);
}

// Install prompt
let deferredPrompt;
window.addEventListener('beforeinstallprompt', (e) => {
  e.preventDefault();
  deferredPrompt = e;
  setTimeout(showInstallPrompt, 5000);
});

function showInstallPrompt() {
  if (!deferredPrompt) return;
  const banner = document.createElement('div');
  banner.style.cssText = 'position:fixed;bottom:100px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,0.9);color:white;padding:15px 25px;border-radius:20px;z-index:99999;display:flex;gap:15px;align-items:center;backdrop-filter:blur(20px);box-shadow:0 10px 30px rgba(0,0,0,0.3);font-size:14px;max-width:350px;';
  banner.innerHTML = `
    <div style="flex:1;"><b>Install TrustFirst</b><br><small style="color:#aaa;">Add to home screen for the best experience</small></div>
    <button onclick="installPWA()" style="background:#007AFF;color:white;border:none;padding:10px 18px;border-radius:15px;font-weight:bold;cursor:pointer;">Install</button>
    <span onclick="this.parentElement.remove()" style="cursor:pointer;color:#888;font-size:18px;">✕</span>
  `;
  document.body.appendChild(banner);
}

async function installPWA() {
  if (!deferredPrompt) return;
  deferredPrompt.prompt();
  const result = await deferredPrompt.userChoice;
  console.debug('[PWA] Install result:', result.outcome);
  deferredPrompt = null;
  document.querySelector('[onclick="installPWA()"]')?.parentElement?.remove();
}

// Background sync registration
async function queueForSync(tag) {
  if ('serviceWorker' in navigator && 'SyncManager' in window) {
    const reg = await navigator.serviceWorker.ready;
    await reg.sync.register(tag);
  }
}

