// ── Story Privacy sub-menu ──
function openStoryPrivacySettings() {
    var existing = document.getElementById('storyPrivacyModal');
    if (existing) existing.remove();

    var sp = camSettingsState.storyPrivacy;

    function privacyRow(label, desc, value, key, options) {
        var optHTML = options.map(function(o) {
            var isActive = sp[key] === o.value;
            return '<div onclick="camSettingsState.storyPrivacy[\'' + key + '\']=\'' + o.value + '\';document.getElementById(\'sp_' + key + '_label\').textContent=\'' + o.label + '\';this.parentElement.querySelectorAll(\'.sp-radio\').forEach(function(r){r.style.background=\'rgba(255,255,255,0.08)\';r.style.border=\'1.5px solid rgba(255,255,255,0.25)\';r.innerHTML=\'\'});this.querySelector(\'.sp-radio\').style.background=\'rgba(0,122,255,0.8)\';this.querySelector(\'.sp-radio\').style.border=\'none\';this.querySelector(\'.sp-radio\').innerHTML=\'<i class=\\\"fa-solid fa-check\\\" style=\\\"color:white;font-size:9px;\\\"></i>\';" ' +
                'style="display:flex;align-items:center;gap:10px;padding:9px 0;cursor:pointer;">' +
                '<div class="sp-radio" style="width:22px;height:22px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;' +
                (isActive ? 'background:rgba(0,122,255,0.8);box-shadow:0 2px 8px rgba(0,122,255,0.4);' : 'background:rgba(255,255,255,0.08);border:1.5px solid rgba(255,255,255,0.25);') + '">' +
                (isActive ? '<i class="fa-solid fa-check" style="color:white;font-size:9px;"></i>' : '') +
                '</div>' +
                '<span style="color:white;font-size:14px;">' + o.label + '</span></div>';
        }).join('');

        return '<div style="padding:16px 24px;border-bottom:0.5px solid rgba(255,255,255,0.06);">' +
            '<div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:10px;">' +
            '<div><b style="color:white;font-size:15px;">' + label + '</b>' +
            '<br><small style="color:rgba(255,255,255,0.4);font-size:12px;">' + desc + '</small></div>' +
            '<span id="sp_' + key + '_label" style="font-size:12px;color:#007AFF;font-weight:700;">' + options.find(function(o){return o.value===sp[key];})?.label + '</span></div>' +
            optHTML + '</div>';
    }

    var modal = document.createElement('div');
    modal.id = 'storyPrivacyModal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9600;background:rgba(0,0,0,0.6);backdrop-filter:blur(20px);display:flex;align-items:flex-end;justify-content:center;';

    modal.innerHTML = '<div style="width:100%;max-width:500px;background:rgba(18,18,22,0.96);backdrop-filter:blur(60px) saturate(200%);-webkit-backdrop-filter:blur(60px) saturate(200%);border-radius:28px 28px 0 0;border-top:0.5px solid rgba(255,255,255,0.1);box-shadow:0 -20px 60px rgba(0,0,0,0.6);max-height:90vh;overflow-y:auto;animation:slideUpOverlay 0.35s cubic-bezier(0.32,0.72,0,1);">' +

        // Header glass island
        '<div style="position:sticky;top:0;z-index:5;display:flex;align-items:center;justify-content:space-between;padding:12px 20px;background:rgba(18,18,22,0.85);backdrop-filter:blur(30px);border-bottom:0.5px solid rgba(255,255,255,0.07);">' +
            '<button onclick="document.getElementById(\'storyPrivacyModal\').remove()" style="background:rgba(255,255,255,0.08);border:0.5px solid rgba(255,255,255,0.12);border-radius:50%;width:34px;height:34px;display:flex;align-items:center;justify-content:center;cursor:pointer;">' +
                '<i class="fa-solid fa-chevron-left" style="color:white;font-size:13px;"></i>' +
            '</button>' +
            '<span style="font-size:16px;font-weight:800;color:white;">Story Privacy</span>' +
            '<button onclick="document.getElementById(\'storyPrivacyModal\').remove();showToast(\'Privacy saved ✓\');" style="background:rgba(0,122,255,0.25);backdrop-filter:blur(20px);border:0.5px solid rgba(0,122,255,0.4);border-radius:18px;padding:7px 18px;cursor:pointer;color:#007AFF;font-size:14px;font-weight:800;">Done</button>' +
        '</div>' +

        // Sections
        privacyRow('Viewing', 'Who can see your story', 'everyone', 'viewing',
            [{value:'everyone',label:'Everyone'},{value:'followers',label:'Followers only'},{value:'close',label:'Close Friends'}]) +

        privacyRow('Replying', 'Who can reply to your story', 'everyone', 'replying',
            [{value:'everyone',label:'Everyone'},{value:'followers',label:'People you follow'},{value:'off',label:'Off'}]) +

        privacyRow('Commenting', 'Who can comment', 'everyone', 'commenting',
            [{value:'everyone',label:'Everyone'},{value:'followers',label:'Followers only'},{value:'off',label:'Off'}]) +

        // TrustFirst options
        '<div style="padding:16px 24px;border-bottom:0.5px solid rgba(255,255,255,0.06);">' +
            '<b style="color:white;font-size:15px;display:block;margin-bottom:4px;">TrustFirst Options</b>' +
            '<small style="color:rgba(255,255,255,0.4);font-size:12px;display:block;margin-bottom:14px;">Private cloud storage & sharing controls</small>' +
            '<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 0;border-bottom:0.5px solid rgba(255,255,255,0.04);">' +
                '<span style="color:white;font-size:14px;">Save story to archive</span>' +
                '<div class="toggle' + (sp.saving ? ' active' : '') + '" onclick="camSettingsState.storyPrivacy.saving=!camSettingsState.storyPrivacy.saving;this.classList.toggle(\'active\');triggerHaptic(10);"></div>' +
            '</div>' +
            '<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 0;">' +
                '<span style="color:white;font-size:14px;">Allow sharing to story/messages</span>' +
                '<div class="toggle' + (sp.sharing ? ' active' : '') + '" onclick="camSettingsState.storyPrivacy.sharing=!camSettingsState.storyPrivacy.sharing;this.classList.toggle(\'active\');triggerHaptic(10);"></div>' +
            '</div>' +
        '</div>' +

        // Hide from
        '<div onclick="showToast(\'Close Friends coming soon\')" style="display:flex;align-items:center;justify-content:space-between;padding:16px 24px;cursor:pointer;" onmouseover="this.style.background=\'rgba(255,255,255,0.04)\'" onmouseout="this.style.background=\'\'">' +
            '<div><b style="color:white;font-size:15px;">Hide story from...</b><br><small style="color:rgba(255,255,255,0.4);font-size:12px;">Manage who is excluded</small></div>' +
            '<i class="fa-solid fa-chevron-right" style="color:rgba(255,255,255,0.25);font-size:13px;"></i>' +
        '</div>' +

        '<div style="height:40px;"></div></div>';

    modal.addEventListener('click', function(e){ if(e.target===modal) modal.remove(); });
    (document.getElementById('app') || document.body).appendChild(modal);
}

