    // ==========================================================================
// BLOCK 1C: END-TO-END ENCRYPTION (Zero-Knowledge)
// Uses Web Crypto API - no plaintext ever touches the server
// ==========================================================================

const E2E = {
    // Key storage (keys stay on device only)
    _keys: null,

    // Initialize: generate or load key pair
    async init() {
        try {
    var stored = await DB.get('mediaCache', 'e2e_keys');
    if (stored && stored.blob) {
        this._keys = JSON.parse(stored.blob);
        console.debug('[E2E] Keys loaded from IndexedDB');
        return;
    }
} catch(e) {
    console.warn('[E2E] No stored keys, generating new ones');
}
        await this.generateKeyPair();
    },

    // Generate identity key pair (X25519-equivalent using ECDH P-256)
    async generateKeyPair() {
        const keyPair = await crypto.subtle.generateKey(
            { name: 'ECDH', namedCurve: 'P-256' },
            true, // extractable for export
            ['deriveKey', 'deriveBits']
        );

        const publicKeyRaw = await crypto.subtle.exportKey('jwk', keyPair.publicKey);
        const privateKeyRaw = await crypto.subtle.exportKey('jwk', keyPair.privateKey);

        // Generate a signed pre-key
        const signedPreKey = await crypto.subtle.generateKey(
            { name: 'ECDH', namedCurve: 'P-256' },
            true,
            ['deriveKey', 'deriveBits']
        );
        const signedPreKeyPub = await crypto.subtle.exportKey('jwk', signedPreKey.publicKey);
        const signedPreKeyPriv = await crypto.subtle.exportKey('jwk', signedPreKey.privateKey);

        // Generate one-time pre-keys (batch of 10)
        const oneTimePreKeys = [];
        for (let i = 0; i < 10; i++) {
            const otpk = await crypto.subtle.generateKey(
                { name: 'ECDH', namedCurve: 'P-256' },
                true,
                ['deriveKey', 'deriveBits']
            );
            oneTimePreKeys.push({
                id: i,
                publicKey: await crypto.subtle.exportKey('jwk', otpk.publicKey),
                privateKey: await crypto.subtle.exportKey('jwk', otpk.privateKey)
            });
        }

        this._keys = {
            identityKey: { publicKey: publicKeyRaw, privateKey: privateKeyRaw },
            signedPreKey: { publicKey: signedPreKeyPub, privateKey: signedPreKeyPriv, id: 1 },
            oneTimePreKeys: oneTimePreKeys
        };

        // Save to device ONLY (never sent to server unencrypted)
        try {
    await DB.update('mediaCache', { id: 'e2e_keys', type: 'e2e', blob: JSON.stringify(this._keys), createdAt: Date.now() });
} catch(e) {
    await DB.add('mediaCache', { id: 'e2e_keys', type: 'e2e', blob: JSON.stringify(this._keys), createdAt: Date.now() });
}
localStorage.removeItem('tf_e2e_keys');

        console.debug('[E2E] New key pair generated and stored on device');
    },

    // Upload public key bundle to server (only PUBLIC keys)
    async publishKeyBundle(userId) {
        if (!this._keys) await this.init();

        const bundle = {
            user_id: userId,
            identity_public_key: JSON.stringify(this._keys.identityKey.publicKey),
            signed_prekey_public: JSON.stringify(this._keys.signedPreKey.publicKey),
            signed_prekey_signature: 'self-signed', // In production, sign with identity key
            signed_prekey_id: this._keys.signedPreKey.id,
            one_time_prekeys: JSON.stringify(
                this._keys.oneTimePreKeys.map(k => ({ id: k.id, publicKey: k.publicKey }))
            )
        };

        await DB.storeKeyBundle(bundle);
        console.debug('[E2E] Public key bundle published to server');
    },

    // Derive shared secret with another user (ECDH)
    async deriveSharedSecret(theirPublicKeyJWK) {
        if (!this._keys) await this.init();

        const myPrivateKey = await crypto.subtle.importKey(
            'jwk',
            this._keys.identityKey.privateKey,
            { name: 'ECDH', namedCurve: 'P-256' },
            false,
            ['deriveBits']
        );

        const theirPublicKey = await crypto.subtle.importKey(
            'jwk',
            typeof theirPublicKeyJWK === 'string' ? JSON.parse(theirPublicKeyJWK) : theirPublicKeyJWK,
            { name: 'ECDH', namedCurve: 'P-256' },
            false,
            []
        );

        const sharedBits = await crypto.subtle.deriveBits(
            { name: 'ECDH', public: theirPublicKey },
            myPrivateKey,
            256
        );

        // Derive AES-GCM key from shared secret using HKDF
        const sharedKeyMaterial = await crypto.subtle.importKey(
            'raw', sharedBits, 'HKDF', false, ['deriveKey']
        );

        const aesKey = await crypto.subtle.deriveKey(
            { name: 'HKDF', hash: 'SHA-256', salt: new Uint8Array(32), info: new TextEncoder().encode('TrustFirst-E2E') },
            sharedKeyMaterial,
            { name: 'AES-GCM', length: 256 },
            false,
            ['encrypt', 'decrypt']
        );

        return aesKey;
    },

    // Cache for derived keys (per user)
    _sessionKeys: new Map(),

    async getSessionKey(userId) {
        if (this._sessionKeys.has(userId)) {
            return this._sessionKeys.get(userId);
        }

        // Fetch their public key bundle from server
        const theirBundle = await DB.getKeyBundle(userId);
        if (!theirBundle) {
            throw new Error('Recipient has no encryption keys published');
        }

        const key = await this.deriveSharedSecret(theirBundle.identity_public_key);
        this._sessionKeys.set(userId, key);
        return key;
    },

    // Encrypt a message
    async encryptMessage(plaintext, recipientUserId) {
        const key = await this.getSessionKey(recipientUserId);
        const nonce = crypto.getRandomValues(new Uint8Array(12));
        const encodedText = new TextEncoder().encode(plaintext);

        const ciphertext = await crypto.subtle.encrypt(
            { name: 'AES-GCM', iv: nonce },
            key,
            encodedText
        );

        return {
            ciphertext: btoa(String.fromCharCode(...new Uint8Array(ciphertext))),
            nonce: btoa(String.fromCharCode(...nonce))
        };
    },

    // Decrypt a message
    async decryptMessage(ciphertextB64, nonceB64, senderUserId) {
        const key = await this.getSessionKey(senderUserId);

        const ciphertext = Uint8Array.from(atob(ciphertextB64), c => c.charCodeAt(0));
        const nonce = Uint8Array.from(atob(nonceB64), c => c.charCodeAt(0));

        const decrypted = await crypto.subtle.decrypt(
            { name: 'AES-GCM', iv: nonce },
            key,
            ciphertext
        );

        return new TextDecoder().decode(decrypted);
    },

    // Encrypt a file/blob
    async encryptFile(file) {
        const arrayBuffer = await file.arrayBuffer();
        const key = await this.getSessionKey(currentChatUser?.id);
        const nonce = crypto.getRandomValues(new Uint8Array(12));

        const encrypted = await crypto.subtle.encrypt(
            { name: 'AES-GCM', iv: nonce },
            key,
            arrayBuffer
        );

        return {
            encryptedBlob: new Blob([encrypted]),
            nonce: btoa(String.fromCharCode(...nonce)),
            originalName: file.name,
            originalType: file.type,
            originalSize: file.size
        };
    },

    // Decrypt a file/blob
    async decryptFile(encryptedBlob, nonceB64, senderUserId, originalType) {
        const key = await this.getSessionKey(senderUserId);
        const nonce = Uint8Array.from(atob(nonceB64), c => c.charCodeAt(0));
        const arrayBuffer = await encryptedBlob.arrayBuffer();

        const decrypted = await crypto.subtle.decrypt(
            { name: 'AES-GCM', iv: nonce },
            key,
            arrayBuffer
        );

        return new Blob([decrypted], { type: originalType });
    }
};

// Initialize E2E on load
E2E.init().then(() => console.debug('[E2E] Encryption ready'));

    // ==========================================================================
// BLOCK 2A: DEVICE FINGERPRINTING
// Creates a stable, unique fingerprint for each device
// Used for: device trust, one-account enforcement, login activity
// ==========================================================================

const DeviceFingerprint = {
    async generate() {
        const components = [];

        // Screen
        components.push(`${screen.width}x${screen.height}x${screen.colorDepth}`);

        // Timezone
        components.push(Intl.DateTimeFormat().resolvedOptions().timeZone);

        // Language
        components.push(navigator.language);

        // Platform
        components.push(navigator.platform);

        // Hardware concurrency (CPU cores)
        components.push(navigator.hardwareConcurrency || 'unknown');

        // Device memory
        components.push(navigator.deviceMemory || 'unknown');

        // Touch support
        components.push('ontouchstart' in window ? 'touch' : 'no-touch');

        // Canvas fingerprint
        try {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            canvas.width = 200;
            canvas.height = 50;
            ctx.textBaseline = 'top';
            ctx.font = '14px Arial';
            ctx.fillStyle = '#f60';
            ctx.fillRect(0, 0, 200, 50);
            ctx.fillStyle = '#069';
            ctx.fillText('TrustFirst:fingerprint', 2, 15);
            ctx.fillStyle = 'rgba(102, 204, 0, 0.7)';
            ctx.fillText('TrustFirst:fingerprint', 4, 17);
            components.push(canvas.toDataURL().slice(-50));
        } catch (e) {
            components.push('canvas-blocked');
        }

        // WebGL renderer
        try {
            const gl = document.createElement('canvas').getContext('webgl');
            if (gl) {
                const dbg = gl.getExtension('WEBGL_debug_renderer_info');
                if (dbg) {
                    components.push(gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL));
                }
            }
        } catch (e) {
            components.push('webgl-blocked');
        }

        // Generate hash from all components
        const raw = components.join('|||');
        const hash = await this.sha256(raw);
        return hash;
    },

    async sha256(message) {
        const msgBuffer = new TextEncoder().encode(message);
        const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
        const hashArray = Array.from(new Uint8Array(hashBuffer));
        return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    },

    // Detect device type
    getDeviceType() {
        const ua = navigator.userAgent;
        if (/tablet|ipad|playbook|silk/i.test(ua)) return 'tablet';
        if (/mobile|iphone|ipod|android|blackberry|opera mini|iemobile/i.test(ua)) return 'mobile';
        return 'desktop';
    },

    // Get browser name
    getBrowser() {
        const ua = navigator.userAgent;
        if (ua.includes('Firefox')) return 'Firefox';
        if (ua.includes('SamsungBrowser')) return 'Samsung Browser';
        if (ua.includes('Opera') || ua.includes('OPR')) return 'Opera';
        if (ua.includes('Edge') || ua.includes('Edg')) return 'Edge';
        if (ua.includes('Chrome')) return 'Chrome';
        if (ua.includes('Safari')) return 'Safari';
        return 'Unknown';
    },

    // Get OS
    getOS() {
        const ua = navigator.userAgent;
        if (ua.includes('Win')) return 'Windows';
        if (ua.includes('Mac')) return 'macOS';
        if (ua.includes('Linux')) return 'Linux';
        if (ua.includes('Android')) return 'Android';
        if (ua.includes('iPhone') || ua.includes('iPad')) return 'iOS';
        return navigator.platform || 'Unknown';
    },

    // Build device info object for storing
    async getDeviceInfo() {
        return {
            device_fingerprint: await this.generate(),
            device_name: `${this.getBrowser()} on ${this.getOS()}`,
            device_type: this.getDeviceType(),
            browser: this.getBrowser(),
            os: this.getOS()
        };
    }
};

    // ==========================================================================
// BLOCK 2C: STRONG PASSWORD VALIDATION + ONE-ACCOUNT ENFORCEMENT
// ==========================================================================

const PasswordPolicy = {
    minLength: 8,
    maxLength: 128,

    rules: [
        {
            id: 'length',
            label: 'At least 8 characters',
            test: (p) => p.length >= 8
        },
        {
            id: 'uppercase',
            label: 'One uppercase letter (A-Z)',
            test: (p) => /[A-Z]/.test(p)
        },
        {
            id: 'lowercase',
            label: 'One lowercase letter (a-z)',
            test: (p) => /[a-z]/.test(p)
        },
        {
            id: 'number',
            label: 'One number (0-9)',
            test: (p) => /[0-9]/.test(p)
        },
        {
            id: 'special',
            label: 'One special character (!@#$...)',
            test: (p) => /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?`~]/.test(p)
        },
        {
            id: 'noSpaces',
            label: 'No spaces',
            test: (p) => !/\s/.test(p)
        },
        {
            id: 'notCommon',
            label: 'Not a common password',
            test: (p) => {
                const common = [
                    'password', '12345678', 'qwerty12', 'letmein1', 'welcome1',
                    'monkey12', 'dragon12', 'master12', 'trustfirst', 'password1',
                    'abc12345', '11111111', 'iloveyou', 'admin123', 'passw0rd'
                ];
                return !common.includes(p.toLowerCase());
            }
        }
    ],

    // Validate password against all rules
    validate(password) {
        const results = this.rules.map(rule => ({
            ...rule,
            passed: rule.test(password)
        }));

        const allPassed = results.every(r => r.passed);
        const score = results.filter(r => r.passed).length;

        return {
            valid: allPassed,
            score: score,
            maxScore: this.rules.length,
            results: results,
            strength: this.getStrengthLabel(score)
        };
    },

    getStrengthLabel(score) {
        if (score <= 2) return { label: 'Very Weak', color: '#FF3B30' };
        if (score <= 3) return { label: 'Weak', color: '#FF9500' };
        if (score <= 5) return { label: 'Fair', color: '#FFD700' };
        if (score <= 6) return { label: 'Strong', color: '#34C759' };
        return { label: 'Very Strong', color: '#007AFF' };
    }
};

// Live password strength checker for the registration form
function checkPasswordStrength(password) {
    const fill = document.getElementById('pw-strength-fill');
    const text = document.getElementById('pw-strength-text');
    if (!fill || !text) return;

    if (!password || password.length === 0) {
        fill.style.width = '0%';
        text.textContent = '';
        return;
    }

    const result = PasswordPolicy.validate(password);
    const percent = Math.round((result.score / result.maxScore) * 100);

    fill.style.width = percent + '%';
    fill.style.background = result.strength.color;
    text.textContent = result.strength.label;
    text.style.color = result.strength.color;

    // Show which rules failed
    const failedRules = result.results.filter(r => !r.passed);
    if (failedRules.length > 0 && password.length > 0) {
        text.textContent += ' — Need: ' + failedRules[0].label;
    }
}

// ==========================================================================
// ONE HUMAN = ONE ACCOUNT ENFORCEMENT
// ==========================================================================

const OneAccountPolicy = {
    // Check if email is already registered
    async checkEmailAvailable(email) {
        try {
            const { data, error } = await sb.from('users')
                .select('id')
                .eq('email', email.toLowerCase().trim())
                .maybeSingle();

            if (error) throw error;
            return !data; // true if available
        } catch (e) {
            console.error('[OneAccount] Email check failed:', e);
            // Fail open for UX, server will still enforce unique constraint
            return true;
        }
    },

    // Check if username is taken
    async checkUsernameAvailable(username) {
        try {
            const { data, error } = await sb.from('users')
                .select('id')
                .eq('username', username.toLowerCase().trim())
                .maybeSingle();

            if (error) throw error;
            return !data;
        } catch (e) {
            console.error('[OneAccount] Username check failed:', e);
            return true;
        }
    },

    // Check if this Stripe Identity ID already has an account
    // This is the core of one-human-one-account
    async checkStripeIdentityAvailable(stripeIdentityId) {
        if (!stripeIdentityId) return true;

        try {
            const { data, error } = await sb.from('users')
                .select('id')
                .eq('stripe_identity_id', stripeIdentityId)
                .maybeSingle();

            if (error) throw error;
            return !data;
        } catch (e) {
            console.error('[OneAccount] Stripe ID check failed:', e);
            return true;
        }
    },

    // Check if this device already has a registered account
    async checkDeviceAccountLimit(fingerprint) {
        try {
            const { data, error } = await sb.from('trusted_devices')
                .select('user_id')
                .eq('device_fingerprint', fingerprint);

            if (error) throw error;

            // Allow up to 2 accounts per device (for families)
            // but flag if more
            const uniqueUsers = [...new Set((data || []).map(d => d.user_id))];
            return {
                allowed: uniqueUsers.length < 2,
                existingCount: uniqueUsers.length
            };
        } catch (e) {
            return { allowed: true, existingCount: 0 };
        }
    },

    // Full pre-registration validation
    async validateRegistration(email, username, deviceFingerprint) {
        const errors = [];

        const emailAvailable = await this.checkEmailAvailable(email);
        if (!emailAvailable) {
            errors.push('This email is already registered. One account per person.');
        }

        const usernameAvailable = await this.checkUsernameAvailable(username);
        if (!usernameAvailable) {
            errors.push('This username is taken. Choose another.');
        }

        const deviceCheck = await this.checkDeviceAccountLimit(deviceFingerprint);
        if (!deviceCheck.allowed) {
            errors.push('Too many accounts created from this device. One human = one account.');
        }

        return {
            valid: errors.length === 0,
            errors: errors
        };
    }
};

    // ==========================================================================
// BLOCK 3A: SUSPICIOUS LOGIN DETECTION
// Analyzes login patterns to flag unusual activity
// ==========================================================================

const SuspiciousLoginDetector = {
    // Flags that make a login suspicious
    suspiciousFactors: [],

    async analyze(newLogin) {
        this.suspiciousFactors = [];
        const userId = newLogin.user_id;

        // Get recent login history
        const recentLogins = await DB.getLoginActivity(userId, 30);

        // Check 1: Impossible travel
        const lastLogin = recentLogins[0];
        if (lastLogin && lastLogin.location_city && newLogin.location_city) {
            const impossibleTravel = this.checkImpossibleTravel(lastLogin, newLogin);
            if (impossibleTravel) {
                this.suspiciousFactors.push({
                    type: 'impossible_travel',
                    severity: 'high',
                    message: `Logged in from ${newLogin.location_city}, ${newLogin.location_country}
                              minutes after login from ${lastLogin.location_city}, ${lastLogin.location_country}`
                });
            }
        }

        // Check 2: New device from new location
        const lastDevices = await DB.getUserDevices(userId);
        const isNewDevice = !lastDevices.some(d => d.device_fingerprint === newLogin.device_fingerprint);
        const isNewLocation = !recentLogins.some(l => l.location_city === newLogin.location_city);

        if (isNewDevice && isNewLocation) {
            this.suspiciousFactors.push({
                type: 'new_device_new_location',
                severity: 'medium',
                message: `New device from new location: ${newLogin.location_city}, ${newLogin.location_country}`
            });
        }

        // Check 3: VPN/Proxy detection (by comparing to known bad ranges)
        if (this.isLikelyVPN(newLogin.ip_address)) {
            this.suspiciousFactors.push({
                type: 'vpn_detected',
                severity: 'low',
                message: 'Login detected from a VPN or proxy service'
            });
        }

        // Check 4: Unusual time
        const now = new Date();
        const hour = now.getHours();
        if (hour >= 2 && hour <= 5) {
            this.suspiciousFactors.push({
                type: 'unusual_time',
                severity: 'low',
                message: `Login at unusual time: ${hour}:00`
            });
        }

        // Check 5: Multiple logins in short time
        const last5Minutes = recentLogins.filter(l => {
            const diff = (new Date() - new Date(l.created_at)) / 1000 / 60;
            return diff < 5;
        });
        if (last5Minutes.length > 1) {
            this.suspiciousFactors.push({
                type: 'rapid_logins',
                severity: 'medium',
                message: `Multiple login attempts in the last 5 minutes`
            });
        }

        return {
            suspicious: this.suspiciousFactors.length > 0,
            factors: this.suspiciousFactors,
            riskLevel: this.calculateRiskLevel()
        };
    },

    checkImpossibleTravel(login1, login2) {
        // Very simple: if more than 900km apart in less than 1 hour, flag it
        // In production, use proper distance calculation with lat/long
        const cities = [
            { name: 'New York', country: 'USA', lat: 40.7128, lng: -74.0060 },
            { name: 'London', country: 'UK', lat: 51.5074, lng: -0.1278 },
            { name: 'Tokyo', country: 'Japan', lat: 35.6762, lng: 139.6503 },
            { name: 'Sydney', country: 'Australia', lat: -33.8688, lng: 151.2093 },
            { name: 'Johannesburg', country: 'South Africa', lat: -26.2041, lng: 28.0473 }
        ];

        const city1 = cities.find(c => c.name === login1.location_city);
        const city2 = cities.find(c => c.name === login2.location_city);

        if (!city1 || !city2) return false;

        const distance = this.haversineDistance(city1.lat, city1.lng, city2.lat, city2.lng);
        const timeDiffMinutes = (new Date(login2.created_at) - new Date(login1.created_at)) / 1000 / 60;

        // Average speed would need to be > 15 km/min (900 km/hour) to be possible
        const maxPossibleDistance = timeDiffMinutes * 15;

        return distance > maxPossibleDistance;
    },

    haversineDistance(lat1, lon1, lat2, lon2) {
        const R = 6371; // Earth's radius in km
        const dLat = (lat2 - lat1) * Math.PI / 180;
        const dLon = (lon2 - lon1) * Math.PI / 180;
        const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
                  Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
                  Math.sin(dLon / 2) * Math.sin(dLon / 2);
        const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        return R * c;
    },

    isLikelyVPN(ipAddress) {
        // In production, check against VPN database or use MaxMind GeoIP
        // For now, simple check: if no valid IPv4 address format, might be obfuscated
        if (!ipAddress) return true;
        return false;
    },

    calculateRiskLevel() {
        if (this.suspiciousFactors.length === 0) return 'low';
        const highSeverity = this.suspiciousFactors.filter(f => f.severity === 'high').length;
        if (highSeverity > 0) return 'high';
        return 'medium';
    }
};

    // ==========================================================================
// BLOCK 3B: DEVICE TRUST MANAGER
// Handle device verification, approval, and revocation
// ==========================================================================

const DeviceTrustManager = {
    async markDeviceAsTrusted(deviceId) {
        try {
            const { error } = await sb.from('trusted_devices')
                .update({ is_trusted: true })
                .eq('id', deviceId);
            if (error) throw error;
            console.debug('[DeviceTrust] Device marked as trusted');
            renderSecurityPage();
        } catch (e) {
            console.error('[DeviceTrust] Failed to trust device:', e);
        }
    },

    async revokeDevice(deviceId) {
        if (!confirm('Remove this device? You\'ll need to log in again on that device.')) return;

        try {
            await DB.removeDevice(deviceId);
            triggerHaptic(20);

            const toast = document.createElement('div');
            toast.style.cssText = `
                position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
                background: rgba(52,199,89,0.95); backdrop-filter: blur(20px);
                color: white; padding: 15px 30px; border-radius: 20px; z-index: 9999;
                font-weight: 700; text-align: center; animation: popIn 0.3s;
            `;
            toast.innerHTML = '<i class="fa-solid fa-check-circle"></i> Device removed';
            document.getElementById('app').appendChild(toast);
            setTimeout(() => toast.remove(), 3000);

            renderSecurityPage();
        } catch (e) {
            console.error('[DeviceTrust] Failed to revoke device:', e);
        }
    },

    async getCurrentDevice() {
        try {
            const deviceInfo = await DeviceFingerprint.getDeviceInfo();
            const session = await DB.getSession();
            if (!session) return null;

            const devices = await DB.getUserDevices(session.user.id);
            return devices.find(d => d.device_fingerprint === deviceInfo.device_fingerprint);
        } catch (e) {
            return null;
        }
    },

    formatDeviceName(device) {
        return `${device.browser} on ${device.os}`;
    },

    getDeviceIcon(deviceType) {
        const iconMap = {
            'mobile': 'fa-mobile-screen',
            'tablet': 'fa-tablet',
            'desktop': 'fa-laptop'
        };
        return iconMap[deviceType] || 'fa-laptop';
    },

    formatLocation(device) {
        if (!device.location_city) return 'Unknown location';
        if (device.location_country) return `${device.location_city}, ${device.location_country}`;
        return device.location_city;
    },

    formatLastActive(device) {
        const lastActive = new Date(device.last_active);
        const now = new Date();
        const diff = now - lastActive;

        const seconds = Math.floor(diff / 1000);
        const minutes = Math.floor(seconds / 60);
        const hours = Math.floor(minutes / 60);
        const days = Math.floor(hours / 24);

        if (seconds < 60) return 'Just now';
        if (minutes < 60) return `${minutes}m ago`;
        if (hours < 24) return `${hours}h ago`;
        if (days < 7) return `${days}d ago`;
        return lastActive.toLocaleDateString();
    }
};

    // ==========================================================================
// BLOCK 3C: RENDER SECURITY PAGE WITH DEVICE LIST
// ==========================================================================

async function renderSecurityPage() {
    try {
        const session = await DB.getSession();
        if (!session) return;

        // Render security alerts
        const alertsDiv = document.getElementById('security-alerts');
        if (alertsDiv) {
            const devices = await DB.getUserDevices(session.user.id);
            const currentDevice = await DeviceTrustManager.getCurrentDevice();

            alertsDiv.innerHTML = `
                <div class="security-alert">
                    <div class="security-alert-icon" style="background:rgba(52,199,89,0.15); color:#34C759;">
                        <i class="fa-solid fa-check"></i>
                    </div>
                    <div>
                        <b style="font-size:14px;">Account Secure</b>
                        <p style="color:#888; font-size:13px; margin-top:3px;">
                            No suspicious activity. ${devices.length} device(s) trusted.
                        </p>
                    </div>
                </div>
                <div class="security-alert">
                    <div class="security-alert-icon" style="background:rgba(0,122,255,0.15); color:#007AFF;">
                        <i class="fa-solid fa-shield-halved"></i>
                    </div>
                    <div>
                        <b style="font-size:14px;">Identity Verified</b>
                        <p style="color:#888; font-size:13px; margin-top:3px;">
                            Stripe verification completed
                        </p>
                    </div>
                </div>
            `;
        }

        // Render devices list
        const devicesDiv = document.getElementById('devices-list');
        if (devicesDiv) {
            const devices = await DB.getUserDevices(session.user.id);
            const currentDevice = await DeviceTrustManager.getCurrentDevice();

            devicesDiv.innerHTML = devices.map(device => `
                <div class="device-card">
                    <div class="device-icon">
                        <i class="fa-solid ${DeviceTrustManager.getDeviceIcon(device.device_type)}"></i>
                    </div>
                    <div style="flex:1;">
                        <b style="font-size:14px;">
                            ${DeviceTrustManager.formatDeviceName(device)}
                        </b>
                        <br>
                        <small style="color:#888;">
                            ${DeviceTrustManager.formatLocation(device)}
                        </small>
                        <br>
                        <small style="color:#aaa; font-size:11px; margin-top:4px;">
                            ${DeviceTrustManager.formatLastActive(device)}
                        </small>
                        ${device.is_trusted ?
                            '<br><span style="color:#34C759; font-size:11px; font-weight:700;">✓ Trusted</span>' :
                            '<br><span style="color:#FF9500; font-size:11px; font-weight:700;">⚠ Not trusted</span>'
                        }
                    </div>
                    <div style="display:flex; flex-direction:column; gap:8px; align-items:flex-end;">
                        ${currentDevice && currentDevice.id === device.id ?
                            '<span style="color:#007AFF; font-size:11px; font-weight:700;">This device</span>' :
                            ''
                        }
                        ${!device.is_trusted ?
                            `<button onclick="DeviceTrustManager.markDeviceAsTrusted('${device.id}')"
                                    style="padding:6px 12px; background:#007AFF; color:white; border:none;
                                           border-radius:8px; font-size:11px; font-weight:700; cursor:pointer;">
                                Trust
                            </button>` :
                            ''
                        }
                        ${!currentDevice || currentDevice.id !== device.id ?
                            `<button onclick="DeviceTrustManager.revokeDevice('${device.id}')"
                                    style="padding:6px 12px; background:#FF3B30; color:white; border:none;
                                           border-radius:8px; font-size:11px; font-weight:700; cursor:pointer;">
                                Remove
                            </button>` :
                            ''
                        }
                    </div>
                </div>
            `).join('');
        }

    } catch (e) {
        console.error('[Security] Render failed:', e);
    }
}

    // ==========================================================================
// BLOCK 3D: LOGIN ACTIVITY HISTORY VIEWER
// ==========================================================================

async function renderLoginActivity() {
    try {
        const session = await DB.getSession();
        if (!session) return;

        const activity = await DB.getLoginActivity(session.user.id, 50);
        const container = document.getElementById('login-activity-content');

        if (!activity || activity.length === 0) {
            container.innerHTML = `
                <div style="text-align:center; padding:40px 20px; color:#888;">
                    <i class="fa-solid fa-history" style="font-size:40px; margin-bottom:15px; display:block;"></i>
                    No login history yet
                </div>
            `;
            return;
        }

        let html = `
            <div class="settings-section-title">Recent Login Activity</div>
            <div class="settings-card">
        `;

        for (const entry of activity) {
            const date = new Date(entry.created_at);
            const timeStr = date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            const dateStr = date.toLocaleDateString();

            const statusColor = {
                'success': '#34C759',
                'failed': '#FF3B30',
                'blocked': '#FF9500',
                'suspicious': '#FFD700'
            }[entry.status] || '#888';

            const statusIcon = {
                'success': 'fa-check-circle',
                'failed': 'fa-xmark-circle',
                'blocked': 'fa-ban',
                'suspicious': 'fa-triangle-exclamation'
            }[entry.status] || 'fa-circle';

            html += `
                <div class="login-activity-item">
                    <div class="login-activity-icon" style="background:${statusColor}15; color:${statusColor};">
                        <i class="fa-solid ${statusIcon}"></i>
                    </div>
                    <div style="flex:1;">
                        <b style="font-size:14px; text-transform:capitalize;">${entry.status}</b>
                        <p style="color:#888; font-size:13px; margin-top:2px;">
                            ${entry.location_city}, ${entry.location_country}
                        </p>
                        <small style="color:#aaa; font-size:11px;">
                            ${entry.login_method || 'password'} • ${entry.user_agent?.substring(0, 40)}...
                        </small>
                    </div>
                    <div style="text-align:right;">
                        <small style="color:#aaa;">
                            ${timeStr}<br>
                            ${dateStr}
                        </small>
                    </div>
                </div>
            `;
        }

        html += `</div>`;
        container.innerHTML = html;

    } catch (e) {
        console.error('[LoginActivity] Render failed:', e);
    }
}

