// SHARE MENU WITH PROPER CLOSE
// ============================================
function openShareMenu(postId) {
    // Remove existing share menu
    const existing = document.getElementById('shareMenuOverlay');
    if (existing) existing.remove();

    const overlay = document.createElement('div');
    overlay.id = 'shareMenuOverlay';
    overlay.style.cssText = `
        position:fixed; top:0; left:0; right:0; bottom:0; z-index:9999;
        background:rgba(0,0,0,0.4); backdrop-filter:blur(8px);
        display:flex; align-items:flex-end; justify-content:center;
    `;
    overlay.innerHTML = `
        <div class="share-menu-content" style="
            background:var(--card-bg); border-radius:20px 20px 0 0; width:100%; max-width:500px;
            padding:20px 20px 40px; transform:translateY(100%);
            animation:slideUpShare 0.3s ease forwards;
        ">
            <div style="width:40px; height:4px; background:var(--text-tertiary); border-radius:2px; margin:0 auto 20px;"></div>
            <h3 style="font-size:18px; font-weight:700; margin-bottom:20px; color:var(--text-primary);">Share</h3>
            <div style="display:flex; gap:20px; overflow-x:auto; padding-bottom:16px;">
                ${['Copy Link', 'Message', 'WhatsApp', 'Twitter', 'Instagram', 'More'].map((label, i) => {
                    const icons = ['🔗', '💬', '📱', '🐦', '📷', '•••'];
                    return `
                        <div onclick="handleShare('${label.toLowerCase()}', '${postId}')" style="
                            display:flex; flex-direction:column; align-items:center; gap:8px; cursor:pointer; min-width:64px;
                        ">
                            <div style="width:56px; height:56px; border-radius:50%; background:var(--bg-secondary);
                                display:flex; align-items:center; justify-content:center; font-size:24px;">
                                ${icons[i]}
                            </div>
                            <span style="font-size:11px; color:var(--text-secondary);">${label}</span>
                        </div>
                    `;
                }).join('')}
            </div>
            <button onclick="document.getElementById('shareMenuOverlay').remove()" style="
                width:100%; padding:14px; border-radius:14px; border:none;
                background:var(--bg-secondary); color:var(--text-primary);
                font-size:16px; font-weight:600; cursor:pointer; margin-top:12px;
            ">Cancel</button>
        </div>
    `;

    // Close when tapping overlay background
    overlay.addEventListener('click', (e) => {
        if (e.target === overlay) {
            overlay.remove();
        }
    });

    document.body.appendChild(overlay);
}

function handleShare(type, postId) {
    const url = `https://trustfirst.app/post/${postId}`;
    switch(type) {
        case 'copy link':
            navigator.clipboard.writeText(url).then(() => showToast('Link copied!'));
            break;
        case 'whatsapp':
            window.open(`https://wa.me/?text=${encodeURIComponent(url)}`);
            break;
        case 'twitter':
            window.open(`https://twitter.com/intent/tweet?url=${encodeURIComponent(url)}`);
            break;
        default:
            if (navigator.share) {
                navigator.share({ url: url });
            }
    }
    if (window.sb && currentUser) {
    sb.from('posts').select('share_count').eq('id', postId).single().then(function(res){
        if (res.data) sb.from('posts').update({ share_count: (res.data.share_count||0)+1 }).eq('id', postId);
    });
}
    document.getElementById('shareMenuOverlay').remove();
}

