function t(key) {
    return (TRANSLATIONS[currentLanguage] && TRANSLATIONS[currentLanguage][key]) || TRANSLATIONS['en'][key] || key;
}

function changeLanguage(lang) {
    currentLanguage = lang;
    secureSave('language', lang);
    // Set RTL for Arabic
    if (lang === 'ar') {
        document.documentElement.setAttribute('dir', 'rtl');
    } else {
        document.documentElement.setAttribute('dir', 'ltr');
    }

    // Update all translatable elements
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        el.textContent = t(key);
    });

    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        el.placeholder = t(key);
    });

    showToast(`Language changed to ${getLanguageName(lang)}`);
}

function getLanguageName(code) {
    const names = { en:'English', es:'Español', fr:'Français', ar:'العربية', zu:'isiZulu', pt:'Português', hi:'हिन्दी', zh:'中文' };
    return names[code] || code;
}

function renderLanguageSelector() {
    return `
        <div class="language-selector" style="padding:16px;">
            <h3 style="font-size:18px; font-weight:700; margin-bottom:16px; color:var(--text-primary);" data-i18n="language">${t('language')}</h3>
            <div style="display:flex; flex-direction:column; gap:4px;">
                ${Object.keys(TRANSLATIONS).map(lang => `
                    <button onclick="changeLanguage('${lang}')" style="
                        display:flex; align-items:center; justify-content:space-between;
                        padding:14px 16px; border-radius:12px; border:none; width:100%;
                        background:${currentLanguage === lang ? 'rgba(0,122,255,0.1)' : 'transparent'};
                        cursor:pointer; text-align:left;
                    ">
                        <span style="font-size:16px; color:var(--text-primary); font-weight:${currentLanguage === lang ? '600' : '400'};">
                            ${getLanguageName(lang)}
                        </span>
                        ${currentLanguage === lang ? '<svg width="20" height="20" viewBox="0 0 24 24" fill="#007AFF" stroke="none"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/></svg>' : ''}
                    </button>
                `).join('')}
            </div>
        </div>
    `;
}

