let currentReelIndex = 0;
let reelsData = [];
var _videoFeedContext = 'feed';
var _videoFeedList   = [];
var _videoFeedIdx    = 0;

function openContextualVideo(videoUrl, context, startIndex, clipArray) {
    _videoFeedContext = context || 'feed';
    _videoFeedIdx    = startIndex || 0;

    if (clipArray && clipArray.length) {
        reelsData = clipArray.map(function(c) {
            return {
                id:             c.id || '',
                videoUrl:       c.videoUrl || c.video_url || c.media_url || videoUrl,
                username:       c.username || (c.users && ('@' + c.users.username)) || '@user',
                caption:        c.caption  || c.text_content || '',
                sound:          c.sound    || c.sound_name   || 'Original Audio',
                likes:          c.likes    || c.like_count   || 0,
                comments:       c.comments || c.comment_count || 0,
                liked:          false,
                bookmarked:     false,
                isOriginalSound: !c.sound_name
            };
        });
    } else {
        reelsData = [{
            id: 'single_' + Date.now(), videoUrl: videoUrl,
            username: '', caption: '', sound: '', likes: 0, comments: 0,
            liked: false, bookmarked: false, isOriginalSound: true
        }];
    }
    currentReelIndex = _videoFeedIdx;

    var navBar = document.querySelector('.nav-container');
    if (navBar) navBar.style.display = 'none';
    var screen = document.getElementById('reel-overlay');
    if (!screen) return;
    screen.style.display = 'block';
    screen.innerHTML =
        '<div id="reelsContainer" style="position:fixed;top:0;left:0;right:0;bottom:0;z-index:5000;background:#000;overflow:hidden;">' +
            '<button onclick="closeReelsPage()" style="position:absolute;top:50px;left:16px;z-index:5010;background:rgba(0,0,0,0.3);border:none;border-radius:50%;width:40px;height:40px;display:flex;align-items:center;justify-content:center;cursor:pointer;backdrop-filter:blur(10px);">' +
                '<svg width="24" height="24" viewBox="0 0 24 24" fill="white" stroke="white" stroke-width="2"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>' +
            '</button>' +
            '<div id="reelsLoading" style="display:none;"></div>' +
            '<div id="reelsViewport" style="width:100%;height:100%;overflow:hidden;position:relative;"></div>' +
            '<div id="speedIndicator" style="display:none;"></div>' +
            '<div id="reelContextMenu" style="display:none;"></div>' +
        '</div>';

    addReelsStyles();
    renderReel(currentReelIndex);
    setupReelGestures();
}

function openFullScreenMedia(url, type) {
    if (type === 'video') {
        openContextualVideo(url, 'dm_gallery', 0, null);
        return;
    }
    var ov = document.createElement('div');
    ov.style.cssText = 'position:fixed;inset:0;z-index:30000;background:#000;display:flex;align-items:center;justify-content:center;cursor:pointer;';
    ov.onclick = function() { ov.remove(); };
    var img = document.createElement('img');
    img.src = url;
    img.style.cssText = 'max-width:100%;max-height:100%;object-fit:contain;';
    ov.appendChild(img);
    document.body.appendChild(ov);
}
let reelsTutorialShown = localStorage.getItem('trustfirst-reels-tutorial') === 'true';
let longPressTimer = null;
let isSpedUp = false;

/* ============================================================
   SENSITIVE CONTENT FILTER
   ============================================================ */
function checkSensitiveContent(videoEl, overlayContainer, reelData) {
    // Check if this clip was server-flagged (set a `is_sensitive` boolean in Supabase)
    var isSensitive = reelData && reelData.is_sensitive === true;
    if (!isSensitive) return;
    var existing = overlayContainer.querySelector('.tc-sensitive-overlay');
    if (existing) return;
    var ov = document.createElement('div');
    ov.className = 'tc-sensitive-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:50;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;backdrop-filter:blur(28px);-webkit-backdrop-filter:blur(28px);background:rgba(0,0,0,0.45);';
    ov.innerHTML =
        '<i class="fa-solid fa-eye-slash" style="font-size:40px;color:rgba(255,255,255,0.9);"></i>' +
        '<b style="font-size:18px;color:white;text-align:center;padding:0 24px;">Sensitive content</b>' +
        '<p style="font-size:13px;color:rgba(255,255,255,0.7);text-align:center;padding:0 32px;line-height:1.55;">This clip may contain content some people find disturbing.</p>' +
        '<button onclick="skipSensitiveVideo(this)" style="width:200px;padding:14px;border-radius:14px;background:#FF3B30;color:white;border:none;font-size:15px;font-weight:700;cursor:pointer;">Skip video</button>' +
        '<button onclick="watchSensitiveAnyway(this)" style="width:200px;padding:12px;border-radius:14px;background:transparent;color:rgba(255,255,255,0.65);border:1px solid rgba(255,255,255,0.25);font-size:14px;cursor:pointer;">Watch anyway</button>' +
        '<button onclick="openSensitiveLearnMore()" style="background:none;border:none;color:rgba(255,255,255,0.5);font-size:13px;cursor:pointer;text-decoration:underline;padding:0;">Learn more</button>';
    if (videoEl) videoEl.pause();
    overlayContainer.appendChild(ov);
}

function watchSensitiveAnyway(btn) {
    var ov = btn.closest('.tc-sensitive-overlay');
    if (ov) ov.remove();
    var videoEl = ov && ov.parentNode ? ov.parentNode.querySelector('video') : null;
    if (videoEl) videoEl.play().catch(function(){});
    triggerHaptic(10);
}

function skipSensitiveVideo(btn) {
    var ov = btn.closest('.tc-sensitive-overlay');
    if (ov) ov.remove();
    // Navigate to next reel
    var scroller = document.getElementById('reel-scroller') || document.getElementById('reelsViewport');
    if (scroller) scroller.scrollTop += scroller.clientHeight;
    triggerHaptic(10);
}

function openSensitiveLearnMore() {
    var existing = document.getElementById('sensitiveLearnMore');
    if (existing) existing.remove();
    var sheet = document.createElement('div');
    sheet.id = 'sensitiveLearnMore';
    sheet.style.cssText = 'position:fixed;inset:0;z-index:20000;display:flex;align-items:flex-end;background:rgba(0,0,0,0.6);backdrop-filter:blur(10px);';
    sheet.innerHTML =
        '<div style="width:100%;max-width:500px;margin:0 auto;background:var(--bg-primary,#fff);border-radius:22px 22px 0 0;padding:24px 24px 48px;animation:modalUp 0.35s cubic-bezier(0.32,0.72,0,1);">' +
            '<div style="width:36px;height:4px;background:#ccc;border-radius:2px;margin:0 auto 20px;"></div>' +
            '<b style="font-size:19px;color:var(--text-primary,#000);display:block;margin-bottom:12px;">Why this video is covered</b>' +
            '<p style="font-size:14px;color:#888;line-height:1.7;margin-bottom:12px;">TrustFirst uses a combination of human moderators and AI technology to identify content that may be disturbing, graphic, or emotionally difficult for some users.</p>' +
            '<p style="font-size:14px;color:#888;line-height:1.7;margin-bottom:20px;">This system works alongside our <b style="color:var(--text-primary,#000);">Community Guidelines</b> to help keep TrustFirst a safe space for everyone.</p>' +
            '<button onclick="document.getElementById(\'sensitiveLearnMore\').remove()" style="width:100%;padding:15px;border-radius:14px;background:#007AFF;color:white;border:none;font-size:15px;font-weight:700;cursor:pointer;">OK</button>' +
        '</div>';
    sheet.addEventListener('click', function(e){ if(e.target===sheet) sheet.remove(); });
    (document.getElementById('app') || document.body).appendChild(sheet);
}

