async function startCamera() {
    try {
        cameraStream = await navigator.mediaDevices.getUserMedia({
            video: { facingMode: isFrontCamera ? 'user' : 'environment', width: { ideal: 1080 }, height: { ideal: 1920 } },
            audio: true
        });
        const preview = document.getElementById('cameraPreview');
        if (preview) {
            preview.srcObject = cameraStream;
            if (isFrontCamera) preview.style.transform = 'scaleX(-1)';
        }
    } catch (err) {
        showToast('Camera permission needed');
        console.error('Camera error:', err);
    }
}

async function rotateCamera() {
    isFrontCamera = !isFrontCamera;
    if (cameraStream) {
        cameraStream.getTracks().forEach(t => t.stop());
    }
    await startCamera();
}

function cycleFlash() {
    const modes = ['off', 'on', 'auto'];
    const current = modes.indexOf(flashMode);
    flashMode = modes[(current + 1) % modes.length];

    const icon = document.getElementById('flashIcon');
    const btn = document.getElementById('flashBtn');

    if (flashMode === 'off') {
        icon.style.opacity = '0.4';
        showToast('Flash Off');
    } else if (flashMode === 'on') {
        icon.style.opacity = '1';
        icon.style.fill = '#FFD60A';
        showToast('Flash On');
    } else {
        icon.style.opacity = '1';
        icon.style.fill = 'white';
        showToast('Flash Auto');
    }

    // Apply torch if available
    if (cameraStream) {
        const track = cameraStream.getVideoTracks()[0];
        if (track.getCapabilities && track.getCapabilities().torch) {
            track.applyConstraints({ advanced: [{ torch: flashMode === 'on' }] });
        }
    }
}

function cycleTimer() {
    const options = [0, 3, 5, 10];
    const current = options.indexOf(timerSeconds);
    timerSeconds = options[(current + 1) % options.length];

    const badge = document.getElementById('timerBadge');
    if (badge) {
        badge.style.display = timerSeconds > 0 ? 'block' : 'none';
        badge.textContent = timerSeconds + 's';
    }
    showToast(timerSeconds > 0 ? `Timer: ${timerSeconds}s` : 'Timer Off');
}

function toggleFilterPanel() {
    const panel = document.getElementById('filterPanel');
    if (panel) panel.style.display = panel.style.display === 'none' ? 'block' : 'none';
}

function applyFilter(filterKey) {
    selectedFilter = filterKey;
    const preview = document.getElementById('cameraPreview');
    if (preview) {
        const baseTransform = isFrontCamera ? 'scaleX(-1)' : '';
        preview.style.filter = CAMERA_FILTERS[filterKey].css;
    }
}

function applyFunnyFilter(filterKey) {
    const preview = document.getElementById('cameraPreview');
    if (preview) {
        const base = isFrontCamera ? 'scaleX(-1)' : '';
        preview.style.transform = base + ' ' + FUNNY_FILTERS[filterKey].effect;
    }
}

let beautyMode = false;
function toggleBeautyMode() {
    beautyMode = !beautyMode;
    const preview = document.getElementById('cameraPreview');
    const btn = document.getElementById('beautyBtn');

    if (beautyMode) {
        preview.style.filter = (preview.style.filter || '') + ' brightness(1.08) contrast(0.95) saturate(1.1)';
        btn.style.background = 'rgba(0,122,255,0.5)';
        showToast('Beauty mode on');
    } else {
        applyFilter(selectedFilter);
        btn.style.background = 'rgba(0,0,0,0.3)';
        showToast('Beauty mode off');
    }
}

function toggleRecording() {
    if (timerSeconds > 0 && !isRecording) {
        startCountdown(() => startRecording());
        return;
    }

    if (isRecording) {
        stopRecording();
    } else {
        startRecording();
    }
}

function startCountdown(callback) {
    let count = timerSeconds;
    const overlay = document.getElementById('timerCountdown');
    const number = document.getElementById('countdownNumber');
    overlay.style.display = 'block';

    const tick = () => {
        if (count <= 0) {
            overlay.style.display = 'none';
            callback();
            return;
        }
        number.textContent = count;
        count--;
        setTimeout(tick, 1000);
    };
    tick();
}

function startRecording() {
    if (!cameraStream) return;
    isRecording = true;
    recordedChunks = [];

    const btn = document.getElementById('recordBtn');
    const inner = document.getElementById('recordInner');
    btn.style.background = 'rgba(255,59,48,0.3)';
    inner.style.width = '30px';
    inner.style.height = '30px';
    inner.style.borderRadius = '6px';

    mediaRecorder = new MediaRecorder(cameraStream, { mimeType: 'video/webm' });
    mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) recordedChunks.push(e.data);
    };
    mediaRecorder.onstop = () => {
        const blob = new Blob(recordedChunks, { type: 'video/webm' });
        showToast('Clip recorded!');
        // Here you'd navigate to an edit/post screen with the blob
    };
    mediaRecorder.start();
}

function stopRecording() {
    isRecording = false;
    if (mediaRecorder && mediaRecorder.state !== 'inactive') {
        mediaRecorder.stop();
    }

    const btn = document.getElementById('recordBtn');
    const inner = document.getElementById('recordInner');
    btn.style.background = 'transparent';
    inner.style.width = '60px';
    inner.style.height = '60px';
    inner.style.borderRadius = '50%';
}

function closeClipCamera() {
    if (cameraStream) {
        cameraStream.getTracks().forEach(t => t.stop());
        cameraStream = null;
    }

    const page = document.getElementById('clipCameraPage');
    if (page) page.remove();

    const navBar = document.querySelector('.bottom-nav, .nav-bar, #bottomNav');
    if (navBar) navBar.style.display = 'flex';

    if (typeof navigateTo === 'function') navigateTo('home');
}

function openGalleryPicker() {
    var input = document.createElement('input');
    input.type = 'file';
    input.accept = 'video/*,image/*';
    input.onchange = function(e) {
        var file = e.target.files[0];
        if (!file) return;
        if (file.size > 500 * 1024 * 1024) { showToast('File must be under 500 MB'); return; }
        window._lastPickedVideoSrc = URL.createObjectURL(file);
        window._lastRecordedBlob = null;
        if (typeof closeLgCam === 'function') closeLgCam();
        if (typeof closeClipCamera === 'function') closeClipCamera();
        showToast('Media selected ✓');
        openPreviewEditScreen();
    };
    input.click();
}

