function toggleAlgoOptions() {
    const menu = document.getElementById('algoOptionsMenu');
    menu.style.display = menu.style.display === 'none' ? 'block' : 'none';
}

function addAlgoTag(list, tag) {
    if (!algorithmPrefs[list].includes(tag)) {
        algorithmPrefs[list].push(tag);
        saveAlgoPrefs();
        showAlgorithmScreen();
    }
}

function removeAlgoTag(list, tag) {
    algorithmPrefs[list] = algorithmPrefs[list].filter(t => t !== tag);
    saveAlgoPrefs();
    showAlgorithmScreen();
}

function saveAlgoPrefs() {
    localStorage.setItem('trustfirst-algo', JSON.stringify(algorithmPrefs));
}

function showAddTagModal(list) {
    const color = list === 'seeMore' ? '#007AFF' : '#FF3B30';
    const modal = document.createElement('div');
    modal.id = 'addTagModal';
    modal.style.cssText = `
        position:fixed; top:0; left:0; right:0; bottom:0; z-index:10000;
        background:rgba(0,0,0,0.5); backdrop-filter:blur(10px);
        display:flex; align-items:center; justify-content:center;
    `;
    modal.innerHTML = `
        <div style="background:var(--card-bg); border-radius:20px; padding:24px; margin:20px; max-width:320px; width:100%;">
            <h3 style="font-size:18px; font-weight:700; color:var(--text-primary); margin-bottom:16px;">Add Topic</h3>
            <input id="newTagInput" type="text" placeholder="Enter a topic..." style="
                width:100%; padding:12px 16px; border-radius:12px; border:1px solid var(--border-color);
                background:var(--input-bg); font-size:15px; color:var(--text-primary); outline:none;
                box-sizing:border-box; margin-bottom:16px;
            " onkeydown="if(event.key==='Enter')addCustomTag('${list}')">
            <div style="display:flex; gap:10px;">
                <button onclick="document.getElementById('addTagModal').remove()" style="
                    flex:1; padding:12px; border-radius:12px; border:none;
                    background:var(--bg-secondary); color:var(--text-primary); font-size:15px; cursor:pointer;
                ">Cancel</button>
                <button onclick="addCustomTag('${list}')" style="
                    flex:1; padding:12px; border-radius:12px; border:none;
                    background:${color}; color:white; font-size:15px; font-weight:600; cursor:pointer;
                ">Add</button>
            </div>
        </div>
    `;
    modal.addEventListener('click', (e) => { if (e.target === modal) modal.remove(); });
    (document.getElementById('app') || document.body).appendChild(modal);
    setTimeout(() => document.getElementById('newTagInput').focus(), 100);
}

function addCustomTag(list) {
    const input = document.getElementById('newTagInput');
    const tag = input.value.trim();
    if (tag) {
        addAlgoTag(list, tag);
        document.getElementById('addTagModal').remove();
    }
}

function setAlgoPref(key, currentValue) {
    const options = key === 'politicalContent'
        ? ['show', 'limited', 'hide']
        : ['standard', 'off', 'strict'];
    const currentIndex = options.indexOf(algorithmPrefs[key]);
    algorithmPrefs[key] = options[(currentIndex + 1) % options.length];
    saveAlgoPrefs();
    showAlgorithmScreen();
    showToast(`${key === 'politicalContent' ? 'Political' : 'Sensitive'} content: ${algorithmPrefs[key]}`);
}

function closeAlgorithmScreen() {
    const page = document.getElementById('algorithmPage');
    if (page) page.remove();
    const navBar = document.querySelector('.bottom-nav, .nav-bar, #bottomNav');
    if (navBar) navBar.style.display = 'flex';
    if (typeof navigateTo === 'function') navigateTo('reels');
}

    // ============================================
// SILENT SECURITY SCANNER
// Runs daily in background, checks for issues
// ============================================
const SecurityScanner = {
    lastScan: localStorage.getItem('trustfirst-last-scan') || null,
    scanResults: JSON.parse(localStorage.getItem('trustfirst-scan-results') || '[]'),

    init() {
        const now = Date.now();
        const lastScan = this.lastScan ? parseInt(this.lastScan) : 0;
        const oneDayMs = 24 * 60 * 60 * 1000;

        if (now - lastScan > oneDayMs) {
            this.runScan();
        }

        // Schedule next scan
        setInterval(() => this.runScan(), oneDayMs);
    },

    async runScan() {
        console.debug('[SecurityScanner] Running silent scan...');
        const results = [];

        // Check 1: Password age
        const passwordAge = this.checkPasswordAge();
        if (passwordAge.issue) results.push(passwordAge);

        // Check 2: Suspicious login locations
        const loginCheck = await this.checkLoginLocations();
        if (loginCheck.issue) results.push(loginCheck);

        // Check 3: Unrecognized devices
        const deviceCheck = this.checkDevices();
        if (deviceCheck.issue) results.push(deviceCheck);

        // Check 4: Privacy settings review
        const privacyCheck = this.checkPrivacySettings();
        if (privacyCheck.issue) results.push(privacyCheck);

        // Check 5: Two-factor authentication
        const tfaCheck = this.checkTwoFactor();
        if (tfaCheck.issue) results.push(tfaCheck);

        // Check 6: Content scan (profile info check)
        const contentCheck = this.checkProfileContent();
        if (contentCheck.issue) results.push(contentCheck);

        this.scanResults = results;
        this.lastScan = Date.now().toString();
        localStorage.setItem('trustfirst-last-scan', this.lastScan);
        localStorage.setItem('trustfirst-scan-results', JSON.stringify(results));

        if (results.length > 0) {
            this.showSecurityNotification(results);
        }

        console.debug(`[SecurityScanner] Scan complete. ${results.length} issues found.`);
    },

    checkPasswordAge() {
        const changed = localStorage.getItem('trustfirst-password-changed');
        if (!changed) return { issue: false };
        const daysSince = (Date.now() - parseInt(changed)) / (1000 * 60 * 60 * 24);
        return daysSince > 90
            ? { issue: true, type: 'password', severity: 'medium', message: 'Password hasn\'t been changed in 90+ days' }
            : { issue: false };
    },

    async checkLoginLocations() {
        // Check Supabase for unusual login locations
        try {
            // This would query your login_activity table
            return { issue: false };
        } catch (e) {
            return { issue: false };
        }
    },

    checkDevices() {
        const devices = JSON.parse(localStorage.getItem('trustfirst-devices') || '[]');
        const untrusted = devices.filter(d => !d.trusted);
        return untrusted.length > 2
            ? { issue: true, type: 'devices', severity: 'high', message: `${untrusted.length} untrusted devices detected` }
            : { issue: false };
    },

    checkPrivacySettings() {
        const settings = JSON.parse(localStorage.getItem('trustfirst-privacy') || '{}');
        if (settings.private_account === false && settings.who_can_message === 'everyone') {
            return { issue: true, type: 'privacy', severity: 'low', message: 'Your account is public and anyone can message you' };
        }
        return { issue: false };
    },

    checkTwoFactor() {
        const tfa = localStorage.getItem('trustfirst-2fa-enabled');
        return !tfa
            ? { issue: true, type: '2fa', severity: 'high', message: 'Two-factor authentication is not enabled' }
            : { issue: false };
    },

    checkProfileContent() {
        // Check if bio contains potentially sensitive info like phone numbers
        const bio = localStorage.getItem('trustfirst-bio') || '';
        const phoneRegex = /\b\d{3}[-.]?\d{3}[-.]?\d{4}\b/;
        const emailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/;

        if (phoneRegex.test(bio)) {
            return { issue: true, type: 'content', severity: 'medium', message: 'Your bio contains a phone number' };
        }
        if (emailRegex.test(bio)) {
            return { issue: true, type: 'content', severity: 'low', message: 'Your bio contains an email address' };
        }
        return { issue: false };
    },

    showSecurityNotification(results) {
        const high = results.filter(r => r.severity === 'high').length;
        const medium = results.filter(r => r.severity === 'medium').length;

        if (high > 0 || medium > 1) {
            // Play soft notification sound
            playNotificationSound();

            // Show in-app notification (not system notification)
            const notif = document.createElement('div');
            notif.style.cssText = `
                position:fixed; top:50px; left:16px; right:16px; z-index:9999;
                background:var(--card-bg); border-radius:16px; padding:16px;
                box-shadow:0 10px 40px rgba(0,0,0,0.2);
                border:1px solid var(--border-color);
                animation:fadeInUp 0.3s ease;
                display:flex; align-items:center; gap:12px;
                cursor:pointer;
            `;
            notif.innerHTML = `
                <div style="width:40px; height:40px; border-radius:50%;
                    background:linear-gradient(135deg, #FF9500, #FF3B30);
                    display:flex; align-items:center; justify-content:center; flex-shrink:0;">
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="white">
                        <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/>
                    </svg>
                </div>
                <div style="flex:1;">
                    <div style="font-size:14px; font-weight:700; color:var(--text-primary);">Security Check</div>
                    <div style="font-size:12px; color:var(--text-secondary);">
                        ${results.length} item${results.length > 1 ? 's' : ''} need${results.length === 1 ? 's' : ''} attention
                    </div>
                </div>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="var(--text-tertiary)" stroke-width="2">
                    <path d="M9 18l6-6-6-6"/>
                </svg>
            `;
            notif.onclick = () => {
                notif.remove();
                showSecurityReport();
            };
            document.body.appendChild(notif);

            setTimeout(() => { if (notif.parentNode) notif.remove(); }, 8000);
        }
    }
};

function showSecurityReport() {
    const results = SecurityScanner.scanResults;
    const modal = document.createElement('div');
    modal.id = 'securityReportModal';
    modal.style.cssText = `
        position:fixed; top:0; left:0; right:0; bottom:0; z-index:10000;
        background:rgba(0,0,0,0.5); backdrop-filter:blur(10px);
        display:flex; align-items:flex-end; justify-content:center;
    `;
    modal.innerHTML = `
        <div style="background:var(--card-bg); border-radius:20px 20px 0 0; width:100%; max-width:500px;
            padding:24px 20px 40px; max-height:70vh; overflow-y:auto;">
            <div style="width:40px; height:4px; background:var(--text-tertiary); border-radius:2px; margin:0 auto 20px;"></div>
            <h2 style="font-size:20px; font-weight:800; color:var(--text-primary); margin-bottom:4px;">Security Report</h2>
            <p style="font-size:13px; color:var(--text-secondary); margin-bottom:20px;">
                Last scanned: ${new Date(parseInt(SecurityScanner.lastScan)).toLocaleDateString()}
            </p>
            ${results.length === 0 ? `
                <div style="text-align:center; padding:40px 0;">
                    <div style="font-size:48px; margin-bottom:12px;">✅</div>
                    <p style="color:var(--text-primary); font-size:16px; font-weight:600;">All clear!</p>
                    <p style="color:var(--text-secondary); font-size:14px;">No security issues found</p>
                </div>
            ` : results.map(r => `
                <div style="display:flex; gap:12px; padding:16px 0; border-bottom:1px solid var(--border-color);">
                    <div style="width:10px; height:10px; border-radius:50%; margin-top:5px; flex-shrink:0;
                        background:${r.severity === 'high' ? '#FF3B30' : r.severity === 'medium' ? '#FF9500' : '#FFCC00'};
                    "></div>
                    <div>
                        <div style="font-size:15px; font-weight:600; color:var(--text-primary);">${r.message}</div>
                        <div style="font-size:12px; color:var(--text-tertiary); margin-top:2px;">
                            ${r.severity.charAt(0).toUpperCase() + r.severity.slice(1)} priority
                        </div>
                    </div>
                </div>
            `).join('')}
            <button onclick="document.getElementById('securityReportModal').remove()" style="
                width:100%; padding:14px; border-radius:14px; border:none;
                background:#007AFF; color:white; font-size:16px; font-weight:600;
                cursor:pointer; margin-top:20px;
            ">Done</button>
        </div>
    `;
    modal.addEventListener('click', (e) => { if (e.target === modal) modal.remove(); });
    document.body.appendChild(modal);
}

// Premium notification sound
function playNotificationSound() {
    try {
        const ctx = new (window.AudioContext || window.webkitAudioContext)();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.frequency.setValueAtTime(880, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(660, ctx.currentTime + 0.15);
        gain.gain.setValueAtTime(0.1, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);
        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime + 0.3);
    } catch (e) {}
}

// Initialize on app load
SecurityScanner.init();

