function closeSoundHub() {
    stopSoundPreview();
    var p = document.getElementById('soundHubPage');
    if (p) p.remove();
    var reelOverlay = document.getElementById('reel-overlay');
    var reelsContainer = document.getElementById('reelsContainer');
    if (!(reelOverlay && reelOverlay.style.display !== 'none') && !reelsContainer) {
        showNavBar();
    }
}

var soundPreviewPlaying = false;
var soundPreviewCtx = null;
var soundPreviewOsc = null;

function toggleSoundPreview(btn) {
    if (soundPreviewPlaying) {
        stopSoundPreview();
        btn.innerHTML = '<i class="fa-solid fa-play" style="margin-left:3px;"></i>';
        btn.style.background = 'rgba(0,122,255,0.12)';
        btn.style.boxShadow = 'none';
        var disc = document.getElementById('soundDisc');
        if (disc) disc.style.animation = 'none';
        return;
    }
    try {
        soundPreviewCtx = new (window.AudioContext || window.webkitAudioContext)({ latencyHint: 'playback' });
// Route audio through speaker, not earpiece
if (soundPreviewCtx.destination && navigator.mediaDevices) {
    try {
        if (typeof soundPreviewCtx.setSinkId === 'function') {
            soundPreviewCtx.setSinkId('default');
        }
    } catch(e) { if (e) console.warn('[Suppressed error]', e); }
}
        soundPreviewOsc = soundPreviewCtx.createOscillator();
        var gain = soundPreviewCtx.createGain();
        soundPreviewOsc.connect(gain);
        gain.connect(soundPreviewCtx.destination);
        soundPreviewOsc.type = 'sine';
        var freqs = [261.63, 329.63, 392, 523.25, 659.25, 523.25, 392];
        freqs.forEach(function(f, i) {
            soundPreviewOsc.frequency.setValueAtTime(f, soundPreviewCtx.currentTime + i * 0.3);
        });
        gain.gain.setValueAtTime(0.12, soundPreviewCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, soundPreviewCtx.currentTime + 2.8);
        soundPreviewOsc.start(soundPreviewCtx.currentTime);
        soundPreviewOsc.stop(soundPreviewCtx.currentTime + 2.8);
        soundPreviewPlaying = true;

        btn.innerHTML = '<i class="fa-solid fa-stop"></i>';
        btn.style.background = 'rgba(0,122,255,0.25)';
        btn.style.boxShadow = '0 0 0 6px rgba(0,122,255,0.1)';

        var disc = document.getElementById('soundDisc');
        if (disc) disc.style.animation = 'spinRepost 3s linear infinite';

        setTimeout(function() {
            soundPreviewPlaying = false;
            if (btn) {
                btn.innerHTML = '<i class="fa-solid fa-play" style="margin-left:3px;"></i>';
                btn.style.background = 'rgba(0,122,255,0.12)';
                btn.style.boxShadow = 'none';
            }
            var disc2 = document.getElementById('soundDisc');
            if (disc2) disc2.style.animation = 'none';
        }, 2800);

    } catch(e) { showToast('Audio preview not available'); }
}

function stopSoundPreview() {
    if (soundPreviewOsc) { try { soundPreviewOsc.stop(); } catch(e) { if (e) console.warn('[Suppressed error]', e); } soundPreviewOsc = null; }
    if (soundPreviewCtx) { try { soundPreviewCtx.close(); } catch(e) { if (e) console.warn('[Suppressed error]', e); } soundPreviewCtx = null; }
    soundPreviewPlaying = false;
}

async function saveSoundToFavorites(name) {
    var saved = JSON.parse(localStorage.getItem('tf-saved-sounds') || '[]');
    var btn = document.querySelector('[onclick*="saveSoundToFavorites"]');
    if (!saved.includes(name)) {
        saved.push(name);
        localStorage.setItem('tf-saved-sounds', JSON.stringify(saved));
        if (btn) { btn.innerHTML = '<i class="fa-solid fa-bookmark"></i> Saved'; btn.style.color = '#007AFF'; btn.style.borderColor = '#007AFF'; }
        if (window.sb && currentUser && currentUser.id) {
            try {
                await sb.from('bookmarks').insert({ user_id: currentUser.id, sound_name: name, item_type: 'audio' });
            } catch(e) { /* non-critical */ }
        }
        showToast('Sound saved ✓');
    } else {
        saved = saved.filter(function(s) { return s !== name; });
        localStorage.setItem('tf-saved-sounds', JSON.stringify(saved));
        if (btn) { btn.innerHTML = '<i class="fa-regular fa-bookmark"></i> Save'; btn.style.color = ''; btn.style.borderColor = ''; }
        if (window.sb && currentUser && currentUser.id) {
            try {
                await sb.from('bookmarks').delete().eq('user_id', currentUser.id).eq('sound_name', name).eq('item_type', 'audio');
            } catch(e) { /* non-critical */ }
        }
        showToast('Removed from saved');
    }
    triggerHaptic(15);
}

function useAudioAndOpenCamera(trackName) {
    closeSoundHub();
    openLiquidGlassCamera(trackName);
}

