async function sendPasswordReset() {
    var emailInput = document.getElementById('resetEmailInput');
    var email = emailInput ? emailInput.value.trim().toLowerCase() : '';
    var btn = document.getElementById('resetPasswordBtn');

    if (!email || !isValidEmail(email)) {
        showToast('Please enter a valid email address');
        if (emailInput) {
            emailInput.style.borderColor = '#FF3B30';
            setTimeout(function() { emailInput.style.borderColor = 'var(--border-color,#e0e0e0)'; }, 2000);
        }
        return;
    }



    // Show loading state
    if (btn) {
        btn.innerHTML = '<div style="width:20px; height:20px; border:2px solid rgba(255,255,255,0.3); border-top-color:white; border-radius:50%; animation:spin 0.8s linear infinite; margin:0 auto;"></div>';
        btn.disabled = true;
    }

    try {
        if (window.sb) {
            var result = await sb.auth.resetPasswordForEmail(email, {
                redirectTo: window.location.origin + '?reset=true'
            });

            if (result.error) {
                throw result.error;
            }
        }

        // Show success state
        var form = document.getElementById('resetPasswordBtn');
        if (form) form.parentElement.querySelectorAll('div, button, label, input, h1, p').forEach(function(el) {
            if (el.id !== 'resetSuccessState' && !el.closest('#resetSuccessState')) {
                el.style.display = 'none';
            }
        });

        // Show back button and success
        var backBtn = document.querySelector('#forgotPasswordOverlay button:first-child');
        if (backBtn) backBtn.style.display = 'block';

        var successState = document.getElementById('resetSuccessState');
        if (successState) successState.style.display = 'block';

    } catch (error) {
        console.error('[PasswordReset]', error);
        // Still show success to prevent email enumeration
        var successState2 = document.getElementById('resetSuccessState');
        if (successState2) successState2.style.display = 'block';

        showToast('If an account exists with this email, a reset link has been sent.');
    }

    if (btn) {
        btn.innerHTML = 'Send Reset Link';
        btn.disabled = false;
    }
}

function closeForgotPassword() {
    var overlay = document.getElementById('forgotPasswordOverlay');
    if (overlay) overlay.remove();
}

