function buildInspirationTab() {
    var trends = [];
    if (window.sb) {
        sb.from('posts')
            .select('text_content')
            .eq('status','published')
            .order('created_at', { ascending: false })
            .limit(500)
            .then(function(r) {
                var counts = {};
                (r.data||[]).forEach(function(p) {
                    var matches = (p.text_content||'').match(/#[\w\u00C0-\u024F]+/g) || [];
                    matches.forEach(function(tag) {
                        counts[tag] = (counts[tag]||0) + 1;
                    });
                });
                var sorted = Object.keys(counts).sort(function(a,b){ return counts[b]-counts[a]; }).slice(0,6);
                if (!sorted.length) return;
                var el = document.getElementById('inspirationTabContent');
                if (!el) return;
                el.innerHTML = '<div style="margin-bottom:12px;"><b style="font-size:13px;font-weight:800;color:#888;text-transform:uppercase;letter-spacing:0.06em;">Trending Topics</b></div>' +
                    '<div style="display:flex;flex-direction:column;gap:10px;">' +
                    sorted.map(function(tag, i) {
                        var n = counts[tag];
                        var fmt = n >= 1000 ? (n/1000).toFixed(1)+'K' : String(n);
                        return '<div style="background:var(--card-bg,#fff);border-radius:18px;padding:14px 16px;border:0.5px solid var(--border-color,rgba(0,0,0,0.06));display:flex;align-items:center;gap:12px;">' +
                            '<div style="width:32px;height:32px;border-radius:50%;background:rgba(255,149,0,0.1);display:flex;align-items:center;justify-content:center;flex-shrink:0;">' +
                                '<b style="font-size:14px;color:#FF9500;">'+(i+1)+'</b>' +
                            '</div>' +
                            '<div style="flex:1;"><b style="font-size:14px;color:var(--text-primary,#000);">'+escapeHtml(tag)+'</b>' +
                            '<div style="display:flex;align-items:center;gap:6px;margin-top:2px;"><i class="fa-solid fa-fire" style="color:#FF6B35;font-size:10px;"></i><small style="color:#888;font-size:11px;">'+fmt+' posts</small></div></div>' +
                        '</div>';
                    }).join('') + '</div>';
            }).catch(function(){});
    }

    return '<div id="inspirationTabContent"><div style="text-align:center;padding:40px 20px;color:#888;"><i class="fa-solid fa-spinner fa-spin" style="font-size:22px;display:block;margin-bottom:12px;"></i><p>Loading trends...</p></div></div>';
}



    function openAdminFlags() {
    var reports = JSON.parse(localStorage.getItem('trustfirst-reports') || '[]');
    var pending = reports.filter(function(r) { return r.status === 'pending'; });

    var overlay = document.createElement('div');
    overlay.id = 'adminFlagsOverlay';
    overlay.className = 'white-overlay';
    overlay.style.display = 'block';
    overlay.style.zIndex = '7500';

    var html =
        '<div class="header-container">' +
        '<div class="liquid-glass-btn" onclick="document.getElementById(\'adminFlagsOverlay\').remove()">' +
        '<i class="fa-solid fa-chevron-left"></i></div>' +
        '<b>Content Flags (' + pending.length + ')</b><div></div></div>' +
        '<div style="padding:20px;">';

    if (pending.length === 0) {
        html += '<div style="text-align:center; padding:60px 20px; color:var(--text-tertiary,#999);">' +
            '<i class="fa-solid fa-check-circle" style="font-size:40px; color:#34C759; display:block; margin-bottom:15px;"></i>' +
            'No pending flags — all clear!</div>';
    } else {
        pending.forEach(function(report, i) {
            var reason = FLAG_REASONS.find(function(r) { return r.id === report.reason; }) || { label: report.reason, icon: 'fa-flag' };
            html +=
                '<div style="background:var(--card-bg,#fff); border:1px solid var(--border-color,#eee);' +
                'border-radius:16px; padding:16px; margin-bottom:12px;">' +
                '<div style="display:flex; align-items:center; gap:10px; margin-bottom:10px;">' +
                '<i class="fa-solid ' + reason.icon + '" style="color:#FF3B30;"></i>' +
                '<b style="flex:1;">' + reason.label + '</b>' +
                '<small style="color:var(--text-tertiary,#999);">' + new Date(report.timestamp).toLocaleDateString() + '</small></div>' +
                (report.details ? '<p style="font-size:13px; color:var(--text-secondary,#888); margin-bottom:10px;">' + escapeHtml(report.details) + '</p>' : '') +
                '<div style="display:flex; gap:8px;">' +
                '<button onclick="resolveFlag(' + i + ',\'dismissed\')" style="flex:1; padding:10px; border-radius:10px; border:none; background:var(--bg-secondary,#f5f5f5); color:var(--text-primary,#000); font-size:13px; font-weight:600; cursor:pointer;">Dismiss</button>' +
                '<button onclick="resolveFlag(' + i + ',\'actioned\')" style="flex:1; padding:10px; border-radius:10px; border:none; background:#FF3B30; color:white; font-size:13px; font-weight:600; cursor:pointer;">Take Action</button>' +
                '</div></div>';
        });
    }

    html += '</div>';
    overlay.innerHTML = html;
    document.getElementById('app').appendChild(overlay);
}

function resolveFlag(index, status) {
    var reports = JSON.parse(localStorage.getItem('trustfirst-reports') || '[]');
    var pending = reports.filter(function(r) { return r.status === 'pending'; });
    if (pending[index]) {
        pending[index].status = status;
        // Update in full list
        var fullIndex = reports.indexOf(pending[index]);
        if (fullIndex > -1) reports[fullIndex].status = status;
        localStorage.setItem('trustfirst-reports', JSON.stringify(reports));
    }
    document.getElementById('adminFlagsOverlay').remove();
    openAdminFlags();
    showToast(status === 'actioned' ? 'Action taken on report' : 'Report dismissed');
}

