async function submitBusinessEmail() {
    var email = (document.getElementById('biz-email') || {}).value || '';
    var name = (document.getElementById('biz-name') || {}).value || '';

    if (!name.trim()) { showToast('Enter your business name'); return; }
    if (!email.trim()) { showToast('Enter your business email'); return; }

    // Block free email providers
    var freeProviders = ['gmail.com','yahoo.com','hotmail.com','outlook.com',
        'icloud.com','aol.com','mail.com','protonmail.com','zoho.com','yandex.com'];
    var domain = email.split('@')[1];
    if (!domain || freeProviders.indexOf(domain.toLowerCase()) > -1) {
        showToast('Please use your business domain email, not a free provider');
        return;
    }

    // Also block if it's a gov email — redirect them
    if (isGovEmail(email)) {
        showToast('This looks like a government email. Please select Government account type.');
        return;
    }

    showToast('Verification email sent to ' + email + ' 📧');

    // Store pending verification
    secureSave('pending_biz_verify', {
        method: 'email',
        business_name: name,
        email: email,
        status: 'email_sent',
        timestamp: Date.now()
    });

    try {
        var verifyResp = await fetch('/api/email/send/', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': 'Bearer ' + (window._authToken || '')
            },
            body: JSON.stringify({
                to: email,
                subject: 'Verify your TrustFirst Business Account',
                html: '<h2>Verify your business</h2><p>Thanks for registering <b>' + escapeHtml(name) + '</b>. Our team will review your documents and verify your account within 24 hours.</p><p>You can continue using TrustFirst while we review.</p>'
            })
        });
        if (verifyResp.ok) {
            showToast('Verification email sent! Check your inbox.');
        }
    } catch(e) {}
    completeRegistration(true);
}

function handleBizDocUpload(input) {
    if (!input.files || !input.files[0]) return;
    var file = input.files[0];

    if (file.size > 10 * 1024 * 1024) {
        showToast('File too large. Maximum 10MB.');
        return;
    }

    var status = document.getElementById('bizDocStatus');
    if (status) {
        status.innerHTML = '<span style="color:#34C759;"><i class="fa-solid fa-check"></i> ' +
            file.name + ' uploaded</span>';
    }

    var btn = document.getElementById('bizDocSubmitBtn');
    if (btn) {
        btn.style.opacity = '1';
        btn.style.pointerEvents = 'all';
    }
}

function submitBusinessDoc() {
    var name = (document.getElementById('biz-name') || {}).value || '';
    var reg = (document.getElementById('biz-reg') || {}).value || '';

    if (!name.trim()) { showToast('Enter your business name'); return; }
    if (!reg.trim()) { showToast('Enter your registration number'); return; }

    secureSave('pending_biz_verify', {
        method: 'document',
        business_name: name,
        registration_number: reg,
        status: 'pending_review',
        timestamp: Date.now()
    });

    showToast('Document submitted for review! We\'ll verify within 24-48 hours.');
    setTimeout(function() { completeRegistration(false); }, 2000);
}

