function getBadgeHTML(accountType, verified) {
    if (!verified && accountType !== 'public_figure') {
        return '<span style="color:#888; font-size:11px; margin-left:4px;">(unverified)</span>';
    }

    var tier = BADGE_TIERS[accountType] || BADGE_TIERS.personal;
    return '<i class="fa-solid ' + tier.icon + ' ' + tier.cssClass + '" ' +
        'title="' + tier.label + '" style="font-size:14px; margin-left:4px;"></i>';
}

