// ============================================
// REAL-TIME SCORE TRACKING — LOG EVENTS
// ============================================
function logTrustEvent(type, data) {
    var events = JSON.parse(localStorage.getItem('tf-trust-events') || '[]');
    events.push({
        type: type,
        data: data || {},
        timestamp: Date.now()
    });
    // Keep last 500 events
    if (events.length > 500) events = events.slice(-500);
    localStorage.setItem('tf-trust-events', JSON.stringify(events));

    // Recalculate if score page is open
    if (document.getElementById('trust-score-overlay') &&
        document.getElementById('trust-score-overlay').style.display !== 'none') {
        renderTrustScore();
    }
}

// Track name changes
function trackNameChange(oldName, newName) {
    var changes = JSON.parse(localStorage.getItem('tf-name-changes') || '[]');
    changes.push({ from: oldName, to: newName, timestamp: Date.now() });
    localStorage.setItem('tf-name-changes', JSON.stringify(changes));
    logTrustEvent('name_change', { from: oldName, to: newName });
}

// Track posts
function trackNewPost(postText) {
    var history = JSON.parse(localStorage.getItem('tf-post-history') || '[]');
    history.push({ text: postText, timestamp: Date.now() });
    localStorage.setItem('tf-post-history', JSON.stringify(history));
    logTrustEvent('new_post', { length: postText.length });
    var analyticsStore = JSON.parse(localStorage.getItem('tf-analytics-posts') || '[]');
analyticsStore.unshift({ text: postText, ts: new Date().toISOString() });
localStorage.setItem('tf-analytics-posts', JSON.stringify(analyticsStore.slice(0, 200)));
}

// Track login
function trackLogin(success, suspicious) {
    var history = JSON.parse(localStorage.getItem('tf-login-history') || '[]');
    history.push({
        success: success,
        failed: !success,
        suspicious: suspicious || false,
        timestamp: Date.now()
    });
    localStorage.setItem('tf-login-history', JSON.stringify(history));
    if (!success) logTrustEvent('failed_login');
    if (suspicious) logTrustEvent('suspicious_login');
}

// Track reports received
function trackReportReceived(reason) {
    var reports = JSON.parse(localStorage.getItem('tf-user-reports') || '[]');
    reports.push({ reason: reason, timestamp: Date.now() });
    localStorage.setItem('tf-user-reports', JSON.stringify(reports));
    logTrustEvent('report_received', { reason: reason });
}

// Track replies
function trackReply() {
    var count = parseInt(localStorage.getItem('tf-replies') || '0');
    localStorage.setItem('tf-replies', String(count + 1));
    logTrustEvent('reply_sent');
}

// Track profile changes
function trackProfileChange() {
    var count = parseInt(localStorage.getItem('tf-profile-changes') || '0');
    localStorage.setItem('tf-profile-changes', String(count + 1));
    logTrustEvent('profile_change');
}

// ============================================
// QUICK TRUST BADGE FOR PROFILE/POSTS
// ============================================
function getTrustBadgeHTML() {
    var cached = secureLoad('trust-score-cache');
    if (!cached || typeof cached !== 'object' || !cached.total) {
        cached = calculateTrustScore();
    }

    var tier = cached.tier || getTrustTier(cached.total || 0);
    return '<span style="display:inline-flex; align-items:center; gap:4px; padding:2px 8px; ' +
        'background:' + tier.color + '15; border-radius:8px; font-size:11px; font-weight:700; color:' + tier.color + ';">' +
        '<i class="fa-solid ' + tier.icon + '" style="font-size:10px;"></i> ' + cached.total + '</span>';
}

    function navigateTo(page) {
    if (page === 'home' && typeof resetNav === 'function') {
        resetNav();
    } else if (page === 'reels' && typeof showReelsPage === 'function') {
        showReelsPage();
    } else if (typeof switchTab === 'function') {
        switchTab(page);
    }
}

 // ==========================================================================
// TRUSTFIRST — REAL DATA LAYER
// Paste at the END of your script, after all existing code
// ==========================================================================

var RealData = {

    async createPost(text, mediaUrl, mediaType) {
        var client = window._sb || window.sb;
if (!client) { showToast('Not connected'); return null; }
var { data: { session } } = await client.auth.getSession();
if (!session) { showToast('Please log in'); return null; }

        var { data, error } = await sb.from('posts').insert({
            user_id: session.user.id,
            text_content: text,
            media_url: mediaUrl || null,
            media_type: mediaType || null,
            status: 'published',
            is_hidden: false
        }).select('*, users:user_id (id, full_name, username, avatar_url, badge_tier, verified)').single();

        if (error) { showToast('Post failed: ' + error.message); return null; }
        return data;
    },

    async getFeed(page, limit) {
        page = page || 1; limit = limit || 20;
        var client = window._sb || window.sb;
if (!client) return [];
var { data: { session } } = await client.auth.getSession();
if (!session) return [];
var userId = session.user.id;
        var offset = (page - 1) * limit;

        var followRes = await client.from('follows').select('following_id').eq('follower_id', userId);
        var followIds = (followRes.data || []).map(function(f) { return f.following_id; });
        followIds.push(userId);

        var { data, error } = await client.from('posts')
            .select('*, users:user_id (id, full_name, username, avatar_url, badge_tier, verified), quoted_post:quoted_post_id (id, text_content, media_url, users:user_id (full_name, username, avatar_url))')
            .in('user_id', followIds)
            .eq('is_hidden', false)
            .order('created_at', { ascending: false })
            .range(offset, offset + limit - 1);

        if (error) { console.error('[Feed]', error); return []; }

        var postIds = (data || []).map(function(p) { return p.id; });
        if (postIds.length === 0) return [];

        var likeRes = await client.from('likes').select('post_id').eq('user_id', userId).in('post_id', postIds);
        var likedIds = (likeRes.data || []).map(function(l) { return l.post_id; });

        var bmRes = await client.from('bookmarks').select('post_id').eq('user_id', userId).in('post_id', postIds);
        var bookmarkedIds = (bmRes.data || []).map(function(b) { return b.post_id; });

        return (data || []).map(function(p) {
            p._liked = likedIds.indexOf(p.id) > -1;
            p._bookmarked = bookmarkedIds.indexOf(p.id) > -1;
            return p;
        });
    },

    async getDiscoverFeed(page, limit) {
        page = page || 1; limit = limit || 20;
        var offset = (page - 1) * limit;
        var { data, error } = await sb.from('posts')
            .select('*, users:user_id (id, full_name, username, avatar_url, badge_tier, verified)')
            .eq('is_hidden', false)
            .order('created_at', { ascending: false })
            .range(offset, offset + limit - 1);
        return data || [];
    },

    async toggleLike(postId) {
        var session = await DB.getSession();
        if (!session) return;
        var userId = session.user.id;
        var check = await sb.from('likes').select('id').eq('user_id', userId).eq('post_id', postId).maybeSingle();
        if (check.data) {
            await sb.from('likes').delete().eq('id', check.data.id);
            var cur = await sb.from('posts').select('like_count').eq('id', postId).single();
            await sb.from('posts').update({ like_count: Math.max(0, (cur.data?.like_count || 1) - 1) }).eq('id', postId);
            return false;
        } else {
            await sb.from('likes').insert({ user_id: userId, post_id: postId });
            var cur = await sb.from('posts').select('like_count').eq('id', postId).single();
            await sb.from('posts').update({ like_count: (cur.data?.like_count || 0) + 1 }).eq('id', postId);
            return true;
        }
    },

    async toggleBookmark(postId) {
        var session = await DB.getSession();
        if (!session) return;
        var userId = session.user.id;
        var check = await sb.from('bookmarks').select('id').eq('user_id', userId).eq('post_id', postId).maybeSingle();
        if (check.data) {
            await sb.from('bookmarks').delete().eq('id', check.data.id);
            return false;
        } else {
            await sb.from('bookmarks').insert({ user_id: userId, post_id: postId });
            return true;
        }
    },

    async toggleFollow(targetUserId) {
        var session = await DB.getSession();
        if (!session) return;
        var userId = session.user.id;
        if (userId === targetUserId) return;
        var check = await sb.from('follows').select('id').eq('follower_id', userId).eq('following_id', targetUserId).maybeSingle();
        if (check.data) {
            await sb.from('follows').delete().eq('id', check.data.id);
            return false;
        } else {
            await sb.from('follows').insert({ follower_id: userId, following_id: targetUserId });
            return true;
        }
    },

    async postComment(postId, text) {
        var session = await DB.getSession();
        if (!session) return null;
        var { data, error } = await sb.from('comments').insert({
            user_id: session.user.id,
            post_id: postId,
            text_content: text
        }).select('*, users:user_id (full_name, username, avatar_url, badge_tier, verified)').single();
        if (error) { console.error('[Comment]', error); return null; }
        return data;
    },

    async getComments(postId) {
        var { data } = await sb.from('comments')
            .select('*, users:user_id (full_name, username, avatar_url, badge_tier, verified)')
            .eq('post_id', postId)
            .eq('is_hidden', false)
            .order('created_at', { ascending: false })
            .limit(50);
        return data || [];
    },

    async getNotifications() {
        var session = await DB.getSession();
        if (!session) return [];
        var { data } = await sb.from('notifications')
            .select('*, actor:actor_id (full_name, username, avatar_url, badge_tier)')
            .eq('user_id', session.user.id)
            .order('created_at', { ascending: false })
            .limit(50);
        return data || [];
    },

    async markNotificationsRead() {
        var session = await DB.getSession();
        if (!session) return;
        await sb.from('notifications')
            .update({ read: true })
            .eq('user_id', session.user.id)
            .eq('read', false);
    },

    async getCounts(userId) {
        var followers = await sb.from('follows').select('id', { count: 'exact', head: true }).eq('following_id', userId);
        var following = await sb.from('follows').select('id', { count: 'exact', head: true }).eq('follower_id', userId);
        var posts = await sb.from('posts').select('id', { count: 'exact', head: true }).eq('user_id', userId).eq('is_hidden', false);
        return {
            followers: followers.count || 0,
            following: following.count || 0,
            posts: posts.count || 0
        };
    },

    async searchUsers(query) {
        if (!query) return [];
        var { data } = await sb.from('users')
            .select('id, full_name, username, avatar_url, badge_tier, verified')
            .or('username.ilike.%' + query + '%,full_name.ilike.%' + query + '%')
            .limit(20);
        return data || [];
    },

    async getUserPosts(userId) {
        var { data } = await sb.from('posts')
            .select('*, users:user_id (id, full_name, username, avatar_url, badge_tier, verified)')
            .eq('user_id', userId)
            .eq('is_hidden', false)
            .order('created_at', { ascending: false })
            .limit(50);
        return data || [];
    },

    async getBookmarkedPosts() {
        var session = await DB.getSession();
        if (!session) return [];
        var { data: bms } = await sb.from('bookmarks').select('post_id').eq('user_id', session.user.id).order('created_at', { ascending: false });
        if (!bms || bms.length === 0) return [];
        var postIds = bms.map(function(b) { return b.post_id; });
        var { data } = await sb.from('posts')
            .select('*, users:user_id (id, full_name, username, avatar_url, badge_tier, verified)')
            .in('id', postIds)
            .eq('is_hidden', false);
        return data || [];
    },

    async deletePost(postId) {
        var session = await DB.getSession();
        if (!session) return false;
        var { error } = await sb.from('posts').delete().eq('id', postId).eq('user_id', session.user.id);
        return !error;
    },

    async reportContent(contentId, contentType, reason, details) {
        var session = await DB.getSession();
        if (!session) return false;
        var { error } = await sb.from('content_reports').insert({
            reporter_id: session.user.id,
            content_id: contentId,
            content_type: contentType,
            reason: reason,
            details: details || ''
        });
        return !error;
    }
};

// ==========================================================================
// HELPER: Time ago
// ==========================================================================
function getTimeAgo(dateStr) {
    var diff = (Date.now() - new Date(dateStr).getTime()) / 1000;
    if (diff < 60) return 'now';
    if (diff < 3600) return Math.floor(diff / 60) + 'm';
    if (diff < 86400) return Math.floor(diff / 3600) + 'h';
    if (diff < 604800) return Math.floor(diff / 86400) + 'd';
    return new Date(dateStr).toLocaleDateString();
}

// ==========================================================================
// RENDER REAL POST CARD
// ==========================================================================
function renderRealPostCard(post) {
    var user = post.users || {};
    var card = document.createElement('div');
    card.className = 'post-card';
    card.setAttribute('data-post-id', post.id);
    card.setAttribute('data-user-id', user.id || post.user_id);
    card.style.animation = 'popIn 0.4s ease';

    var timeAgo = typeof getTimeAgo === 'function' ? getTimeAgo(post.created_at) : 'now';
    var avatarUrl = user.avatar_url || 'https://ui-avatars.com/api/?name=' + encodeURIComponent(user.full_name || 'U') + '&background=007AFF&color=fff';
    var displayName = user.full_name || user.username || 'User';
    var handle = '@' + (user.username || 'user');
    var badgeClass = user.badge_tier || 'verify-blue';
    var likedClass = post._liked ? 'fa-solid' : 'fa-regular';
    var likedColor = post._liked ? 'color:#FF3B30;' : '';
    var bookmarkClass = post._bookmarked ? 'fa-solid' : 'fa-regular';
    var bookmarkColor = post._bookmarked ? 'color:#007AFF;' : '';
    var likeCount = post.like_count || 0;
    var commentCount = post.comment_count || 0;
    var repostCount = post.repost_count || 0;

    // Apply algorithm filters
    var _algoPrefs = JSON.parse(localStorage.getItem('trustfirst-algo') || '{}');
    var _postText = (post.text_content || '').toLowerCase();
    var _politicalKeywords = ['election','politics','government','democrat','republican','politician','vote','ballot','parliament','president','minister','anc','da ','eff ','party '];
    var _sensitiveKeywords = ['nudity','explicit','adult','nsfw','18+','sexual','gore','violence'];
    if (_algoPrefs.politicalContent === 'hide' && _politicalKeywords.some(function(k){ return _postText.includes(k); })) return document.createElement('div');
    if (_algoPrefs.sensitiveContent === 'strict' && _sensitiveKeywords.some(function(k){ return _postText.includes(k); })) return document.createElement('div');
    if (_algoPrefs.politicalContent === 'show') { /* boost — no filter */ }

    // Check follow state
    var followedUsers = JSON.parse(localStorage.getItem('tf-followed-users') || '[]');
    var isFollowing = followedUsers.indexOf(user.id || post.user_id) > -1;
    var isOwnPost = currentUser && currentUser.id === (user.id || post.user_id);

    // Build interactive block
    var interactiveHTML = '';
    if (post.post_type && post.post_type !== 'text') {
        var options = post.poll_options || [];
        var votes = post.poll_votes || {};
        var total = Object.values(votes).reduce(function(a, b) { return Number(a) + Number(b); }, 0);

        if (post.post_type === 'poll') {
            var voted = localStorage.getItem('poll_voted_' + post.id);
            if (voted !== null) {
                var bars = options.map(function(opt, i) {
                    var count = votes[i] || 0;
                    var pct = total > 0 ? Math.round((count / total) * 100) : 0;
                    var isVoted = i === parseInt(voted);
                    return '<div style="margin-bottom:10px;"><div style="display:flex;justify-content:space-between;margin-bottom:4px;">' +
                        '<span style="font-size:14px;font-weight:' + (isVoted ? '700' : '400') + ';color:' + (isVoted ? '#007AFF' : 'var(--text-primary,#000)') + ';">' + (isVoted ? '✓ ' : '') + escapeHtml(opt) + '</span>' +
                        '<span style="font-size:13px;color:#888;">' + pct + '%</span></div>' +
                        '<div style="height:6px;background:var(--bg-secondary,#f0f0f0);border-radius:3px;overflow:hidden;">' +
                        '<div style="height:100%;width:' + pct + '%;background:' + (isVoted ? '#007AFF' : '#ccc') + ';border-radius:3px;transition:width 0.8s;"></div></div></div>';
                }).join('');
                interactiveHTML = '<div style="padding:14px;background:var(--bg-secondary,#f9f9f9);border-radius:16px;margin-bottom:12px;"><div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;"><i class="fa-solid fa-chart-bar" style="color:#007AFF;"></i><span style="font-size:13px;font-weight:700;color:#007AFF;">Poll Results</span></div>' + bars + '<small style="color:#888;font-size:12px;">' + total + ' vote' + (total !== 1 ? 's' : '') + '</small></div>';
            } else {
                var buttons = options.map(function(opt, i) {
                    return '<button onclick="votePoll(\'' + post.id + '\',' + i + ')" style="width:100%;padding:12px;border-radius:12px;border:1.5px solid #007AFF;background:transparent;color:#007AFF;font-size:14px;font-weight:600;cursor:pointer;margin-bottom:8px;text-align:left;">'+escapeHtml(opt)+'</button>';
                }).join('');
                interactiveHTML = '<div style="padding:14px;background:var(--bg-secondary,#f9f9f9);border-radius:16px;margin-bottom:12px;"><div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;"><i class="fa-solid fa-chart-bar" style="color:#007AFF;"></i><span style="font-size:13px;font-weight:700;color:#007AFF;">Poll · Tap to vote</span></div>' + buttons + '<small style="color:#888;font-size:12px;">' + total + ' vote' + (total !== 1 ? 's' : '') + ' so far</small></div>';
            }
        } else if (post.post_type === 'quiz') {
            var correct = post.quiz_correct_answer || 0;
            var answered = localStorage.getItem('quiz_answered_' + post.id);
            if (answered !== null) {
                var wasRight = parseInt(answered) === correct;
                var optHTML = options.map(function(opt, i) {
                    var border = '#eee', bg = 'transparent', color = 'var(--text-primary,#000)', icon = '';
                    if (i === correct) { border='#34C759'; bg='rgba(52,199,89,0.1)'; color='#34C759'; icon='<i class="fa-solid fa-check" style="color:#34C759;"></i>'; }
                    else if (i === parseInt(answered)) { border='#FF3B30'; bg='rgba(255,59,48,0.1)'; color='#FF3B30'; icon='<i class="fa-solid fa-xmark" style="color:#FF3B30;"></i>'; }
                    return '<div style="padding:12px;border-radius:12px;border:1.5px solid '+border+';background:'+bg+';margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;"><span style="font-size:14px;color:'+color+';font-weight:'+(i===correct?'700':'400')+';">'+escapeHtml(opt)+'</span>'+icon+'</div>';
                }).join('');
                interactiveHTML = '<div style="padding:14px;background:var(--bg-secondary,#f9f9f9);border-radius:16px;margin-bottom:12px;"><div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;"><i class="fa-solid fa-circle-question" style="color:'+(wasRight?'#34C759':'#FF3B30')+';"></i><span style="font-size:13px;font-weight:700;color:'+(wasRight?'#34C759':'#FF3B30')+'">'+(wasRight?'🎉 Correct!':'❌ Wrong answer')+'</span></div>' + optHTML + '</div>';
            } else {
                var qButtons = options.map(function(opt, i) {
                    return '<button onclick="answerQuiz(\''+post.id+'\','+i+','+correct+')" style="width:100%;padding:12px;border-radius:12px;border:1.5px solid #5856D6;background:transparent;color:#5856D6;font-size:14px;font-weight:600;cursor:pointer;margin-bottom:8px;text-align:left;">'+escapeHtml(opt)+'</button>';
                }).join('');
                interactiveHTML = '<div style="padding:14px;background:var(--bg-secondary,#f9f9f9);border-radius:16px;margin-bottom:12px;"><div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;"><i class="fa-solid fa-circle-question" style="color:#5856D6;"></i><span style="font-size:13px;font-weight:700;color:#5856D6;">Quiz · Pick your answer</span></div>' + qButtons + '</div>';
            }
        } else if (post.post_type === 'question') {
            interactiveHTML = '<div style="padding:14px;background:linear-gradient(135deg,rgba(0,122,255,0.05),rgba(88,86,214,0.05));border-radius:16px;margin-bottom:12px;border:1px solid rgba(0,122,255,0.12);"><div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;"><i class="fa-solid fa-comment-dots" style="color:#007AFF;"></i><span style="font-size:13px;font-weight:700;color:#007AFF;">Question · Share your answer</span></div><button onclick="openAnswerSheet(\''+post.id+'\')" style="width:100%;padding:12px;border-radius:12px;border:1.5px solid #007AFF;background:transparent;color:#007AFF;font-size:14px;font-weight:600;cursor:pointer;">✍️ Write your answer</button></div>';
        }
    }

    card.innerHTML =
        '<div class="post-header">' +
            '<img src="' + escapeHtml(avatarUrl) + '" class="post-avatar" onclick="viewUserProfile(\'' + (user.id || post.user_id) + '\')" style="cursor:pointer;">' +
            '<div style="flex:1;min-width:0;">' +
                '<div class="post-info"><b style="display:flex;align-items:center;gap:4px;">' +
                    '<span class="clickable-user" onclick="viewUserProfile(\'' + (user.id || post.user_id) + '\')">' + escapeHtml(displayName) + '</span>' +
                    (user.verified ? '<i class="fa-solid fa-circle-check ' + badgeClass + '" style="font-size:12px;"></i>' : '') +
                '</b></div>' +
                '<div class="post-info"><small>' + escapeHtml(handle) + ' · ' + timeAgo + '</small></div>' +
            '</div>' +
            (!isOwnPost ? '<button class="feed-follow-btn' + (isFollowing ? ' following' : '') + '" onclick="realToggleFollow(this,\'' + (user.id || post.user_id) + '\')" style="flex-shrink:0;">' + (isFollowing ? 'Following' : 'Follow') + '</button>' : '') +
            '<i class="fa-solid fa-ellipsis" style="margin-left:8px;padding:5px;cursor:pointer;flex-shrink:0;" onclick="openPostMenu(\'' + post.id + '\',\'' + (user.id || post.user_id) + '\')"></i>' +
        '</div>' +
        (function() {
            var txt = post.text_content || '';
            var musicMatch = txt.match(/^([\s\S]*?)\n\n🎵\s+(.+?)\s+—\s+(.+)$/);
            if (musicMatch) {
                var bodyText = musicMatch[1].trim();
                var mName = musicMatch[2].trim();
                var mArtist = musicMatch[3].trim();
                var musicBubble =
                    '<div onclick="openPostThoughtViewer(this,\'' + escapeHtml(post.id) + '\')" style="display:flex;align-items:center;gap:10px;background:rgba(0,122,255,0.06);border:0.5px solid rgba(0,122,255,0.15);border-radius:18px;padding:10px 14px;margin:4px 16px 8px;cursor:pointer;">' +
                        '<div style="width:40px;height:40px;border-radius:50%;background:linear-gradient(135deg,#007AFF,#5856D6);display:flex;align-items:center;justify-content:center;flex-shrink:0;box-shadow:0 2px 8px rgba(0,122,255,0.3);">' +
                            '<i class="fa-solid fa-music" style="color:white;font-size:16px;"></i>' +
                        '</div>' +
                        '<div style="flex:1;min-width:0;">' +
                            '<b style="font-size:13px;color:var(--text-primary,#000);display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(mName) + '</b>' +
                            '<small style="color:#888;font-size:11px;">' + escapeHtml(mArtist) + '</small>' +
                        '</div>' +
                        '<div style="display:flex;align-items:flex-end;gap:2px;height:20px;flex-shrink:0;" id="postMusicBars_' + escapeHtml(post.id) + '">' +
                            [8,14,6,18,10,14,6].map(function(h){ return '<div style="width:3px;height:'+h+'px;background:#007AFF;border-radius:2px;animation:soundPulse 0.8s ease-in-out infinite;animation-delay:'+( Math.floor(Math.random()*5)*0.1)+'s;"></div>'; }).join('') +
                        '</div>' +
                    '</div>';
                return (bodyText ? '<div class="post-content">' + (typeof formatPostText === 'function' ? formatPostText(bodyText) : escapeHtml(bodyText)) + '</div>' : '') + musicBubble;
            }
            return txt ? '<div class="post-content">' + (typeof formatPostText === 'function' ? formatPostText(txt) : escapeHtml(txt).replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" target="_blank" rel="noopener noreferrer" style="color:#007AFF;text-decoration:underline;">$1</a>')) + '</div>' : '';
        })() +
        (post.media_url ? '<div class="post-media-box"><img src="' + escapeHtml(post.media_url) + '" class="post-img" loading="lazy" onerror="this.closest(\'.post-media-box\').style.display=\'none\'"></div>' : '') +
        interactiveHTML +
        '<div class="post-icons">' +
            '<div onclick="realToggleLike(this,\'' + post.id + '\')" data-liked="' + (post._liked ? 'true' : 'false') + '">' +
                '<i class="' + likedClass + ' fa-heart" style="' + likedColor + '"></i> ' +
                '<span style="font-size:13px;color:#888;">' + likeCount + '</span>' +
            '</div>' +
            '<div onclick="realOpenComments(\'' + post.id + '\')">' +
                '<i class="fa-regular fa-comment"></i>' +
                ' <span style="font-size:13px;color:#888;">' + commentCount + '</span>' +
            '</div>' +
            '<div onclick="handleRepost(\'' + post.id + '\')">' +
    '<i class="fa-solid fa-retweet"></i>' +
    ' <span style="font-size:13px;color:#888;">' + repostCount + '</span>' +
'</div>' +
'<div onclick="realToggleBookmark(this,\'' + post.id + '\')" data-bookmarked="' + (post._bookmarked ? 'true' : 'false') + '">' +
    '<i class="' + bookmarkClass + ' fa-bookmark" style="' + bookmarkColor + '"></i>' +
'</div>' +
'<div onclick="openShare(\'' + post.id + '\')"><i class="fa-solid fa-share-nodes"></i></div>' +
        '</div>';

    // Track view when post scrolls into viewport — deduplicated per session
    if (post.id && !String(post.id).startsWith('local_') && window.sb && currentUser) {
        var _viewedKey = 'tf_viewed_' + currentUser.id;
        var _viewedSet = JSON.parse(localStorage.getItem(_viewedKey) || '[]');
        if (_viewedSet.indexOf(post.id) === -1) {
            var viewObserver = new IntersectionObserver(function(entries, obs) {
                if (entries[0].isIntersecting) {
                    obs.disconnect();
                    var _viewed = JSON.parse(localStorage.getItem(_viewedKey) || '[]');
                    if (_viewed.indexOf(post.id) !== -1) return; // double-check
                    _viewed.push(post.id);
                    if (_viewed.length > 500) _viewed = _viewed.slice(-500); // keep list lean
                    localStorage.setItem(_viewedKey, JSON.stringify(_viewed));
                    sb.from('posts').update({ view_count: (post.view_count || 0) + 1 }).eq('id', post.id).then(function(){});
                }
            }, { threshold: 0.5 });
            viewObserver.observe(card);
        }
    }
    return card;
}

function openPostThoughtViewer(el, postId) {
    // Parse music name from the sticker label inside the clicked element
    var nameEl = el.querySelector('b');
    var artistEl = el.querySelector('small');
    var mName = nameEl ? nameEl.textContent : 'Song';
    var mArtist = artistEl ? artistEl.textContent : '';
    // Get the post text if any
    var card = el.closest('[data-post-id]');
    var textEl = card ? card.querySelector('.post-content') : null;
    var thoughtText = textEl ? textEl.textContent.trim() : '';
    openThoughtViewer(thoughtText || '🎵', mName + ' — ' + mArtist, { name: mName, artist: mArtist, artUrl: null, previewUrl: null });
}

// Format post text — linkify hashtags and mentions
function formatPostText(text) {
    if (!text) return '';
    var safe = escapeHtml(text);
    safe = safe.replace(/#(\w+)/g, '<span onclick="searchHashtag(\'$1\')" style="color:#007AFF;font-weight:600;cursor:pointer;">#$1</span>');
    safe = safe.replace(/@(\w+)/g, '<span onclick="viewUserByUsername(\'$1\')" style="color:#007AFF;font-weight:600;cursor:pointer;">@$1</span>');
    return safe;
}

function searchHashtag(tag) {
    navOpenSearch();
    setTimeout(function() {
        var input = document.getElementById('navSearchInput');
        if (input) {
            input.value = '#' + tag;
            handleNavSearch('#' + tag);
        }
    }, 400);
}

async function viewUserByUsername(username) {
    if (window.sb) {
        var result = await sb.from('users').select('id').eq('username', username.toLowerCase()).maybeSingle();
        if (result.data) { viewUserProfile(result.data.id); return; }
    }
    showToast('@' + username);
}

// ==========================================================================
// REAL LIKE TOGGLE
// ==========================================================================
async function realToggleLike(el, postId) {
    if (!canPerformAction('like a post')) return;
    var icon = el.querySelector('i') || el.querySelector('svg');
    var count = el.querySelector('span');
    var liked = el.getAttribute('data-liked') === 'true';
    var prevCount = count ? parseInt(count.textContent) || 0 : 0;
    triggerHaptic(30);

    // Optimistic UI
    if (liked) {
        if (icon?.classList) { icon.className = 'fa-regular fa-heart'; icon.style.color = ''; }
        if (count) count.textContent = Math.max(0, prevCount - 1);
        el.setAttribute('data-liked', 'false');
    } else {
        if (icon?.classList) { icon.className = 'fa-solid fa-heart'; icon.style.color = '#FF3B30'; }
        if (count) count.textContent = prevCount + 1;
        el.setAttribute('data-liked', 'true');
    }

    var result = await RealData.toggleLike(postId);
    if (result === undefined) {
        // Rollback on auth failure
        if (liked) {
            if (icon?.classList) { icon.className = 'fa-solid fa-heart'; icon.style.color = '#FF3B30'; }
            if (count) count.textContent = prevCount;
            el.setAttribute('data-liked', 'true');
        } else {
            if (icon?.classList) { icon.className = 'fa-regular fa-heart'; icon.style.color = ''; }
            if (count) count.textContent = prevCount;
            el.setAttribute('data-liked', 'false');
        }
    }
}

// ==========================================================================
// REAL BOOKMARK TOGGLE
// ==========================================================================
async function realToggleBookmark(el, postId) {
    if (!canPerformAction('bookmark')) return;
    var icon = el.querySelector('i');
    var bookmarked = el.getAttribute('data-bookmarked') === 'true';
    triggerHaptic(15);

    // Optimistic UI
    if (bookmarked) {
        icon.className = 'fa-regular fa-bookmark'; icon.style.color = '';
        el.setAttribute('data-bookmarked', 'false');
    } else {
        icon.className = 'fa-solid fa-bookmark'; icon.style.color = '#007AFF';
        el.setAttribute('data-bookmarked', 'true');
    }

    try {
        var result = await RealData.toggleBookmark(postId);
        if (result === undefined) throw new Error('auth');
        // Silent success — no toast needed for bookmark
    } catch(e) {
        // Rollback
        if (bookmarked) {
            icon.className = 'fa-solid fa-bookmark'; icon.style.color = '#007AFF';
            el.setAttribute('data-bookmarked', 'true');
        } else {
            icon.className = 'fa-regular fa-bookmark'; icon.style.color = '';
            el.setAttribute('data-bookmarked', 'false');
        }
        showToast('Could not save. Try again.');
    }
}

// ==========================================================================
// REAL COMMENTS
// ==========================================================================
currentCommentPostId = null;

async function realOpenComments(postId) {
    if (!currentUser) return;
    currentCommentPostId = postId;

    var overlay = document.getElementById('comment-overlay');
    if (overlay) overlay.style.display = 'flex';

    var list = document.getElementById('comment-list');
    if (list) list.innerHTML = '<div style="text-align:center;padding:30px;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;font-size:20px;"></i></div>';

    var comments = await RealData.getComments(postId);
    if (!list) return;

    if (comments.length === 0) {
        list.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">' +
            '<i class="fa-regular fa-comment" style="font-size:30px;color:#ccc;display:block;margin-bottom:10px;"></i>' +
            'No comments yet. Be the first!</div>';
        return;
    }

    list.innerHTML = '';

    // Fetch like counts + current user's liked state for all comments in one query
    var likeCountMap = {};
    var userLikedSet = new Set();
    if (window.sb && currentUser && comments.length) {
        try {
            var cIds = comments.map(function(c) { return c.id; });
            var { data: allLikes } = await sb.from('comment_likes').select('comment_id, user_id').in('comment_id', cIds);
            if (allLikes) {
                allLikes.forEach(function(l) {
                    likeCountMap[l.comment_id] = (likeCountMap[l.comment_id] || 0) + 1;
                    if (l.user_id === currentUser.id) userLikedSet.add(l.comment_id);
                });
            }
        } catch(e) { /* non-critical */ }
    }

    comments.forEach(function(c) {
        var u = c.users || {};
        var avatar = u.avatar_url || 'https://ui-avatars.com/api/?name=' + encodeURIComponent(u.full_name || 'U') + '&background=007AFF&color=fff';
        var userLiked = userLikedSet.has(c.id);
        var likeCount = likeCountMap[c.id] || 0;
        var item = document.createElement('div');
        item.className = 'comment-item';
        item.innerHTML =
            '<img src="' + escapeHtml(avatar) + '" class="comment-avatar" style="align-self:flex-start;">' +
            '<div class="comment-bubble" style="flex:1;">' +
                '<div style="display:flex;align-items:center;gap:5px;margin-bottom:3px;">' +
                    '<b style="font-size:13px;color:var(--text-primary,#000);cursor:pointer;" onclick="viewUserProfile(\'' + escapeHtml(c.user_id || '') + '\')">' + escapeHtml(u.full_name || u.username || 'User') + '</b>' +
                    (u.verified ? '<i class="fa-solid fa-circle-check ' + (u.badge_tier || 'verify-blue') + '" style="font-size:9px;"></i>' : '') +
                    '<small style="color:#aaa;font-size:11px;margin-left:4px;">' + getTimeAgo(c.created_at) + '</small>' +
                '</div>' +
                '<p style="font-size:14px;line-height:1.4;margin:0 0 6px;">' + escapeHtml(c.text_content) + '</p>' +
                '<div style="display:flex;align-items:center;gap:14px;">' +
                    '<div onclick="toggleCommentLike(this,\'' + c.id + '\')" style="display:flex;align-items:center;gap:4px;cursor:pointer;">' +
                        '<i class="fa-' + (userLiked ? 'solid' : 'regular') + ' fa-heart" style="font-size:13px;color:' + (userLiked ? '#FF3B30' : '#888') + ';transition:0.2s;"></i>' +
                        '<span style="font-size:11px;color:#888;">' + likeCount + '</span>' +
                    '</div>' +
                    '<span onclick="openCommentReply(\'' + escapeHtml(u.full_name || u.username || 'User') + '\')" style="font-size:12px;color:#888;cursor:pointer;font-weight:600;">Reply</span>' +
                '</div>' +
            '</div>';
        list.appendChild(item);
    });
}

// ==========================================================================
// OVERRIDE: postComment — make it real
// ==========================================================================
var _originalPostComment = typeof postComment === 'function' ? postComment : null;

postComment = async function() {
    if (!currentCommentPostId) {
        // Try to get postId from comment sheet if available
        var sheet = document.getElementById('comment-sheet') || document.getElementById('comments-overlay');
        var pid = sheet ? sheet.getAttribute('data-post-id') : null;
        if (pid) { currentCommentPostId = pid; }
        else { if (_originalPostComment) _originalPostComment(); return; }
    }
    if (!canPerformAction('comment')) return;

    var input = document.getElementById('comment-input');
    if (!input) return;
    var text = input.value.trim();
    if (!text) return;

    if (containsBannedWords(text)) {
        showToast('Comment violates guidelines');
        return;
    }

    var result = await RealData.postComment(currentCommentPostId, text);
    if (result) {
        input.value = '';
        triggerHaptic(15);
        // Immediately update the comment count on the post card in the feed
        var postCard = document.querySelector('[data-post-id="' + currentCommentPostId + '"]');
        if (postCard) {
            postCard.querySelectorAll('button, div').forEach(function(btn) {
                if (btn.querySelector('.fa-comment, .fa-comment-dots')) {
                    var span = btn.querySelector('span');
                    if (span) span.textContent = (parseInt(span.textContent) || 0) + 1;
                }
            });
        }
        // Send notification to post owner
        if (window.sb && currentUser) {
            try {
                var postData = await sb.from('posts').select('user_id').eq('id', currentCommentPostId).single();
                if (postData.data && postData.data.user_id !== currentUser.id) {
                    await sb.from('notifications').insert({
                        user_id: postData.data.user_id,
                        actor_id: currentUser.id,
                        type: 'comment',
                        post_id: currentCommentPostId,
                        message: (currentUser.username || currentUser.name || 'Someone') + ' replied to your post'
                    });
                }
            } catch(e) { /* notification failure is non-critical */ }
        }
        await realOpenComments(currentCommentPostId);
    } else {
        showToast('Comment failed');
    }
};

// ==========================================================================
// OVERRIDE: initFeed — load real posts
// ==========================================================================
initFeed = async function() {
    var feed = document.getElementById('feed-panels');
    if (!feed) return;

    feed.innerHTML = '<div style="text-align:center;padding:60px 20px;">' +
        '<i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;font-size:24px;"></i>' +
        '<p style="color:#aaa;margin-top:10px;font-size:13px;">Loading feed...</p></div>';

// Show cached posts immediately while Supabase loads
var cacheEntry = null;
try { cacheEntry = JSON.parse(localStorage.getItem('tf-cached-feed') || 'null'); } catch(e) {}
var cacheAge = cacheEntry && cacheEntry.ts ? Date.now() - cacheEntry.ts : Infinity;
var cachedPosts = (cacheAge < 5 * 60 * 1000 && cacheEntry && cacheEntry.posts) ? cacheEntry.posts : [];
if (cachedPosts.length) {
    feed.innerHTML = '';
    cachedPosts.forEach(function(p){ if(p) feed.appendChild(renderRealPostCard(p)); });
}

    currentFeedPage = 1;

    var posts = [];

    if (isChildAccount()) {
        // CHILDREN get a filtered, age-appropriate feed
        posts = await getChildSafeFeed();
    } else {
        posts = await RealData.getFeed(1, 20);
        if (posts.length === 0) {
            posts = await RealData.getDiscoverFeed(1, 20);
        }
    }

    // Child-safe feed — filters to verified educational/family accounts only
async function getChildSafeFeed() {
    if (!window.sb) return buildLocalChildFeed();
    try {
        var childSafeTypes = ['personal', 'business', 'government'];
        var result = await sb.from('posts')
            .select('*, users:user_id (id, full_name, username, avatar_url, badge_tier, verified, account_type)')
            .eq('is_hidden', false)
            .eq('status', 'published')
            .not('text_content', 'ilike', '%nsfw%')
            .not('text_content', 'ilike', '%18+%')
            .not('text_content', 'ilike', '%adult%')
            .eq('users.verified', true)
            .order('created_at', { ascending: false })
            .limit(20);
        return result.data || buildLocalChildFeed();
    } catch(e) {
        return buildLocalChildFeed();
    }
}

function buildLocalChildFeed() {
    // Safe placeholder posts for offline/fallback
    return [{
        id: 'safe_1',
        text_content: 'Welcome to TrustFirst Kids! This is a safe space. 🌟',
        post_type: 'text',
        created_at: new Date().toISOString(),
        like_count: 12, comment_count: 3, repost_count: 0,
        _liked: false, _bookmarked: false,
        users: { full_name: 'TrustFirst Kids', username: 'trustfirst_kids', verified: true, badge_tier: 'verify-green', avatar_url: null }
    }];
}

// Enhanced parent notification system
async function notifyParentOfChildAction(actionType, details) {
    if (!isChildAccount()) return;
    var parentLink = secureLoad('parent_link_request');
    if (!parentLink || !parentLink.parent_id) return;

    var notification = {
        type: 'child_activity',
        child_name: currentUser ? currentUser.name : 'Your child',
        action: actionType,
        details: details || '',
        timestamp: new Date().toISOString()
    };

    // Save to local queue
    var queue = JSON.parse(localStorage.getItem('parent_notif_queue') || '[]');
    queue.push(notification);
    localStorage.setItem('parent_notif_queue', JSON.stringify(queue.slice(-50)));

    // Send to Supabase if online
    if (window.sb && navigator.onLine) {
        try {
            await sb.from('notifications').insert({
                user_id: parentLink.parent_id,
                actor_id: currentUser.id,
                type: 'child_activity',
                message: currentUser.name + ' ' + actionType,
                preview_text: details,
                read: false
            });
        } catch(e) { console.warn('[ParentNotif]', e); }
    }
}


if (posts.length) localStorage.setItem('tf-cached-feed', JSON.stringify({ ts: Date.now(), posts: posts }));
    feed.innerHTML = '';

    if (posts.length === 0 && cachedPosts.length === 0) {
        feed.innerHTML = '<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;padding:80px 32px;gap:16px;">' +
            '<i class="fa-regular fa-newspaper" style="font-size:48px;color:#ccc;"></i>' +
            '<p style="font-weight:700;font-size:17px;color:var(--text-primary,#000);margin:0;">Nothing here yet</p>' +
            '<p style="font-size:14px;color:#888;text-align:center;margin:0;line-height:1.5;">Follow people or post something to get your feed started.</p>' +
            '</div>';
        return;
    }
    if (posts.length === 0) return;

    posts.forEach(function(post) {
        feed.appendChild(renderRealPostCard(post));
    });

    fillProfileGrid();
    renderParentRequests();
    loadFeedStories();
};

async function loadFeedStories() {
    var bar = document.getElementById('feed-stories');
    if (!bar) return;

    // "Your story" button
    var myAvatar = (currentUser && currentUser.avatar_url)
        ? currentUser.avatar_url
        : 'https://ui-avatars.com/api/?name=' + encodeURIComponent((currentUser && currentUser.username) || 'U') + '&background=007AFF&color=fff&size=100';

    bar.innerHTML = '<div class="story-item" onclick="openStoryPicker()">' +
        '<div style="width:68px;height:68px;border-radius:50%;padding:3px;background:rgba(0,0,0,0.08);position:relative;display:flex;align-items:center;justify-content:center;">' +
        '<img src="' + myAvatar + '" class="story-pic" style="width:62px;height:62px;">' +
        '<div style="position:absolute;bottom:0;right:0;width:22px;height:22px;border-radius:50%;background:#007AFF;border:2px solid white;display:flex;align-items:center;justify-content:center;"><i class="fa-solid fa-plus" style="color:white;font-size:10px;"></i></div>' +
        '</div><small style="font-size:11px;">Your Story</small></div>';

    if (!window.sb || !currentUser) return;
    try {
        var since = new Date(Date.now() - 86400000).toISOString();
        var { data } = await sb
            .from('stories')
            .select('user_id, users:user_id(id, full_name, username, avatar_url)')
            .gte('created_at', since)
            .neq('user_id', currentUser.id)
            .limit(15);

        (data || []).forEach(function(s) {
            var u = s.users || {};
            var name = u.full_name || u.username || 'User';
            var avatar = u.avatar_url || 'https://ui-avatars.com/api/?name=' + encodeURIComponent(name.charAt(0)) + '&background=007AFF&color=fff&size=100';
            bar.innerHTML += '<div class="story-item" onclick="openStoryViewer(\'' + escapeHtml(u.id || '') + '\')">' +
                '<div class="ring-blue"><img src="' + escapeHtml(avatar) + '" class="story-pic" onerror="this.src=\'https://ui-avatars.com/api/?name=' + encodeURIComponent(name.charAt(0)) + '&background=007AFF&color=fff&size=100\'"></div>' +
                '<small style="font-size:11px;">' + escapeHtml(name.split(' ')[0]) + '</small></div>';
        });
    } catch(e) { console.warn('[FeedStories]', e); }
}

// ==========================================================================
// OVERRIDE: createPostFromComposer — save to database
// ==========================================================================
createPostFromComposer = async function() {
    if (!canPerformAction('create a post')) return;

    var textarea = document.getElementById('composer-text');
    var postText = textarea.value.trim();

    if (!postText) { showToast('Write something first!'); return; }

    if (typeof isAIGenerated === 'function' && isAIGenerated(postText)) {
        showToast('AI-generated content is not allowed.');
        return;
    }

    if (containsBannedWords(postText)) {
        showToast('Content violates our guidelines.');
        return;
    }

    var postBtn = document.getElementById('composer-post-btn');
    if (postBtn) {
        postBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Posting...';
        postBtn.disabled = true;
    }

    var post = await RealData.createPost(postText);

    if (post) {
        closePage('composer-overlay');
        textarea.value = '';
        if (postBtn) {
            postBtn.textContent = 'Post';
            postBtn.style.opacity = '0.5';
            postBtn.style.pointerEvents = 'none';
            postBtn.disabled = false;
        }
        triggerHaptic(50);
        showToast('Posted!');

        // Reload the feed with the new post
        await initFeed();
    } else {
        if (postBtn) {
            postBtn.textContent = 'Post';
            postBtn.disabled = false;
        }
        showToast('Failed to post. Try again.');
    }
};

// ==========================================================================
// POST MENU — Delete own posts, report others
// ==========================================================================
var _activePostMenuId = null;
var _activePostUserId = null;

function openPostMenu(postId, postUserId) {
    _activePostMenuId = postId;
    _activePostUserId = postUserId;
    var existing = document.getElementById('lgPostMenuOverlay');
    if (existing) { existing.remove(); return; }

    DB.getSession().then(function(session) {
        var isOwn = session && session.user && session.user.id === postUserId;

        var overlay = document.createElement('div');
        overlay.id = 'lgPostMenuOverlay';
        overlay.style.cssText = 'position:absolute;inset:0;z-index:9999;background:rgba(0,0,0,0.45);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);display:flex;align-items:flex-end;justify-content:center;overflow:hidden;border-radius:inherit;';

        overlay.innerHTML = `
            <div id="lgPostMenuSheet" style="width:100%;max-width:500px;padding:0 12px 36px;animation:slideUpOverlay 0.35s cubic-bezier(0.32,0.72,0,1);">

                <!-- Main actions card -->
                <div style="background:rgba(255,255,255,0.72);backdrop-filter:blur(60px) saturate(200%);-webkit-backdrop-filter:blur(60px) saturate(200%);border:0.5px solid rgba(255,255,255,0.8);border-radius:22px;box-shadow:0 12px 40px rgba(0,0,0,0.18),0 1.5px 0 rgba(255,255,255,0.9) inset;overflow:hidden;margin-bottom:10px;">

                    <div onclick="lgPostAction('not_interested')" class="lg-menu-row" style="display:flex;align-items:center;justify-content:space-between;padding:17px 20px;border-bottom:0.5px solid rgba(0,0,0,0.07);cursor:pointer;" onmouseover="this.style.background='rgba(0,0,0,0.04)'" onmouseout="this.style.background=''">
                        <span style="font-size:15px;font-weight:600;color:var(--text-primary,#000);">Not interested in this post</span>
                        <i class="fa-solid fa-eye-slash" style="color:#888;font-size:15px;"></i>
                    </div>

                    <div onclick="lgPostAction('interactions')" class="lg-menu-row" style="display:flex;align-items:center;justify-content:space-between;padding:17px 20px;border-bottom:0.5px solid rgba(0,0,0,0.07);cursor:pointer;" onmouseover="this.style.background='rgba(0,0,0,0.04)'" onmouseout="this.style.background=''">
                        <span style="font-size:15px;font-weight:600;color:var(--text-primary,#000);">View post interactions</span>
                        <i class="fa-solid fa-chart-simple" style="color:#888;font-size:15px;"></i>
                    </div>

                    <div onclick="lgPostAction('report')" class="lg-menu-row" style="display:flex;align-items:center;justify-content:space-between;padding:17px 20px;border-bottom:0.5px solid rgba(0,0,0,0.07);cursor:pointer;" onmouseover="this.style.background='rgba(0,0,0,0.04)'" onmouseout="this.style.background=''">
                        <span style="font-size:15px;font-weight:600;color:#FF3B30;">Report post</span>
                        <i class="fa-solid fa-flag" style="color:#FF3B30;font-size:15px;"></i>
                    </div>

                    ${isOwn ? `
                    <div onclick="realDeletePost('${postId}')" class="lg-menu-row" style="display:flex;align-items:center;justify-content:space-between;padding:17px 20px;cursor:pointer;" onmouseover="this.style.background='rgba(255,59,48,0.04)'" onmouseout="this.style.background=''">
                        <span style="font-size:15px;font-weight:600;color:#FF3B30;">Delete post</span>
                        <i class="fa-solid fa-trash" style="color:#FF3B30;font-size:15px;"></i>
                    </div>` : ''}
                </div>

                <!-- User profile card -->
                ${!isOwn ? `
                <div onclick="lgOpenUserSubMenu()" style="background:rgba(255,255,255,0.72);backdrop-filter:blur(60px) saturate(200%);-webkit-backdrop-filter:blur(60px) saturate(200%);border:0.5px solid rgba(255,255,255,0.8);border-radius:22px;box-shadow:0 12px 40px rgba(0,0,0,0.15),0 1.5px 0 rgba(255,255,255,0.9) inset;overflow:hidden;margin-bottom:10px;display:flex;align-items:center;gap:12px;padding:16px 20px;cursor:pointer;" onmouseover="this.style.background='rgba(0,0,0,0.06)'" onmouseout="this.style.background='rgba(255,255,255,0.72)'">
                    <img src="https://ui-avatars.com/api/?name=User&background=888&color=fff&size=80" id="lgMenuUserAvatar" style="width:40px;height:40px;border-radius:50%;object-fit:cover;flex-shrink:0;">
                    <div style="flex:1;">
                        <b style="font-size:14px;color:var(--text-primary,#000);display:block;">View account options</b>
                        <small style="color:#888;font-size:12px;">Follow, mute or block</small>
                    </div>
                    <i class="fa-solid fa-chevron-right" style="color:#ccc;font-size:13px;"></i>
                </div>` : ''}

                <!-- Cancel -->
                <div onclick="document.getElementById('lgPostMenuOverlay').remove()" style="background:rgba(255,255,255,0.72);backdrop-filter:blur(60px) saturate(200%);-webkit-backdrop-filter:blur(60px) saturate(200%);border:0.5px solid rgba(255,255,255,0.8);border-radius:22px;box-shadow:0 8px 24px rgba(0,0,0,0.12),0 1.5px 0 rgba(255,255,255,0.9) inset;padding:17px;text-align:center;cursor:pointer;font-size:16px;font-weight:700;color:#007AFF;">
                    Cancel
                </div>
            </div>`;

        overlay.addEventListener('click', function(e) { if (e.target === overlay) overlay.remove(); });
        (document.getElementById('app') || document.body).appendChild(overlay);
    });
}

function lgPostAction(action) {
    var overlay = document.getElementById('lgPostMenuOverlay');
    if (overlay) overlay.remove();
    switch(action) {
        case 'not_interested':
            var card = document.querySelector('[data-post-id="' + _activePostMenuId + '"]');
            if (card) {
                card.style.transition = 'opacity 0.4s, transform 0.4s';
                card.style.opacity = '0';
                card.style.transform = 'scale(0.95)';
                setTimeout(function() { card.remove(); }, 400);
            }
            showToast('You won\'t see posts like this');
            break;
        case 'interactions':
            showPostInteractions(_activePostMenuId);
            break;
        case 'report':
            openReportMenu(_activePostMenuId, 'post');
            break;
    }
}

