function previewGroupPic(input) {
    var file = input.files[0];
    if (!file || file.size > 5*1024*1024) { showToast('Max 5MB'); return; }
    var reader = new FileReader();
    reader.onload = function(e) {
        var prev = document.getElementById('groupPicPreview');
        if (prev) prev.innerHTML = '<img src="' + e.target.result + '" style="width:100%;height:100%;object-fit:cover;">';
    };
    reader.readAsDataURL(file);
}

function setGroupPrivacy(p) {
    selectedGroupPrivacy = p;
    const pub = document.getElementById('privacy-public');
    const priv = document.getElementById('privacy-private');
    if (pub) { pub.style.borderColor = p === 'Public' ? '#007AFF' : '#eee'; pub.style.color = p === 'Public' ? '#007AFF' : '#888'; pub.style.background = p === 'Public' ? 'rgba(0,122,255,0.06)' : 'transparent'; }
    if (priv) { priv.style.borderColor = p === 'Private' ? '#007AFF' : '#eee'; priv.style.color = p === 'Private' ? '#007AFF' : '#888'; priv.style.background = p === 'Private' ? 'rgba(0,122,255,0.06)' : 'transparent'; }
}

async function createGroup(emoji, color) {
    const name = document.getElementById('group-name-input')?.value.trim();
    const desc = document.getElementById('group-desc-input')?.value.trim();
    if (!name) { showToast('Enter a group name'); return; }
    if (!currentUser) { showToast('Please log in'); return; }

    const submitBtn = document.querySelector('#createGroupModal button[onclick*="createGroup"]');
    if (submitBtn) { submitBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>'; submitBtn.disabled = true; }

    if (!window.sb) { showToast('Not connected. Try again.'); if (submitBtn) { submitBtn.textContent = 'Create Group'; submitBtn.disabled = false; } return; }
    try {
        const privacy = window._grpPrivacy || 'Public';
        const { data: group, error } = await sb.from('groups').insert({
            name, description: desc || null, emoji, color,
            privacy: privacy, admin_id: currentUser.id, member_count: 1, is_active: true
        }).select().single();

        if (group) {
            await sb.from('group_members').insert({ group_id: group.id, user_id: currentUser.id, role: 'admin' });
            document.getElementById('createGroupModal')?.remove();
            showToast('Group created! 🎉');
            triggerHaptic(50);
            await loadGroups();
            openGroup(group.id);
        } else {
            showToast('Failed: ' + (error?.message || 'Try again'));
            if (submitBtn) { submitBtn.textContent = 'Create Group'; submitBtn.disabled = false; }
        }
    } catch(e) {
        showToast('Failed: ' + (e?.message || 'Try again'));
        if (submitBtn) { submitBtn.textContent = 'Create Group'; submitBtn.disabled = false; }
    }
}

function postToGroup(groupId) {
    if (!groupId) return;
    currentGroupId = groupId;
    openPage('composer-overlay');
    const banner = document.getElementById('composer-group-banner');
    if (banner) {
        banner.style.display = 'flex';
        banner.innerHTML = `<i class="fa-solid fa-users"></i> <span style="flex:1;">Posting to group</span> <span onclick="currentGroupId=null;this.parentElement.style.display='none';" style="cursor:pointer;color:#FF3B30;font-size:18px;">×</span>`;
    }
}

// Add Groups to the nav burger menu
var _origNavGoTo = navGoTo;
navGoTo = function(destination) {
    if (destination === 'groups') {
        loadGroups();
        return;
    }
    _origNavGoTo(destination);
};

// ==========================================================================
// REAL NOTIFICATIONS (FIXED)
// ==========================================================================

var allNotifications = [];
var currentNotifFilter = 'all';

async function loadRealNotifications() {
    const area = document.getElementById('notif-content-area');
    if (!area) return;
    area.innerHTML = '<div style="text-align:center;padding:40px;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;font-size:24px;"></i></div>';

    if (!window.sb || !currentUser) {
        area.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">Sign in to see notifications</div>';
        return;
    }

    const { data: notifs } = await sb.from('notifications')
        .select('*, actor:actor_id (full_name, username, avatar_url, badge_tier, verified)')
        .eq('user_id', currentUser.id)
        .order('created_at', { ascending: false })
        .limit(60);

    allNotifications = notifs || [];

    // Mark all as read
    await sb.from('notifications').update({ read: true }).eq('user_id', currentUser.id).eq('read', false);
    navNotifications.likes = 0;
    navNotifications.alerts = 0;
    navUpdateBadges();

    renderNotifList(currentNotifFilter);
}

function renderNotifList(filter) {
    const area = document.getElementById('notif-content-area');
    if (!area) return;

    const filtered = filter === 'all' ? allNotifications : allNotifications.filter(n => n.type === filter);

    if (filtered.length === 0) {
        area.innerHTML = `<div style="text-align:center;padding:60px 20px;color:#888;">
            <i class="fa-regular fa-bell" style="font-size:40px;color:#ccc;display:block;margin-bottom:15px;"></i>
            No ${filter === 'all' ? '' : filter} notifications yet
        </div>`;
        return;
    }

    area.innerHTML = filtered.map(n => renderNotifCard(n)).join('');
}

function filterNotifs(type, el) {
    currentNotifFilter = type;
    document.querySelectorAll('.notif-tab').forEach(t => {
        t.style.color = '#888';
        t.style.borderBottom = '2px solid transparent';
    });
    el.style.color = '#007AFF';
    el.style.borderBottom = '2px solid #007AFF';
    renderNotifList(type);
}

function renderNotifCard(notif) {
    const actor = notif.actor || {};
    const avatar = actor.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(actor.full_name || 'U')}&background=007AFF&color=fff&size=80`;
    const badgeClass = actor.badge_tier || 'verify-blue';
    const timeAgo = getTimeAgo ? getTimeAgo(notif.created_at) : 'now';

    const styles = {
        like:    { icon: 'fa-heart',      color: '#FF2D55', bg: '#FF2D5512' },
        comment: { icon: 'fa-comment',    color: '#007AFF', bg: '#007AFF12' },
        follow:  { icon: 'fa-user-plus',  color: '#34C759', bg: '#34C75912' },
        repost:  { icon: 'fa-retweet',    color: '#34C759', bg: '#34C75912' },
        mention: { icon: 'fa-at',         color: '#5856D6', bg: '#5856D612' },
        reply:   { icon: 'fa-reply',      color: '#007AFF', bg: '#007AFF12' },
    };
    const s = styles[notif.type] || styles.like;

    const messages = {
        like:    'liked your post',
        comment: 'commented on your post',
        follow:  'started following you',
        repost:  'reposted your post',
        mention: 'mentioned you',
        reply:   'replied to your comment',
    };
    const message = notif.message || messages[notif.type] || 'interacted with you';

    return `
        <div style="display:flex;align-items:center;gap:12px;padding:14px 20px;border-bottom:1px solid var(--border-color,#f0f0f0);${!notif.read ? 'background:rgba(0,122,255,0.02);' : ''}cursor:pointer;" onclick="viewUserProfile('${actor.id || ''}')">
            <div style="position:relative;flex-shrink:0;">
                <img src="${escapeHtml(avatar)}" style="width:46px;height:46px;border-radius:50%;object-fit:cover;">
                <div style="position:absolute;bottom:-3px;right:-3px;width:22px;height:22px;border-radius:50%;background:${s.bg};border:2px solid var(--card-bg,#fff);display:flex;align-items:center;justify-content:center;">
                    <i class="fa-solid ${s.icon}" style="font-size:9px;color:${s.color};"></i>
                </div>
            </div>
            <div style="flex:1;min-width:0;">
                <p style="font-size:14px;color:var(--text-primary,#000);margin:0;line-height:1.4;">
                    <b>${escapeHtml(actor.full_name || actor.username || 'Someone')}</b>
                    ${actor.verified ? `<i class="fa-solid fa-circle-check ${badgeClass}" style="font-size:10px;"></i>` : ''}
                    ${message}
                </p>
                ${notif.preview_text ? `<p style="font-size:12px;color:#888;margin:3px 0 0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">"${escapeHtml(notif.preview_text)}"</p>` : ''}
                <small style="color:#aaa;font-size:11px;">${timeAgo}</small>
            </div>
            ${!notif.read ? '<div style="width:8px;height:8px;border-radius:50%;background:#007AFF;flex-shrink:0;"></div>' : ''}
        </div>`;
}

async function markAllNotifsRead() {
    allNotifications = allNotifications.map(n => ({ ...n, read: true }));
    renderNotifList(currentNotifFilter);
    if (window.sb && currentUser) {
        await sb.from('notifications').update({ read: true }).eq('user_id', currentUser.id);
    }
    showToast('All marked as read ✓');
}

// Wire up notifications to open properly
navGoTo = function(destination) {
    var layerMap = {
        'notifications': ['msg-overlay','profile-overlay','reel-overlay'],
        'messages':      ['notif-overlay','profile-overlay','reel-overlay'],
        'account':       ['notif-overlay','msg-overlay','reel-overlay'],
        'reels':         ['notif-overlay','msg-overlay','profile-overlay'],
        'groups':        ['notif-overlay','msg-overlay','profile-overlay','reel-overlay']
    };
    if (layerMap[destination]) {
        layerMap[destination].forEach(function(id) {
            var el = document.getElementById(id);
            if (el) el.style.display = 'none';
        });
    }
    document.querySelectorAll('.liquid-pill .nav-icon').forEach(function(i) { i.classList.remove('nav-active'); });

    if (destination === 'reels') {
        hideNavBar();
        var reelEl = document.getElementById('reel-overlay');
        if (reelEl) { reelEl.style.display = 'flex'; reelEl.style.flexDirection = 'column'; }
        initReels();
        setTimeout(function() {
            var btn = document.querySelector('#reel-overlay .liquid-glass-btn');
            if (btn) { btn.style.cssText = 'position:fixed!important;top:50px!important;left:20px!important;z-index:100000!important;width:40px;height:40px;border-radius:50%;background:rgba(255,255,255,0.22);backdrop-filter:blur(12px);display:flex;align-items:center;justify-content:center;cursor:pointer;'; btn.onclick = closeReelOverlay; }
        }, 80);
        var ri = document.getElementById('nav-reels'); if (ri) ri.classList.add('nav-active');
        return;
    }
    if (destination === 'notifications') {
        var nav = document.querySelector('.nav-container'); if (nav) nav.style.display = 'flex';
        if (typeof requestNotificationPermission === 'function') requestNotificationPermission();
        openPage('notif-overlay');
        if (typeof loadRealNotifications === 'function') loadRealNotifications();
        navNotifications.likes = navNotifications.reposts = navNotifications.alerts = 0;
        navUpdateBadges();
        var ni = document.getElementById('nav-notif'); if (ni) ni.classList.add('nav-active');
        return;
    }
    if (destination === 'messages') {
        hideNavBar();
        openPage('msg-overlay');
        fillMsgContent();
        navNotifications.messages = 0;
        navUpdateBadges();
        var mi = document.getElementById('nav-msgs'); if (mi) mi.classList.add('nav-active');
        return;
    }
    if (destination === 'account') {
        var nav2 = document.querySelector('.nav-container'); if (nav2) nav2.style.display = 'flex';
        openPage('profile-overlay');
        loadMyProfile();
        fillProfileGrid();
        var ai = document.getElementById('nav-account'); if (ai) ai.classList.add('nav-active');
        return;
    }
    if (destination === 'groups') {
        loadGroups();
        return;
    }
};

// Subscribe to real-time new notifications
var _notifChannelSubscribed = false;
function subscribeToNotifications() {
    if (!window.sb || !currentUser) return;
    if (_notifChannelSubscribed) return;
    _notifChannelSubscribed = true;
    sb.channel('notifs-' + currentUser.id)
        .on('postgres_changes', {
            event: 'INSERT', schema: 'public', table: 'notifications',
            filter: `user_id=eq.${currentUser.id}`
        }, (payload) => {
            const notif = payload.new;
            allNotifications.unshift(notif);
            navNotifications[notif.type === 'message' ? 'messages' : 'alerts'] += 1;
            navUpdateBadges();
            showToast(({ like:'❤️ liked your post', comment:'💬 New comment', follow:'🤝 New follower!', repost:'🔁 Someone reposted you' })[notif.type] || '🔔 New notification');
            triggerHaptic(20);
            const area = document.getElementById('notif-content-area');
            if (area && document.getElementById('notif-overlay')?.style.display !== 'none') {
                area.insertAdjacentHTML('afterbegin', renderNotifCard(notif));
            }
        }).subscribe();
}

// Start notification subscription when app launches
var _origLaunchAppFinal = launchApp;
launchApp = function() {
    _origLaunchAppFinal();
    setTimeout(subscribeToNotifications, 2000);
};

// Add Groups to the + menu
document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('.add-option').forEach(function(opt) {
        if (opt.textContent.includes('Create Post')) {
            const groupOpt = document.createElement('div');
            groupOpt.className = 'add-option';
            groupOpt.innerHTML = '<i class="fa-solid fa-users"></i> Groups';
            groupOpt.onclick = function() { togglePlusMenu(); loadGroups(); };
            opt.parentElement.appendChild(groupOpt);
        }
    });
});

console.debug('[TrustFirst] Polls, Scheduling, Groups, Notifications loaded ✅');

    // ==========================================================================
// LIQUID GLASS NAVIGATION CONTROLLER
// ==========================================================================
var navState = 'collapsed'; // 'collapsed', 'others', 'search'
var navNotifications = {
    likes: 0,
    reposts: 0,
    messages: 0,
    alerts: 0
};

// --- Core State Machine ---
function navSetState(newState) {
    var app = document.querySelector('.app');
    var pill = document.getElementById('liquidPill');
    if (!app || !pill) return;

    // Remove all states
    app.classList.remove('is-others', 'is-search');

    // Clear active from all icons
    document.querySelectorAll('.liquid-pill .nav-icon').forEach(function(icon) {
        icon.classList.remove('nav-active');
    });

    navState = newState;

    if (newState === 'others') {
        app.classList.add('is-others');
        triggerSweep();
    } else if (newState === 'search') {
        app.classList.add('is-search');
        triggerSweep();
        setTimeout(function() {
            var input = document.getElementById('navSearchInput');
            if (input) input.focus();
        }, 400);
    }

    // Home is always active in collapsed state
    if (newState === 'collapsed') {
        var homeIcon = document.getElementById('nav-home');
        if (homeIcon) homeIcon.classList.add('nav-active');
    }

    navUpdateBadges();
}

function triggerSweep() {
    var pill = document.getElementById('liquidPill');
    if (!pill) return;
    pill.classList.remove('sweep');
    void pill.offsetWidth; // force reflow
    pill.classList.add('sweep');
}

// --- Navigation Actions ---
function navHome() {
    navSetState('collapsed');
    var homeIcon = document.getElementById('nav-home');
    if (homeIcon) homeIcon.classList.add('nav-active');

    // Close ALL overlays including profile
    ['msg-overlay','profile-overlay','notif-overlay','reel-overlay',
     'settings-overlay','activity-overlay','saved-overlay','archive-overlay',
     'groups-overlay','group-page-overlay','drafts-overlay','scheduled-overlay',
     'contact-profile-overlay','cp-privacy-overlay','trustAnalyticsOverlay',
     'liveSettingsPage','user-profile-overlay'].forEach(function(id){
        var el = document.getElementById(id);
        if (el) el.style.display = 'none';
    });
    document.querySelectorAll('.settings-sub-overlay').forEach(function(el){ el.style.display='none'; });

    var nav = document.querySelector('.nav-container');
    if (nav) nav.style.display = 'flex';

    var feed = document.getElementById('feed-panels');
    if (feed) { feed.style.display = ''; feed.scrollTo({ top:0, behavior:'smooth' }); }

    triggerHaptic(10);
}

function navToggleOthers() {
    if (navState === 'others') {
        navSetState('collapsed');
    } else {
        navSetState('others');
    }
    triggerHaptic(15);
}

function navAutoExpandBurger() {
    // Only auto-expand when the nav is collapsed (droplet on home)
    // so hovering/focusing the burger naturally opens the menu
    if (navState === 'collapsed') {
        navSetState('others');
        triggerHaptic(10);
    }
}

function navOpenSearch() {
    var circle = document.getElementById('searchCircle');
    if (circle) {
        circle.classList.remove('bounce');
        void circle.offsetWidth;
        circle.classList.add('bounce');
    }
    navSetState('search');
    triggerHaptic(10);
    setTimeout(function() {
        var inp = document.getElementById('navSearchInput');
        if (inp) inp.focus();
        function outsideClick(e) {
            var pill = document.querySelector('.liquid-pill');
            var sp = document.getElementById('searchSeparatePill');
            var sc = document.getElementById('searchCircle');
            var disc = document.getElementById('discovery-page');
            if (pill && !pill.contains(e.target) && sc && !sc.contains(e.target) && sp && !sp.contains(e.target) && (!disc || !disc.contains(e.target))) {
                navCloseSearch();
                document.removeEventListener('click', outsideClick);
            }
        }
        document.addEventListener('click', outsideClick);
    }, 300);
}

function navCloseSearch() {
    navSetState('collapsed');
    var input = document.getElementById('navSearchInput');
    if (input) input.value = '';
    // Also hide discovery page
    var disc = document.getElementById('discovery-page');
    if (disc) disc.style.display = 'none';
    var si = document.getElementById('s-input');
    if (si) si.value = '';
    triggerHaptic(10);
}

function navGoTo(destination) {
    // Keep others expanded while navigating
    var app = document.querySelector('.app');
    if (app) app.classList.add('is-others');
    // Set active icon
    document.querySelectorAll('.liquid-pill .nav-icon').forEach(function(icon) {
        icon.classList.remove('nav-active');
    });

    var targetIcon = null;

    switch (destination) {
        case 'reels':
    targetIcon = document.getElementById('nav-reels');
    hideNavBar();
    var reelEl = document.getElementById('reel-overlay');
    if (reelEl) { reelEl.style.display = 'flex'; reelEl.style.flexDirection = 'column'; }
    initReels();
    // Fix back button so it doesn't scroll with content
    setTimeout(function() {
        var btn = document.querySelector('#reel-overlay .liquid-glass-btn');
        if (btn) {
            btn.style.cssText = 'position:fixed!important;top:50px!important;left:20px!important;z-index:100000!important;width:40px;height:40px;border-radius:50%;background:rgba(255,255,255,0.22);backdrop-filter:blur(12px);display:flex;align-items:center;justify-content:center;cursor:pointer;';
            btn.onclick = closeReelOverlay;
        }
    }, 80);
    break;

        case 'notifications':
            targetIcon = document.getElementById('nav-notif');
            var nav = document.querySelector('.nav-container');
            if (nav) nav.style.display = 'flex';
            if (typeof requestNotificationPermission === 'function') requestNotificationPermission();
            if (typeof openPage === 'function') openPage('notif-overlay');
            if (typeof loadRealNotifications === 'function') loadRealNotifications();
            navNotifications.likes = 0;
            navNotifications.reposts = 0;
            navNotifications.alerts = 0;
            break;

        case 'messages':
    targetIcon = document.getElementById('nav-msgs');
    var profCheck = document.getElementById('profile-overlay');
    if (profCheck) profCheck.style.display = 'none';
    var notifCheck = document.getElementById('notif-overlay');
    if (notifCheck) notifCheck.style.display = 'none';
    hideNavBar();
    openPage('msg-overlay');
    fillMsgContent();
    navNotifications.messages = 0;
    break;

       case 'account':
            targetIcon = document.getElementById('nav-account');
            var navAcc = document.querySelector('.nav-container');
            if (navAcc) navAcc.style.display = 'flex';
            if (typeof openPage === 'function') openPage('profile-overlay');
            loadMyProfile();
            fillProfileGrid();
            break;
    }

    if (targetIcon) {
        targetIcon.classList.add('nav-active');
    }

    navUpdateBadges();
    triggerHaptic(15);
}

// --- Search ---
function handleNavSearch(query) {
    var disc = document.getElementById('discovery-page');
    if (!disc) return;
    if (!query || query.length < 2) {
        disc.style.display = 'none';
        return;
    }
    disc.style.display = 'flex';
    disc.style.zIndex = '5500';
    var si = document.getElementById('s-input');
    if (!si) {
        si = document.createElement('input');
        si.id = 's-input';
        si.style.display = 'none';
        document.body.appendChild(si);
    }
    si.value = query;
    simulateRealtimeSearch();
}

function executeNavSearch() {
    var input = document.getElementById('navSearchInput');
    var query = input ? input.value.trim() : '';
    if (!query) return;

    // Navigate to discovery/search results
    navCloseSearch();
    if (typeof openPage === 'function') openPage('search-overlay');
    if (typeof performSearch === 'function') performSearch(query);
}

function resetNav() {
    var disc = document.getElementById('discovery-page');
    if (disc) disc.style.display = 'none';
    navCloseSearch();
}

// --- Badge System ---
function navUpdateBadges() {
    var burgerBadge = document.getElementById('burger-badge');
    var notifBadge = document.getElementById('notif-badge');
    var msgsBadge = document.getElementById('msgs-badge');

    var totalNotifs = navNotifications.likes + navNotifications.reposts + navNotifications.alerts;
    var totalMsgs = navNotifications.messages;
    var grandTotal = totalNotifs + totalMsgs;

    if (navState === 'collapsed' || navState === 'search') {
        // Collapsed: show combined badge on burger
        if (burgerBadge) {
            burgerBadge.textContent = grandTotal > 0 ? (grandTotal > 99 ? '99+' : grandTotal) : '';
            burgerBadge.setAttribute('data-count', grandTotal);
        }
        if (notifBadge) { notifBadge.textContent = ''; notifBadge.setAttribute('data-count', '0'); }
        if (msgsBadge) { msgsBadge.textContent = ''; msgsBadge.setAttribute('data-count', '0'); }
    } else {
        // Expanded: split badges
        if (burgerBadge) { burgerBadge.textContent = ''; burgerBadge.setAttribute('data-count', '0'); }
        if (notifBadge) {
            notifBadge.textContent = totalNotifs > 0 ? (totalNotifs > 99 ? '99+' : totalNotifs) : '';
            notifBadge.setAttribute('data-count', totalNotifs);
        }
        if (msgsBadge) {
            msgsBadge.textContent = totalMsgs > 0 ? (totalMsgs > 99 ? '99+' : totalMsgs) : '';
            msgsBadge.setAttribute('data-count', totalMsgs);
        }
    }
}

// --- Simulate incoming notifications (for testing) ---
function navAddNotification(type, count) {
    count = count || 1;
    if (navNotifications.hasOwnProperty(type)) {
        navNotifications[type] += count;
    }
    navUpdateBadges();
}

// --- Close all overlays helper ---
function closeAllOverlays() {
    // Only close page overlays, NOT the feed or main content
    var overlayIds = [
        'msg-overlay', 'notif-overlay', 'profile-page', 'reel-overlay',
        'search-overlay', 'discovery-page', 'settings-overlay',
        'parent-hub', 'qr-overlay', 'call-overlay', 'live-overlay',
        'composer-overlay', 'user-profile-overlay'
    ];
    overlayIds.forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.style.display = 'none';
    });
    // Also close any dynamically created overlays
    document.querySelectorAll('.page-overlay').forEach(function(el) {
        el.style.display = 'none';
    });
}

// --- Show/hide nav bar ---
function showNavBar() {
    var nav = document.querySelector('.nav-container');
    if (nav) nav.style.display = 'flex';
}

function hideNavBar() {
    var nav = document.querySelector('.nav-container');
    if (nav) nav.style.display = 'none';
}

// --- Initialize ---
(function initNav() {
    // Set initial state
    navSetState('collapsed');

   navUpdateBadges();
})();

