function openContactProfile() {
    var chatUserName = document.getElementById('chat-user-name');
    var name = chatUserName ? chatUserName.textContent : 'User';

    document.getElementById('cp-name').textContent = name;
    document.getElementById('cp-status').textContent = 'Loading...';
    var _cpAvEl = document.getElementById('cp-avatar');
    if (window._currentChatUserId && window.sb) {
        window.sb.from('users').select('full_name,username,avatar_url,last_seen').eq('id', window._currentChatUserId).single()
            .then(function(res) {
                var u = res.data || {};
                if (u.full_name || u.username) document.getElementById('cp-name').textContent = u.full_name || u.username;
                if (u.avatar_url && _cpAvEl) _cpAvEl.src = u.avatar_url;
                var diff = u.last_seen ? Date.now() - new Date(u.last_seen).getTime() : null;
                var st = diff !== null && diff < 180000 ? 'Active now'
                    : (diff !== null && diff < 3600000 ? 'Active ' + Math.floor(diff/60000) + 'm ago' : 'Tap to view profile');
                var el = document.getElementById('cp-status'); if (el) el.textContent = st;
            }).catch(function() {
                if (_cpAvEl) _cpAvEl.src = 'https://ui-avatars.com/api/?name=' + encodeURIComponent(name||'U') + '&background=007AFF&color=fff&size=200';
                var el = document.getElementById('cp-status'); if (el) el.textContent = 'Active now';
            });
    } else {
        if (_cpAvEl) _cpAvEl.src = 'https://ui-avatars.com/api/?name=' + encodeURIComponent(name||'U') + '&background=007AFF&color=fff&size=200';
        var el = document.getElementById('cp-status'); if (el) el.textContent = 'Active now';
    }

    var overlay = document.getElementById('contact-profile-overlay');
    if (overlay) overlay.style.display = 'block';

    switchCPMediaTab('photos');
    triggerHaptic(10);
}

function openChatUserProfile() {
    var handle = document.getElementById('chat-user-handle');
    var username = handle ? handle.textContent.replace('@','').trim() : null;
    if (!username) { openContactProfile(); return; }
if (!window.sb) {
    if (window._currentChatUser) { openUserProfile(window._currentChatUser); return; }
    openContactProfile(); return;
}
    window.sb.from('users').select('*').eq('username', username).single().then(function(res) {
        if (res.data) { openUserProfile(res.data); }
        else { openContactProfile(); }
    });
}

function closeContactProfile() {
    var overlay = document.getElementById('contact-profile-overlay');
    if (overlay) overlay.style.display = 'none';
}

function openCPPrivacy() {
    var overlay = document.getElementById('cp-privacy-overlay');
    if (overlay) overlay.style.display = 'block';
}

function closeCPPrivacy() {
    var overlay = document.getElementById('cp-privacy-overlay');
    if (overlay) overlay.style.display = 'none';
}

function toggleCPMute(btn) {
    var icon = btn.querySelector('i');
    var label = btn.querySelector('span');
    if (icon.classList.contains('fa-bell-slash')) {
        icon.classList.replace('fa-bell-slash', 'fa-bell');
        icon.style.color = '#34C759';
        label.textContent = 'Unmute';
        showToast('Notifications unmuted');
    } else {
        icon.classList.replace('fa-bell', 'fa-bell-slash');
        icon.style.color = '#FF9500';
        label.textContent = 'Mute';
        showToast('Notifications muted');
    }
    triggerHaptic(15);
}

function switchCPMediaTab(tab) {
    var tabs = ['photos', 'videos', 'files'];
    tabs.forEach(function(t) {
        var el = document.getElementById('cp-tab-' + t);
        if (!el) return;
        var isActive = t === tab;
        el.style.background = isActive ? 'rgba(0,122,255,0.1)' : 'transparent';
        el.querySelector('i').style.color = isActive ? '#007AFF' : '#888';
        el.querySelector('span').style.color = isActive ? '#007AFF' : '#888';
    });

    var grid = document.getElementById('cp-media-grid');
    if (!grid) return;
    grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:40px 20px;color:#aaa;font-size:13px;"><i class="fa-regular fa-image" style="font-size:32px;display:block;margin-bottom:10px;color:#ddd;"></i>No shared ' + tab + ' yet</div>';

    if (!window.sb || !window.currentChatUserId) return;

    var mediaType = tab === 'photos' ? 'image' : tab === 'videos' ? 'video' : 'file';
    window.sb.from('messages')
        .select('media_url, media_type, id')
        .or('sender_id.eq.' + (window.currentUser ? window.currentUser.id : '') + ',receiver_id.eq.' + (window.currentUser ? window.currentUser.id : ''))
        .eq('media_type', mediaType)
        .not('media_url', 'is', null)
        .order('created_at', { ascending: false })
        .limit(18)
        .then(function(res) {
            if (!res.data || res.data.length === 0) return;
            grid.innerHTML = '';
            res.data.forEach(function(msg) {
                grid.innerHTML += '<div style="aspect-ratio:1;overflow:hidden;cursor:pointer;" onclick="openImgViewer(\'' + escapeHtml(msg.media_url) + '\')">' +
                    '<img src="' + escapeHtml(msg.media_url) + '" style="width:100%;height:100%;object-fit:cover;" loading="lazy">' +
                '</div>';
            });
        });
}

