var lgStream = null;
var lgRecording = false;
var lgRecorder = null;
var lgChunks = [];
var lgFront = true;
var lgTimerVal = 0;
var lgAudioTrack = null;
var lgGridOn = false;
var lgFlashOn = false;

function openLiquidGlassCamera(audioTrack) {
    lgAudioTrack = audioTrack || null;

    var navBar = document.querySelector('.nav-container');
    if (navBar) navBar.style.display = 'none';

    var existing = document.getElementById('lgCameraPage');
    if (existing) existing.remove();

    var page = document.createElement('div');
    page.id = 'lgCameraPage';
    page.className = 'active';

    page.innerHTML =
        /* Video */
        '<video id="lgVid" autoplay playsinline muted style="width:100%;height:100%;object-fit:cover;transition:filter 0.3s;"></video>' +

        /* Grid overlay */
        '<svg id="lgGridSvg" style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none;display:none;z-index:3;" viewBox="0 0 100 100" preserveAspectRatio="none">' +
            '<line x1="33" y1="0" x2="33" y2="100" stroke="rgba(255,255,255,0.22)" stroke-width="0.3"/>' +
            '<line x1="66" y1="0" x2="66" y2="100" stroke="rgba(255,255,255,0.22)" stroke-width="0.3"/>' +
            '<line x1="0" y1="33" x2="100" y2="33" stroke="rgba(255,255,255,0.22)" stroke-width="0.3"/>' +
            '<line x1="0" y1="66" x2="100" y2="66" stroke="rgba(255,255,255,0.22)" stroke-width="0.3"/>' +
        '</svg>' +

        /* REC indicator */
        '<div id="lgRecBar" style="display:none;position:absolute;top:0;left:0;right:0;height:3px;background:#FF3B30;z-index:10;animation:recPulse 1s infinite;"></div>' +

        /* TOP BAR */
        '<div style="position:absolute;top:0;left:0;right:0;padding:50px 16px 0;display:flex;justify-content:space-between;align-items:center;z-index:10;background:linear-gradient(to bottom,rgba(0,0,0,0.38),transparent);">' +
            '<button class="lg-btn" onclick="closeLgCam()"><i class="fa-solid fa-xmark" style="font-size:18px;"></i></button>' +

            (lgAudioTrack ?
                '<div class="cam-audio-pill" onclick="closeLgCam();openSoundHub(\'' + escapeHtml(lgAudioTrack) + '\');">' +
                    '<i class="fa-solid fa-music" style="color:white;font-size:12px;flex-shrink:0;"></i>' +
                    '<span>' + escapeHtml(lgAudioTrack) + '</span>' +
                '</div>'
            :
                '<div class="cam-audio-pill" onclick="closeLgCam();openSoundHub();">' +
                    '<i class="fa-solid fa-music" style="color:rgba(255,255,255,0.7);font-size:12px;flex-shrink:0;"></i>' +
                    '<span style="color:rgba(255,255,255,0.7);">Add Audio</span>' +
                '</div>'
            ) +

            '<button class="lg-btn" onclick="lgCycleFlash()" id="lgFlashBtn"><i class="fa-solid fa-bolt" id="lgFlashIc" style="font-size:16px;opacity:0.5;"></i></button>' +
        '</div>' +

        /* RIGHT CONTROLS */
        '<div style="position:absolute;right:14px;top:50%;transform:translateY(-50%);display:flex;flex-direction:column;gap:16px;z-index:10;">' +
            '<button class="lg-btn" onclick="lgFlipCam()"><i class="fa-solid fa-camera-rotate" style="font-size:18px;"></i></button>' +
            '<button class="lg-btn" onclick="lgToggleGrid()" id="lgGridBtn"><i class="fa-solid fa-border-all" style="font-size:15px;opacity:0.55;" id="lgGridIc"></i></button>' +
            '<div style="position:relative;">' +
                '<button class="lg-btn" onclick="lgCycleTimer()" id="lgTimerBtn"><i class="fa-solid fa-stopwatch" style="font-size:16px;opacity:0.55;"></i></button>' +
                '<span id="lgTimerBdg" style="display:none;position:absolute;top:-4px;right:-4px;background:#007AFF;color:white;font-size:9px;font-weight:800;border-radius:10px;padding:1px 5px;"></span>' +
            '</div>' +
        '</div>' +

        /* BOTTOM BAR */
        '<div style="position:absolute;bottom:0;left:0;right:0;padding:0 0 44px;z-index:10;background:linear-gradient(transparent,rgba(0,0,0,0.48));">' +
            /* Duration pills */
            '<div style="display:flex;justify-content:center;gap:6px;margin-bottom:28px;padding:0 16px;overflow-x:auto;">' +
                '<div class="dur-pill" onclick="lgSetDur(this,\'15s\')">15s</div>' +
                '<div class="dur-pill active" onclick="lgSetDur(this,\'60s\')">60s</div>' +
                '<div class="dur-pill" onclick="lgSetDur(this,\'3m\')">3m</div>' +
                '<div class="dur-pill" onclick="lgSetDur(this,\'10m\')">10m</div>' +
            '</div>' +
            /* Controls row */
            '<div style="display:flex;align-items:center;justify-content:space-around;padding:0 30px;">' +
                '<button onclick="lgGallery()" style="width:52px;height:52px;border-radius:14px;background:rgba(255,255,255,0.2);border:2px solid rgba(255,255,255,0.4);cursor:pointer;backdrop-filter:blur(10px);display:flex;align-items:center;justify-content:center;">' +
                    '<i class="fa-regular fa-image" style="color:white;font-size:22px;"></i>' +
                '</button>' +
                '<div class="shutter-ring" id="lgShutter" onclick="lgToggleRec()">' +
                    '<div class="shutter-dot" id="lgDot"></div>' +
                '</div>' +
                '<button class="lg-btn" onclick="lgFlipCam()" style="width:52px;height:52px;">' +
                    '<i class="fa-solid fa-camera-rotate" style="font-size:20px;"></i>' +
                '</button>' +
            '</div>' +
        '</div>' +

        /* Countdown overlay */
        '<div id="lgCd" style="display:none;position:absolute;inset:0;background:rgba(0,0,0,0.45);z-index:20;align-items:center;justify-content:center;">' +
            '<span id="lgCdNum" style="font-size:110px;font-weight:900;color:white;text-shadow:0 4px 30px rgba(0,0,0,0.5);"></span>' +
        '</div>';

    var appRoot = document.querySelector('.app') || document.body;
    appRoot.appendChild(page);
    lgStartStream();
}

async function lgStartStream() {
    try {
        if (lgStream) lgStream.getTracks().forEach(function(t) { t.stop(); });
        lgStream = await navigator.mediaDevices.getUserMedia({
            video: { facingMode: lgFront ? 'user' : 'environment', width: { ideal: 1080 } },
            audio: true
        });
        var vid = document.getElementById('lgVid');
        if (vid) {
            vid.srcObject = lgStream;
            vid.style.transform = lgFront ? 'scaleX(-1)' : 'scaleX(1)';
        }
    } catch(e) {
        showToast('Camera access needed');
        closeLgCam();
    }
}

function closeLgCam() {
    if (lgStream) { lgStream.getTracks().forEach(function(t) { t.stop(); }); lgStream = null; }
    lgRecording = false;
    lgAudioTrack = null;
    var page = document.getElementById('lgCameraPage');
    if (page) page.remove();
    // Only show nav bar if we're NOT inside the reel overlay
    var reelOpen = document.getElementById('reel-overlay');
    var reelIsOpen = reelOpen && reelOpen.style.display !== 'none' && reelOpen.style.display !== '';
    if (!reelIsOpen) {
        showNavBar();
    }
}

function lgFlipCam() {
    lgFront = !lgFront;
    if (lgStream) lgStream.getTracks().forEach(function(t) { t.stop(); });
    lgStartStream();
    triggerHaptic(10);
}

function lgCycleFlash() {
    lgFlashOn = !lgFlashOn;
    var ic = document.getElementById('lgFlashIc');
    if (ic) ic.style.opacity = lgFlashOn ? '1' : '0.5';
    var ic2 = document.getElementById('lgFlashIc');
    if (ic2) ic2.style.color = lgFlashOn ? '#FFD700' : 'white';
    showToast(lgFlashOn ? 'Flash On' : 'Flash Off');
    if (lgStream) {
        var track = lgStream.getVideoTracks()[0];
        if (track && track.getCapabilities && track.getCapabilities().torch) {
            track.applyConstraints({ advanced: [{ torch: lgFlashOn }] }).catch(function(){});
        }
    }
    triggerHaptic(10);
}

function lgToggleGrid() {
    lgGridOn = !lgGridOn;
    var svg = document.getElementById('lgGridSvg');
    var ic = document.getElementById('lgGridIc');
    if (svg) svg.style.display = lgGridOn ? 'block' : 'none';
    if (ic) { ic.style.opacity = lgGridOn ? '1' : '0.55'; ic.style.color = lgGridOn ? '#007AFF' : 'white'; }
    triggerHaptic(10);
}

function lgCycleTimer() {
    var opts = [0, 3, 5, 10];
    var idx = opts.indexOf(lgTimerVal);
    lgTimerVal = opts[(idx + 1) % opts.length];
    var bdg = document.getElementById('lgTimerBdg');
    var ic = document.querySelector('#lgTimerBtn i');
    if (bdg) { bdg.style.display = lgTimerVal > 0 ? 'block' : 'none'; bdg.textContent = lgTimerVal + 's'; }
    if (ic) ic.style.opacity = lgTimerVal > 0 ? '1' : '0.55';
    showToast(lgTimerVal > 0 ? 'Timer: ' + lgTimerVal + 's' : 'Timer off');
    triggerHaptic(10);
}

function lgSetDur(el, dur) {
    document.querySelectorAll('#lgCameraPage .dur-pill').forEach(function(p) { p.classList.remove('active'); });
    el.classList.add('active');
}

function lgToggleRec() {
    if (lgTimerVal > 0 && !lgRecording) {
        var cd = document.getElementById('lgCd');
        var num = document.getElementById('lgCdNum');
        if (cd) cd.style.display = 'flex';
        var count = lgTimerVal;
        var tick = function() {
            if (num) num.textContent = count;
            if (count <= 0) {
                if (cd) cd.style.display = 'none';
                lgStartRec();
                return;
            }
            count--;
            setTimeout(tick, 1000);
        };
        tick();
        return;
    }
    if (lgRecording) { lgStopRec(); } else { lgStartRec(); }
}

function lgStartRec() {
    if (!lgStream) return;
    lgRecording = true; lgChunks = [];
    var dot = document.getElementById('lgDot');
    var bar = document.getElementById('lgRecBar');
    if (dot) dot.classList.add('rec');
    if (bar) bar.style.display = 'block';
    try {
        lgRecorder = new MediaRecorder(lgStream, { mimeType: 'video/webm' });
        lgRecorder.ondataavailable = function(e) { if (e.data.size > 0) lgChunks.push(e.data); };
        lgRecorder.onstop = function() {
    var blob = new Blob(lgChunks, { type: 'video/webm' });
    window._lastRecordedBlob = blob;
    triggerHaptic(30);
    closeLgCam();
    openPreviewEditScreen();
};
        lgRecorder.start();
    } catch(e) { console.warn('[LgCam] Record error:', e); }
    triggerHaptic(30);
}

function lgStopRec() {
    lgRecording = false;
    var dot = document.getElementById('lgDot');
    var bar = document.getElementById('lgRecBar');
    if (dot) dot.classList.remove('rec');
    if (bar) bar.style.display = 'none';
    if (lgRecorder && lgRecorder.state !== 'inactive') lgRecorder.stop();
    triggerHaptic(20);
}

function lgGallery() {
    var input = document.createElement('input');
    input.type = 'file'; input.accept = 'video/*,image/*';
    input.onchange = function(e) {
        var f = e.target.files[0];
        if (f) { closeLgCam(); showToast('Media selected: ' + f.name); }
    };
    input.click();
}

// ============================================================
// REAL WEBRTC CALLS — Supabase-signaled peer-to-peer
// ============================================================
var rtcLocalStream   = null;
var rtcRemoteStream  = null;
var rtcPeerConn      = null;
var rtcCallActive    = false;
var rtcCallId        = null;
var rtcSignalChannel = null;

var RTC_CONFIG = {
    iceServers: [
        { urls: 'stun:stun.l.google.com:19302' },
        { urls: 'stun:stun1.l.google.com:19302' }
    ]
};

// Called by the CALLER after initiateCall() writes the row
async function startRealCall(targetUserId, targetUserName, isVideo) {
    isVideo = isVideo || false;
    if (rtcCallActive) { showToast('Already in a call'); return; }

    try {
        rtcLocalStream = await navigator.mediaDevices.getUserMedia({ audio: true, video: isVideo });
    } catch(e) {
        showToast('Microphone permission is required for calls');
        return;
    }

    rtcCallActive = true;
    var _callerAvatar = '';
    if (window.sb) {
        try {
            var _pr = await window.sb.from('profiles').select('avatar_url').eq('id', targetUserId).single();
            if (_pr.data) _callerAvatar = _pr.data.avatar_url || '';
        } catch(e) {}
    }
    _showCallOverlay(targetUserName, isVideo, 'outgoing', _callerAvatar, targetUserId);

    rtcPeerConn = new RTCPeerConnection(RTC_CONFIG);
    rtcLocalStream.getTracks().forEach(function(t) { rtcPeerConn.addTrack(t, rtcLocalStream); });

    rtcPeerConn.ontrack = function(e) {
        rtcRemoteStream = e.streams[0];
        var remoteAudio = document.getElementById('call-remote-audio');
        if (remoteAudio) { remoteAudio.srcObject = rtcRemoteStream; remoteAudio.play().catch(function(){}); }
    };

    // Send ICE candidates to Supabase
    rtcPeerConn.onicecandidate = async function(e) {
        if (!e.candidate || !rtcCallId) return;
        await window.sb.from('call_signals').insert({
            call_id:   rtcCallId,
            sender_id: currentUser.id,
            type:      'ice',
            payload:   JSON.stringify(e.candidate)
        });
    };

    var offer = await rtcPeerConn.createOffer();
    await rtcPeerConn.setLocalDescription(offer);

    // Store offer in the call row
    await window.sb.from('calls').update({ offer: JSON.stringify(offer) }).eq('id', rtcCallId);

    // Listen for answer + ICE from callee
    rtcSignalChannel = window.sb
        .channel('call_' + rtcCallId)
        .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'call_signals', filter: 'call_id=eq.' + rtcCallId },
            async function(payload) {
                var sig = payload.new;
                if (sig.sender_id === currentUser.id) return;
                if (sig.type === 'answer') {
                    await rtcPeerConn.setRemoteDescription(new RTCSessionDescription(JSON.parse(sig.payload)));
                    showToast(targetUserName + ' answered 📞');
                    triggerHaptic(30);
                    var callStatus = document.getElementById('call-status-text');
                    if (callStatus) callStatus.textContent = 'Connected';
                } else if (sig.type === 'ice') {
                    try { await rtcPeerConn.addIceCandidate(new RTCIceCandidate(JSON.parse(sig.payload))); } catch(e) {}
                } else if (sig.type === 'end') {
                    endRealCall();
                }
            })
        .subscribe();
}

// Called when the CALLEE accepts the incoming call
async function acceptIncomingCall(callId, callerId) {
    if (rtcCallActive) { showToast('Already in a call'); return; }
    rtcCallId = callId;

    try {
        rtcLocalStream = await navigator.mediaDevices.getUserMedia({ audio: true, video: false });
    } catch(e) {
        showToast('Microphone permission is required');
        return;
    }

    rtcCallActive = true;

    var callRow = await window.sb.from('calls').select('*').eq('id', callId).single();
    if (!callRow.data || !callRow.data.offer) { showToast('Call expired'); endRealCall(); return; }

    rtcPeerConn = new RTCPeerConnection(RTC_CONFIG);
    rtcLocalStream.getTracks().forEach(function(t) { rtcPeerConn.addTrack(t, rtcLocalStream); });

    rtcPeerConn.ontrack = function(e) {
        rtcRemoteStream = e.streams[0];
        var remoteAudio = document.getElementById('call-remote-audio');
        if (remoteAudio) { remoteAudio.srcObject = rtcRemoteStream; remoteAudio.play().catch(function(){}); }
    };

    rtcPeerConn.onicecandidate = async function(e) {
        if (!e.candidate) return;
        await window.sb.from('call_signals').insert({
            call_id:   callId,
            sender_id: currentUser.id,
            type:      'ice',
            payload:   JSON.stringify(e.candidate)
        });
    };

    await rtcPeerConn.setRemoteDescription(new RTCSessionDescription(JSON.parse(callRow.data.offer)));
    var answer = await rtcPeerConn.createAnswer();
    await rtcPeerConn.setLocalDescription(answer);

    await window.sb.from('call_signals').insert({
        call_id: callId, sender_id: currentUser.id, type: 'answer', payload: JSON.stringify(answer)
    });
    await window.sb.from('calls').update({ status: 'active' }).eq('id', callId);

    // Listen for ICE + end from caller
    rtcSignalChannel = window.sb
        .channel('call_answer_' + callId)
        .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'call_signals', filter: 'call_id=eq.' + callId },
            async function(payload) {
                var sig = payload.new;
                if (sig.sender_id === currentUser.id) return;
                if (sig.type === 'ice') {
                    try { await rtcPeerConn.addIceCandidate(new RTCIceCandidate(JSON.parse(sig.payload))); } catch(e) {}
                } else if (sig.type === 'end') {
                    endRealCall();
                }
            })
        .subscribe();

    var callStatus = document.getElementById('call-status-text');
    if (callStatus) callStatus.textContent = 'Connected';
    triggerHaptic(50);
}

// ============================================================
// CALL ENGINE — COMPLETE
// ============================================================
var _callTimerInterval  = null;
var _callTimerSeconds   = 0;
var _callIsVideo        = false;
var _callTargetId       = null;
var _callTargetName     = '';
var _callTargetAvatar   = '';
var _callMicMuted       = false;
var _callCamOff         = false;
var _callSpeakerOn      = true;
var _callMinimized      = false;
var _callNoAnswerTimer  = null;
var _vmRecorder         = null;
var _vmChunks           = [];
var _vmBlob             = null;
var _vmTimerInterval    = null;
var _vmSeconds          = 0;
var _callBgBlurEnabled  = false;
var _callDotsInterval   = null;

function _showCallOverlay(name, isVideo, direction, avatarUrl, targetId) {
    _callTargetName   = name || 'Unknown';
    _callTargetId     = targetId || null;
    _callTargetAvatar = avatarUrl || '';
    _callIsVideo      = isVideo || false;

    var ov = document.getElementById('call-overlay');
    if (!ov) return;
    ov.style.display = 'flex';
    ov.setAttribute('data-state', direction === 'incoming' ? 'incoming' : 'calling');

    // Populate avatar
    var img = document.getElementById('call-avatar-img');
    if (img && avatarUrl) { img.src = avatarUrl; img.style.display = 'block'; }
    var naImg = document.getElementById('call-na-avatar-img');
    if (naImg && avatarUrl) naImg.src = avatarUrl;

    // Populate names
    document.getElementById('call-display-name').textContent = name || 'Unknown';
    document.getElementById('call-na-name').textContent = name || 'Unknown';

    // vm sheet name/avatar
    var vmName = document.getElementById('vm-to-name');
    var vmAvatar = document.getElementById('vm-to-avatar-img');
    if (vmName) vmName.textContent = name || 'Unknown';
    if (vmAvatar && avatarUrl) vmAvatar.src = avatarUrl;

    // Status text + animated dots
    var statusEl = document.getElementById('call-status-text');
    var topStatus = document.getElementById('call-top-status');
    var dots = document.getElementById('call-dots');
    if (statusEl) statusEl.style.display = 'flex';
    if (topStatus) topStatus.textContent = isVideo ? 'TrustVideo' : 'TrustCall';

    if (_callDotsInterval) clearInterval(_callDotsInterval);
    var dotCount = 0;
    _callDotsInterval = setInterval(function() {
        dotCount = (dotCount + 1) % 4;
        if (dots) dots.textContent = '.'.repeat(dotCount);
    }, 500);

    if (direction === 'outgoing') {
        if (statusEl) statusEl.childNodes[0].textContent = 'Calling';
        // Auto no-answer after 30s
        _callNoAnswerTimer = setTimeout(function() {
            _showNoAnswerScreen();
        }, 30000);
    } else {
        if (statusEl) statusEl.childNodes[0].textContent = 'Incoming call';
        triggerHaptic(100);
    }

    // Init local video if video call
    if (isVideo && direction === 'outgoing') _startLocalVideo();

    // Tap to show/hide controls
    ov.onclick = function(e) {
        if (e.target === ov || e.target.id === 'call-remote-video' || e.target.id === 'call-avatar-state') {
            _toggleCallControls();
        }
    };

    // Swipe down to minimize
    var startY = 0;
    ov.addEventListener('touchstart', function(e) { startY = e.touches[0].clientY; }, { passive: true });
    ov.addEventListener('touchmove', function(e) {
        if (e.touches[0].clientY - startY > 80) minimizeCall();
    }, { passive: true });

    // Make self preview draggable
    _initDraggableSelfPreview();
}

function _startLocalVideo() {
    navigator.mediaDevices.getUserMedia({ video: true, audio: true }).then(function(stream) {
        rtcLocalStream = stream;
        var localVid = document.getElementById('call-local-video');
        if (localVid) { localVid.srcObject = stream; }
        var selfPreview = document.getElementById('call-self-preview');
        if (selfPreview) selfPreview.style.display = 'block';
    }).catch(function() {});
}

function _initDraggableSelfPreview() {
    var el = document.getElementById('call-self-preview');
    if (!el) return;
    var isDragging = false, startX, startY, origLeft, origTop;
    el.addEventListener('touchstart', function(e) {
        if (e.touches.length !== 1) return;
        isDragging = true;
        startX = e.touches[0].clientX; startY = e.touches[0].clientY;
        origLeft = el.offsetLeft; origTop = el.offsetTop;
    }, { passive: true });
    el.addEventListener('touchmove', function(e) {
        if (!isDragging) return;
        var dx = e.touches[0].clientX - startX;
        var dy = e.touches[0].clientY - startY;
        el.style.left = Math.max(0, origLeft + dx) + 'px';
        el.style.top  = Math.max(0, origTop  + dy) + 'px';
        el.style.right = 'auto';
    }, { passive: true });
    el.addEventListener('touchend', function() { isDragging = false; });
}

function _callConnected() {
    if (_callNoAnswerTimer) { clearTimeout(_callNoAnswerTimer); _callNoAnswerTimer = null; }
    if (_callDotsInterval) { clearInterval(_callDotsInterval); _callDotsInterval = null; }

    var ov = document.getElementById('call-overlay');
    if (ov) ov.setAttribute('data-state', 'connected');

    // Show timer
    var timerDisplay = document.getElementById('call-timer-display');
    var topStatus = document.getElementById('call-top-status');
    if (timerDisplay) timerDisplay.style.display = 'block';
    if (topStatus) topStatus.style.display = 'none';

    _callTimerSeconds = 0;
    _callTimerInterval = setInterval(function() {
        _callTimerSeconds++;
        var m = Math.floor(_callTimerSeconds / 60);
        var s = _callTimerSeconds % 60;
        var timeStr = m + ':' + (s < 10 ? '0' : '') + s;
        if (timerDisplay) timerDisplay.textContent = timeStr;
        // Keep mini bubble timer in sync
        var miniTimer = document.getElementById('call-mini-timer');
        if (miniTimer) miniTimer.textContent = timeStr;
    }, 1000);

    var statusEl = document.getElementById('call-status-text');
    if (statusEl) statusEl.style.display = 'none';

    triggerHaptic(20);
}

function _showNoAnswerScreen() {
    if (_callDotsInterval) { clearInterval(_callDotsInterval); _callDotsInterval = null; }
    var ov = document.getElementById('call-overlay');
    var na = document.getElementById('call-no-answer');
    var avatarState = document.getElementById('call-avatar-state');
    var topBar = document.getElementById('call-top-bar');
    var bottomDock = document.getElementById('call-bottom-dock');
    if (ov) ov.setAttribute('data-state', 'noanswer');
    // Hide the "Calling..." screen so it doesn't overlap no-answer
    if (avatarState) avatarState.style.display = 'none';
    if (topBar) topBar.style.display = 'none';
    if (bottomDock) bottomDock.style.display = 'none';
    if (na) na.style.display = 'flex';
}

function _toggleCallControls() {
    var top = document.getElementById('call-top-bar');
    var bot = document.getElementById('call-bottom-dock');
    var currentOpacity = top ? top.style.opacity : '1';
    var hide = currentOpacity !== '0';
    if (top) top.style.opacity = hide ? '0' : '1';
    if (bot) bot.style.opacity = hide ? '0' : '1';
}

function endRealCall() {
    if (_callTimerInterval) { clearInterval(_callTimerInterval); _callTimerInterval = null; }
    if (_callDotsInterval) { clearInterval(_callDotsInterval); _callDotsInterval = null; }
    if (_callNoAnswerTimer) { clearTimeout(_callNoAnswerTimer); _callNoAnswerTimer = null; }
    if (rtcPeerConn) { rtcPeerConn.close(); rtcPeerConn = null; }
    if (rtcLocalStream) { rtcLocalStream.getTracks().forEach(function(t) { t.stop(); }); rtcLocalStream = null; }
    if (rtcSignalChannel && window.sb) { window.sb.removeChannel(rtcSignalChannel); rtcSignalChannel = null; }
    if (rtcCallId && window.sb && currentUser) {
        window.sb.from('call_signals').insert({ call_id: rtcCallId, sender_id: currentUser.id, type: 'end', payload: '{}' }).then(function() {});
        window.sb.from('calls').update({ status: 'ended' }).eq('id', rtcCallId).then(function() {});
        rtcCallId = null;
    }
    rtcCallActive = false;
    var ov = document.getElementById('call-overlay');
    if (ov) { ov.style.display = 'none'; ov.removeAttribute('data-state'); }
    var remoteAudio = document.getElementById('call-remote-audio');
    if (remoteAudio) remoteAudio.srcObject = null;
    var remoteVid = document.getElementById('call-remote-video');
    if (remoteVid) { remoteVid.srcObject = null; remoteVid.style.display = 'none'; }
    var selfPreview = document.getElementById('call-self-preview');
    if (selfPreview) selfPreview.style.display = 'none';
    var noAnswer = document.getElementById('call-no-answer');
    if (noAnswer) noAnswer.style.display = 'none';
    var mini = document.getElementById('call-mini-bubble');
    if (mini) mini.style.display = 'none';
    var timerDisplay = document.getElementById('call-timer-display');
    var topStatus = document.getElementById('call-top-status');
    if (timerDisplay) { timerDisplay.style.display = 'none'; }
    if (topStatus) topStatus.style.display = 'block';
    _callTimerSeconds = 0;
    _callMinimized = false;
    showToast('Call ended');
    triggerHaptic(20);
}

function acceptCall() {
    if (window._pendingIncomingCallId) {
        acceptIncomingCall(window._pendingIncomingCallId, window._pendingIncomingCallerId);
    }
}

function retryCall() {
    var noAnswer = document.getElementById('call-no-answer');
    if (noAnswer) noAnswer.style.display = 'none';
    // Reset call state so startRealCall doesn't block with "Already in a call"
    rtcCallActive = false;
    if (rtcPeerConn) { rtcPeerConn.close(); rtcPeerConn = null; }
    if (rtcLocalStream) { rtcLocalStream.getTracks().forEach(function(t){ t.stop(); }); rtcLocalStream = null; }
    // Restore the calling UI for the fresh attempt
    var avatarState = document.getElementById('call-avatar-state');
    var topBar = document.getElementById('call-top-bar');
    if (avatarState) avatarState.style.display = 'flex';
    if (topBar) { topBar.style.display = 'flex'; topBar.style.opacity = '1'; }
    if (_callTargetId) {
        startRealCall(_callTargetId, _callTargetName, _callIsVideo);
    }
}

function closeCallNoAnswer() {
    endRealCall();
}

function minimizeCall() {
    var ov = document.getElementById('call-overlay');
    var mini = document.getElementById('call-mini-bubble');
    if (ov) ov.style.display = 'none';
    if (mini) mini.style.display = 'block';
    _callMinimized = true;
}

function maximizeCall() {
    var ov = document.getElementById('call-overlay');
    var mini = document.getElementById('call-mini-bubble');
    if (ov) ov.style.display = 'flex';
    if (mini) mini.style.display = 'none';
    _callMinimized = false;
}

function toggleCallMic() {
    _callMicMuted = !_callMicMuted;
    if (rtcLocalStream) {
        rtcLocalStream.getAudioTracks().forEach(function(t) { t.enabled = !_callMicMuted; });
    }
    var btn = document.getElementById('call-mic-btn');
    if (btn) {
        btn.classList.toggle('call-ctrl-muted', _callMicMuted);
        btn.innerHTML = _callMicMuted ? '<i class="fa-solid fa-microphone-slash"></i>' : '<i class="fa-solid fa-microphone"></i>';
    }
    triggerHaptic(10);
}

function toggleCallCamera() {
    _callCamOff = !_callCamOff;
    if (rtcLocalStream) {
        rtcLocalStream.getVideoTracks().forEach(function(t) { t.enabled = !_callCamOff; });
    }
    var btn = document.getElementById('call-cam-btn');
    var camOff = document.getElementById('call-self-cam-off');
    if (btn) {
        btn.classList.toggle('call-ctrl-muted', _callCamOff);
        btn.innerHTML = _callCamOff ? '<i class="fa-solid fa-video-slash"></i>' : '<i class="fa-solid fa-video"></i>';
    }
    if (camOff) camOff.style.display = _callCamOff ? 'flex' : 'none';
    triggerHaptic(10);
}

function callFlipCamera() {
    if (!rtcLocalStream) return;
    var track = rtcLocalStream.getVideoTracks()[0];
    if (!track) return;
    var settings = track.getSettings();
    var facingMode = settings.facingMode === 'user' ? 'environment' : 'user';
    navigator.mediaDevices.getUserMedia({ video: { facingMode: facingMode }, audio: false }).then(function(newStream) {
        var newTrack = newStream.getVideoTracks()[0];
        if (rtcPeerConn) {
            var sender = rtcPeerConn.getSenders().find(function(s) { return s.track && s.track.kind === 'video'; });
            if (sender) sender.replaceTrack(newTrack);
        }
        rtcLocalStream.removeTrack(track);
        track.stop();
        rtcLocalStream.addTrack(newTrack);
        var localVid = document.getElementById('call-local-video');
        if (localVid) localVid.srcObject = rtcLocalStream;
    }).catch(function() {});
    triggerHaptic(15);
}

function toggleCallSpeaker() {
    _callSpeakerOn = !_callSpeakerOn;
    var btn = document.getElementById('call-speaker-btn');
    if (btn) {
        btn.classList.toggle('call-ctrl-active', _callSpeakerOn);
        btn.innerHTML = _callSpeakerOn ? '<i class="fa-solid fa-volume-high"></i>' : '<i class="fa-solid fa-volume-xmark"></i>';
    }
    triggerHaptic(10);
}

function toggleCallBgBlur() {
    _callBgBlurEnabled = !_callBgBlurEnabled;
    var remoteVid = document.getElementById('call-remote-video');
    if (remoteVid) remoteVid.style.filter = _callBgBlurEnabled ? 'blur(0)' : '';
    closeCallMoreMenu();
    showToast(_callBgBlurEnabled ? 'Background blur on' : 'Background blur off');
}

function sendCallReaction(emoji) {
    var layer = document.getElementById('call-reactions-layer');
    if (!layer) return;
    var el = document.createElement('div');
    var left = 20 + Math.random() * 60;
    el.style.cssText = 'position:absolute;bottom:120px;left:' + left + '%;font-size:32px;pointer-events:none;animation:callReactionFloat 2.5s ease-out forwards;z-index:9;';
    el.textContent = emoji;
    layer.appendChild(el);
    setTimeout(function() { el.remove(); }, 2600);
    triggerHaptic(8);
}

function openCallMoreMenu() {
    var m = document.getElementById('call-more-menu');
    if (m) m.style.display = 'flex';
}
function closeCallMoreMenu() {
    var m = document.getElementById('call-more-menu');
    if (m) m.style.display = 'none';
}

function callShareScreen() {
    closeCallMoreMenu();
    if (!navigator.mediaDevices || !navigator.mediaDevices.getDisplayMedia) {
        showToast('Screen sharing not supported on this device'); return;
    }
    navigator.mediaDevices.getDisplayMedia({ video: true }).then(function(screenStream) {
        var screenTrack = screenStream.getVideoTracks()[0];
        if (rtcPeerConn) {
            var sender = rtcPeerConn.getSenders().find(function(s) { return s.track && s.track.kind === 'video'; });
            if (sender) sender.replaceTrack(screenTrack);
        }
        screenTrack.onended = function() { showToast('Screen share stopped'); };
        showToast('Sharing screen…');
    }).catch(function() { showToast('Screen share cancelled'); });
}

// Voice message in call
function openCallVoiceMsg() {
    var sheet = document.getElementById('call-voice-msg-sheet');
    if (sheet) sheet.style.display = 'flex';
}
function closeCallVoiceMsg() {
    var sheet = document.getElementById('call-voice-msg-sheet');
    if (sheet) sheet.style.display = 'none';
    _stopVmRecording(true);
    _vmBlob = null;
    var sendBtn = document.getElementById('vm-send-btn');
    var recBtn  = document.getElementById('vm-record-btn');
    if (sendBtn) sendBtn.style.display = 'none';
    if (recBtn)  recBtn.style.display  = 'flex';
    document.getElementById('vm-timer').textContent = '0:00';
    document.getElementById('vm-waveform').innerHTML = '<div style="color:rgba(255,255,255,0.3);font-size:13px;" id="vm-waveform-idle">Hold button to record</div>';
}

function startVmRecording() {
    if (_vmRecorder) return;
    _vmChunks = [];
    navigator.mediaDevices.getUserMedia({ audio: true }).then(function(stream) {
        _vmRecorder = new MediaRecorder(stream, { mimeType: MediaRecorder.isTypeSupported('audio/webm') ? 'audio/webm' : 'audio/ogg' });
        _vmRecorder.ondataavailable = function(e) { if (e.data.size > 0) _vmChunks.push(e.data); };
        _vmRecorder.onstop = function() {
            _vmBlob = new Blob(_vmChunks, { type: _vmRecorder.mimeType });
            stream.getTracks().forEach(function(t) { t.stop(); });
            var sendBtn = document.getElementById('vm-send-btn');
            var recBtn  = document.getElementById('vm-record-btn');
            if (sendBtn) sendBtn.style.display = 'flex';
            if (recBtn)  recBtn.innerHTML = '<i class="fa-solid fa-microphone"></i> Re-record';
        };
        _vmRecorder.start();
        _vmSeconds = 0;
        _buildVmWaveform();
        _vmTimerInterval = setInterval(function() {
            _vmSeconds++;
            var m = Math.floor(_vmSeconds / 60), s = _vmSeconds % 60;
            var t = document.getElementById('vm-timer');
            if (t) t.textContent = m + ':' + (s < 10 ? '0' : '') + s;
            if (_vmSeconds >= 120) stopVmRecording(); // 2min cap
        }, 1000);
        var recBtn = document.getElementById('vm-record-btn');
        if (recBtn) { recBtn.style.background = '#FF3B30'; recBtn.innerHTML = '<i class="fa-solid fa-circle"></i> Recording…'; }
    }).catch(function() { showToast('Microphone permission required'); });
}

function _buildVmWaveform() {
    var wf = document.getElementById('vm-waveform');
    if (!wf) return;
    wf.innerHTML = '';
    for (var i = 0; i < 28; i++) {
        var bar = document.createElement('div');
        var delay = (i * 0.06).toFixed(2);
        var height = (10 + Math.random() * 30);
        bar.style.cssText = 'width:3px;background:#007AFF;border-radius:2px;height:' + height + 'px;animation:vmBarAnim 0.6s ease-in-out ' + delay + 's infinite alternate;flex-shrink:0;';
        wf.appendChild(bar);
    }
}

function stopVmRecording() { _stopVmRecording(false); }
function _stopVmRecording(cancel) {
    if (_vmTimerInterval) { clearInterval(_vmTimerInterval); _vmTimerInterval = null; }
    if (_vmRecorder && _vmRecorder.state !== 'inactive') {
        if (cancel) { _vmRecorder.ondataavailable = null; _vmRecorder.onstop = null; }
        _vmRecorder.stop();
    }
    _vmRecorder = null;
}

async function sendVoiceMessage() {
    if (!_vmBlob) { showToast('Record a message first'); return; }
    if (!window.sb || !currentUser || !_callTargetId) { showToast('Not connected'); return; }
    var sendBtn = document.getElementById('vm-send-btn');
    if (sendBtn) { sendBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>'; sendBtn.disabled = true; }
    try {
        var ext = _vmBlob.type.includes('webm') ? 'webm' : 'ogg';
        var path = currentUser.id + '/vm_' + Date.now() + '.' + ext;
        var { data, error } = await window.sb.storage.from('voice_messages').upload(path, _vmBlob, { contentType: _vmBlob.type });
        if (error) throw error;
        var { data: { publicUrl } } = window.sb.storage.from('voice_messages').getPublicUrl(path);
        var caption = document.getElementById('vm-caption-input').value.trim();
        await window.sb.from('messages').insert({
            sender_id: currentUser.id, receiver_id: _callTargetId,
            message_type: 'voice', media_url: publicUrl,
            content: caption || null, created_at: new Date().toISOString()
        });
        closeCallVoiceMsg();
        endRealCall();
        showToast('Voice message sent ✓');
    } catch(e) {
        if (sendBtn) { sendBtn.innerHTML = '<i class="fa-solid fa-paper-plane"></i>'; sendBtn.disabled = false; }
        showToast('Failed to send. Try again.');
    }
}

// Re-wire DOMContentLoaded for incoming call listener
document.addEventListener('DOMContentLoaded', function() {
    if (!window.sb) {
        var waitSb = setInterval(function() {
            if (window.sb && currentUser && currentUser.id) {
                clearInterval(waitSb);
                _initIncomingCallListener();
            }
        }, 800);
    } else if (currentUser && currentUser.id) {
        _initIncomingCallListener();
    }
});

function _initIncomingCallListener() {
    window.sb.channel('incoming_calls_' + currentUser.id)
        .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'calls', filter: 'callee_id=eq.' + currentUser.id },
            async function(payload) {
                var call = payload.new;
                if (call.status !== 'ringing') return;
                window._pendingIncomingCallId   = call.id;
                window._pendingIncomingCallerId = call.caller_id;
                rtcCallId = call.id;
                // Fetch caller name + avatar
                var profile = { full_name: 'Unknown', avatar_url: '' };
                try {
                    var r = await window.sb.from('profiles').select('full_name,avatar_url').eq('id', call.caller_id).single();
                    if (r.data) profile = r.data;
                } catch(e) {}
                _showCallOverlay(profile.full_name, call.type === 'video', 'incoming', profile.avatar_url, call.caller_id);
            })
        .subscribe();
}

// Listen for incoming calls from ANY user (Supabase Realtime)
document.addEventListener('DOMContentLoaded', function() {
    if (!window.sb || !currentUser) return;
    window.sb.channel('incoming_calls_' + (currentUser && currentUser.id ? currentUser.id : 'none'))
        .on('postgres_changes', {
            event: 'INSERT', schema: 'public', table: 'calls',
            filter: 'callee_id=eq.' + (currentUser ? currentUser.id : 'none')
        }, function(payload) {
            var call = payload.new;
            if (call.status !== 'ringing') return;
            window._pendingIncomingCallId     = call.id;
            window._pendingIncomingCallerId   = call.caller_id;
            rtcCallId = call.id;
            // Show incoming call UI
            _showCallOverlay(call.caller_id, call.type === 'video', 'incoming');
            var callOverlay = document.getElementById('call-overlay');
            if (callOverlay) callOverlay.style.display = 'flex';
            triggerHaptic(100);
        })
        .subscribe();
});


