var _giphyTab = 'gif';
function switchGiphyTab(tab) {
    _giphyTab = tab;
    var gif = document.getElementById('gif-tab-btn');
    var stk = document.getElementById('sticker-tab-btn');
    if (gif) { gif.style.background = tab==='gif'?'#007AFF':'var(--bg-secondary,#f0f0f0)'; gif.style.color = tab==='gif'?'white':'var(--text-primary,#000)'; }
    if (stk) { stk.style.background = tab==='sticker'?'#007AFF':'var(--bg-secondary,#f0f0f0)'; stk.style.color = tab==='sticker'?'white':'var(--text-primary,#000)'; }
    var searchBox = document.getElementById('gifSearchBox');
    searchGiphy(searchBox ? searchBox.value : '', tab);
}

var _giphyTimer = null;
async function searchGiphy(query, tab) {
    tab = tab || _giphyTab || 'gif';
    clearTimeout(_giphyTimer);
    _giphyTimer = setTimeout(async function() {
        var grid = document.getElementById('giphy-grid');
        if (!grid) return;
        grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;font-size:20px;"></i></div>';

        try {
            var endpoint = tab === 'sticker' ? 'stickers' : 'gifs';
            var q = query.trim();
            var url = '/api/giphy/search/?q=' + encodeURIComponent(q || 'trending') +
                '&type=' + endpoint;

            var res  = await fetch(url);
            var data = await res.json();
            var items = data.data || [];

            grid.innerHTML = '';
            if (!items.length) {
                grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:#888;">No results</div>';
                return;
            }

            items.forEach(function(item) {
                var src      = item.images.fixed_height_small.url;
                var preview  = item.images.preview_gif ? item.images.preview_gif.url : src;
                var original = item.images.original.url;
                var cell = document.createElement('div');
                cell.style.cssText = 'cursor:pointer;border-radius:6px;overflow:hidden;background:#f0f0f0;aspect-ratio:1;transition:transform 0.15s;';
                cell.onmouseover = function(){ this.style.transform='scale(0.96)'; };
                cell.onmouseout  = function(){ this.style.transform='scale(1)'; };
                var img = document.createElement('img');
                img.src = src;
                img.style.cssText = 'width:100%;height:100%;object-fit:cover;display:block;';
                img.loading = 'lazy';
                img.onclick = function() {
                    sendGiphyInChat(original, item.title || 'GIF');
                    document.getElementById('gifStickerPanel')?.remove();
                };
                cell.appendChild(img);
                grid.appendChild(cell);
            });
        } catch(e) {
            grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:#888;">Could not load. Check connection.</div>';
        }
    }, 400);
}

function sendGiphyInChat(gifUrl, alt) {
   var chBroadcast = document.getElementById('ch-broadcast');
    var isChannel = chBroadcast && chBroadcast.style.display !== 'none';
    var chatBody = isChannel ? document.getElementById('chFeed') : document.getElementById('chat-body');
    if (!chatBody) return;
    var bubble = document.createElement('div');
    bubble.style.cssText = 'margin-left:auto;margin-bottom:10px;max-width:200px;border-radius:18px;overflow:hidden;animation:popIn 0.25s ease;';
    bubble.setAttribute('data-msg-bubble','true');
    var img = document.createElement('img');
    img.src = gifUrl;
    img.alt = alt;
    img.style.cssText = 'width:100%;display:block;border-radius:18px;';
    bubble.appendChild(img);
    chatBody.appendChild(bubble);
    chatBody.scrollTop = chatBody.scrollHeight;
    triggerHaptic(12);
}

function switchGifTab(tab) {
    var gifBtn = document.getElementById('gif-tab-btn');
    var stickerBtn = document.getElementById('sticker-tab-btn');
    var grid = document.getElementById('gif-sticker-grid');
    if (!grid) return;

    if (gifBtn) { gifBtn.style.background = tab === 'gif' ? '#007AFF' : 'var(--bg-secondary,#f0f0f0)'; gifBtn.style.color = tab === 'gif' ? 'white' : 'var(--text-primary,#000)'; }
    if (stickerBtn) { stickerBtn.style.background = tab === 'sticker' ? '#007AFF' : 'var(--bg-secondary,#f0f0f0)'; stickerBtn.style.color = tab === 'sticker' ? 'white' : 'var(--text-primary,#000)'; }

    grid.innerHTML = '';

    if (tab === 'gif') {
        var gifs = ['😂', '🔥', '❤️', '🎉', '😍', '💀', '🙌', '😭', '🚀', '✨', '😎', '🥳'];
        gifs.forEach(function(g, i) {
            var div = document.createElement('div');
            div.style.cssText = 'background:var(--bg-secondary,#f0f0f0);border-radius:10px;aspect-ratio:1;display:flex;align-items:center;justify-content:center;font-size:32px;cursor:pointer;';
            div.textContent = g;
            div.onclick = function() {
                sendGifMessage(g);
                document.getElementById('gifStickerPanel').remove();
            };
            grid.appendChild(div);
        });
    } else {
        var stickers = ['🐶','🐱','🐭','🐹','🐰','🦊','🐻','🐼','🐨','🐯','🦁','🐮'];
        stickers.forEach(function(s) {
            var div = document.createElement('div');
            div.style.cssText = 'background:var(--bg-secondary,#f0f0f0);border-radius:10px;aspect-ratio:1;display:flex;align-items:center;justify-content:center;font-size:36px;cursor:pointer;';
            div.textContent = s;
            div.onclick = function() {
                sendGifMessage(s);
                document.getElementById('gifStickerPanel').remove();
            };
            grid.appendChild(div);
        });
    }
}

function sendGifMessage(content) {
    var chatBody = document.getElementById('chat-body');
    if (!chatBody) return;
    var bubble = document.createElement('div');
    bubble.style.cssText = 'font-size:48px;margin-left:auto;margin-bottom:8px;display:block;text-align:right;animation:popIn 0.25s ease;';
    bubble.textContent = content;
    chatBody.appendChild(bubble);
    chatBody.scrollTop = chatBody.scrollHeight;
    triggerHaptic(12);
}

    async function realToggleFollow(btn, userId) {
    if (!canPerformAction('follow a user')) return;
    var followedUsers = JSON.parse(localStorage.getItem('tf-followed-users') || '[]');
    var isFollowing = followedUsers.indexOf(userId) > -1;
    triggerHaptic(20);

    if (isFollowing) {
        followedUsers = followedUsers.filter(function(id) { return id !== userId; });
        btn.classList.remove('following');
        btn.textContent = 'Follow';

    } else {
        followedUsers.push(userId);
        btn.classList.add('following');
        btn.textContent = 'Following';

    }
    localStorage.setItem('tf-followed-users', JSON.stringify(followedUsers));

    if (window.sb && currentUser && currentUser.id) {
        try {
            if (isFollowing) {
                await sb.from('follows').delete().eq('follower_id', currentUser.id).eq('following_id', userId);
            } else {
                await sb.from('follows').insert({ follower_id: currentUser.id, following_id: userId });
            }
        } catch(e) {
            // Rollback optimistic UI
            if (isFollowing) {
                btn.classList.add('following');
                btn.textContent = 'Following';
            } else {
                btn.classList.remove('following');
                btn.textContent = 'Follow';
            }
        }
    }
}

    // ============================================================
// COMMENT LIKE + REPLY
// ============================================================
async function toggleCommentLike(el, commentId) {
    var icon = el.querySelector('i');
    var count = el.querySelector('span');
    var liked = icon.classList.contains('fa-solid');
    triggerHaptic(15);

    // Optimistic
    icon.classList.toggle('fa-regular');
    icon.classList.toggle('fa-solid');
    icon.style.color = !liked ? '#FF3B30' : '#888';
    if (count) count.textContent = !liked
        ? (parseInt(count.textContent) || 0) + 1
        : Math.max(0, (parseInt(count.textContent) || 1) - 1);

    if (window.sb && currentUser && commentId) {
        try {
            var check = await sb.from('comment_likes')
                .select('id').eq('user_id', currentUser.id).eq('comment_id', commentId).maybeSingle();
            if (check.data) {
                await sb.from('comment_likes').delete().eq('id', check.data.id);
            } else {
                await sb.from('comment_likes').insert({ user_id: currentUser.id, comment_id: commentId });
            }
        } catch(e) {
            // Rollback
            icon.classList.toggle('fa-regular');
            icon.classList.toggle('fa-solid');
            icon.style.color = liked ? '#FF3B30' : '#888';
            if (count) count.textContent = liked
                ? (parseInt(count.textContent) || 0) + 1
                : Math.max(0, (parseInt(count.textContent) || 1) - 1);
        }
    }
}

