(function updateTimeMgmtDisplay() {
    try {
        var sessions = JSON.parse(localStorage.getItem('tf_session_log') || '[]');
        var now = Date.now();
        var dayMs = 86400000;
        var weekTotal = 0;
        var dayCounts = {};
        sessions.forEach(function(s) {
            if (now - s.ts < 7 * dayMs) {
                weekTotal += (s.dur || 0);
                var day = new Date(s.ts).toDateString();
                dayCounts[day] = (dayCounts[day] || 0) + (s.dur || 0);
            }
        });
        var days = Object.values(dayCounts);
        var avg = days.length ? Math.round(weekTotal / 7) : 0;
        function fmtMs(ms) {
            var s = Math.floor(ms/1000), m = Math.floor(s/60), h = Math.floor(m/60);
            return h > 0 ? h + 'h ' + (m%60) + 'm' : (m > 0 ? m + 'm' : '< 1m');
        }
        var avgEl = document.getElementById('tm-daily-avg');
        var wkEl  = document.getElementById('tm-weekly-total');
        if (avgEl) avgEl.textContent = fmtMs(avg);
        if (wkEl)  wkEl.textContent  = fmtMs(weekTotal);
    } catch(e) {}
})();

