/* ── Time Management Bar Chart ── */
async function renderTMBarChart() {
    var wrap = document.getElementById('tmBarChart');
    if (!wrap || wrap.children.length > 0) return;
    var days = ['Sun','Mon','Tue','Wed','Thu','Fri','Today'];
    var vals = [0,0,0,0,0,0,0];
    try {
        if (window.sb && currentUser) {
            var since = new Date(); since.setDate(since.getDate() - 6); since.setHours(0,0,0,0);
            var { data } = await window.sb
                .from('session_logs')
                .select('started_at, duration_seconds')
                .eq('user_id', currentUser.id)
                .gte('started_at', since.toISOString());
            if (data) {
                data.forEach(function(row) {
                    var d = new Date(row.started_at);
                    var idx = Math.floor((d - since) / 86400000);
                    if (idx >= 0 && idx < 7) vals[idx] += Math.round((row.duration_seconds || 0) / 60);
                });
            }
        }
    } catch(e) { /* show zeros on error */ }
    var max = Math.max.apply(null, vals) || 1;
    var colors = ['#007AFF','#34C759','#FF9500','#FF3B30','#5856D6','#FF2D55','#00C7BE'];
    days.forEach(function(d, i) {
        var pct = Math.max(4, Math.round((vals[i] / max) * 100));
        var col = document.createElement('div');
        col.className = 'tf-bar-col';
        col.innerHTML =
            '<div class="tf-bar-fill" style="height:' + pct + '%;background:' + colors[i] + ';border-radius:4px;width:100%;"></div>' +
            '<div class="tf-bar-lbl">' + d + '</div>';
        wrap.appendChild(col);
    });
    // Update hero labels with real data
    var total = vals.reduce(function(s,v){ return s+v; }, 0);
    var activeDays = vals.filter(function(v){ return v > 0; }).length || 1;
    var avg = Math.round(total / activeDays);
    var fmtMin = function(m) {
        if (m < 60) return m + 'm';
        return Math.floor(m/60) + 'h ' + (m%60 ? (m%60)+'m' : '');
    };
    var avgEl = document.getElementById('tmDailyAvgLabel');
    var totEl = document.getElementById('tmWeeklyTotalLabel');
    if (avgEl) avgEl.textContent = total === 0 ? '0m' : fmtMin(avg);
    if (totEl) totEl.innerHTML = total === 0
        ? 'No sessions recorded yet'
        : 'You used TrustFirst <b>' + fmtMin(total) + '</b> in the last 7 days';
}

/* ── Daily Limit picker ── */
function openDailyLimit() {
    var modal = document.createElement('div');
    modal.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;z-index:20000;background:rgba(0,0,0,0.5);backdrop-filter:blur(10px);display:flex;align-items:flex-end;justify-content:center;';
    var opts = ['30 min','1 hour','1.5 hours','2 hours','3 hours'];
    modal.innerHTML = '<div style="background:var(--card-bg,#fff);border-radius:24px 24px 0 0;width:100%;max-width:500px;padding:20px 20px max(44px,env(safe-area-inset-bottom,44px));max-height:85vh;overflow-y:auto;box-sizing:border-box;">' +
        '<div style="width:40px;height:4px;background:#ccc;border-radius:2px;margin:0 auto 20px;"></div>' +
        '<h3 style="font-size:18px;font-weight:800;margin-bottom:16px;color:var(--text-primary,#000);">Set Daily Limit</h3>' +
        opts.map(function(o) {
            return '<div onclick="setDailyLimit(\'' + o + '\',this)" style="padding:15px;border-radius:14px;border:1.5px solid var(--border-color,#eee);margin-bottom:8px;cursor:pointer;font-size:15px;font-weight:600;color:var(--text-primary,#000);">' + o + '</div>';
        }).join('') +
        '<button onclick="this.closest(\'div\').parentElement.remove()" style="width:100%;padding:14px;border-radius:14px;border:none;background:var(--bg-secondary,#f0f0f0);color:var(--text-primary,#000);font-size:15px;cursor:pointer;margin-top:8px;">Cancel</button>' +
        '</div>';
    modal.addEventListener('click', function(e) { if (e.target === modal) modal.remove(); });
    document.body.appendChild(modal);
}

async function setDailyLimit(limit, el) {
    el.closest('div').parentElement.remove();
    var minutes = { '30 min': 30, '1 hour': 60, '1.5 hours': 90, '2 hours': 120, '3 hours': 180 }[limit] || 60;
    localStorage.setItem('tf-daily-limit-minutes', minutes);
    if (window.sb && currentUser) {
        await window.sb.from('profiles').update({ daily_limit_minutes: minutes }).eq('id', currentUser.id);
    }
    showToast('Daily limit set: ' + limit);
    triggerHaptic(20);
}

// Enforce daily limit on session start. Add inside your main DOMContentLoaded init:
async function checkDailyLimit() {
    var limit = parseInt(localStorage.getItem('tf-daily-limit-minutes') || '0');
    if (!limit) return;
    var today = new Date(); today.setHours(0,0,0,0);
    if (!window.sb || !currentUser) return;
    var { data } = await window.sb.from('session_logs')
        .select('duration_seconds')
        .eq('user_id', currentUser.id)
        .gte('started_at', today.toISOString());
    if (!data) return;
    var todayMinutes = data.reduce(function(s, r) { return s + Math.round((r.duration_seconds||0)/60); }, 0);
    if (todayMinutes >= limit) {
        var wb = document.querySelector('.wb-overlay');
        if (wb) { wb.style.display = 'flex'; }
        showToast('You\'ve reached your ' + limit + '-minute daily limit');
    }
}

/* ── Custom filtered words ── */
var customFilterWords = JSON.parse(localStorage.getItem('tf-custom-filter-words') || '[]');

function addCustomFilterWord() {
    var input = document.getElementById('customWordInput');
    var word = input ? input.value.trim() : '';
    if (!word) return;
    if (customFilterWords.indexOf(word) > -1) { showToast('Word already added'); return; }
    customFilterWords.push(word);
    localStorage.setItem('tf-custom-filter-words', JSON.stringify(customFilterWords));
    if (input) input.value = '';
    renderCustomWordList();
    updateCustomWordCount();
    triggerHaptic(15);
}

function removeCustomWord(word) {
    customFilterWords = customFilterWords.filter(function(w) { return w !== word; });
    localStorage.setItem('tf-custom-filter-words', JSON.stringify(customFilterWords));
    renderCustomWordList();
    updateCustomWordCount();
}

function renderCustomWordList() {
    var list = document.getElementById('customWordList');
    if (!list) return;
    if (customFilterWords.length === 0) {
        list.innerHTML = '<div style="text-align:center;padding:40px;color:#888;font-size:14px;">No custom words added yet</div>';
        return;
    }
    list.innerHTML = '<div class="settings-card">' +
        customFilterWords.map(function(w) {
            return '<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 20px;border-bottom:1px solid var(--border-color,#f0f0f0);">' +
                '<span style="font-size:15px;color:var(--text-primary,#000);">' + escapeHtml(w) + '</span>' +
                '<button onclick="removeCustomWord(\'' + escapeHtml(w) + '\')" style="background:none;border:none;cursor:pointer;color:#FF3B30;font-size:13px;font-weight:700;">Remove</button>' +
                '</div>';
        }).join('') +
        '</div>';
}

function updateCustomWordCount() {
    var el = document.getElementById('customWordCount');
    if (el) el.textContent = customFilterWords.length + ' word' + (customFilterWords.length !== 1 ? 's' : '') + ' added';
}

/* ── Block search ── */
async function renderBlockSearch(query) {
    var results = document.getElementById('blockSearchResults');
    if (!results) return;
    if (!query || query.length < 2) {
        results.innerHTML = '<div style="text-align:center;padding:40px;color:#888;font-size:14px;">Search for a username or name</div>';
        return;
    }
    results.innerHTML = '<div style="text-align:center;padding:20px;color:#888;">Searching…</div>';
    if (!window.sb) return;
    var { data } = await window.sb.from('users')
        .select('id, full_name, username, avatar_url, badge_tier')
        .or('username.ilike.%' + query + '%,full_name.ilike.%' + query + '%')
        .neq('id', currentUser.id)
        .limit(20);
    if (!data || data.length === 0) {
        results.innerHTML = '<div style="text-align:center;padding:40px;color:#888;font-size:14px;">No results for "' + escapeHtml(query) + '"</div>';
        return;
    }
    results.innerHTML = '<div class="settings-card">' +
        data.map(function(u) {
            var blocked = (typeof cpBlockedUsers !== 'undefined' && cpBlockedUsers.indexOf(u.id) > -1);
            return '<div style="display:flex;align-items:center;gap:12px;padding:14px 20px;border-bottom:1px solid var(--border-color,#f0f0f0);">' +
                '<img src="' + escapeHtml(u.avatar_url || 'https://ui-avatars.com/api/?name=' + encodeURIComponent(u.full_name || 'U') + '&background=eee&size=80') + '" style="width:44px;height:44px;border-radius:50%;object-fit:cover;flex-shrink:0;">' +
                '<div style="flex:1;"><b style="font-size:15px;">' + escapeHtml(u.full_name || '') + '</b><br><small style="color:#888;">@' + escapeHtml(u.username || '') + '</small></div>' +
                '<button onclick="blockUserById(\'' + u.id + '\',\'' + escapeHtml(u.full_name || u.username) + '\',this)" ' +
                'style="padding:8px 16px;border-radius:20px;border:1px solid ' + (blocked ? '#eee' : '#FF3B30') + ';background:transparent;color:' + (blocked ? '#888' : '#FF3B30') + ';font-size:13px;font-weight:700;cursor:pointer;flex-shrink:0;">' +
                (blocked ? 'Unblock' : 'Block') + '</button>' +
                '</div>';
        }).join('') +
        '</div>';
}

async function blockUserById(userId, displayName, btn) {
    if (!window.sb || !currentUser) return;
    var alreadyBlocked = (typeof cpBlockedUsers !== 'undefined' && cpBlockedUsers.indexOf(userId) > -1);
    if (alreadyBlocked) {
        await window.sb.from('blocks').delete().match({ blocker_id: currentUser.id, blocked_id: userId });
        cpBlockedUsers = cpBlockedUsers.filter(function(id) { return id !== userId; });
        localStorage.setItem('tf-blocked-users', JSON.stringify(cpBlockedUsers));
        btn.textContent = 'Block'; btn.style.color = '#FF3B30'; btn.style.borderColor = '#FF3B30';
        showToast(displayName + ' unblocked');
    } else {
        await window.sb.from('blocks').insert({ blocker_id: currentUser.id, blocked_id: userId });
        if (typeof cpBlockedUsers !== 'undefined') cpBlockedUsers.push(userId);
        localStorage.setItem('tf-blocked-users', JSON.stringify(cpBlockedUsers));
        btn.textContent = 'Blocked'; btn.style.color = '#888'; btn.style.borderColor = '#eee';
        showToast(displayName + ' blocked');
    }
}

/* ── Accessibility caption helper ── */
function setCaption(type) {
    localStorage.setItem('tf-caption-pref', type);
    ['always','translated','never'].forEach(function(t) {
        var el = document.getElementById('cap-' + t);
        if (!el) return;
        if (t === type) {
            el.style.background = '#007AFF';
            el.style.borderColor = '#007AFF';
            el.innerHTML = '<i class="fa-solid fa-check" style="color:white;font-size:10px;"></i>';
        } else {
            el.style.background = 'transparent';
            el.style.borderColor = '#ddd';
            el.innerHTML = '';
        }
    });
    showToast('Captions: ' + type);
    triggerHaptic(10);
}
