/* ── Override Privacy overlay to fix "Restricted Users" click ── */
// The existing onclick="openPage('cp-privacy-overlay')" opens the wrong overlay
// Find that row and fix it:
document.addEventListener('DOMContentLoaded', function() {
    var rows = document.querySelectorAll('.settings-row');
    rows.forEach(function(row) {
        var onclick = row.getAttribute('onclick') || '';
        // Fix restricted users row
        if (onclick.includes("openPage('cp-privacy-overlay')") && row.textContent.includes('Restricted')) {
            row.setAttribute('onclick', "openSub('restrictedIntroOverlay')");
        }
        // Fix interaction control row
        if (onclick.includes('openInteractionControl')) {
            row.setAttribute('onclick', "openSub('interactionControlOverlay')");
        }
        // Fix filtered words row
        if (onclick.includes('openFilteredWords')) {
            row.setAttribute('onclick', "openSub('filteredWordsOverlay')");
        }
        // Fix muted accounts row
        if (onclick.includes('openMutedAccounts')) {
            row.setAttribute('onclick', "openSub('mutedAccountsOverlay')");
        }
        // Fix preferred content row
        if (onclick.includes('openPreferredContent')) {
            row.setAttribute('onclick', "openPreferredContent()");
        }
        // Fix device permissions row
        if (onclick.includes('openDevicePermissions')) {
            row.setAttribute('onclick', "openSub('devicePermissionsOverlay')");
        }
        // Fix accessibility row
        if (onclick.includes('openAccessibilitySettings')) {
            row.setAttribute('onclick', "openSub('accessibilityOverlay')");
        }
        // Fix media quality row
        if (onclick.includes('openMediaQuality')) {
            row.setAttribute('onclick', "openSub('mediaQualityOverlay')");
        }
        // Fix Like & Share Counts toggle in privacy — replace with clickable row
        if (onclick.includes("openTrustCircle")) {
            row.setAttribute('onclick', "openSub('trustCircleOverlay')");
        }
        if (onclick.includes("openBlockedList")) {
            row.setAttribute('onclick', "openSub('blockedAccountsOverlay')");
        }
        if (onclick.includes("openStoryRepliesSettings")) {
            row.setAttribute('onclick', "openSub('msgStoryRepliesOverlay')");
        }
        if (onclick.includes("openCommentsSettings")) {
            row.setAttribute('onclick', "openSub('commentsSettingsOverlay')");
        }
    });
    // Fix time management which is weirdly nested in the settings overlay
    var tmRow = document.querySelector('[onclick*="openTimeManagement"]');
    if (tmRow) tmRow.setAttribute('onclick', 'openTimeManagement()');
});

