    ;(function installDropletNav() {
    function init() {
        var pill = document.getElementById('liquidPill');
        if (!pill) return;
        var old = document.getElementById('navDroplet');
        if (old) old.remove();
        var droplet = document.createElement('div');
        droplet.id = 'navDroplet';
        pill.appendChild(droplet);

        var currentX = null;
        var raf = null;

        function spring(t) {
            return 1 - Math.pow(2, -10 * t) * Math.cos(t * Math.PI * 2.4);
        }

        function center(icon) {
            var pr = pill.getBoundingClientRect();
            var ir = icon.getBoundingClientRect();
            return ir.left - pr.left + ir.width * 0.5;
        }

        function addHalo(icon) {
            document.querySelectorAll('.nav-halo').forEach(function(h){ h.remove(); });
            if (!icon) return;
            var h = document.createElement('div');
            h.className = 'nav-halo';
            icon.appendChild(h);
            setTimeout(function(){ if (h.parentNode) h.remove(); }, 500);
        }

        function fallIn(toCx) {
            if (raf) cancelAnimationFrame(raf);
            droplet.style.opacity = '1';
            var start = null;
            var dur = 420;
            function step(ts) {
                if (!start) start = ts;
                var p = Math.min((ts - start) / dur, 1);
                var s = spring(p);
                var cy = -14 + 14 * s;
                var impact = p > 0.75 ? (p - 0.75) / 0.25 : 0;
                var w = 4 + Math.sin(impact * Math.PI) * 2.5;
                var h = Math.max((p < 0.75 ? 9 - p * 4 : 5 - Math.sin(impact * Math.PI) * 1.5), 3.5);
                droplet.style.top    = (3 + cy) + 'px';
                droplet.style.left   = (toCx - w * 0.5) + 'px';
                droplet.style.width  = w + 'px';
                droplet.style.height = h + 'px';
                droplet.style.borderRadius = w <= 5.5 ? '50%' : (w/2) + 'px';
                if (p < 1) { raf = requestAnimationFrame(step); }
                else {
                    droplet.style.cssText += ';top:3px;width:5px;height:5px;border-radius:50%;left:'+(toCx-2.5)+'px;';
                    currentX = toCx;
                }
            }
            raf = requestAnimationFrame(step);
        }

        function slide(fromCx, toCx) {
            if (raf) cancelAnimationFrame(raf);
            var dist = Math.abs(toCx - fromCx);
            var dur  = Math.min(Math.max(dist * 1.2, 220), 480);
            var start = null;
            function step(ts) {
                if (!start) start = ts;
                var p  = Math.min((ts - start) / dur, 1);
                var s  = spring(p);
                var cx = fromCx + (toCx - fromCx) * s;
                var stretch = Math.sin(p * Math.PI);
                var w = p < 0.82
                    ? 5 + stretch * Math.min(dist * 0.55, 36)
                    : 5 + Math.sin(((p-0.82)/0.18)*Math.PI) * 2.5;
                var h = Math.max(p < 0.82
                    ? 5 - stretch * 1.5
                    : 5 - Math.sin(((p-0.82)/0.18)*Math.PI) * 1.5, 3);
                droplet.style.width        = w + 'px';
                droplet.style.height       = h + 'px';
                droplet.style.left         = (cx - w*0.5) + 'px';
                droplet.style.borderRadius = w <= 6 ? '50%' : (w/2) + 'px';
                droplet.style.opacity      = '1';
                currentX = cx;
                if (p < 1) { raf = requestAnimationFrame(step); }
                else {
                    droplet.style.width='5px'; droplet.style.height='5px';
                    droplet.style.left=(toCx-2.5)+'px'; droplet.style.borderRadius='50%';
                    currentX = toCx;
                }
            }
            raf = requestAnimationFrame(step);
        }

        var first = true;
        function refresh() {
            var active = document.querySelector('.liquid-pill .nav-icon.nav-active');
            if (!active) { droplet.style.opacity='0'; currentX=null; return; }
            var cx = center(active);
            if (currentX === null || first) {
                first = false; currentX = cx;
                fallIn(cx); addHalo(active);
            } else if (Math.abs(cx - currentX) > 3) {
                slide(currentX, cx); addHalo(active);
            }
        }

        var mo = new MutationObserver(function(){ setTimeout(refresh, 12); });
        document.querySelectorAll('.liquid-pill .nav-icon').forEach(function(ic){
            mo.observe(ic, { attributes: true, attributeFilter: ['class'] });
        });
        setTimeout(refresh, 250);

        new MutationObserver(function(){
            var dark = document.documentElement.getAttribute('data-theme')==='dark';
            droplet.style.background  = dark ? '#0A84FF' : '#007AFF';
            droplet.style.boxShadow   = dark
                ? '0 0 0 3px rgba(10,132,255,0.14),0 2px 8px rgba(10,132,255,0.5)'
                : '0 0 0 3px rgba(0,122,255,0.12),0 2px 8px rgba(0,122,255,0.45)';
        }).observe(document.documentElement, { attributes: true, attributeFilter:['data-theme'] });
    }

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
    else setTimeout(init, 300);
})();

    window._dl = { active:false, pct:0, timer:null };

function downloadReel() {
    var menu = document.getElementById('reelLongPressMenu');
    if (menu) menu.remove();
    if (window._dl.active) { showToast('Already downloading'); return; }
    window._dl.active = true; window._dl.pct = 0;

    /* Pill */
    var old = document.getElementById('reelDlPill');
    if (old) old.remove();
    var pill = document.createElement('div');
    pill.id = 'reelDlPill';
    pill.style.cssText = [
        'position:fixed;top:54px;left:50%;transform:translateX(-50%);',
        'z-index:99990;display:flex;align-items:center;gap:10px;',
        'padding:10px 16px 10px 10px;border-radius:30px;white-space:nowrap;',
        'background:rgba(12,12,16,0.72);',
        'backdrop-filter:blur(50px) saturate(200%);',
        '-webkit-backdrop-filter:blur(50px) saturate(200%);',
        'border:0.5px solid rgba(255,255,255,0.14);',
        'box-shadow:0 8px 32px rgba(0,0,0,0.4),0 1px 0 rgba(255,255,255,0.07) inset;',
        'animation:dlPillIn 0.42s cubic-bezier(0.34,1.56,0.64,1);'
    ].join('');
    pill.innerHTML =
        '<style>@keyframes dlPillIn{0%{opacity:0;transform:translateX(-50%) translateY(-22px) scale(0.85)}100%{opacity:1;transform:translateX(-50%) translateY(0) scale(1)}}</style>' +
        '<div style="width:26px;height:26px;border-radius:50%;background:rgba(0,122,255,0.2);border:1px solid rgba(0,122,255,0.4);display:flex;align-items:center;justify-content:center;flex-shrink:0;">' +
            '<i class="fa-solid fa-arrow-down-to-line" style="color:#007AFF;font-size:10px;"></i></div>' +
        '<div style="display:flex;flex-direction:column;gap:3px;">' +
            '<span style="color:white;font-size:13px;font-weight:700;">Downloading</span>' +
            '<div style="width:70px;height:3px;background:rgba(255,255,255,0.1);border-radius:2px;overflow:hidden;">' +
                '<div id="dlBar" style="height:100%;width:0%;background:linear-gradient(90deg,#007AFF,#34C759);border-radius:2px;transition:width 0.18s ease;"></div>' +
            '</div>' +
        '</div>' +
        '<span id="dlPct" style="color:rgba(255,255,255,0.55);font-size:12px;font-weight:700;min-width:30px;text-align:right;">0%</span>';
    document.body.appendChild(pill);

    /* Home ring */
    var homeIcon = document.getElementById('nav-home');
    if (homeIcon) {
        homeIcon.style.position = 'relative';
        var oldRing = document.getElementById('homeRing');
        if (oldRing) oldRing.remove();
        var ring = document.createElement('div');
        ring.id = 'homeRing';
        ring.style.cssText = [
            'position:absolute;inset:-6px;border-radius:50%;pointer-events:none;z-index:5;',
            'background:conic-gradient(#34C759 0deg,rgba(255,255,255,0.07) 0deg);',
            '-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 3.5px),black calc(100% - 3.5px));',
            'mask:radial-gradient(farthest-side,transparent calc(100% - 3.5px),black calc(100% - 3.5px));'
        ].join('');
        homeIcon.appendChild(ring);
    }

    /* Animate */
    window._dl.timer = setInterval(function() {
        window._dl.pct += Math.random() * 9 + 2.5;
        if (window._dl.pct >= 100) { window._dl.pct = 100; clearInterval(window._dl.timer); _dlUpdate(100); setTimeout(_dlDone, 280); return; }
        _dlUpdate(window._dl.pct);
    }, 160);
}

function _dlUpdate(pct) {
    var p = Math.round(pct);
    var bar = document.getElementById('dlBar');
    var pctEl = document.getElementById('dlPct');
    var ring = document.getElementById('homeRing');
    if (bar)   bar.style.width = p + '%';
    if (pctEl) pctEl.textContent = p + '%';
    if (ring)  ring.style.background = 'conic-gradient(#34C759 ' + Math.round(pct/100*360) + 'deg,rgba(255,255,255,0.07) ' + Math.round(pct/100*360) + 'deg)';
}

function _dlDone() {
    /* Update pill */
    var pill = document.getElementById('reelDlPill');
    if (pill) {
        pill.querySelector('.fa-arrow-down-to-line').className = 'fa-solid fa-check';
        pill.querySelector('.fa-check').style.color = '#34C759';
        var label = pill.querySelector('span[style*="font-weight:700"]');
        if (label) label.textContent = 'Saved to device';
        var pctEl = document.getElementById('dlPct');
        if (pctEl) pctEl.style.display = 'none';
        setTimeout(function() {
            if (!pill) return;
            pill.style.transition = 'opacity 0.35s ease,transform 0.35s cubic-bezier(0.34,1.56,0.64,1)';
            pill.style.opacity = '0';
            pill.style.transform = 'translateX(-50%) translateY(-18px) scale(0.9)';
            setTimeout(function(){ if (pill.parentNode) pill.remove(); }, 360);
        }, 1500);
    }

    /* Home icon morphs */
    var homeIcon = document.getElementById('nav-home');
    if (homeIcon) {
        var ring = document.getElementById('homeRing');
        if (ring) ring.remove();
        var origClass = homeIcon.className;
        homeIcon.style.cssText += ';animation:iconSpring26 0.48s cubic-bezier(0.34,1.56,0.64,1);';
        homeIcon.classList.remove('fa-house');
        homeIcon.classList.add('fa-circle-check');
        homeIcon.style.color = '#34C759';
        setTimeout(function() {
            homeIcon.style.animation = '';
            homeIcon.className = origClass;
            homeIcon.style.color = '';
            window._dl.active = false; window._dl.pct = 0;
        }, 2600);
    }
    triggerHaptic && triggerHaptic(50);
}



    var AudioFP = (function(){
    var _ctx = null;
    function ctx(){ if (!_ctx||_ctx.state==='closed') _ctx=new(window.AudioContext||window.webkitAudioContext)(); return _ctx; }

    async function analyze(file) {
        try {
            var ab  = await file.arrayBuffer();
            var buf = await ctx().decodeAudioData(ab.slice(0));
            var ch  = buf.getChannelData(0);
            var sr  = buf.sampleRate;
            var dur = buf.duration;
            var len = Math.min(ch.length, sr * 30);

            /* RMS energy */
            var sq = 0;
            for (var i=0;i<len;i++) sq += ch[i]*ch[i];
            var rms = Math.sqrt(sq/len);

            /* ZCR */
            var zc = 0;
            for (var j=1;j<len;j++) if ((ch[j]>=0)!==(ch[j-1]>=0)) zc++;
            var zcr = zc/dur;

            /* BPM */
            var ws = Math.floor(sr*0.01);
            var maxS = Math.min(ch.length,sr*25);
            var energies=[];
            for (var k=0;k<maxS;k+=ws){
                var e=0; for(var m=k;m<k+ws&&m<ch.length;m++) e+=ch[m]*ch[m]; energies.push(e/ws);
            }
            var mean=energies.reduce(function(a,b){return a+b;},0)/energies.length;
            var thr=mean*1.5; var peaks=[];
            for (var n=1;n<energies.length-1;n++) if(energies[n]>thr&&energies[n]>energies[n-1]&&energies[n]>energies[n+1]) peaks.push(n);
            var bpm=120;
            if(peaks.length>=3){
                var ints=[]; for(var o=1;o<peaks.length;o++) ints.push(peaks[o]-peaks[o-1]);
                var avgI=ints.reduce(function(a,b){return a+b;},0)/ints.length;
                bpm=Math.round(60/((avgI*ws)/sr));
                while(bpm>190) bpm=Math.round(bpm/2);
                while(bpm<55)  bpm=Math.round(bpm*2);
            }

            /* Genre */
            var genre='Pop';
            if(bpm>160&&rms>0.1) genre='Drum & Bass';
            else if(bpm>128&&rms>0.08) genre='Electronic';
            else if(bpm>=108&&bpm<=128) genre='Amapiano';
            else if(bpm>=96&&bpm<=112) genre='Afrobeats';
            else if(bpm>=85&&bpm<=100) genre='R&B / Soul';
            else if(bpm<85&&rms<0.04) genre='Ambient';
            else if(zcr>1200) genre='Hip-Hop';

            return { bpm:bpm, genre:genre, duration:Math.round(dur), energy:Math.round(rms*1000)/1000 };
        } catch(e){ return null; }
    }
    return { analyze:analyze };
})();

/* Hook into file input */
(function(){
    function attach(){
        var fi=document.getElementById('file-input');
        if(!fi||fi._afpHooked) return;
        fi._afpHooked=true;
        fi.addEventListener('change',async function(e){
            var f=e.target.files&&e.target.files[0];
            if(!f||(!f.type.startsWith('video/')&&!f.type.startsWith('audio/'))) return;
            var result=await AudioFP.analyze(f);
            if(!result) return;
            var cached=JSON.parse(localStorage.getItem('tf-detected-sounds')||'[]');
            cached.unshift({
                name: f.name.replace(/\.[^/.]+$/,'').replace(/[-_]/g,' '),
                bpm:result.bpm, genre:result.genre,
                duration:result.duration, isOriginal:true,
                timestamp:Date.now()
            });
            localStorage.setItem('tf-detected-sounds',JSON.stringify(cached.slice(0,30)));
            // BPM stored silently — only surface in audio toolbar, not as a toast
window._lastAudioFingerprint = { genre: result.genre, bpm: result.bpm, duration: result.duration };
        });
    }
    document.readyState==='loading'?document.addEventListener('DOMContentLoaded',attach):attach();
})();

