    var _cvrStream = null, _cvrRecorder = null, _cvrChunks = [], _cvrSecs = 0, _cvrInterval = null, _cvrFront = true;

function openCircularVideoRecorder() {
    document.getElementById('circularVideoRecorder').style.display = 'flex';
    _cvrFront = true;
    _cvrStartStream();
    triggerHaptic(30);
}

async function _cvrStartStream() {
    if (_cvrStream) _cvrStream.getTracks().forEach(function(t){ t.stop(); });
    _cvrStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: _cvrFront ? 'user' : 'environment', width: 480, height: 480 },
        audio: true
    });
    var vid = document.getElementById('cvrVideo');
    if (vid) vid.srcObject = _cvrStream;
    // auto-start recording
    _cvrChunks = []; _cvrSecs = 0;
    _cvrRecorder = new MediaRecorder(_cvrStream, { mimeType: 'video/webm' });
    _cvrRecorder.ondataavailable = function(e){ if(e.data.size>0) _cvrChunks.push(e.data); };
    _cvrRecorder.start();
    var timerEl = document.getElementById('cvrTimer');
    if (timerEl) timerEl.style.display = 'block';
    _cvrInterval = setInterval(function(){
        _cvrSecs++;
        var m = String(Math.floor(_cvrSecs/60)).padStart(2,'0');
        var s = String(_cvrSecs%60).padStart(2,'0');
        if (timerEl) timerEl.textContent = m + ':' + s;
        if (_cvrSecs >= 60) stopCVR();
        var sendBtn = document.getElementById('cvrSendBtn');
        if (sendBtn && _cvrSecs >= 1) { sendBtn.style.opacity='1'; sendBtn.style.pointerEvents='all'; }
    }, 1000);
}

function cvrFlip() { _cvrFront = !_cvrFront; _cvrStartStream(); }

function stopCVR() {
    clearInterval(_cvrInterval);
    if (_cvrRecorder && _cvrRecorder.state !== 'inactive') _cvrRecorder.stop();
}

function discardCVR() { clearInterval(_cvrInterval); closeCVR(); }

function sendCVR() {
    stopCVR();
    closeCVR();
    // Insert circle video bubble
    var chatBody = document.getElementById('chat-body');
    if (!chatBody) return;
    var blob = new Blob(_cvrChunks, { type: 'video/webm' });
    var url  = URL.createObjectURL(blob);
    var bubble = document.createElement('div');
    bubble.style.cssText = 'margin-left:auto;margin-bottom:10px;animation:popIn 0.3s ease;cursor:pointer;';
    bubble.innerHTML =
        '<video src="' + url + '" autoplay loop muted playsinline ' +
            'style="width:120px;height:120px;border-radius:50%;object-fit:cover;display:block;' +
                   'border:3px solid #007AFF;box-shadow:0 4px 16px rgba(0,122,255,0.35);"></video>';
    chatBody.appendChild(bubble);
    chatBody.scrollTop = chatBody.scrollHeight;
    showToast('Video note sent 🎥');
    triggerHaptic(25);
}

function closeCVR() {
    clearInterval(_cvrInterval);
    if (_cvrStream) _cvrStream.getTracks().forEach(function(t){ t.stop(); }); _cvrStream = null;
    document.getElementById('circularVideoRecorder').style.display = 'none';
    document.getElementById('cvrTimer').style.display = 'none';
}

