async function createRealChannel() {
    var name = (document.getElementById('ch-name-input')||{}).value?.trim();
    var desc = (document.getElementById('ch-desc-input')||{}).value?.trim();
    if (!name) { showToast('Enter a channel name'); return; }
    if (!currentUser) { showToast('Please log in'); return; }

    var newCh = {
        id: 'local_' + Date.now(),
        name: name,
        description: desc || null,
        emoji: window._chEmoji || '📢',
        color: window._chColor || '#007AFF',
        owner_id: currentUser.id,
        follower_count: 1,
        verified: false
    };

    if (window.sb) {
        try {
            var { data, error } = await sb.from('channels').insert({
                name: newCh.name,
                description: newCh.description,
                emoji: newCh.emoji,
                color: newCh.color,
                owner_id: newCh.owner_id,
                follower_count: 1
            }).select().single();
            if (!error && data) {
                newCh = data;
                await sb.from('channel_followers').insert({ channel_id: data.id, user_id: currentUser.id }).catch(function(){});
            }
        } catch(e) { console.warn('[createChannel]', e); }
    }

    // Save locally so it shows immediately even if DB failed
    var localChannels = JSON.parse(localStorage.getItem('tf-local-channels') || '[]');
    localChannels.unshift(newCh);
    localStorage.setItem('tf-local-channels', JSON.stringify(localChannels));

    document.getElementById('createChannelModal')?.remove();
    showToast('Channel "' + name + '" created! 📢');
    triggerHaptic(50);

    // Navigate to channels tab
    var channelsTab = Array.from(document.querySelectorAll('.m-tab')).find(function(t){ return t.textContent.trim().toLowerCase().includes('channel'); });
    if (channelsTab) {
        setMsgTab('channels', channelsTab);
    } else {
        // Open msg hub if not open, then switch
        launchMessageHub();
        setTimeout(function(){
            var tab = Array.from(document.querySelectorAll('.m-tab')).find(function(t){ return t.textContent.trim().toLowerCase().includes('channel'); });
            if (tab) setMsgTab('channels', tab);
        }, 400);
    }
}

    function autoArchiveExpiredStories() {
    var storyKeys = Object.keys(localStorage).filter(function(k){ return k.startsWith('story_time_'); });
    var archived = JSON.parse(localStorage.getItem('tf-story-archive') || '[]');

    storyKeys.forEach(function(key) {
        var storyTime = parseInt(localStorage.getItem(key)||'0');
        if (storyTime && (Date.now() - storyTime) > 86400000) {
            // Story is older than 24h — move to archive
            var handle = key.replace('story_time_','');
            var storyData = localStorage.getItem('story_data_' + handle);
            if (storyData) {
                archived.unshift({
                    handle: handle,
                    data: storyData,
                    archived_at: new Date().toISOString(),
                    type: 'story'
                });
                localStorage.removeItem('story_data_' + handle);
            }
            localStorage.removeItem(key);
        }
    });

    localStorage.setItem('tf-story-archive', JSON.stringify(archived.slice(0, 200)));
}

async function loadRealActivityTab(tab, container) {
    if (!window.sb || !currentUser) {
        // Keep showing fallback, don't hardcode
        container.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">Sign in to see real activity</div>';
        return;
    }

    try {
        if (tab === 'likes') {
            var { data } = await sb.from('likes').select('*, posts:post_id(text_content,media_url,created_at)').eq('user_id', currentUser.id).order('created_at',{ascending:false}).limit(30);
            if (!data || !data.length) { container.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">No likes yet</div>'; return; }
            container.innerHTML = (data||[]).map(function(l) {
                var p = l.posts || {};
                return '<div class="activity-item"><div class="activity-icon" style="background:rgba(233,30,99,0.1);color:#e91e63;"><i class="fa-solid fa-heart"></i></div><div style="flex:1;"><b>Liked a post</b><p style="color:#888;font-size:13px;margin-top:2px;">' + escapeHtml((p.text_content||'').substring(0,60)) + '</p></div><small style="color:#aaa;">' + getTimeAgo(l.created_at) + '</small></div>';
            }).join('');
        } else if (tab === 'reposts') {
            container.innerHTML = '<div style="text-align:center;padding:40px;color:#888;"><i class="fa-solid fa-retweet" style="font-size:30px;color:#ccc;display:block;margin-bottom:12px;"></i>No reposts yet</div>';
        } else if (tab === 'bookmarks') {
            var { data: bms } = await sb.from('bookmarks').select('*, posts:post_id(text_content,media_url,created_at)').eq('user_id', currentUser.id).order('created_at',{ascending:false}).limit(30);
            if (!bms || !bms.length) { container.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">No bookmarks yet</div>'; return; }
            container.innerHTML = (bms||[]).map(function(b) {
                var p = b.posts || {};
                return '<div class="activity-item"><div class="activity-icon" style="background:rgba(0,122,255,0.1);color:#007AFF;"><i class="fa-solid fa-bookmark"></i></div><div style="flex:1;"><b>Saved a post</b><p style="color:#888;font-size:13px;margin-top:2px;">' + escapeHtml((p.text_content||'').substring(0,60)) + '</p></div><small style="color:#aaa;">' + getTimeAgo(b.created_at) + '</small></div>';
            }).join('');
        } else if (tab === 'history') {
            var hist = JSON.parse(localStorage.getItem('tf-watch-history') || '[]');
            if (!hist.length) { container.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">No watch history yet</div>'; return; }
            container.innerHTML = hist.slice(0,30).map(function(h) {
                return '<div class="activity-item"><div class="activity-icon" style="background:rgba(255,149,0,0.1);color:#FF9500;"><i class="fa-solid fa-play"></i></div><div style="flex:1;"><b>' + escapeHtml(h.title||'Watched a clip') + '</b><p style="color:#888;font-size:13px;">' + escapeHtml(h.creator||'') + '</p></div><small style="color:#aaa;">' + getTimeAgo(h.timestamp) + '</small></div>';
            }).join('');
        } else if (tab === 'violations') {
            var reports = JSON.parse(localStorage.getItem('trustfirst-reports') || '[]');
            var myViolations = reports.filter(function(r){ return r.content_owner_id === (currentUser && currentUser.id); });
            if (!myViolations.length) {
                container.innerHTML = '<div style="text-align:center;padding:60px 20px;"><i class="fa-solid fa-shield-check" style="font-size:40px;color:#34C759;display:block;margin-bottom:15px;"></i><h3 style="color:var(--text-primary,#000);">All Clear</h3><p style="color:#888;font-size:14px;margin-top:8px;">No violations on your account.</p></div>';
                return;
            }
            container.innerHTML = myViolations.map(function(v) {
                return '<div style="background:var(--card-bg,#fff);border:1px solid rgba(255,59,48,0.15);border-radius:16px;padding:16px;margin:10px 20px;">' +
                    '<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px;">' +
                        '<div class="violations-badge">' + (v.status==='pending'?'⏳ Under Review':v.status==='resolved'?'✓ Resolved':'❌ Violation') + '</div>' +
                        '<small style="color:#aaa;">' + new Date(v.timestamp).toLocaleDateString() + '</small>' +
                    '</div>' +
                    '<p style="font-size:14px;color:var(--text-primary,#000);margin-bottom:12px;">' + escapeHtml(v.reason||'Policy violation') + '</p>' +
                    (v.status==='pending' ?
                        '<div style="display:flex;gap:8px;">' +
                            '<button onclick="appealViolation(\'' + v.id + '\')" style="flex:1;padding:10px;border-radius:12px;border:1.5px solid #007AFF;background:transparent;color:#007AFF;font-weight:700;cursor:pointer;">Appeal</button>' +
                            '<button onclick="acknowledgeViolation(\'' + v.id + '\')" style="flex:1;padding:10px;border-radius:12px;border:none;background:#f0f0f0;color:#555;font-weight:700;cursor:pointer;">Acknowledge</button>' +
                        '</div>' : '') +
                '</div>';
            }).join('');
        }
    } catch(e) {
        container.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">Could not load activity</div>';
    }
}

function appealViolation(id) {
    var modal = document.createElement('div');
    modal.style.cssText = 'position:fixed;inset:0;z-index:99998;background:rgba(0,0,0,0.5);display:flex;align-items:flex-end;justify-content:center;';
    modal.innerHTML = '<div style="background:var(--bg-primary,#fff);width:100%;max-width:430px;border-radius:24px 24px 0 0;padding:24px 20px 40px;">' +
        '<p style="font-size:13px;font-weight:800;color:#888;text-transform:uppercase;letter-spacing:1px;margin-bottom:14px;">Appeal Reason</p>' +
        '<textarea id="_appealInput" placeholder="Why do you believe this was an error?" style="width:100%;height:100px;padding:14px;border-radius:14px;border:1px solid var(--border-color,#eee);font-size:15px;resize:none;outline:none;background:var(--input-bg,#f5f5f5);color:var(--text-primary,#000);box-sizing:border-box;margin-bottom:16px;"></textarea>' +
        '<button onclick="(function(){var r=document.getElementById(\'_appealInput\').value.trim();if(!r)return;document.body.querySelector(\'[data-appeal-modal]\').remove();showToast(\'Appeal submitted. We\\\'ll review within 48 hours.\');triggerHaptic(20);})()" style="width:100%;padding:16px;border-radius:14px;border:none;background:#007AFF;color:white;font-size:16px;font-weight:700;cursor:pointer;margin-bottom:10px;">Submit Appeal</button>' +
        '<button onclick="this.closest(\'[data-appeal-modal]\').remove()" style="width:100%;padding:14px;border-radius:14px;border:none;background:transparent;color:#888;font-size:14px;cursor:pointer;">Cancel</button>' +
    '</div>';
    modal.setAttribute('data-appeal-modal', '');
    modal.addEventListener('click', function(e){ if(e.target===modal) modal.remove(); });
    document.body.appendChild(modal);
}

function acknowledgeViolation(id) {
    showToast('Acknowledged. Thank you for your understanding.');
    triggerHaptic(15);
}

async function startStripeVerification(userId) {
    // 1. Ask our backend to create the session (secret key stays server-side)
    const res = await fetch('/api/stripe/create-verification/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ user_id: userId })
    });
    const { client_secret, error } = await res.json();
    if (error) { showToast('Verification failed: ' + error); return; }

    // 2. Use the client_secret with Stripe.js (publishable key only)
    const stripe = Stripe(STRIPE_PUBLISHABLE_KEY);
    const { error: stripeError } = await stripe.verifyIdentity(client_secret);
    if (stripeError) {
        showToast(stripeError.message);
    } else {
        showToast('Identity verified! ✅');
    }
}

