window._edCurrentEffect = 'none';
function edApplyEffect(id) {
    window._edCurrentEffect = id;
    document.querySelectorAll('[id^="efItem_"]').forEach(function(el){ el.style.border='1.5px solid transparent'; el.style.background='rgba(255,255,255,0.07)'; });
    var sel = document.getElementById('efItem_'+id);
    if (sel) { sel.style.border='1.5px solid #007AFF'; sel.style.background='rgba(0,122,255,0.15)'; }
    var vid = document.getElementById('edVideo');
    if (vid) {
        var filters = {none:'none',blur:'blur(4px)',grayscale:'grayscale(100%)',sepia:'sepia(80%)',warm:'saturate(150%) hue-rotate(-20deg)',cool:'hue-rotate(180deg) saturate(120%)',glow:'brightness(1.3) contrast(1.1)',vhs:'contrast(1.2) saturate(60%) hue-rotate(5deg)',mirror:'scaleX(-1)',zoom:'scale(1.15)',glitch:'hue-rotate(90deg) saturate(200%) contrast(1.3)'};
        vid.style.filter = filters[id] || 'none';
        if (id === 'mirror') vid.style.transform = 'scaleX(-1)'; else vid.style.transform = '';
    }
    edState.isDirty = true;
    showToast(id === 'none' ? 'Effect removed' : 'Effect applied');
    triggerHaptic(10);
}
function edFilterEffects(q) {
    document.querySelectorAll('[id^="efItem_"]').forEach(function(el){
        el.style.display = (!q || el.getAttribute('data-label').includes(q.toLowerCase())) ? '' : 'none';
    });
}
function edEffectsTab(tab) {
    ['all','fav','sug'].forEach(function(t){
        var btn = document.getElementById('edEffTab'+t.charAt(0).toUpperCase()+t.slice(1));
        if (btn) { btn.style.background = t===tab ? 'rgba(0,122,255,0.9)' : 'rgba(255,255,255,0.1)'; btn.style.color = t===tab ? 'white' : 'rgba(255,255,255,0.6)'; }
    });
    var grid = document.getElementById('edEffectsGrid');
    if (!grid) return;
    var items = grid.querySelectorAll('[id^="efItem_"]');
    items.forEach(function(el){
        var id = el.id.replace('efItem_','');
        if (tab === 'all') el.style.display = '';
        else if (tab === 'fav') el.style.display = (window._edEffectFavs||[]).includes(id) ? '' : 'none';
        else el.style.display = ['neon','vhs','glitch','glow','warm'].includes(id) ? '' : 'none';
    });
}

/* ---- VOICE PANEL ---- */
function edOpenVoicePanel() {
    var existing = document.getElementById('edVoicePanel');
    if (existing) { existing.remove(); return; }
    var panel = document.createElement('div');
    panel.id = 'edVoicePanel';
    panel.style.cssText = 'position:absolute;left:0;right:0;bottom:0;z-index:500;background:rgba(10,10,10,0.96);backdrop-filter:blur(30px);border-radius:24px 24px 0 0;padding:20px;animation:slideUpOverlay 0.32s cubic-bezier(0.34,1.56,0.64,1);';
    panel.innerHTML =
        '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;">'+
            '<span style="color:white;font-size:17px;font-weight:700;">Voice Over</span>'+
            '<button onclick="edStopVoiceRecord();document.getElementById(\'edVoicePanel\').remove();" style="background:rgba(255,255,255,0.12);border:none;color:white;width:30px;height:30px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;"><i class="fa-solid fa-xmark"></i></button>'+
        '</div>'+
        // Waveform line
        '<div style="height:40px;background:rgba(255,255,255,0.06);border-radius:12px;margin-bottom:18px;overflow:hidden;position:relative;">'+
            '<div id="edVoiceWave" style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;gap:2px;padding:0 8px;"></div>'+
            '<span id="edVoiceDuration" style="position:absolute;right:10px;top:50%;transform:translateY(-50%);color:rgba(255,255,255,0.5);font-size:12px;font-weight:700;">0:00</span>'+
        '</div>'+
        // Record button
        '<div style="display:flex;justify-content:center;margin-bottom:18px;">'+
            '<button id="edVoiceRecBtn" onclick="edToggleVoiceRecord()" style="width:72px;height:72px;border-radius:50%;background:white;border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;position:relative;box-shadow:0 4px 20px rgba(255,255,255,0.2);">'+
                '<div id="edVoiceCircle" style="position:absolute;inset:-4px;border-radius:50%;border:3px solid transparent;"></div>'+
                '<div id="edVoiceRecIcon" style="width:24px;height:24px;border-radius:50%;background:#FF3B30;"></div>'+
            '</button>'+
        '</div>'+
        '<p id="edVoiceStatus" style="color:rgba(255,255,255,0.4);font-size:13px;text-align:center;">Tap to start recording</p>';
    var overlay = document.getElementById('preview-edit-overlay');
    if (overlay) overlay.appendChild(panel);
    window._edVoiceRecording = false;
    window._edVoiceRAF = null;
    window._edVoiceMediaRecorder = null;
    window._edVoiceStartTime = null;
}
function edToggleVoiceRecord() {
    if (!window._edVoiceRecording) {
        navigator.mediaDevices.getUserMedia({audio:true}).then(function(stream){
            window._edVoiceRecording = true;
            window._edVoiceStartTime = Date.now();
            var vid = document.getElementById('edVideo');
            if (vid) { vid.muted = true; vid.currentTime = 0; vid.play().catch(function(){}); }
            var recBtn = document.getElementById('edVoiceRecBtn');
            var recIcon = document.getElementById('edVoiceRecIcon');
            var circle = document.getElementById('edVoiceCircle');
            var status = document.getElementById('edVoiceStatus');
            if (recIcon) { recIcon.style.width='20px'; recIcon.style.height='20px'; recIcon.style.borderRadius='4px'; recIcon.style.background='#007AFF'; }
            if (status) status.textContent = 'Recording…';
            // Animate blue circle
            var vidDuration = (vid && vid.duration && isFinite(vid.duration)) ? vid.duration : 15;
            var circleAnim = null;
            if (circle) {
                circle.style.transition = 'none';
                circle.style.borderColor = 'transparent';
                var startT = performance.now();
                function animCircle(now) {
                    var elapsed = (now - startT) / 1000;
                    var pct = Math.min(elapsed / vidDuration, 1);
                    var deg = pct * 360;
                    circle.style.background = 'conic-gradient(#007AFF '+deg+'deg, transparent '+deg+'deg)';
                    circle.style.borderRadius = '50%';
                    circle.style.inset = '-6px';
                    circle.style.width = 'calc(100% + 12px)';
                    circle.style.height = 'calc(100% + 12px)';
                    if (window._edVoiceRecording) circleAnim = requestAnimationFrame(animCircle);
                }
                circleAnim = requestAnimationFrame(animCircle);
            }
            // Waveform animation
            var waveEl = document.getElementById('edVoiceWave');
            var waveAnim;
            function animWave() {
                if (!waveEl || !window._edVoiceRecording) return;
                waveEl.innerHTML = Array.from({length:28}, function(){
                    var h = Math.random()*28+4;
                    return '<div style="width:3px;height:'+h+'px;background:rgba(0,122,255,0.7);border-radius:2px;flex-shrink:0;transition:height 0.08s;"></div>';
                }).join('');
                waveAnim = setTimeout(animWave, 100);
            }
            animWave();
            // Duration counter
            var durEl = document.getElementById('edVoiceDuration');
            var durInt = setInterval(function(){
                if (!window._edVoiceRecording) { clearInterval(durInt); return; }
                var secs = Math.floor((Date.now() - window._edVoiceStartTime)/1000);
                var m = Math.floor(secs/60), s = secs%60;
                if (durEl) durEl.textContent = m+':'+(s<10?'0':'')+s;
            }, 500);
            window._edVoiceMediaRecorder = new MediaRecorder(stream);
            var chunks = [];
            window._edVoiceMediaRecorder.ondataavailable = function(e){ chunks.push(e.data); };
            window._edVoiceMediaRecorder.onstop = function(){
                stream.getTracks().forEach(function(t){t.stop();});
                clearTimeout(waveAnim); clearInterval(durInt);
                var blob = new Blob(chunks, {type:'audio/webm'});
                var url = URL.createObjectURL(blob);
                edState.audioTracks.push({id:'voice_'+Date.now(), label:'Voice Over', url:url, startMs:0, durationMs:(Date.now()-window._edVoiceStartTime)});
                edState.isDirty = true; edRenderTimeline();
                showToast('Voice over added ✅'); triggerHaptic(20);
                var panel = document.getElementById('edVoicePanel');
                if (panel) panel.remove();
            };
            window._edVoiceMediaRecorder.start();
        }).catch(function(){ showToast('Microphone access denied'); });
    } else {
        window._edVoiceRecording = false;
        if (window._edVoiceMediaRecorder) window._edVoiceMediaRecorder.stop();
        var vid = document.getElementById('edVideo');
        if (vid) vid.pause();
        cancelAnimationFrame(window._edVoiceRAF);
    }
}
function edStopVoiceRecord() {
    if (window._edVoiceRecording && window._edVoiceMediaRecorder) {
        window._edVoiceRecording = false;
        window._edVoiceMediaRecorder.stop();
    }
}

