                '<i class="fa-solid fa-magnifying-glass" style="color:rgba(255,255,255,0.4);font-size:14px;"></i>'+
                '<input id="edMusicSearch" placeholder="Search songs…" oninput="edSearchMusic(this.value)" style="flex:1;background:transparent;border:none;outline:none;color:white;font-size:14px;">'+
            '</div>'+
            '<button onclick="edImportAudio()" style="flex-shrink:0;background:rgba(255,255,255,0.1);border:none;color:white;border-radius:14px;padding:8px 14px;font-size:13px;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px;"><i class="fa-solid fa-folder-open"></i> Import</button>'+
        '</div>'+
        '<div id="edMusicList" style="flex:1;overflow-y:auto;padding:0 14px 20px;">'+
            '<div style="text-align:center;padding:30px;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;font-size:24px;"></i><p style="color:rgba(255,255,255,0.4);margin-top:10px;font-size:13px;">Search for a song above</p></div>'+
        '</div>';
    var overlay = document.getElementById('preview-edit-overlay');
