function edSearchMusic(q) {
    edSearchMusicReal(q || 'trending');
}
async function edSearchMusicReal(query) {
    var list = document.getElementById('edMusicList');
    if (!list) return;
    list.innerHTML = '<div style="text-align:center;padding:30px;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;font-size:24px;"></i><p style="color:rgba(255,255,255,0.4);margin-top:10px;font-size:13px;">Loading…</p></div>';
    try {
        var res = await fetch('https://itunes.apple.com/search?term='+encodeURIComponent(query)+'&media=music&entity=song&limit=20&country=ZA');
        var data = await res.json();
        var tracks = (data.results || []).filter(function(t){ return t.previewUrl; });
        if (!tracks.length) { list.innerHTML = '<p style="text-align:center;color:rgba(255,255,255,0.4);padding:30px;font-size:13px;">No songs found</p>'; return; }
        list.innerHTML = tracks.map(function(t){
            var art = (t.artworkUrl100||'').replace('100x100','300x300');
            var dur = t.trackTimeMillis ? Math.floor(t.trackTimeMillis/60000)+':'+String(Math.floor((t.trackTimeMillis%60000)/1000)).padStart(2,'0') : '';
            return '<div onclick="edAddMusicTrackReal(\''+escapeHtml(t.trackName)+'\',\''+escapeHtml(t.artistName)+'\',\''+escapeHtml(t.previewUrl||'')+'\',\''+escapeHtml(art)+'\')" style="display:flex;align-items:center;gap:12px;padding:12px;border-radius:14px;background:rgba(255,255,255,0.05);margin-bottom:8px;cursor:pointer;border:0.5px solid rgba(255,255,255,0.06);">'+
                '<img src="'+escapeHtml(art)+'" style="width:42px;height:42px;border-radius:10px;object-fit:cover;flex-shrink:0;" onerror="this.style.display=\'none\'">'+
                '<div style="flex:1;min-width:0;"><div style="color:white;font-size:14px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+escapeHtml(t.trackName)+'</div><div style="color:rgba(255,255,255,0.45);font-size:12px;margin-top:2px;">'+escapeHtml(t.artistName)+' · '+dur+'</div></div>'+
                '<i class="fa-solid fa-plus" style="color:#007AFF;flex-shrink:0;"></i></div>';
        }).join('');
    } catch(e) {
        list.innerHTML = '<p style="text-align:center;color:rgba(255,255,255,0.4);padding:30px;font-size:13px;">Connection error. Try again.</p>';
    }
}
function edAddMusicTrackReal(title, artist, previewUrl, artUrl) {
    edState.audioTracks.push({id:'music_'+Date.now(), label:title+' — '+artist, url:previewUrl, artUrl:artUrl, startMs:0, durationMs:180000});
    edState.isDirty = true; edRenderTimeline(); edSaveHistory(); editorSaveDraft(false);
    var m = document.getElementById('edMusicModal');
    if (m) m.remove();
    showToast(title + ' added 🎵'); triggerHaptic(15);
}
function edRenderMusicList(songs) {
    var list = document.getElementById('edMusicList');
    if (!list) return;
    if (!songs.length) { list.innerHTML = '<p style="text-align:center;color:rgba(255,255,255,0.4);padding:30px;font-size:13px;">No songs found</p>'; return; }
    list.innerHTML = songs.map(function(s, idx){
        return '<div onclick="edAddMusicTrack(\''+escapeHtml(s.title)+'\',\''+escapeHtml(s.artist)+'\')" style="display:flex;align-items:center;gap:12px;padding:12px;border-radius:14px;background:rgba(255,255,255,0.05);margin-bottom:8px;cursor:pointer;border:0.5px solid rgba(255,255,255,0.06);">'+
            '<div style="width:42px;height:42px;border-radius:10px;background:rgba(0,122,255,0.25);display:flex;align-items:center;justify-content:center;flex-shrink:0;"><i class="fa-solid fa-music" style="color:#007AFF;font-size:16px;"></i></div>'+
            '<div style="flex:1;min-width:0;"><div style="color:white;font-size:14px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+escapeHtml(s.title)+'</div><div style="color:rgba(255,255,255,0.45);font-size:12px;margin-top:2px;">'+escapeHtml(s.artist)+' · '+s.duration+'</div></div>'+
            '<i class="fa-solid fa-plus" style="color:#007AFF;flex-shrink:0;"></i>'+
        '</div>';
    }).join('');
}
function edAddMusicTrack(title, artist) {
    edState.audioTracks.push({id:'music_'+Date.now(), label:title+' — '+artist, startMs:0, durationMs:180000});
    edState.isDirty = true; edRenderTimeline(); edSaveHistory(); editorSaveDraft(false);
    var m = document.getElementById('edMusicModal');
    if (m) m.remove();
    showToast(title + ' added 🎵'); triggerHaptic(15);
}
function edImportAudio() {
    var inp = document.createElement('input');
    inp.type = 'file'; inp.accept = 'audio/*,video/*';
    inp.onchange = function() {
        if (!inp.files || !inp.files.length) return;
        var file = inp.files[0];
        var url = URL.createObjectURL(file);
        edState.audioTracks.push({id:'import_'+Date.now(), label:file.name.split('.')[0], url:url, startMs:0, durationMs:180000});
        edState.isDirty = true; edRenderTimeline();
        var m = document.getElementById('edMusicModal');
        if (m) m.remove();
        showToast(file.name.split('.')[0]+' imported 🎵'); triggerHaptic(15);
    };
    inp.click();
}

/* ---- TEXT BOTTOM SHEET ---- */
var _edTextState = {text:'', font:'Classic', color:'#ffffff', effect:'none', animation:'none', align:'center'};
var _edFonts = ['Classic','Modern','Poster','Bubble','Typewriter','Serif','Mono','Rounded'];
var _edTextEffects = ['None','Neon','Hard Shadow','3D Offset','Pixel','Glow','Retro'];
var _edTextAnims = ['None','Typewriter','Pop','Fade','Slide Right','Reveal','Bounce','Spin'];
function edOpenTextSheet() {
    var existing = document.getElementById('edTextSheet');
    if (existing) { existing.remove(); return; }
    var sheet = document.createElement('div');
    sheet.id = 'edTextSheet';
    sheet.style.cssText = 'position:absolute;left:0;right:0;bottom:0;height:70%;z-index:500;background:#1a1a1a;border-radius:24px 24px 0 0;display:flex;flex-direction:column;animation:slideUpOverlay 0.35s cubic-bezier(0.34,1.56,0.64,1);';
    sheet.innerHTML =
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 16px 8px;">'+
            '<div style="width:32px;"></div>'+
            '<div style="width:36px;height:4px;background:rgba(255,255,255,0.2);border-radius:2px;margin:0 auto;"></div>'+
            '<button onclick="edApplyText()" style="background:none;border:none;color:#007AFF;font-size:15px;font-weight:700;cursor:pointer;">Done</button>'+
        '</div>'+
        // Tab icons
        '<div style="display:flex;overflow-x:auto;gap:0;border-bottom:0.5px solid rgba(255,255,255,0.1);scrollbar-width:none;">'+
            [
                {id:'kbd',icon:'fa-keyboard',tip:'Text'},
                {id:'font',icon:'fa-font',tip:'Fonts'},
                {id:'color',icon:'fa-palette',tip:'Color'},
                {id:'anim',icon:'fa-film',tip:'Animate'},
                {id:'effect',icon:'fa-star',tip:'Effect'},
                {id:'style',icon:'fa-text-height',tip:'Style'},
                {id:'format',icon:'fa-align-center',tip:'Format'}
            ].map(function(t,i){
                return '<button id="edTxtTab_'+t.id+'" onclick="edTextTab(\''+t.id+'\')" style="flex:1;min-width:48px;padding:10px 0;background:none;border:none;border-bottom:2px solid '+(i===0?'#007AFF':'transparent')+';color:'+(i===0?'#007AFF':'rgba(255,255,255,0.4)')+';cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:3px;font-size:10px;font-weight:600;">'+
                    '<i class="fa-solid '+t.icon+'" style="font-size:17px;"></i>'+t.tip+
                '</button>';
            }).join('')+
        '</div>'+
        '<div id="edTextTabBody" style="flex:1;overflow-y:auto;padding:16px;"></div>';
    var overlay = document.getElementById('preview-edit-overlay');
    if (overlay) overlay.appendChild(sheet);
    edTextTab('kbd');
}
function edTextTab(id) {
    ['kbd','font','color','anim','effect','style','format'].forEach(function(t){
        var btn = document.getElementById('edTxtTab_'+t);
        if (btn) { btn.style.borderBottom = t===id ? '2px solid #007AFF' : '2px solid transparent'; btn.style.color = t===id ? '#007AFF' : 'rgba(255,255,255,0.4)'; }
    });
    var body = document.getElementById('edTextTabBody');
    if (!body) return;
    if (id === 'kbd') {
        body.innerHTML = '<textarea id="edTxtInput" placeholder="Type something…" oninput="_edTextState.text=this.value" style="width:100%;min-height:100px;background:rgba(255,255,255,0.07);border:0.5px solid rgba(255,255,255,0.15);border-radius:14px;color:white;font-size:18px;padding:14px;outline:none;resize:none;font-family:inherit;">'+escapeHtml(_edTextState.text)+'</textarea>';
        setTimeout(function(){ var el=document.getElementById('edTxtInput'); if(el) el.focus(); }, 100);
    } else if (id === 'font') {
        body.innerHTML = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">'+
            _edFonts.map(function(f){
                var sel = f===_edTextState.font;
                return '<button onclick="edSetTextFont(\''+f+'\')" id="edFont_'+f+'" style="padding:14px;border-radius:14px;border:1.5px solid '+(sel?'#007AFF':'rgba(255,255,255,0.12)')+';background:'+(sel?'rgba(0,122,255,0.15)':'rgba(255,255,255,0.05)')+';color:white;font-size:15px;font-weight:700;cursor:pointer;">'+f+'</button>';
            }).join('')+
        '</div>';
    } else if (id === 'color') {
        var presets = ['#ffffff','#000000','#FF3B30','#FF9500','#FFD60A','#34C759','#007AFF','#5856D6','#FF2D55','#BF5AF2','#32D74B','#0A84FF'];
        body.innerHTML =
            '<div style="display:flex;align-items:center;gap:10px;margin-bottom:16px;">'+
                '<div style="width:36px;height:36px;border-radius:50%;background:'+_edTextState.color+';border:2px solid rgba(255,255,255,0.3);flex-shrink:0;"></div>'+
                '<div style="flex:1;overflow-x:auto;display:flex;gap:8px;scrollbar-width:none;">'+
                presets.map(function(c){
                    return '<div onclick="edSetTextColor(\''+c+'\')" style="width:32px;height:32px;border-radius:50%;background:'+c+';flex-shrink:0;cursor:pointer;border:2px solid '+(c===_edTextState.color?'white':'transparent')+';"></div>';
                }).join('')+
                '</div>'+
            '</div>'+
            ['Hue','Saturation','Brightness'].map(function(label, i){
                var grad = i===0 ? 'linear-gradient(to right,red,yellow,lime,cyan,blue,magenta,red)' : i===1 ? 'linear-gradient(to right,#888,'+_edTextState.color+')' : 'linear-gradient(to right,#000,#fff)';
                return '<div style="margin-bottom:14px;"><p style="color:rgba(255,255,255,0.5);font-size:12px;margin-bottom:6px;">'+label+'</p>'+
                    '<div style="height:10px;border-radius:5px;background:'+grad+';position:relative;cursor:pointer;" onclick="edSliderClick(event,\''+label.toLowerCase()+'\')">'+
                        '<div style="position:absolute;top:-3px;left:50%;width:16px;height:16px;background:white;border-radius:50%;transform:translateX(-50%);box-shadow:0 2px 6px rgba(0,0,0,0.4);pointer-events:none;"></div>'+
                    '</div></div>';
            }).join('');
    } else if (id === 'anim') {
        body.innerHTML = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">'+
            _edTextAnims.map(function(a){
                var sel = a===_edTextState.animation || (a==='None' && _edTextState.animation==='none');
                return '<button onclick="edSetTextAnim(\''+a+'\')" style="padding:14px;border-radius:14px;border:1.5px solid '+(sel?'#007AFF':'rgba(255,255,255,0.12)')+';background:'+(sel?'rgba(0,122,255,0.15)':'rgba(255,255,255,0.05)')+';color:white;font-size:13px;font-weight:700;cursor:pointer;">'+a+'</button>';
            }).join('')+
        '</div>';
    } else if (id === 'effect') {
        body.innerHTML = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">'+
            _edTextEffects.map(function(ef){
                var sel = ef===_edTextState.effect || (ef==='None' && _edTextState.effect==='none');
                var style = ef==='Neon'?'text-shadow:0 0 10px #007AFF,0 0 20px #007AFF;' : ef==='Hard Shadow'?'text-shadow:3px 3px 0 #000;' : ef==='3D Offset'?'text-shadow:2px 2px 0 #555,4px 4px 0 #333;' : ef==='Pixel'?'font-family:monospace;letter-spacing:2px;' : ef==='Glow'?'text-shadow:0 0 14px white;' : ef==='Retro'?'letter-spacing:3px;text-transform:uppercase;' : '';
                return '<button onclick="edSetTextEffect(\''+ef+'\')" style="padding:14px;border-radius:14px;border:1.5px solid '+(sel?'#007AFF':'rgba(255,255,255,0.12)')+';background:'+(sel?'rgba(0,122,255,0.15)':'rgba(255,255,255,0.05)')+';color:white;font-size:13px;font-weight:700;cursor:pointer;'+style+'">'+ef+'</button>';
            }).join('')+
        '</div>';
    } else if (id === 'style') {
        var styleOpts = [
            {label:'Bold',prop:'fontWeight',val:'900',off:'400'},
            {label:'Italic',prop:'fontStyle',val:'italic',off:'normal'},
            {label:'Underline',prop:'textDecoration',val:'underline',off:'none'},
            {label:'Shadow',prop:'textShadow',val:'2px 2px 6px rgba(0,0,0,0.6)',off:'none'},
            {label:'Outline',prop:'webkitTextStroke',val:'1px rgba(0,0,0,0.5)',off:'0'},
            {label:'Uppercase',prop:'textTransform',val:'uppercase',off:'none'},
            {label:'Wide',prop:'letterSpacing',val:'4px',off:'normal'},
            {label:'Tight',prop:'letterSpacing',val:'-1px',off:'normal'}
        ];
        body.innerHTML = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">'+
            styleOpts.map(function(opt){
                var isOn = _edTextState['style_'+opt.label] === true;
                return '<button id="edStyleBtn_'+opt.label+'" onclick="edToggleStyle(\''+opt.label+'\',\''+opt.prop+'\',\''+escapeHtml(opt.val)+'\',\''+escapeHtml(opt.off)+'\')" style="padding:14px;border-radius:14px;border:1.5px solid '+(isOn?'#007AFF':'rgba(255,255,255,0.12)')+';background:'+(isOn?'rgba(0,122,255,0.15)':'rgba(255,255,255,0.05)')+';color:white;font-size:14px;font-weight:700;cursor:pointer;">'+opt.label+'</button>';
            }).join('')+
        '</div>';
    } else if (id === 'format') {
        body.innerHTML = '<div style="display:flex;gap:10px;justify-content:center;margin-bottom:16px;">'+
            [{a:'left',icon:'fa-align-left'},{a:'center',icon:'fa-align-center'},{a:'right',icon:'fa-align-right'}].map(function(x){
                return '<button onclick="edSetTextAlign(\''+x.a+'\')" style="width:50px;height:50px;border-radius:14px;border:1.5px solid rgba(255,255,255,0.15);background:rgba(255,255,255,0.06);color:white;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:18px;"><i class="fa-solid '+x.icon+'"></i></button>';
            }).join('')+
        '</div>'+
        '<div style="display:flex;gap:8px;flex-wrap:wrap;">'+
            [{label:'Bold',css:'font-weight:900'},{label:'Italic',css:'font-style:italic'},{label:'Underline',css:'text-decoration:underline'},{label:'Uppercase',css:'text-transform:uppercase'},{label:'Small',css:'font-size:12px'},{label:'Large',css:'font-size:28px'}]
            .map(function(opt){ return '<button style="padding:8px 14px;border-radius:20px;border:0.5px solid rgba(255,255,255,0.2);background:rgba(255,255,255,0.06);color:white;font-size:13px;cursor:pointer;'+opt.css+'">'+opt.label+'</button>'; }).join('')+
        '</div>';
    }
}
function edSetTextFont(f) { _edTextState.font = f; edTextTab('font'); }
function edSetTextColor(c) { _edTextState.color = c; edTextTab('color'); }
function edSetTextAnim(a) { _edTextState.animation = a; edTextTab('anim'); }
function edSetTextEffect(e) { _edTextState.effect = e; edTextTab('effect'); }
function edSetTextAlign(a) { _edTextState.align = a; }
function edToggleStyle(label, prop, val, off) {
    var key = 'style_' + label;
    _edTextState[key] = !_edTextState[key];
    edTextTab('style');
}
function edSliderClick(e, type) {
    var rect = e.currentTarget.getBoundingClientRect();
    var pct = (e.clientX - rect.left) / rect.width;
    if (type === 'hue') { var h = Math.round(pct*360); _edTextState.color = 'hsl('+h+',100%,50%)'; }
    edTextTab('color');
}
function edApplyText() {
    var inp = document.getElementById('edTxtInput');
    if (inp) _edTextState.text = inp.value.trim();
    if (!_edTextState.text) { document.getElementById('edTextSheet').remove(); return; }
    var layer = document.getElementById('edTextLayer');
    if (layer) {
        var el = document.createElement('div');
        var fontMap = {Classic:'sans-serif',Modern:'"SF Pro Display",sans-serif',Poster:'Georgia,serif',Bubble:'Arial Rounded MT Bold,sans-serif',Typewriter:'"Courier New",monospace',Serif:'Georgia,serif',Mono:'monospace',Rounded:'Arial,sans-serif'};
        var effectMap = {Neon:'text-shadow:0 0 10px '+_edTextState.color+',0 0 20px '+_edTextState.color+';','Hard Shadow':'text-shadow:3px 3px 0 #000;','3D Offset':'text-shadow:2px 2px 0 #555,4px 4px 0 #333;',Pixel:'letter-spacing:3px;',Glow:'text-shadow:0 0 14px '+_edTextState.color+',0 0 28px '+_edTextState.color+';',Retro:'letter-spacing:3px;text-transform:uppercase;'};
        el.textContent = _edTextState.text;
        el.style.cssText = 'position:absolute;left:10%;right:10%;top:40%;text-align:'+_edTextState.align+';color:'+_edTextState.color+';font-size:22px;font-weight:800;font-family:'+fontMap[_edTextState.font]+';cursor:move;padding:4px 8px;'+(effectMap[_edTextState.effect]||'');
        // Drag
        el.addEventListener('touchstart', function(e){ var sx=e.touches[0].clientX,sy=e.touches[0].clientY; var area=document.getElementById('edPreviewArea'); var rect=area.getBoundingClientRect(); var ox=el.offsetLeft,oy=el.offsetTop;
            function mv(ev){ el.style.left=(ox+ev.touches[0].clientX-sx)+'px'; el.style.top=(oy+ev.touches[0].clientY-sy)+'px'; el.style.right='auto'; }
            function en(){ document.removeEventListener('touchmove',mv); document.removeEventListener('touchend',en); }
            document.addEventListener('touchmove',mv,{passive:true}); document.addEventListener('touchend',en); }, {passive:true});
        layer.appendChild(el);
    }
    edState.isDirty = true; edRenderTimeline(); edSaveHistory(); editorSaveDraft(false);
    var sheet = document.getElementById('edTextSheet');
    if (sheet) sheet.remove();
    showToast('Text added ✅'); triggerHaptic(15);
    _edTextState = {text:'', font:'Classic', color:'#ffffff', effect:'none', animation:'none', align:'center'};
}

/* ---- FILTER PANEL ---- */
var _edFilters = [
    {id:'none',label:'Original',css:'none'},
    {id:'vivid',label:'Vivid',css:'saturate(180%) contrast(1.1)'},
    {id:'matte',label:'Matte',css:'contrast(0.9) saturate(70%) brightness(1.05)'},
    {id:'fade',label:'Fade',css:'contrast(0.85) brightness(1.1) saturate(80%)'},
    {id:'chrome',label:'Chrome',css:'saturate(200%) contrast(1.2)'},
    {id:'noir',label:'Noir',css:'grayscale(100%) contrast(1.3)'},
    {id:'warm',label:'Warm',css:'hue-rotate(-20deg) saturate(130%)'},
    {id:'cool',label:'Cool',css:'hue-rotate(30deg) saturate(110%)'},
    {id:'golden',label:'Golden',css:'sepia(60%) saturate(150%)'},
    {id:'dramatic',label:'Dramatic',css:'contrast(1.4) saturate(120%)'}
];
/* ──────────────────────────────────────────
   CROP PANEL
────────────────────────────────────────── */
function edOpenCropPanel() {
    var existing = document.getElementById('edCropPanel');
    if (existing) { existing.remove(); return; }
    var overlay = document.getElementById('preview-edit-overlay');
    if (!overlay) return;

    // Inject crop grid over the preview
    var previewArea = document.getElementById('edPreviewArea');
    var cropGrid = document.createElement('div');
    cropGrid.id = 'edCropGrid';
    cropGrid.style.cssText = 'position:absolute;inset:0;z-index:300;pointer-events:none;' +
        'border:2px solid white;box-shadow:0 0 0 9999px rgba(0,0,0,0.55);' +
        'display:grid;grid-template-columns:1fr 1fr 1fr;grid-template-rows:1fr 1fr 1fr;';
    for (var i = 0; i < 9; i++) {
        var cell = document.createElement('div');
        cell.style.cssText = 'border:0.5px solid rgba(255,255,255,0.3);';
        cropGrid.appendChild(cell);
    }
    // Corner handles
    ['top:0;left:0;border-right:none;border-bottom:none;',
     'top:0;right:0;border-left:none;border-bottom:none;',
     'bottom:0;left:0;border-right:none;border-top:none;',
     'bottom:0;right:0;border-left:none;border-top:none;'].forEach(function(pos) {
        var h = document.createElement('div');
        h.style.cssText = 'position:absolute;width:20px;height:20px;border:3px solid white;pointer-events:all;cursor:pointer;' + pos;
        cropGrid.appendChild(h);
    });
    if (previewArea) previewArea.appendChild(cropGrid);

    var p = document.createElement('div');
    p.id = 'edCropPanel';
    p.style.cssText = 'position:absolute;left:0;right:0;bottom:0;z-index:500;' +
        'background:rgba(10,10,10,0.97);backdrop-filter:blur(30px);' +
        'border-radius:24px 24px 0 0;padding:20px 16px max(32px,env(safe-area-inset-bottom,32px));' +
        'animation:slideUpOverlay 0.3s cubic-bezier(0.32,0.72,0,1);';

    var RATIOS = [
        {label:'Freeform', icon:'⬜', w:'1', h:'1', id:'free'},
        {label:'9:16',     icon:'▯',  w:'9', h:'16', id:'916'},
        {label:'16:9',     icon:'▭',  w:'16', h:'9', id:'169'},
        {label:'1:1',      icon:'□',  w:'1', h:'1', id:'11'},
        {label:'3:4',      icon:'▯',  w:'3', h:'4', id:'34'},
        {label:'4:3',      icon:'▭',  w:'4', h:'3', id:'43'}
    ];
    var activeCrop = '916';

    p.innerHTML =
        '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;">' +
            '<button onclick="edCloseCropPanel()" style="background:rgba(255,255,255,0.1);border:none;color:white;width:32px;height:32px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;"><i class="fa-solid fa-xmark"></i></button>' +
            '<span style="color:white;font-size:17px;font-weight:700;">Crop</span>' +
            '<button onclick="edApplyCrop()" style="background:#007AFF;border:none;color:white;font-size:14px;font-weight:700;padding:8px 20px;border-radius:20px;cursor:pointer;">Apply</button>' +
        '</div>' +
        '<div style="display:flex;gap:8px;overflow-x:auto;padding-bottom:4px;scrollbar-width:none;">' +
        RATIOS.map(function(r) {
            var isActive = r.id === activeCrop;
            return '<button id="cropRatio_' + r.id + '" onclick="edSelectCropRatio(\'' + r.id + '\',\'' + r.w + '\',\'' + r.h + '\')" style="' +
                'flex-shrink:0;display:flex;flex-direction:column;align-items:center;gap:6px;' +
                'padding:12px 14px;border-radius:16px;border:2px solid ' + (isActive ? '#FF3B30' : 'rgba(255,255,255,0.15)') + ';' +
                'background:' + (isActive ? 'rgba(255,59,48,0.12)' : 'rgba(255,255,255,0.07)') + ';' +
                'color:' + (isActive ? '#FF3B30' : 'rgba(255,255,255,0.8)') + ';cursor:pointer;min-width:64px;">' +
                '<span style="font-size:18px;line-height:1;">' + r.icon + '</span>' +
                '<span style="font-size:12px;font-weight:700;">' + r.label + '</span>' +
            '</button>';
        }).join('') +
        '</div>' +
        '<button onclick="edResetCrop()" style="margin-top:16px;display:flex;align-items:center;gap:6px;background:none;border:none;color:rgba(255,255,255,0.45);font-size:14px;cursor:pointer;padding:4px 0;">' +
            '<i class="fa-solid fa-arrow-rotate-left"></i> Reset' +
        '</button>';

    overlay.appendChild(p);
}

function edSelectCropRatio(id, w, h) {
    document.querySelectorAll('[id^="cropRatio_"]').forEach(function(btn) {
        btn.style.border = '2px solid rgba(255,255,255,0.15)';
        btn.style.background = 'rgba(255,255,255,0.07)';
        btn.style.color = 'rgba(255,255,255,0.8)';
    });
    var sel = document.getElementById('cropRatio_' + id);
    if (sel) {
        sel.style.border = '2px solid #FF3B30';
        sel.style.background = 'rgba(255,59,48,0.12)';
        sel.style.color = '#FF3B30';
    }
    // Resize crop grid to match ratio
    var grid = document.getElementById('edCropGrid');
    if (grid && id !== 'free') {
        var ratio = parseFloat(w) / parseFloat(h);
        var previewArea = document.getElementById('edPreviewArea');
        if (previewArea) {
            var ph = previewArea.offsetHeight;
            var pw = previewArea.offsetWidth;
            var newW, newH;
            if (ratio > pw / ph) { newW = pw; newH = pw / ratio; }
            else { newH = ph; newW = ph * ratio; }
            grid.style.inset = 'auto';
            grid.style.width = Math.round(newW) + 'px';
            grid.style.height = Math.round(newH) + 'px';
            grid.style.top = Math.round((ph - newH) / 2) + 'px';
            grid.style.left = Math.round((pw - newW) / 2) + 'px';
        }
    } else if (grid) {
        grid.style.inset = '0';
        grid.style.width = '';
        grid.style.height = '';
        grid.style.top = '';
        grid.style.left = '';
    }
    edState.isDirty = true;
    triggerHaptic(8);
}

function edApplyCrop() {
    edCloseCropPanel();
    showToast('Crop applied ✅');
    triggerHaptic(15);
}

function edResetCrop() {
    var grid = document.getElementById('edCropGrid');
    if (grid) { grid.style.cssText = grid.style.cssText.replace(/width:[^;]+;?/g,'').replace(/height:[^;]+;?/g,''); grid.style.inset = '0'; }
    document.querySelectorAll('[id^="cropRatio_"]').forEach(function(btn) {
        btn.style.border = '2px solid rgba(255,255,255,0.15)';
        btn.style.background = 'rgba(255,255,255,0.07)';
        btn.style.color = 'rgba(255,255,255,0.8)';
    });
    showToast('Reset');
    triggerHaptic(8);
}

function edCloseCropPanel() {
    var p = document.getElementById('edCropPanel');
    if (p) p.remove();
    var g = document.getElementById('edCropGrid');
    if (g) g.remove();
}

