// --- Vibe Check ---
var _vibeAudioCtx = null;
function _getVibeCtx() {
    if (!_vibeAudioCtx) _vibeAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
    return _vibeAudioCtx;
}
function vibePlayPop() {
    try {
        var ctx = _getVibeCtx();
        var o = ctx.createOscillator();
        var g = ctx.createGain();
        o.connect(g); g.connect(ctx.destination);
        o.frequency.setValueAtTime(600, ctx.currentTime);
        o.frequency.exponentialRampToValueAtTime(300, ctx.currentTime + 0.08);
        g.gain.setValueAtTime(0.18, ctx.currentTime);
        g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.12);
        o.start(); o.stop(ctx.currentTime + 0.12);
    } catch(e) {}
}
function vibePlaySnap() {
    try {
        var ctx = _getVibeCtx();
        var o = ctx.createOscillator();
        var g = ctx.createGain();
        o.connect(g); g.connect(ctx.destination);
        o.type = 'sine';
        o.frequency.setValueAtTime(900, ctx.currentTime);
        o.frequency.exponentialRampToValueAtTime(1400, ctx.currentTime + 0.06);
        g.gain.setValueAtTime(0.2, ctx.currentTime);
        g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);
        o.start(); o.stop(ctx.currentTime + 0.1);
    } catch(e) {}
}
function vibePlayShuffle() {
    try {
        var ctx = _getVibeCtx();
        for (var i = 0; i < 4; i++) {
            (function(i) {
                var o = ctx.createOscillator();
                var g = ctx.createGain();
                o.connect(g); g.connect(ctx.destination);
                o.type = 'triangle';
                o.frequency.value = 300 + Math.random() * 400;
                g.gain.setValueAtTime(0, ctx.currentTime + i * 0.04);
                g.gain.linearRampToValueAtTime(0.08, ctx.currentTime + i * 0.04 + 0.02);
                g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + i * 0.04 + 0.1);
                o.start(ctx.currentTime + i * 0.04);
                o.stop(ctx.currentTime + i * 0.04 + 0.1);
            })(i);
        }
    } catch(e) {}
}

(function initVibeCheck() {
    document.addEventListener('DOMContentLoaded', function() {
        var tags = document.querySelectorAll('.vibe-tag');
        var dropzone = document.getElementById('vibe-dropzone');
        if (!tags.length || !dropzone) return;
        var _dragging = null, _startX, _startY, _origX, _origY, _clone;

        tags.forEach(function(tag) {
            tag.addEventListener('pointerdown', function(e) {
                e.preventDefault();
                vibePlayPop();
                _dragging = tag;
                var rect = tag.getBoundingClientRect();
                _startX = e.clientX; _startY = e.clientY;
                _origX = rect.left; _origY = rect.top;
                _clone = tag.cloneNode(true);
                _clone.style.cssText = 'position:fixed;left:'+rect.left+'px;top:'+rect.top+'px;width:'+rect.width+'px;pointer-events:none;z-index:9999;transform:scale(1.08);box-shadow:0 8px 24px rgba(0,0,0,0.22);opacity:0.92;padding:8px 16px;border-radius:20px;font-size:13px;font-weight:700;background:'+getComputedStyle(tag).background+';color:'+getComputedStyle(tag).color+';';
                document.body.appendChild(_clone);
                tag.style.opacity = '0.3';
                tag.setPointerCapture(e.pointerId);
            });
            tag.addEventListener('pointermove', function(e) {
                if (!_dragging || _dragging !== tag) return;
                var dx = e.clientX - _startX, dy = e.clientY - _startY;
                _clone.style.left = (_origX + dx) + 'px';
                _clone.style.top = (_origY + dy) + 'px';
                var dzRect = dropzone.getBoundingClientRect();
                if (e.clientX > dzRect.left && e.clientX < dzRect.right && e.clientY > dzRect.top && e.clientY < dzRect.bottom) {
                    dropzone.classList.add('dragover');
                } else {
                    dropzone.classList.remove('dragover');
                }
            });
            tag.addEventListener('pointerup', function(e) {
                if (!_dragging || _dragging !== tag) return;
                var dzRect = dropzone.getBoundingClientRect();
                if (e.clientX > dzRect.left && e.clientX < dzRect.right && e.clientY > dzRect.top && e.clientY < dzRect.bottom) {
                    var word = tag.getAttribute('data-word');
                    var bg = getComputedStyle(tag).background;
                    var col = getComputedStyle(tag).color;
                    dropzone.innerHTML = '<span style="padding:8px 20px;border-radius:20px;font-size:14px;font-weight:700;background:'+bg+';color:'+col+';">'+word+'</span>';
                    dropzone.classList.add('filled');
                    dropzone.classList.remove('dragover');
                    vibePlaySnap();
                    if (typeof triggerHaptic === 'function') triggerHaptic(12);
                } else {
                    dropzone.classList.remove('dragover');
                    tag.style.opacity = '1';
                }
                if (_clone && _clone.parentNode) _clone.parentNode.removeChild(_clone);
                _dragging = null; _clone = null;
            });
        });
    });
})();

function vibeCheckShuffle() {
    vibePlayShuffle();
    var cluster = document.getElementById('vibe-tags');
    if (!cluster) return;
    var tags = Array.from(cluster.querySelectorAll('.vibe-tag'));
    for (var i = tags.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        cluster.appendChild(tags[j]);
        tags.splice(j, 1);
    }
    var angles = [-2, 0, 1.5, -1, 2, 0, -1.5];
    cluster.querySelectorAll('.vibe-tag').forEach(function(t, i) {
        t.style.transform = 'rotate('+( angles[i % angles.length] )+'deg)';
        t.style.animation = 'popIn 0.25s ease '+(i*0.03)+'s both';
    });
    if (typeof triggerHaptic === 'function') triggerHaptic(8);
    var dz = document.getElementById('vibe-dropzone');
    if (dz && dz.classList.contains('filled')) {
        dz.innerHTML = '<span id="vibe-drop-placeholder"><i class="fa-regular fa-circle-dot" style="margin-right:6px;"></i>Drop a word here</span>';
        dz.classList.remove('filled');
    }
}

// --- Breathe Evenly ---
var _breatheTimer = null, _breathePhase = 0, _breatheCount = 0, _breatheRunning = false;
var _breathePhases = ['Inhale…', 'Hold.', 'Exhale…', 'Hold.'];
var _breatheStyles = ['scale(1.55)', 'scale(1.55)', 'scale(1)', 'scale(1)'];
var _breatheAudioCtx = null;

function _getBreatheCtx() {
    if (!_breatheAudioCtx) _breatheAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
    return _breatheAudioCtx;
}
function _breatheChime(freq) {
    try {
        var ctx = _getBreatheCtx();
        var o = ctx.createOscillator();
        var g = ctx.createGain();
        o.connect(g); g.connect(ctx.destination);
        o.type = 'sine';
        o.frequency.setValueAtTime(freq, ctx.currentTime);
        g.gain.setValueAtTime(0.001, ctx.currentTime);
        g.gain.linearRampToValueAtTime(0.12, ctx.currentTime + 0.2);
        g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 1.5);
        o.start(); o.stop(ctx.currentTime + 1.6);
    } catch(e) {}
}
var _breatheChimeFreqs = [523, 659, 784, 659];

function toggleBreathe() {
    if (_breatheRunning) {
        _breatheRunning = false;
        clearTimeout(_breatheTimer);
        var pulse = document.getElementById('breathe-pulse');
        var wrap = document.getElementById('breathe-pulse-wrap');
        var icon = document.getElementById('breathe-btn-icon');
        if (pulse) pulse.style.transform = 'scale(1)';
        if (wrap) wrap.style.display = 'none';
        if (icon) { icon.className = 'fa-solid fa-play'; icon.style.marginLeft = '2px'; }
        document.getElementById('breathe-phase-label').textContent = '';
        document.getElementById('breathe-count-label').textContent = '';
    } else {
        _breatheRunning = true;
        _breathePhase = 0;
        _breatheCount = 0;
        var wrap = document.getElementById('breathe-pulse-wrap');
        var icon = document.getElementById('breathe-btn-icon');
        if (wrap) wrap.style.display = 'block';
        if (icon) { icon.className = 'fa-solid fa-stop'; icon.style.marginLeft = '0'; }
        runBreathePhase();
    }
}
function runBreathePhase() {
    if (!_breatheRunning) return;
    var pulse = document.getElementById('breathe-pulse');
    var phaseLabel = document.getElementById('breathe-phase-label');
    var countLabel = document.getElementById('breathe-count-label');
    if (!pulse) return;
    var phase = _breathePhase % 4;
    if (phase === 0) _breatheCount++;
    if (_breatheCount > 8) { toggleBreathe(); showToast('Session complete 🧘 Great work!'); return; }
    pulse.style.transform = _breatheStyles[phase];
    if (phaseLabel) phaseLabel.textContent = _breathePhases[phase];
    if (countLabel) countLabel.textContent = 'Round ' + _breatheCount + ' of 8';
    _breatheChime(_breatheChimeFreqs[phase]);
    var countDown = 4;
    var cdInterval = setInterval(function() {
        countDown--;
        if (countLabel && _breatheRunning) countLabel.textContent = 'Round ' + _breatheCount + ' of 8  •  ' + countDown + 's';
    }, 1000);
    _breatheTimer = setTimeout(function() {
        clearInterval(cdInterval);
        _breathePhase++;
        runBreathePhase();
    }, 4000);
}

// --- Soothing Sounds ---
var _soundsCtx = null, _soundsNode = null, _soundsGain = null, _soundsPlaying = false;
var _soundsTrack = 'white', _soundsVisInterval = null;
var _soundsTrackNames = { white: 'White Noise', rain: 'Light Rain', ocean: 'Ocean Waves' };

function _getSoundsCtx() {
    if (!_soundsCtx) _soundsCtx = new (window.AudioContext || window.webkitAudioContext)();
    return _soundsCtx;
}
function _makeSoundsNode(track) {
    var ctx = _getSoundsCtx();
    var bufSize = ctx.sampleRate * 2;
    var buf = ctx.createBuffer(1, bufSize, ctx.sampleRate);
    var data = buf.getChannelData(0);
    if (track === 'white') {
        for (var i = 0; i < bufSize; i++) data[i] = (Math.random() * 2 - 1);
    } else if (track === 'rain') {
        for (var i = 0; i < bufSize; i++) data[i] = (Math.random() * 2 - 1) * 0.7;
        var filter = ctx.createBiquadFilter();
        filter.type = 'lowpass'; filter.frequency.value = 800;
        var src = ctx.createBufferSource(); src.buffer = buf; src.loop = true;
        src.connect(filter); return { src: src, extra: filter };
    } else if (track === 'ocean') {
        for (var i = 0; i < bufSize; i++) {
            data[i] = (Math.random() * 2 - 1) * (0.5 + 0.5 * Math.sin(i / ctx.sampleRate * 0.3));
        }
    }
    var src = ctx.createBufferSource(); src.buffer = buf; src.loop = true;
    return { src: src, extra: null };
}
function toggleSounds() {
    if (_soundsPlaying) {
        stopSounds();
    } else {
        startSounds();
    }
}
function startSounds() {
    try {
        var ctx = _getSoundsCtx();
        if (ctx.state === 'suspended') ctx.resume();
        stopSounds(true);
        var node = _makeSoundsNode(_soundsTrack);
        _soundsGain = ctx.createGain();
        _soundsGain.gain.setValueAtTime(0, ctx.currentTime);
        _soundsGain.gain.linearRampToValueAtTime(0.4, ctx.currentTime + 1.5);
        if (node.extra) { node.extra.connect(_soundsGain); }
        else { node.src.connect(_soundsGain); }
        _soundsGain.connect(ctx.destination);
        node.src.start();
        _soundsNode = node.src;
        _soundsPlaying = true;
        var icon = document.getElementById('sounds-icon');
        var btn = document.getElementById('sounds-mute-btn');
        if (icon) icon.className = 'fa-solid fa-pause';
        if (btn) btn.classList.add('playing');
        startSoundsVis();
        if (icon) { icon.style.marginLeft = '0'; }
    } catch(e) { showToast('Audio unavailable'); }
}
function stopSounds(silent) {
    if (_soundsNode) {
        try {
            if (!silent && _soundsGain) {
                _soundsGain.gain.setValueAtTime(_soundsGain.gain.value, _soundsCtx.currentTime);
                _soundsGain.gain.linearRampToValueAtTime(0, _soundsCtx.currentTime + 0.8);
                var ref = _soundsNode;
                setTimeout(function() { try { ref.stop(); } catch(e) {} }, 900);
            } else {
                _soundsNode.stop();
            }
        } catch(e) {}
        _soundsNode = null;
    }
    _soundsPlaying = false;
    clearInterval(_soundsVisInterval);
    var icon = document.getElementById('sounds-icon');
    var btn = document.getElementById('sounds-mute-btn');
    if (icon) { icon.className = 'fa-solid fa-play'; icon.style.marginLeft = '2px'; }
    if (btn) btn.classList.remove('playing');
    stopSoundsVis();
}
function switchSoundTrack(track, el) {
    _soundsTrack = track;
    document.querySelectorAll('.sounds-dot').forEach(function(d) { d.classList.remove('active'); });
    if (el) el.classList.add('active');
    var lbl = document.getElementById('sounds-track-label');
    if (lbl) lbl.textContent = _soundsTrackNames[track] || track;
    if (_soundsPlaying) { stopSounds(true); setTimeout(startSounds, 100); }
}
function initSoundsVisualizer() {
    var vis = document.getElementById('sounds-visualizer');
    if (!vis || vis.children.length > 0) return;
    for (var i = 0; i < 22; i++) {
        var b = document.createElement('div');
        b.className = 'sounds-vis-bar';
        vis.appendChild(b);
    }
}
function startSoundsVis() {
    clearInterval(_soundsVisInterval);
    _soundsVisInterval = setInterval(function() {
        var bars = document.querySelectorAll('.sounds-vis-bar');
        bars.forEach(function(b) {
            var h = _soundsPlaying ? (4 + Math.random() * 36) : 4;
            b.style.height = h + 'px';
        });
    }, 80);
}
function stopSoundsVis() {
    clearInterval(_soundsVisInterval);
    document.querySelectorAll('.sounds-vis-bar').forEach(function(b) { b.style.height = '4px'; });
}
function drawSoundsRipple() {
    var canvas = document.getElementById('sounds-ripple-canvas');
    if (!canvas) return;
    var ctx = canvas.getContext('2d');
    var w = canvas.offsetWidth, h = canvas.offsetHeight;
    canvas.width = w; canvas.height = h;
    var t = 0;
    function frame() {
        if (!document.getElementById('sounds-ripple-canvas')) return;
        ctx.clearRect(0, 0, w, h);
        ctx.strokeStyle = 'rgba(255,255,255,0.6)';
        var maxR = Math.max(w, h) * 0.7;
        for (var r = 0; r < maxR; r += 30) {
            var phase = (r / maxR + t * 0.003) % 1;
            ctx.globalAlpha = (1 - phase) * 0.5;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.arc(w / 2, h / 2, r + (phase * 30), 0, Math.PI * 2);
            ctx.stroke();
        }
        t++;
        requestAnimationFrame(frame);
    }
    frame();
}

