async function loadDiscoverPeople() {
    var list = document.getElementById('discover-people-list'); // adjust to your element
    if (!window.sb || !currentUser) return;
    var { data } = await sb.from('users')
        .select('id, full_name, username, avatar_url, bio, verified')
        .neq('id', currentUser.id)
        .limit(20);
    if (!data || data.length === 0) {
        if (list) list.innerHTML = '<p style="text-align:center;color:#888;padding:40px;">No suggestions yet.</p>';
        return;
    }
    // check who currentUser follows
    var { data: following } = await sb.from('follows')
        .select('following_id')
        .eq('follower_id', currentUser.id);
    var followingIds = new Set((following || []).map(function(f) { return f.following_id; }));
    if (list) list.innerHTML = data.map(function(u) {
        var isFollowing = followingIds.has(u.id);
        var avatar = u.avatar_url || ('https://ui-avatars.com/api/?name=' + encodeURIComponent(u.full_name || 'U') + '&background=007AFF&color=fff&size=80');
        return '<div style="display:flex;align-items:center;gap:12px;padding:12px 16px;">' +
            '<img src="' + escapeHtml(avatar) + '" style="width:46px;height:46px;border-radius:50%;object-fit:cover;">' +
            '<div style="flex:1;"><b style="font-size:14px;">' + escapeHtml(u.full_name || '') + '</b>' +
            '<div style="font-size:12px;color:#888;">@' + escapeHtml(u.username || '') + '</div></div>' +
            '<button onclick="toggleFollow(\'' + u.id + '\',this)" style="padding:7px 16px;border-radius:20px;border:none;background:' + (isFollowing ? '#f0f0f0' : '#007AFF') + ';color:' + (isFollowing ? '#333' : '#fff') + ';font-weight:700;font-size:13px;cursor:pointer;">' +
            (isFollowing ? 'Following' : 'Follow') + '</button></div>';
    }).join('');
}

var _fsData = { followers: [], following: [] };
var _fsTab = 'followers';
function openFollowersScreen() {
    openPage('followers-screen');
    var titleEl = document.getElementById('fs-title');
    if (titleEl && currentUser) titleEl.textContent = currentUser.name || 'Followers';
    renderFsList();
}
function switchFsTab(tab) {
    _fsTab = tab;
    document.getElementById('fs-tab-followers').classList.toggle('active', tab === 'followers');
    document.getElementById('fs-tab-following').classList.toggle('active', tab === 'following');
    document.getElementById('fs-search-input').value = '';
    renderFsList();
}
function renderFsList(filter) {
    var list = document.getElementById('fs-list-content');
    if (!list) return;
    var items = _fsData[_fsTab] || [];
    if (filter) {
        var f = filter.toLowerCase();
        items = items.filter(function(u) { return u.name.toLowerCase().includes(f) || u.handle.toLowerCase().includes(f); });
    }
    if (!items.length) {
        list.innerHTML = '<div style="text-align:center;padding:50px 20px;color:#888;font-size:14px;">No users found</div>';
        return;
    }
    list.innerHTML = items.map(function(u, i) {
        var btnCls = u.state === 'Following' ? 'fs-follow-btn following-state' : 'fs-follow-btn';
        var delay = (i * 0.05) + 's';
        return '<div class="fs-user-row" style="animation-delay:'+delay+';">' +
            '<img class="fs-avatar" src="'+u.avatar+'" onerror="this.src=\'https://ui-avatars.com/api/?name=U&background=888&color=fff&size=80\'">' +
            '<div class="fs-user-info">' +
                '<div class="fs-name">'+u.name+(u.verified ? ' <i class="fa-solid fa-circle-check" style="color:#007AFF;font-size:13px;"></i>' : '')+'</div>' +
                '<div class="fs-handle"><span>@'+u.handle+'</span>'+(u.followsYou ? '<span class="fs-follows-badge">Follows you</span>' : '')+'</div>' +
                (u.bio ? '<div class="fs-bio">'+u.bio+'</div>' : '') +
            '</div>' +
            '<button class="'+btnCls+'" onclick="toggleFsFollow('+u.id+',this)">'+u.state+'</button>' +
        '</div>';
    }).join('');
}
function filterFsList(val) { renderFsList(val); }
function toggleFsFollow(id, btn) {
    var all = [].concat(_fsData.followers, _fsData.following);
    var user = all.find(function(u) { return u.id === id; });
    if (!user) return;
    if (user.state === 'Following') {
        user.state = _fsTab === 'followers' ? 'Follow back' : 'Follow';
        btn.textContent = user.state;
        btn.classList.remove('following-state');
    } else {
        user.state = 'Following';
        btn.textContent = 'Following';
        btn.classList.add('following-state');
        btn.style.animation = 'popIn 0.25s ease';
    }
    if (typeof triggerHaptic === 'function') triggerHaptic(10);
}

