    function openChatBubbleMenu(bubble) {
    document.querySelectorAll('.chat-bubble').forEach(b => b.classList.remove('focused'));
    bubble.classList.add('focused');
    document.getElementById('chat-body').classList.add('bubble-focused');
    triggerHaptic(30);
    var existing = document.getElementById('chatBubbleContextMenu');
    if (existing) existing.remove();
    var menu = document.createElement('div');
    menu.id = 'chatBubbleContextMenu';
    menu.style.cssText = 'position:absolute;bottom:80px;left:50%;transform:translateX(-50%);z-index:8000;background:var(--bg-primary,#fff);border-radius:18px;box-shadow:0 8px 32px rgba(0,0,0,0.18);overflow:hidden;min-width:200px;animation:popIn 0.2s ease;';
    var msgText = bubble.querySelector('p,span')?.textContent || '';
    menu.innerHTML = ['Reply','Copy','Forward','React','Delete'].map(function(a){
        return '<div onclick="chatBubbleAction(\''+a+'\',\''+encodeURIComponent(msgText)+'\');document.getElementById(\'chatBubbleContextMenu\').remove();" style="padding:14px 20px;font-size:15px;font-weight:500;cursor:pointer;border-bottom:0.5px solid var(--border-color,#f0f0f0);">'+(a==='Delete'?'<span style="color:#FF3B30;">'+a+'</span>':a)+'</div>';
    }).join('');
    var chatBody = document.getElementById('chat-body');
    chatBody.appendChild(menu);
    document.addEventListener('click', function rm(e){ if(!e.target.closest('#chatBubbleContextMenu')&&!e.target.closest('.chat-bubble')){ menu.remove(); document.removeEventListener('click',rm); } });
    setTimeout(function(){ document.getElementById('chat-body').classList.remove('bubble-focused'); bubble.classList.remove('focused'); }, 4000);
}
function chatBubbleAction(action, msgEncoded) {
    var msg = decodeURIComponent(msgEncoded);
    if (action === 'Copy') { navigator.clipboard?.writeText(msg); showToast('Copied!'); }
    else if (action === 'Reply') { var inp = document.getElementById('chat-msg-input'); if(inp){ inp.value = ''; inp.placeholder = 'Replying: ' + msg.substring(0,30) + '…'; inp.focus(); } }
    else { showToast(action + ' coming soon'); }
}

