window.addPollOption = function() {
    var opts = document.getElementById('pollOptions');
    var items = opts ? opts.querySelectorAll('.poll-opt-pill') : [];
    if (items.length >= 4) { showToast('Max 4 options'); return; }
    var pill = document.createElement('div');
    pill.className = 'poll-opt-pill';
    pill.style.cssText = 'display:flex;align-items:center;background:var(--card-bg,#f7f7f7);border-radius:50px;padding:14px 18px;border:1.5px solid var(--border-color,#e8e8e8);gap:8px;animation:popIn 0.2s ease;';
    pill.innerHTML = '<input placeholder="Option '+(items.length+1)+'" style="flex:1;background:none;border:none;outline:none;font-size:15px;font-weight:600;color:var(--text-primary,#000);font-family:inherit;"><button onclick="this.parentNode.remove()" style="background:none;border:none;color:#FF3B30;font-size:16px;cursor:pointer;padding:0;">×</button>';
    if (opts) opts.appendChild(pill);
    if (items.length >= 3) { var b=document.getElementById('addPollOptBtn');if(b)b.style.display='none'; }
    triggerHaptic(8);
};
window.savePoll = function() {
    var q = document.getElementById('pollQuestion');
    if (!q||!q.value.trim()) { showToast('Add a question first'); return; }
    document.getElementById('pollCreatorPage').remove();
    showToast('Poll added to trustclip 📊');
};

