window.openCurrencyPicker = function() {
    var currencies = [
        {code:'ZAR',sym:'R',name:'South African Rand'},
        {code:'USD',sym:'$',name:'US Dollar'},
        {code:'EUR',sym:'€',name:'Euro'},
        {code:'GBP',sym:'£',name:'British Pound'},
        {code:'NGN',sym:'₦',name:'Nigerian Naira'},
        {code:'KES',sym:'KSh',name:'Kenyan Shilling'},
        {code:'GHS',sym:'₵',name:'Ghanaian Cedi'}
    ];
    var picker = document.createElement('div');
    picker.style.cssText = 'position:absolute;inset:0;z-index:9700;display:flex;align-items:flex-end;background:rgba(0,0,0,0.5);backdrop-filter:blur(10px);';
    picker.innerHTML =
        '<div style="width:100%;background:var(--bg-primary,#fff);border-radius:22px 22px 0 0;padding:0 0 40px;animation:modalUp 0.3s cubic-bezier(0.32,0.72,0,1);">' +
            '<div style="width:36px;height:4px;background:#ccc;border-radius:2px;margin:14px auto 0;"></div>' +
            '<div style="padding:14px 20px 8px;"><b style="font-size:17px;color:var(--text-primary,#000);">Select currency</b></div>' +
            currencies.map(function(c){
                return '<div onclick="setCurrency(\''+c.code+'\',\''+c.sym+'\')" style="display:flex;align-items:center;gap:14px;padding:14px 20px;border-top:0.5px solid var(--border-color,#f0f0f0);cursor:pointer;">' +
                    '<div style="width:38px;height:38px;border-radius:50%;background:var(--card-bg,#f2f2f7);display:flex;align-items:center;justify-content:center;font-size:15px;font-weight:700;color:var(--text-primary,#000);">'+c.sym+'</div>' +
                    '<div><div style="font-size:15px;font-weight:600;color:var(--text-primary,#000);">'+c.name+'</div><div style="font-size:13px;color:#888;">'+c.code+'</div></div>' +
                    '</div>';
            }).join('') +
        '</div>';
    picker.addEventListener('click',function(e){ if(e.target===picker) picker.remove(); });
    (document.getElementById('productDetailsScreen')||document.getElementById('app')||document.body).appendChild(picker);
};
window.setCurrency = function(code,sym) {
    var s=document.getElementById('pdCurrSymbol');if(s)s.textContent=sym;
    var pickers=document.querySelectorAll('[style*="z-index: 9700"],[style*="z-index:9700"]');
    pickers.forEach(function(p){p.remove();});
    showToast('Currency: '+code);
};
window.saveProductDetails = function() {
    var t=document.getElementById('pdTitle');
    if(!t||!t.value.trim()){showToast('Add a product title');return;}
    document.getElementById('productDetailsScreen').remove();
    showToast('Product added to trustclip 🛍️');
    triggerHaptic(20);
};

    function showReelUploadProgress(pct) {
    var ring = document.getElementById('nav-reels-ring');
    var circle = document.getElementById('nav-reels-ring-circle');
    var icon = document.getElementById('nav-reels');
    if (!ring || !circle || !icon) return;
    ring.style.display = 'block';
    var offset = 100 - Math.min(100, Math.max(0, pct));
    circle.style.strokeDashoffset = offset;
    if (pct >= 100) {
        circle.style.stroke = '#34C759';
        icon.className = 'fa-solid fa-check nav-icon others-only';
        setTimeout(function() {
            ring.style.display = 'none';
            circle.style.stroke = '#007AFF';
            circle.style.strokeDashoffset = 100;
            icon.className = 'fa-solid fa-clapperboard nav-icon others-only';
        }, 1500);
    }
}

    /* ============================================================
   FREE UP SPACE SCREEN
   ============================================================ */
function openFreeUpSpaceScreen() {
    var existing = document.getElementById('freeUpSpaceScreen');
    if (existing) existing.remove();
    var tcDrafts = [];
    try { tcDrafts = JSON.parse(localStorage.getItem('tf_tc_drafts') || '[]'); } catch(e) {}
    var draftSizeMB = tcDrafts.reduce(function(a,d){ return a + parseFloat(d.fileSize||'0'); },0).toFixed(1);
    var screen = document.createElement('div');
    screen.id = 'freeUpSpaceScreen';
    screen.style.cssText = 'position:absolute;inset:0;z-index:9100;display:flex;flex-direction:column;background:var(--bg-secondary,#f2f2f7);animation:slideUpOverlay 0.3s cubic-bezier(0.32,0.72,0,1);overflow-y:auto;';
    screen.innerHTML =
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;background:var(--bg-primary,#fff);border-bottom:0.5px solid var(--border-color,#f0f0f0);position:sticky;top:0;z-index:2;">' +
            '<button onclick="document.getElementById(\'freeUpSpaceScreen\').remove()" style="background:none;border:none;color:#007AFF;font-size:22px;cursor:pointer;"><i class="fa-solid fa-chevron-left"></i></button>' +
            '<b style="font-size:17px;color:var(--text-primary,#000);">Free Up Space</b>' +
            '<div style="width:36px;"></div>' +
        '</div>' +
        '<div style="padding:20px 20px 8px;">' +
            '<div style="background:var(--card-bg,#fff);border-radius:18px;padding:18px;">' +
                '<p style="font-size:13px;font-weight:700;color:#888;text-transform:uppercase;letter-spacing:0.05em;margin-bottom:14px;">Storage used</p>' +
                (function(){
                    var lsSize = 0;
                    try { for (var k in localStorage) { if (Object.prototype.hasOwnProperty.call(localStorage,k)) lsSize += (localStorage[k]||'').length * 2; } } catch(e){}
                    var lsMB = Math.round(lsSize / 1048576 * 10) / 10;
                    var tfPct = Math.min(Math.round(lsMB / 5 * 100), 90);
                    var freePct = 100 - tfPct;
                    return '<div style="height:10px;border-radius:5px;background:#f0f0f0;overflow:hidden;margin-bottom:10px;display:flex;">' +
                        '<div style="width:' + tfPct + '%;background:#007AFF;border-radius:5px 0 0 5px;min-width:4px;"></div>' +
                        '<div style="width:' + freePct + '%;background:#f0f0f0;"></div>' +
                        '</div>' +
                        '<div style="display:flex;gap:16px;flex-wrap:wrap;">' +
                        '<div style="display:flex;align-items:center;gap:6px;"><div style="width:10px;height:10px;border-radius:50%;background:#007AFF;"></div><span style="font-size:12px;color:#888;">TrustFirst ' + lsMB + 'MB</span></div>' +
                        '<div style="display:flex;align-items:center;gap:6px;"><div style="width:10px;height:10px;border-radius:50%;background:#e0e0e0;"></div><span style="font-size:12px;color:#888;">Free space available</span></div>' +
                        '</div>';
                })() +
            '</div>' +
        '</div>' +
        '<div style="padding:0 20px 8px;">' +
            '<p style="font-size:12px;font-weight:700;color:#888;text-transform:uppercase;letter-spacing:0.06em;padding:14px 0 6px;">Actions</p>' +
            '<div style="background:var(--card-bg,#fff);border-radius:18px;overflow:hidden;">' +
                '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 18px;border-bottom:0.5px solid var(--border-color,#f0f0f0);">' +
                    (function(){ var kb = 0; try { for(var k in localStorage){ if(k.startsWith('tf_cache_')||k.startsWith('tf_img_')) kb += (localStorage[k]||'').length; } } catch(e){} return '<div><b style="font-size:15px;color:var(--text-primary,#000);">Cache</b><p style="font-size:12px;color:#888;margin:2px 0 0;">Temporary files — '+(kb?Math.max(1,Math.round(kb/1024))+'KB':'empty')+'</p></div>'; })() +
                    '<button onclick="clearTrustFirstCache(this)" style="padding:8px 18px;border-radius:10px;background:rgba(255,149,0,0.1);color:#FF9500;border:none;font-size:13px;font-weight:700;cursor:pointer;">Clear</button>' +
                '</div>' +
                '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 18px;border-bottom:0.5px solid var(--border-color,#f0f0f0);">' +
                    '<div><b style="font-size:15px;color:var(--text-primary,#000);">Downloads</b><p style="font-size:12px;color:#888;margin:2px 0 0;">Offline videos, effects, filters — 340MB</p></div>' +
                    '<button onclick="clearTrustFirstDownloads(this)" style="padding:8px 18px;border-radius:10px;background:rgba(255,59,48,0.1);color:#FF3B30;border:none;font-size:13px;font-weight:700;cursor:pointer;">Clear</button>' +
                '</div>' +
                '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 18px;">' +
                    '<div><b style="font-size:15px;color:var(--text-primary,#000);">Drafts</b><p style="font-size:12px;color:#888;margin:2px 0 0;">' + tcDrafts.length + ' trustclip draft' + (tcDrafts.length!==1?'s':'') + ' — ' + draftSizeMB + 'MB</p></div>' +
                    '<button onclick="document.getElementById(\'freeUpSpaceScreen\').remove();openTrustclipDraftsScreen();" style="padding:8px 18px;border-radius:10px;background:rgba(0,122,255,0.1);color:#007AFF;border:none;font-size:13px;font-weight:700;cursor:pointer;">Manage</button>' +
                '</div>' +
            '</div>' +
        '</div>' +
        '<div style="padding:16px 24px;"><p style="font-size:12px;color:#aaa;line-height:1.65;">System files required for app stability cannot be cleared. Clearing downloads removes offline videos but does not delete posted content.</p></div>';
    (document.getElementById('app') || document.body).appendChild(screen);
}

function clearTrustFirstCache(btn) {
    btn.textContent = 'Cleared ✓';
    btn.style.background = 'rgba(52,199,89,0.1)';
    btn.style.color = '#34C759';
    btn.disabled = true;
    showToast('Cache cleared — 128MB freed');
    triggerHaptic(20);
}

function clearTrustFirstDownloads(btn) {
    if (!confirm('Clear all downloaded videos, effects and filters?')) return;
    btn.textContent = 'Cleared ✓';
    btn.style.background = 'rgba(52,199,89,0.1)';
    btn.style.color = '#34C759';
    btn.disabled = true;
    try { localStorage.removeItem('tf_offline_videos'); } catch(e) {}
    showToast('Downloads cleared — 340MB freed');
    triggerHaptic(20);
}

