async function fcSearchUser() {
    var input = document.getElementById('fc-username-input');
    var resultEl = document.getElementById('fc-search-result');
    if (!input || !resultEl) return;
    var username = input.value.trim().replace(/^@/, '').toLowerCase();
    if (!username) { resultEl.innerHTML = ''; return; }
    if (!window._sb) { resultEl.innerHTML = '<p style="font-size:13px;color:#888;padding:8px 0;">Not connected.</p>'; return; }
    resultEl.innerHTML = '<div style="text-align:center;padding:16px;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;"></i></div>';
    try {
        var { data, error } = await window._sb
            .from('profiles')
            .select('id,display_name,username,avatar_url,identity_verified,account_type')
            .eq('username', username)
            .maybeSingle();
        if (error || !data) {
            resultEl.innerHTML = '<div style="background:rgba(255,59,48,0.07);border-radius:14px;padding:14px 16px;display:flex;align-items:center;gap:10px;"><i class="fa-solid fa-user-xmark" style="color:#FF3B30;font-size:18px;"></i><span style="font-size:14px;color:var(--text-primary,#000);">No account found for <b>@' + escapeHtml(username) + '</b></span></div>';
            return;
        }
        var avatarHtml = data.avatar_url
            ? '<img src="' + escapeHtml(data.avatar_url) + '" style="width:46px;height:46px;border-radius:50%;object-fit:cover;border:2px solid var(--border-color,#eee);">'
            : '<div style="width:46px;height:46px;border-radius:50%;background:#e0e0e0;display:flex;align-items:center;justify-content:center;"><i class="fa-solid fa-user" style="color:#aaa;font-size:20px;"></i></div>';
        resultEl.innerHTML =
            '<div style="background:var(--card-bg,#fff);border-radius:16px;padding:14px 16px;border:1.5px solid var(--border-color,#eee);display:flex;align-items:center;gap:12px;">' +
                avatarHtml +
                '<div style="flex:1;min-width:0;">' +
                    '<b style="font-size:15px;color:var(--text-primary,#000);display:block;">' + escapeHtml(data.display_name || data.username) + '</b>' +
                    '<span style="font-size:13px;color:#888;">@' + escapeHtml(data.username) + '</span>' +
                '</div>' +
                '<button onclick="fcSendLinkRequest(\'' + data.id + '\',\'' + escapeHtml(data.username) + '\',\'' + escapeHtml(data.display_name || data.username) + '\')" style="padding:10px 16px;border-radius:12px;border:none;background:#007AFF;color:#fff;font-size:13px;font-weight:700;cursor:pointer;">Link</button>' +
            '</div>';
    } catch(e) {
        resultEl.innerHTML = '<p style="font-size:13px;color:#888;padding:8px 0;">Search failed. Try again.</p>';
    }
}

async function fcSendLinkRequest(childId, childUsername, childName) {
    if (!window._sb || !currentUser) return;
    try {
        var { error } = await window._sb.from('family_links').insert({
            parent_id: currentUser.id,
            child_id: childId,
            status: 'pending',
            created_at: new Date().toISOString()
        });
        if (error) throw error;
        // Notify child
        await window._sb.from('notifications').insert({
            user_id: childId,
            type: 'family_link_request',
            from_user_id: currentUser.id,
            message: (currentUser.display_name || currentUser.username) + ' wants to link your account in Family Center',
            created_at: new Date().toISOString(),
            read: false
        });
        document.getElementById('fc-search-result').innerHTML =
            '<div style="background:rgba(52,199,89,0.1);border-radius:14px;padding:14px 16px;display:flex;align-items:center;gap:10px;"><i class="fa-solid fa-circle-check" style="color:#34C759;font-size:18px;"></i><span style="font-size:14px;color:var(--text-primary,#000);">Link request sent to <b>' + escapeHtml(childName) + '</b></span></div>';
        document.getElementById('fc-username-input').value = '';
        var statusEl = document.getElementById('fc-linked-status');
        if (statusEl) statusEl.innerHTML = 'Request sent to <b>' + escapeHtml(childName) + '</b> — awaiting approval';
    } catch(e) {
        showToast('Could not send link request: ' + (e.message || 'Try again'));
    }
}

function setAppLanguage(lang) {
    _appLang = lang;
    localStorage.setItem('tf-lang', lang);
    if (typeof applyAppTranslations === 'function') applyAppTranslations(lang);
    else if (typeof renderSettingsTranslations === 'function') renderSettingsTranslations();
    showToast('Language updated');
}

function renderNotif(n) {
    if (isSleepModeActive()) return; // Sleep mode — silence all notifications
}

function formatCount(n) {
    if (n >= 1000000) return (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'M';
    if (n >= 1000) return (n / 1000).toFixed(1).replace(/\.0$/, '') + 'K';
    return String(n);
}

function waitForSb() {
    if (window.sb) return Promise.resolve();
    return new Promise(function(resolve, reject) {
        var check = setInterval(function() {
            if (window.sb) { clearInterval(check); resolve(); }
        }, 100);
        setTimeout(function() {
            clearInterval(check);
            if (!window.sb) reject(new Error('Supabase connection timeout'));
            else resolve();
        }, 10000);
    });
}

