// ── Video player ──
function toggleVideoPlay(wrap) {
    const vid = wrap.querySelector('.post-video');
    const overlay = wrap.querySelector('.vid-play-overlay');
    const bar = wrap.querySelector('.vid-bottom-bar');
    if (vid.paused) {
        document.querySelectorAll('.post-video').forEach(v => {
            if (v !== vid) {
                v.pause();
                v.closest('.post-video-wrap').querySelector('.vid-play-overlay').style.opacity = '1';
                v.closest('.post-video-wrap').querySelector('.vid-bottom-bar').style.opacity = '0';
            }
        });
        vid.play();
        overlay.style.opacity = '0';
        bar.style.opacity = '1';
        vid.ontimeupdate = () => {
            const pct = (vid.currentTime / vid.duration) * 100 || 0;
            wrap.querySelector('.vid-progress-fill').style.width = pct + '%';
            wrap.querySelector('.vid-time').textContent = fmtTime(vid.currentTime);
        };
        vid.onended = () => {
            overlay.style.opacity = '1';
            bar.style.opacity = '0';
            wrap.querySelector('.vid-progress-fill').style.width = '0%';
        };
    } else {
        vid.pause();
        overlay.style.opacity = '1';
        bar.style.opacity = '0';
    }
}

function toggleVideoMute(btn) {
    const vid = btn.closest('.post-video-wrap').querySelector('.post-video');
    vid.muted = !vid.muted;
    btn.className = vid.muted
        ? 'fa-solid fa-volume-xmark vid-mute-btn'
        : 'fa-solid fa-volume-high vid-mute-btn';
    btn.style.cssText = 'color:white;font-size:13px;';
}

function seekVideo(progressWrap, e) {
    const vid = progressWrap.closest('.post-video-wrap').querySelector('.post-video');
    const rect = progressWrap.getBoundingClientRect();
    const pct = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    vid.currentTime = pct * vid.duration;
}

function fmtTime(s) {
    if (!s || isNaN(s)) return '0:00';
    return Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0');
}

function tfToggleTopicFollow(cat, btn) {
    var key = 'tf-topic-follow-' + cat;
    var following = localStorage.getItem(key) === '1';
    if (following) {
        localStorage.removeItem(key);
        btn.textContent = 'Follow';
        btn.style.background = (_dsTopicData[cat]||{color:'#007AFF'}).color;
    } else {
        localStorage.setItem(key, '1');
        btn.textContent = 'Following ✓';
        btn.style.background = '#34C759';
        triggerHaptic(12);
    }
    showToast(following ? 'Unfollowed '+cat : 'Following '+cat+' 🎉');
    if (window.sb && currentUser) {
        if (following) {
            (async function(){ try { await sb.from('topic_follows').delete().eq('user_id', currentUser.id).eq('topic', cat); } catch(e){} })();
        } else {
            sb.from('topic_follows').insert({ user_id: currentUser.id, topic: cat }).catch(function(){});
        }
    }
}

async function sendMediaInChat(file, caption) {
    var chatBody = document.getElementById('chat-body');
    if (!chatBody) return;
    var isVideo = file.type.startsWith('video/');
    var msgType = isVideo ? 'video' : 'image';
    var localUrl = URL.createObjectURL(file);
    var msgId = 'local_' + Date.now();
    var time = new Date().toLocaleTimeString('en-ZA', { hour: '2-digit', minute: '2-digit' });

    // Show optimistic uploading bubble
    var m = {
        id: msgId,
        sender_id: currentUser ? currentUser.id : null,
        message_type: msgType,
        media_url: localUrl,
        status: 'uploading',
        created_at: new Date().toISOString()
    };
    chatBody.insertAdjacentHTML('beforeend', renderMessageBubble(m));
    chatBody.scrollTop = chatBody.scrollHeight;

    if (!window.sb || !currentUser) {
        _markMsgFailed(msgId);
        return;
    }

    try {
        var ext = file.name.split('.').pop() || (isVideo ? 'mp4' : 'jpg');
        var path = currentUser.id + '/chat/' + Date.now() + '.' + ext;
        var bucket = isVideo ? 'videos' : 'images';
        var total = file.size;
        var progEl = document.getElementById('upload-prog-' + msgId);

        // Upload with XHR for progress
        var { data, error } = await window.sb.storage.from(bucket).upload(path, file, { cacheControl: '3600', upsert: false });
        if (error) throw error;

        var urlResult = window.sb.storage.from(bucket).getPublicUrl(path);
        var publicUrl = urlResult.data && urlResult.data.publicUrl;

        // Update bubble to sent state
        var oldBubble = chatBody.querySelector('[data-msg-id="' + msgId + '"]');
        if (oldBubble) {
            var newM = Object.assign({}, m, { media_url: publicUrl, status: 'sent' });
            var newHtml = renderMessageBubble(newM);
            var wrapper = oldBubble.closest('[style*="flex-direction:column"]') || oldBubble.parentElement;
            if (wrapper) wrapper.outerHTML = newHtml;
        }

        // Save to DB
        if (currentConversationId) {
            await window.sb.from('messages').insert({
                conversation_id: currentConversationId,
                sender_id: currentUser.id,
                message_type: msgType,
                media_url: publicUrl,
                content: caption || null,
                created_at: new Date().toISOString()
            });
        }
    } catch(e) {
        _markMsgFailed(msgId);
        showToast('Upload failed');
        console.error('[sendMediaInChat]', e);
    }
}

function _markMsgFailed(msgId) {
    var chatBody = document.getElementById('chat-body');
    if (!chatBody) return;
    var bubble = chatBody.querySelector('[data-msg-id="' + msgId + '"]');
    if (bubble) {
        bubble.setAttribute('data-msg-status', 'failed');
        // Remove uploading overlay
        var overlay = bubble.querySelector('[style*="rgba(0,0,0,0.5)"]');
        if (overlay) overlay.remove();
        // Add error badge
        var badge = document.createElement('div');
        badge.style.cssText = 'position:absolute;bottom:-6px;right:-10px;width:20px;height:20px;border-radius:50%;background:#FF3B30;display:flex;align-items:center;justify-content:center;z-index:2;box-shadow:0 2px 6px rgba(255,59,48,0.5);';
        badge.innerHTML = '<span style="color:white;font-size:11px;font-weight:900;line-height:1;">!</span>';
        bubble.style.position = 'relative';
        bubble.appendChild(badge);
    }
}

async function joinRealChannel(btn, channelId) {
    if (!currentUser) { showToast('Sign in to join channels'); return; }
    btn.disabled = true;
    btn.textContent = 'Joining...';
    try {
        await window.sb.from('channel_followers').insert({ channel_id: channelId, user_id: currentUser.id });
        await window.sb.from('channels').update({ follower_count: window.sb.rpc('increment') }).eq('id', channelId).catch(function(){});
        btn.textContent = 'Joined';
        btn.style.background = '#34C759';
        btn.style.borderColor = '#34C759';
        btn.style.color = 'white';
        btn.disabled = false;
        showToast('Joined channel');
        triggerHaptic(20);
    } catch(e) {
        btn.textContent = 'Join';
        btn.disabled = false;
        showToast('Could not join. Try again.');
    }
}
